{
  "name": "ANIQ SUSILO - FINANCE MONTHLY",
  "description": "A professional, dark-themed monthly finance tracker for Aniq Susilo, featuring salary calculation, budgeting, investment tracking, and yearly analysis."
}

export interface SalaryData {
  basicSalary: number;
  housingAllowance: number;
  shiftAllowance: number;
  overtimeHours: number;
  bonusMultiplier: number; // For annual bonus calculation
  thr: number;
  leavePay: number; // Uang cuti
  taxRate: number; // Percentage
  otherDeductions: number;
}

export interface BudgetItem {
  id: string;
  name: string;
  budget: number;
  actual: number;
}

export interface OtherBudgetItem {
  id: string;
  name: string;
  actual: number;
}

export interface BudgetCategory {
  items: BudgetItem[];
}

export interface OtherBudgetCategory {
  allocation: number;
  items: OtherBudgetItem[];
}

export interface BudgetData {
  needs: BudgetCategory;
  savings: BudgetCategory;
  debt: BudgetCategory;
  others: OtherBudgetCategory;
}

export interface InvestmentItem {
  id: string;
  name: string;
  currentValue: number;
  targetValue: number;
}

export interface MonthlyData {
  salary: SalaryData;
  budget: BudgetData;
  investments: InvestmentItem[];
}

// Global state map: key is "YYYY-MM"
export interface AppState {
  [key: string]: MonthlyData;
}

export const DEFAULT_SALARY: SalaryData = {
  basicSalary: 0,
  housingAllowance: 0,
  shiftAllowance: 0,
  overtimeHours: 0,
  bonusMultiplier: 0,
  thr: 0,
  leavePay: 0,
  taxRate: 0,
  otherDeductions: 0,
};

export const DEFAULT_BUDGET: BudgetData = {
  needs: { items: [] },
  savings: { items: [] },
  debt: { items: [] },
  others: { allocation: 0, items: [] },
};

export const formatRupiah = (value: number): string => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency',
    currency: 'IDR',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(value);
};

export const parseRupiah = (value: string): number => {
  const clean = value.replace(/[^0-9]/g, '');
  return clean ? parseInt(clean, 10) : 0;
};

// Calculations based on requirements
export const calculateOvertime = (basic: number, housing: number, hours: number) => {
  return ((basic + housing) / 173) * hours;
};

export const calculateBonus = (basic: number, housing: number, multiplier: number) => {
  return (basic + housing) * multiplier;
};

export const calculateGrossIncome = (
  basic: number,
  housing: number,
  shift: number,
  otValue: number,
  bonusValue: number,
  thr: number,
  leave: number
) => {
  return basic + housing + shift + otValue + bonusValue + thr + leave;
};

export const calculateTax = (gross: number, rate: number) => {
  return gross * (rate / 100);
};

import React from 'react';
import { formatRupiah, parseRupiah } from '../../utils';

interface CurrencyInputProps {
  label: string;
  value: number;
  onChange: (val: number) => void;
  placeholder?: string;
  className?: string;
  disabled?: boolean;
}

const CurrencyInput: React.FC<CurrencyInputProps> = ({
  label,
  value,
  onChange,
  placeholder = 'Rp 0',
  className = '',
  disabled = false
}) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const numericValue = parseRupiah(e.target.value);
    onChange(numericValue);
  };

  // Format value for display, but allow typing
  // We use a controlled input that displays the formatted string
  const displayValue = value === 0 ? '' : formatRupiah(value).replace('Rp', '').trim();

  return (
    <div className={`flex flex-col gap-1 ${className}`}>
      <label className="text-sm text-slate-400 font-medium">{label}</label>
      <div className="relative">
        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 font-semibold">Rp</span>
        <input
          type="text"
          value={displayValue}
          onChange={handleChange}
          disabled={disabled}
          placeholder="0"
          className="w-full bg-slate-800 border border-slate-700 rounded-lg py-2 pl-10 pr-4 text-white focus:outline-none focus:ring-2 focus:ring-emerald-500 disabled:opacity-50 text-right font-mono"
        />
      </div>
    </div>
  );
};

export default CurrencyInput;

import React, { useEffect } from 'react';
