            value={data.shiftAllowance} 
            onChange={(v) => updateField('shiftAllowance', v)} 
          />

          <div className="flex flex-col gap-1">
            <label className="text-sm text-slate-400 font-medium">Lembur / Overtime (Jam)</label>
            <input 
              type="number" 
              step="0.1"
              value={data.overtimeHours}
              onChange={(e) => updateField('overtimeHours', parseFloat(e.target.value) || 0)}
              className="w-full bg-slate-800 border border-slate-700 rounded-lg py-2 px-4 text-white focus:outline-none focus:ring-2 focus:ring-emerald-500 text-right"
