          </div>

          <div className="flex flex-col gap-1">
            <label className="text-sm text-slate-400 font-medium">Bonus Tahunan (Multiplier)</label>
            <input 
              type="number" 
              step="0.1"
              value={data.bonusMultiplier}
              onChange={(e) => updateField('bonusMultiplier', parseFloat(e.target.value) || 0)}
              className="w-full bg-slate-800 border border-slate-700 rounded-lg py-2 px-4 text-white focus:outline-none focus:ring-2 focus:ring-emerald-500 text-right"
              placeholder="Ex: 1.5"
            />
            <p className="text-xs text-emerald-500 text-right">Hasil: {formatRupiah(bonusRupiah)}</p>
          </div>

          <CurrencyInput 
            label="THR / Tunjangan Hari Raya" 
            value={data.thr} 
            onChange={(v) => updateField('thr', v)} 
          />
          <CurrencyInput 
            label="Uang Cuti" 
            value={data.leavePay} 
            onChange={(v) => updateField('leavePay', v)} 
          />

          <div className="md:col-span-2 bg-emerald-900/20 p-4 rounded-lg flex justify-between items-center border border-emerald-500/30 mt-2">
            <span className="text-slate-200 font-semibold">Total Penghasilan Kotor (Gross)</span>
            <span className="text-xl font-bold text-emerald-400">{formatRupiah(grossIncome)}</span>
          </div>
        </div>
      </div>

      <div className="bg-slate-800/50 p-6 rounded-xl border border-slate-700">
        <h3 className="text-xl font-bold text-red-400 mb-4 border-b border-slate-700 pb-2">Potongan Pendapatan</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
