            <label className="text-sm text-slate-400 font-medium">Pajak PPh (%)</label>
            <input 
              type="number" 
              step="0.1"
              value={data.taxRate}
              onChange={(e) => updateField('taxRate', parseFloat(e.target.value) || 0)}
