          <CurrencyInput 
            label="Potongan Lain-lain" 
            value={data.otherDeductions} 
            onChange={(v) => updateField('otherDeductions', v)} 
          />

          <div className="md:col-span-2 bg-red-900/20 p-3 rounded-lg flex justify-between items-center border border-red-500/30">
