export default SalarySlip;

import React, { useState } from 'react';
import { BudgetData, BudgetItem, OtherBudgetItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, AlertTriangle, CheckCircle } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  // Helper to calculate totals
  const calcTotalBudget = () => {
    const needs = data.needs.items.reduce((acc, item) => acc + item.budget, 0);
    const savings = data.savings.items.reduce((acc, item) => acc + item.budget, 0);
    const debt = data.debt.items.reduce((acc, item) => acc + item.budget, 0);
    const others = data.others.allocation;
    return needs + savings + debt + others;
  };

  const calcTotalActual = () => {
    const needs = data.needs.items.reduce((acc, item) => acc + item.actual, 0);
    const savings = data.savings.items.reduce((acc, item) => acc + item.actual, 0);
    const debt = data.debt.items.reduce((acc, item) => acc + item.actual, 0);
    const others = data.others.items.reduce((acc, item) => acc + item.actual, 0);
    return needs + savings + debt + others;
  };

  const totalAllocated = calcTotalBudget();
  const totalActual = calcTotalActual();
  const balance = income - totalActual;

  const isOverBudget = totalAllocated > income;
  const isOverSpent = totalActual > totalAllocated;

  // Render Generic Category
  const CategorySection = ({ 
    title, 
    items, 
    type,
    color 
  }: { 
    title: string; 
    items: BudgetItem[]; 
    type: 'needs' | 'savings' | 'debt';
    color: string;
  }) => {
    const [expanded, setExpanded] = useState(false);

    const catTotalAllocated = items.reduce((a, b) => a + b.budget, 0);
    const catTotalActual = items.reduce((a, b) => a + b.actual, 0);
    const catRemaining = catTotalAllocated - catTotalActual;
    const isCatOver = catTotalActual > catTotalAllocated;

    const addItem = () => {
      const newItem: BudgetItem = { id: Date.now().toString(), name: '', budget: 0, actual: 0 };
      onChange({
        ...data,
        [type]: { items: [...items, newItem] }
      });
    };

    const updateItem = (id: string, field: keyof BudgetItem, val: any) => {
      const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
      onChange({ ...data, [type]: { items: newItems } });
    };

    const deleteItem = (id: string) => {
      const newItems = items.filter(item => item.id !== id);
      onChange({ ...data, [type]: { items: newItems } });
    };

    return (
      <div className={`bg-slate-800/50 rounded-xl border border-${color}-500/30 overflow-hidden mb-4`}>
        <div 
          className="p-4 flex justify-between items-center cursor-pointer hover:bg-slate-700/50 transition-colors"
          onClick={() => setExpanded(!expanded)}
        >
          <div className="flex items-center gap-3">
             <div className={`p-2 rounded-full bg-${color}-500/20 text-${color}-400`}>
                {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
             </div>
             <div>
               <h4 className="font-bold text-slate-200">{title}</h4>
               <p className="text-xs text-slate-400">
                 {items.length} Items | Alloc: {formatRupiah(catTotalAllocated)} | Act: {formatRupiah(catTotalActual)}
               </p>
             </div>
          </div>
          <div className="text-right">
             <div className={`text-sm font-bold ${isCatOver ? 'text-red-400' : 'text-emerald-400'}`}>
               Sisa: {formatRupiah(catRemaining)}
             </div>
             {isCatOver && <span className="text-xs text-red-500 flex items-center justify-end gap-1"><AlertTriangle size={12}/> Overbudget</span>}
          </div>
        </div>

        {expanded && (
          <div className="p-4 bg-slate-900/50 border-t border-slate-700">
             {items.map((item) => (
               <div key={item.id} className="grid grid-cols-1 md:grid-cols-12 gap-2 mb-3 items-end p-3 bg-slate-800 rounded-lg border border-slate-700">
                 <div className="md:col-span-4">
                   <label className="text-xs text-slate-400">Item Name</label>
                   <input 
                     type="text" 
                     value={item.name} 
                     onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                     className="w-full bg-slate-700 rounded p-2 text-white text-sm"
                     placeholder="Nama Item..."
                   />
                 </div>
                 <div className="md:col-span-3">
                   <CurrencyInput 
                     label="Anggaran" 
                     value={item.budget} 
                     onChange={(v) => updateItem(item.id, 'budget', v)}
                     className="text-sm"
                   />
                 </div>
                 <div className="md:col-span-3">
                   <CurrencyInput 
                     label="Realisasi" 
                     value={item.actual} 
                     onChange={(v) => updateItem(item.id, 'actual', v)}
                     className="text-sm"
                   />
                 </div>
                 <div className="md:col-span-2 flex justify-end pb-1">
                   <button onClick={() => deleteItem(item.id)} className="p-2 text-red-400 hover:bg-red-900/30 rounded">
                     <Trash2 size={18} />
                   </button>
                 </div>
                 {item.budget > 0 && item.actual === 0 && (
                    <div className="col-span-12 text-xs text-yellow-500 italic mt-1">
                      * Belum ada realisasi
                    </div>
                 )}
               </div>
             ))}

             <button 
               onClick={addItem}
               className={`w-full py-2 border border-dashed border-${color}-500/50 text-${color}-400 rounded-lg hover:bg-${color}-500/10 flex items-center justify-center gap-2 transition-colors`}
             >
               <Plus size={16} /> Tambah Item {title}
             </button>
          </div>
        )}
      </div>
    );
  };

  // Render Special "Others" Category
  const OthersCategory = () => {
    const [expanded, setExpanded] = useState(false);
    const { allocation, items } = data.others;

    const catTotalActual = items.reduce((a, b) => a + b.actual, 0);
    const catRemaining = allocation - catTotalActual;
    const isCatOver = catTotalActual > allocation;

    const addItem = () => {
      const newItem: OtherBudgetItem = { id: Date.now().toString(), name: '', actual: 0 };
      onChange({
        ...data,
        others: { ...data.others, items: [...items, newItem] }
      });
    };

    const updateAllocation = (val: number) => {
      onChange({ ...data, others: { ...data.others, allocation: val } });
    }

    const updateItem = (id: string, field: keyof OtherBudgetItem, val: any) => {
      const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
      onChange({ ...data, others: { ...data.others, items: newItems } });
    };

    const deleteItem = (id: string) => {
      const newItems = items.filter(item => item.id !== id);
      onChange({ ...data, others: { ...data.others, items: newItems } });
    };

    return (
      <div className="bg-slate-800/50 rounded-xl border border-purple-500/30 overflow-hidden mb-4">
        <div 
          className="p-4 flex justify-between items-center cursor-pointer hover:bg-slate-700/50 transition-colors"
          onClick={() => setExpanded(!expanded)}
        >
          <div className="flex items-center gap-3">
             <div className="p-2 rounded-full bg-purple-500/20 text-purple-400">
                {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
             </div>
             <div>
               <h4 className="font-bold text-slate-200">Kebutuhan Lain-lain</h4>
               <p className="text-xs text-slate-400">
                 Global Alloc: {formatRupiah(allocation)} | Actual: {formatRupiah(catTotalActual)}
               </p>
             </div>
          </div>
          <div className="text-right">
             <div className={`text-sm font-bold ${isCatOver ? 'text-red-400' : 'text-emerald-400'}`}>
               Sisa: {formatRupiah(catRemaining)}
             </div>
             {isCatOver && <span className="text-xs text-red-500 flex items-center justify-end gap-1"><AlertTriangle size={12}/> Overbudget</span>}
          </div>
        </div>

        {expanded && (
          <div className="p-4 bg-slate-900/50 border-t border-slate-700">
             <div className="mb-4 bg-purple-900/20 p-4 rounded-lg border border-purple-500/20">
               <CurrencyInput 
                 label="Total Alokasi Lain-lain (Memotong Anggaran Utama)"
                 value={allocation}
                 onChange={updateAllocation}
               />
             </div>

             {items.map((item) => (
               <div key={item.id} className="grid grid-cols-1 md:grid-cols-12 gap-2 mb-3 items-end p-3 bg-slate-800 rounded-lg border border-slate-700">
                 <div className="md:col-span-7">
                   <label className="text-xs text-slate-400">Item Name</label>
                   <input 
                     type="text" 
                     value={item.name} 
                     onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                     className="w-full bg-slate-700 rounded p-2 text-white text-sm"
                     placeholder="Nama Item..."
                   />
                 </div>
                 <div className="md:col-span-3">
                   <CurrencyInput 
                     label="Realisasi" 
                     value={item.actual} 
                     onChange={(v) => updateItem(item.id, 'actual', v)}
                     className="text-sm"
                   />
                 </div>
                 <div className="md:col-span-2 flex justify-end pb-1">
                   <button onClick={() => deleteItem(item.id)} className="p-2 text-red-400 hover:bg-red-900/30 rounded">
                     <Trash2 size={18} />
                   </button>
                 </div>
                  {item.actual === 0 && (
                    <div className="col-span-12 text-xs text-yellow-500 italic mt-1">
                      * Belum ada realisasi
                    </div>
                 )}
               </div>
             ))}

             <button 
               onClick={addItem}
               className="w-full py-2 border border-dashed border-purple-500/50 text-purple-400 rounded-lg hover:bg-purple-500/10 flex items-center justify-center gap-2 transition-colors"
             >
               <Plus size={16} /> Tambah Item Lain-lain
             </button>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Summary Header */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-slate-800 p-4 rounded-xl border border-slate-700">
           <p className="text-slate-400 text-sm">Penghasilan (Net)</p>
           <h3 className="text-xl font-bold text-white">{formatRupiah(income)}</h3>
        </div>
        <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 relative overflow-hidden">
           <p className="text-slate-400 text-sm">Total Anggaran (Alloc)</p>
           <h3 className={`text-xl font-bold ${isOverBudget ? 'text-red-400' : 'text-blue-400'}`}>
             {formatRupiah(totalAllocated)}
           </h3>
           <div className="w-full bg-slate-700 h-1 mt-2 rounded-full overflow-hidden">
              <div 
                className={`h-full ${isOverBudget ? 'bg-red-500' : 'bg-blue-500'}`} 
                style={{ width: `${Math.min((totalAllocated / income) * 100, 100)}%` }} 
              />
           </div>
           {isOverBudget && <span className="text-[10px] text-red-400 absolute top-2 right-2 flex items-center gap-1"><AlertTriangle size={10}/> Over Budget</span>}
        </div>
        <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 relative">
           <p className="text-slate-400 text-sm">Aktual Pengeluaran</p>
           <h3 className={`text-xl font-bold ${isOverSpent ? 'text-red-400' : 'text-orange-400'}`}>
             {formatRupiah(totalActual)}
           </h3>
           <div className="w-full bg-slate-700 h-1 mt-2 rounded-full overflow-hidden">
              <div 
                className={`h-full ${isOverSpent ? 'bg-red-500' : 'bg-orange-500'}`} 
                style={{ width: `${Math.min((totalActual / totalAllocated) * 100, 100)}%` }} 
              />
           </div>
        </div>
        <div className={`bg-slate-800 p-4 rounded-xl border border-slate-700 ${balance < 0 ? 'border-red-500/50 bg-red-900/10' : 'border-emerald-500/50 bg-emerald-900/10'}`}>
           <p className="text-slate-400 text-sm">Sisa Saldo</p>
           <h3 className={`text-xl font-bold ${balance < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
             {formatRupiah(balance)}
           </h3>
           {balance > 0 && <span className="text-[10px] text-emerald-400 flex items-center gap-1 mt-1"><CheckCircle size={10}/> Safe</span>}
           {balance < 0 && <span className="text-[10px] text-red-400 flex items-center gap-1 mt-1"><AlertTriangle size={10}/> Deficit</span>}
        </div>
      </div>

      {/* Categories */}
      <div className="space-y-4">
        <CategorySection title="Kebutuhan Pokok" items={data.needs.items} type="needs" color="blue" />
        <CategorySection title="Tabungan / Investasi" items={data.savings.items} type="savings" color="emerald" />
        <CategorySection title="Hutang / Cicilan" items={data.debt.items} type="debt" color="red" />
        <OthersCategory />
      </div>
    </div>
  );
};

export default Budget;

import React from 'react';
import { InvestmentItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { Plus, Trash2, TrendingUp, Target } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

interface InvestmentsProps {
  items: InvestmentItem[];
  onChange: (items: InvestmentItem[]) => void;
}

const COLORS = ['#10B981', '#3B82F6', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899'];

const Investments: React.FC<InvestmentsProps> = ({ items, onChange }) => {
  const addItem = () => {
    const newItem: InvestmentItem = { id: Date.now().toString(), name: '', currentValue: 0, targetValue: 0 };
    onChange([...items, newItem]);
  };

  const updateItem = (id: string, field: keyof InvestmentItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onChange(newItems);
  };

  const deleteItem = (id: string) => {
    onChange(items.filter(item => item.id !== id));
  };

  const totalPortfolio = items.reduce((acc, item) => acc + item.currentValue, 0);
  const totalTarget = items.reduce((acc, item) => acc + item.targetValue, 0);
  const progress = totalTarget > 0 ? (totalPortfolio / totalTarget) * 100 : 0;

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Header Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-6 rounded-2xl border border-slate-700 shadow-xl relative overflow-hidden">
          <div className="absolute right-0 top-0 p-4 opacity-10">
            <TrendingUp size={100} className="text-emerald-500" />
          </div>
          <h3 className="text-slate-400 font-medium mb-1">Total Portofolio Investasi</h3>
          <div className="text-3xl md:text-4xl font-bold text-emerald-400">{formatRupiah(totalPortfolio)}</div>
          <div className="mt-4">
             <div className="flex justify-between text-xs text-slate-400 mb-1">
               <span>Target Pencapaian Global</span>
               <span>{progress.toFixed(1)}%</span>
             </div>
             <div className="w-full bg-slate-700 h-2 rounded-full overflow-hidden">
               <div className="bg-emerald-500 h-full rounded-full transition-all duration-500" style={{ width: `${Math.min(progress, 100)}%` }}></div>
             </div>
          </div>
        </div>

        {/* Chart */}
        <div className="bg-slate-800 p-4 rounded-2xl border border-slate-700 h-48 flex items-center">
          {items.length > 0 && totalPortfolio > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={items}
                  cx="50%"
                  cy="50%"
                  innerRadius={40}
                  outerRadius={70}
                  paddingAngle={5}
                  dataKey="currentValue"
                >
                  {items.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip 
                  formatter={(value: number) => formatRupiah(value)}
                  contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#fff' }}
                />
              </PieChart>
            </ResponsiveContainer>
          ) : (
             <div className="w-full text-center text-slate-500">Belum ada data investasi</div>
          )}
        </div>
      </div>

      {/* List */}
      <div className="bg-slate-800/50 rounded-xl border border-slate-700 overflow-hidden">
         <div className="p-4 bg-slate-800 border-b border-slate-700 flex justify-between items-center">
            <h3 className="font-bold text-slate-200">Aset Investasi</h3>
            <button 
              onClick={addItem}
              className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg flex items-center gap-2 text-sm transition-colors"
            >
              <Plus size={16} /> Tambah Aset
            </button>
         </div>
         <div className="p-4 space-y-4">
            {items.map((item) => (
              <div key={item.id} className="bg-slate-900/50 p-4 rounded-lg border border-slate-700 grid grid-cols-1 md:grid-cols-12 gap-4 items-end">
                  <div className="md:col-span-4">
                    <label className="text-xs text-slate-400 block mb-1">Nama Aset</label>
                    <input 
                      type="text" 
                      value={item.name} 
                      onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                      className="w-full bg-slate-800 border border-slate-700 rounded p-2 text-white text-sm focus:ring-1 focus:ring-emerald-500"
                      placeholder="Misal: Saham BBCA"
                    />
                  </div>
                  <div className="md:col-span-3">
                    <CurrencyInput 
                      label="Saldo Saat Ini" 
                      value={item.currentValue} 
                      onChange={(v) => updateItem(item.id, 'currentValue', v)}
                      className="text-sm"
                    />
                  </div>
                  <div className="md:col-span-3">
                    <CurrencyInput 
                      label="Target Dana" 
                      value={item.targetValue} 
                      onChange={(v) => updateItem(item.id, 'targetValue', v)}
                      className="text-sm"
                    />
                  </div>
                  <div className="md:col-span-2 flex justify-between items-center">
                    <div className="text-xs text-slate-400 mr-2">
                       {item.targetValue > 0 && (
                         <span className="flex items-center gap-1">
                           <Target size={12} /> {((item.currentValue / item.targetValue) * 100).toFixed(0)}%
                         </span>
                       )}
                    </div>
                    <button onClick={() => deleteItem(item.id)} className="p-2 text-red-400 hover:bg-red-900/30 rounded">
                      <Trash2 size={18} />
                    </button>
                  </div>
              </div>
            ))}
            {items.length === 0 && (
              <div className="text-center py-8 text-slate-500">
                Mulai tambahkan portofolio investasi Anda
              </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default Investments;

import React from 'react';
import { BudgetData } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { formatRupiah } from '../utils';

interface MonthlyChartsProps {
  budgetData: BudgetData;
  income: number;
}

const MonthlyCharts: React.FC<MonthlyChartsProps> = ({ budgetData, income }) => {
  // Aggregate data
  const needsAlloc = budgetData.needs.items.reduce((a, b) => a + b.budget, 0);
  const needsActual = budgetData.needs.items.reduce((a, b) => a + b.actual, 0);

  const savingsAlloc = budgetData.savings.items.reduce((a, b) => a + b.budget, 0);
  const savingsActual = budgetData.savings.items.reduce((a, b) => a + b.actual, 0);

  const debtAlloc = budgetData.debt.items.reduce((a, b) => a + b.budget, 0);
  const debtActual = budgetData.debt.items.reduce((a, b) => a + b.actual, 0);

  const othersAlloc = budgetData.others.allocation;
  const othersActual = budgetData.others.items.reduce((a, b) => a + b.actual, 0);

  const totalAllocated = needsAlloc + savingsAlloc + debtAlloc + othersAlloc;
  const totalActual = needsActual + savingsActual + debtActual + othersActual;

  const barData = [
    { name: 'Total', Anggaran: totalAllocated, Aktual: totalActual },
    { name: 'Pokok', Anggaran: needsAlloc, Aktual: needsActual },
    { name: 'Tabungan', Anggaran: savingsAlloc, Aktual: savingsActual },
    { name: 'Cicilan', Anggaran: debtAlloc, Aktual: debtActual },
    { name: 'Lainnya', Anggaran: othersAlloc, Aktual: othersActual },
  ];

  const pieAllocData = [
    { name: 'Pokok', value: needsAlloc },
    { name: 'Tabungan', value: savingsAlloc },
    { name: 'Cicilan', value: debtAlloc },
    { name: 'Lainnya', value: othersAlloc },
  ].filter(d => d.value > 0);

  const pieActualData = [
    { name: 'Pokok', value: needsActual },
    { name: 'Tabungan', value: savingsActual },
    { name: 'Cicilan', value: debtActual },
    { name: 'Lainnya', value: othersActual },
  ].filter(d => d.value > 0);

  const COLORS = ['#3B82F6', '#10B981', '#EF4444', '#8B5CF6'];

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-slate-800 p-3 border border-slate-700 rounded shadow-xl text-xs">
          <p className="font-bold text-slate-200 mb-1">{label}</p>
          {payload.map((entry: any, index: number) => (
            <p key={index} style={{ color: entry.color }}>
              {entry.name}: {formatRupiah(entry.value)}
            </p>
          ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Performance Bar Chart */}
      <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
        <h3 className="text-lg font-bold text-slate-200 mb-4 border-l-4 border-emerald-500 pl-3">Kinerja Item Anggaran (Budget vs Actual)</h3>
        <div className="h-80 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={barData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
              <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} />
              <YAxis stroke="#94a3b8" fontSize={12} tickFormatter={(val) => `Rp${val/1000}k`} />
              <Tooltip content={<CustomTooltip />} />
              <Legend />
              <Bar dataKey="Anggaran" fill="#3B82F6" radius={[4, 4, 0, 0]} />
              <Bar dataKey="Aktual" fill="#10B981" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Allocation Pie */}
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
           <h3 className="text-lg font-bold text-slate-200 mb-4 border-l-4 border-blue-500 pl-3">Komposisi Rencana Alokasi</h3>
           <div className="h-64">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieAllocData}
                    cx="50%"
                    cy="50%"
                    outerRadius={80}
                    dataKey="value"
                    labelLine={false}
                    label={({ cx, cy, midAngle, innerRadius, outerRadius, percent, index }) => {
                       // Only show label if > 5%
                       if (percent < 0.05) return null;
                       const RADIAN = Math.PI / 180;
                       const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
                       const x = cx + radius * Math.cos(-midAngle * RADIAN);
                       const y = cy + radius * Math.sin(-midAngle * RADIAN);
                       return (
                         <text x={x} y={y} fill="white" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central" fontSize={10}>
                           {`${(percent * 100).toFixed(0)}%`}
                         </text>
                       );
                    }}
                  >
                    {pieAllocData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                  <Legend iconSize={10} layout="vertical" verticalAlign="middle" align="right"/>
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>

        {/* Realization Pie */}
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
           <h3 className="text-lg font-bold text-slate-200 mb-4 border-l-4 border-orange-500 pl-3">Komposisi Realisasi Pengeluaran</h3>
           <div className="h-64">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieActualData}
                    cx="50%"
                    cy="50%"
                    outerRadius={80}
                    dataKey="value"
                    labelLine={false}
                    label={({ cx, cy, midAngle, innerRadius, outerRadius, percent, index }) => {
                       if (percent < 0.05) return null;
                       const RADIAN = Math.PI / 180;
                       const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
                       const x = cx + radius * Math.cos(-midAngle * RADIAN);
                       const y = cy + radius * Math.sin(-midAngle * RADIAN);
                       return (
                         <text x={x} y={y} fill="white" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central" fontSize={10}>
                           {`${(percent * 100).toFixed(0)}%`}
                         </text>
                       );
                    }}
                  >
                    {pieActualData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                  <Legend iconSize={10} layout="vertical" verticalAlign="middle" align="right"/>
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>
      </div>
    </div>
  );
};

export default MonthlyCharts;

import React, { useMemo } from 'react';
import { AppState } from '../types';
import { calculateGrossIncome, calculateTax, formatRupiah } from '../utils';
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';

interface YearlySummaryProps {
  appState: AppState;
  year: number;
}

const YearlySummary: React.FC<YearlySummaryProps> = ({ appState, year }) => {
  const summaryData = useMemo(() => {
    const months = Array.from({ length: 12 }, (_, i) => {
      const monthNum = i + 1;
      const monthKey = `${year}-${String(monthNum).padStart(2, '0')}`;
      const data = appState[monthKey];

      if (!data) {
        return {
          month: new Date(year, i).toLocaleString('id-ID', { month: 'short' }),
          income: 0,
          expense: 0,
          margin: 0,
          profit: 0
        };
      }

      // Calculate Income
      const { salary } = data;
      const otRupiah = ((salary.basicSalary + salary.housingAllowance) / 173) * salary.overtimeHours;
      const bonusRupiah = (salary.basicSalary + salary.housingAllowance) * salary.bonusMultiplier;
      const gross = calculateGrossIncome(
        salary.basicSalary, 
        salary.housingAllowance, 
        salary.shiftAllowance, 
        otRupiah, 
        bonusRupiah, 
        salary.thr, 
        salary.leavePay
      );
      const tax = calculateTax(gross, salary.taxRate);
      const netIncome = gross - tax - salary.otherDeductions;

      // Calculate Expense (Actuals)
      const { budget } = data;
      const expense = 
        budget.needs.items.reduce((a, b) => a + b.actual, 0) +
        budget.savings.items.reduce((a, b) => a + b.actual, 0) + // Include savings as expense in cashflow? Usually yes in simple budgeting, or distinct. Prompt says "Total pengeluaran". Savings are usually "Out" from cash.
        budget.debt.items.reduce((a, b) => a + b.actual, 0) +
        budget.others.items.reduce((a, b) => a + b.actual, 0);

      const profit = netIncome - expense;
      const margin = netIncome > 0 ? (profit / netIncome) * 100 : 0;

      return {
        month: new Date(year, i).toLocaleString('id-ID', { month: 'short' }),
        income: netIncome,
        expense: expense,
        margin: margin,
        profit: profit
      };
    });
    return months;
  }, [appState, year]);

  const totalIncome = summaryData.reduce((acc, curr) => acc + curr.income, 0);
  const totalExpense = summaryData.reduce((acc, curr) => acc + curr.expense, 0);
  const netProfit = totalIncome - totalExpense;

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-slate-800 p-3 border border-slate-700 rounded shadow-xl text-xs">
          <p className="font-bold text-slate-200 mb-1">{label} {year}</p>
          <p className="text-emerald-400">Income: {formatRupiah(payload[0].value)}</p>
          <p className="text-red-400">Expense: {formatRupiah(payload[1].value)}</p>
          <p className="text-blue-400 border-t border-slate-600 pt-1 mt-1">Profit: {formatRupiah(payload[0].value - payload[1].value)}</p>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 animate-fadeIn">
       {/* Cards */}
       <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-gradient-to-br from-emerald-900/50 to-slate-800 p-6 rounded-xl border border-emerald-500/30">
            <h4 className="text-slate-400 text-sm uppercase tracking-wider">Total Pendapatan {year}</h4>
            <div className="text-2xl font-bold text-emerald-400 mt-2">{formatRupiah(totalIncome)}</div>
          </div>
          <div className="bg-gradient-to-br from-red-900/50 to-slate-800 p-6 rounded-xl border border-red-500/30">
            <h4 className="text-slate-400 text-sm uppercase tracking-wider">Total Pengeluaran {year}</h4>
            <div className="text-2xl font-bold text-red-400 mt-2">{formatRupiah(totalExpense)}</div>
          </div>
          <div className="bg-gradient-to-br from-blue-900/50 to-slate-800 p-6 rounded-xl border border-blue-500/30">
            <h4 className="text-slate-400 text-sm uppercase tracking-wider">Net Profit {year}</h4>
            <div className={`text-2xl font-bold mt-2 ${netProfit >= 0 ? 'text-blue-400' : 'text-red-400'}`}>{formatRupiah(netProfit)}</div>
          </div>
       </div>

       {/* Trend Chart */}
       <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
         <h3 className="text-lg font-bold text-slate-200 mb-4">Trend Akumulasi Bulanan</h3>
         <div className="h-72 w-full">
           <ResponsiveContainer width="100%" height="100%">
             <AreaChart data={summaryData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorIncome" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10B981" stopOpacity={0.8}/>
                    <stop offset="95%" stopColor="#10B981" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorExpense" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#EF4444" stopOpacity={0.8}/>
                    <stop offset="95%" stopColor="#EF4444" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <XAxis dataKey="month" stroke="#94a3b8" fontSize={12} />
                <YAxis stroke="#94a3b8" fontSize={12} tickFormatter={(val) => `${val/1000000}M`} />
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                <Tooltip content={<CustomTooltip />} />
                <Area type="monotone" dataKey="income" stroke="#10B981" fillOpacity={1} fill="url(#colorIncome)" strokeWidth={2} />
                <Area type="monotone" dataKey="expense" stroke="#EF4444" fillOpacity={1} fill="url(#colorExpense)" strokeWidth={2} />
             </AreaChart>
           </ResponsiveContainer>
         </div>
       </div>

       {/* Table */}
       <div className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden">
         <div className="p-4 border-b border-slate-700">
            <h3 className="text-lg font-bold text-slate-200">Ringkasan Periode {year}</h3>
         </div>
         <div className="overflow-x-auto">
           <table className="w-full text-left text-sm text-slate-300">
             <thead className="bg-slate-900/50 text-slate-400 uppercase font-medium">
               <tr>
                 <th className="px-6 py-3">Bulan</th>
                 <th className="px-6 py-3 text-right">Pendapatan</th>
                 <th className="px-6 py-3 text-right">Pengeluaran</th>
                 <th className="px-6 py-3 text-right">Margin Profit</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-700">
               {summaryData.map((row) => (
                 <tr key={row.month} className="hover:bg-slate-700/30 transition-colors">
                   <td className="px-6 py-3 font-medium text-white">{row.month}</td>
                   <td className="px-6 py-3 text-right text-emerald-400">{formatRupiah(row.income)}</td>
                   <td className="px-6 py-3 text-right text-red-400">{formatRupiah(row.expense)}</td>
                   <td className="px-6 py-3 text-right">
                      <span className={`px-2 py-1 rounded text-xs font-bold ${row.margin > 20 ? 'bg-emerald-500/20 text-emerald-400' : row.margin > 0 ? 'bg-yellow-500/20 text-yellow-400' : 'bg-red-500/20 text-red-400'}`}>
                        {row.margin.toFixed(1)}%
                      </span>
                   </td>
                 </tr>
               ))}
             </tbody>
           </table>
         </div>
       </div>
    </div>
  );
};

export default YearlySummary;

import React, { useState, useEffect } from 'react';
import { AppState, MonthlyData, DEFAULT_SALARY, DEFAULT_BUDGET } from './types';
import SalarySlip from './components/SalarySlip';
import Budget from './components/Budget';
import MonthlyCharts from './components/MonthlyCharts';
import Investments from './components/Investments';
import YearlySummary from './components/YearlySummary';
import { calculateGrossIncome, calculateTax, calculateOvertime, calculateBonus } from './utils';
import { Wallet, LayoutDashboard, PieChart, TrendingUp, Calendar, ChevronLeft, ChevronRight, Save } from 'lucide-react';

const TABS = [
  { id: 'salary', label: 'Slip Gaji', icon: Wallet },
  { id: 'budget', label: 'Anggaran', icon: LayoutDashboard },
  { id: 'charts', label: 'Grafik Bulanan', icon: PieChart },
  { id: 'invest', label: 'Investasi', icon: TrendingUp },
  { id: 'year', label: 'Akumulasi Pertahun', icon: Calendar },
];

const App: React.FC = () => {
  // State
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('finance_app_data');
    return saved ? JSON.parse(saved) : {};
  });
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  // Derived State
  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;
  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  // Helper: Income Calculation for passing to props
  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     const tax = calculateTax(gross, salary.taxRate);
     return gross - tax - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  // Persist
  useEffect(() => {
    localStorage.setItem('finance_app_data', JSON.stringify(appState));
  }, [appState]);

  // Month Change Logic
  useEffect(() => {
    if (!appState[currentMonthKey]) {
      // Check if previous month exists
      const prevDate = new Date(currentDate);
      prevDate.setMonth(currentDate.getMonth() - 1);
      const pKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;

      if (appState[pKey]) {
        setPrevMonthKey(pKey);
        setShowCopyModal(true);
      } else {
        // Initialize default if no prev month
        initializeMonth(false);
      }
    }
  }, [currentMonthKey]);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      const prev = appState[prevMonthKey];
      // Deep copy to avoid reference issues, reset actuals to 0 usually? 
      // Prompt says "Copy data", implying structure and allocations, but maybe not specific OT hours.
      // Let's copy structure and allocations, but reset "Actual" values and overtime/bonus specific inputs?
      // For simplicity based on prompt "menyalin data", usually means copying the budget plan. 
      // I will copy everything but maybe reset Actuals to 0 is safer for a new month.
      // However, let's just copy exactly as requested "menyalin data". 
      // Users can modify numbers.
      newData = JSON.parse(JSON.stringify(prev));
      // Reset Actuals for budget items
      newData.budget.needs.items.forEach(i => i.actual = 0);
      newData.budget.savings.items.forEach(i => i.actual = 0);
      newData.budget.debt.items.forEach(i => i.actual = 0);
      newData.budget.others.items.forEach(i => i.actual = 0); // Others items are pure actuals usually, so maybe clear list? Let's keep structure but 0.

      // Reset fluctuating salary inputs?
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = {
        salary: { ...DEFAULT_SALARY },
        budget: { ...DEFAULT_BUDGET },
        investments: []
      };
    }

    setAppState(prev => ({
      ...prev,
      [currentMonthKey]: newData
    }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => ({
      ...prev,
      [currentMonthKey]: { ...currentData, ...newData }
    }));
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans selection:bg-emerald-500 selection:text-white">
      {/* Navbar */}
      <nav className="sticky top-0 z-50 bg-slate-900/90 backdrop-blur-md border-b border-slate-800 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="bg-gradient-to-tr from-emerald-500 to-cyan-500 p-2 rounded-lg shadow-lg shadow-emerald-500/20">
                 <Wallet className="text-white h-6 w-6" />
              </div>
              <div>
                <h1 className="text-lg font-bold tracking-tight text-white leading-tight">ANIQ SUSILO</h1>
                <p className="text-xs text-emerald-400 font-medium tracking-widest">FINANCE MONTHLY</p>
              </div>
            </div>

            <div className="flex items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
               <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-700 rounded-md transition-colors text-slate-400 hover:text-white">
                 <ChevronLeft size={18} />
               </button>
               <div className="px-4 font-mono font-bold text-emerald-400 w-32 text-center">
                 {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' })}
               </div>
               <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-700 rounded-md transition-colors text-slate-400 hover:text-white">
                 <ChevronRight size={18} />
               </button>
            </div>
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="border-t border-slate-800 bg-slate-900/50">
          <div className="max-w-7xl mx-auto px-4 overflow-x-auto">
            <div className="flex space-x-1 py-1">
              {TABS.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`
                      flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-md whitespace-nowrap transition-all duration-200
                      ${isActive 
                        ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' 
                        : 'text-slate-400 hover:text-white hover:bg-slate-800'}
                    `}
                  >
                    <Icon size={16} />
                    {tab.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </nav>

      {/* Content Area */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 pb-20">
        {activeTab === 'salary' && (
          <SalarySlip 
            data={currentData.salary} 
            onChange={(s) => updateCurrentData({ salary: s })} 
          />
        )}
        {activeTab === 'budget' && (
          <Budget 
            income={currentNetIncome} 
            data={currentData.budget} 
            onChange={(b) => updateCurrentData({ budget: b })} 
          />
        )}
        {activeTab === 'charts' && (
          <MonthlyCharts 
            budgetData={currentData.budget} 
            income={currentNetIncome} 
          />
        )}
        {activeTab === 'invest' && (
          <Investments 
            items={currentData.investments} 
            onChange={(i) => updateCurrentData({ investments: i })} 
          />
        )}
        {activeTab === 'year' && (
          <YearlySummary 
            appState={appState} 
            year={currentDate.getFullYear()} 
          />
        )}
      </main>

      {/* Copy Modal */}
      {showCopyModal && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
           <div className="bg-slate-800 rounded-2xl border border-slate-700 p-6 max-w-sm w-full shadow-2xl animate-fadeIn">
              <h3 className="text-xl font-bold text-white mb-2">Bulan Baru Terdeteksi</h3>
              <p className="text-slate-400 mb-6">Data untuk bulan ini belum tersedia. Apakah Anda ingin menyalin struktur anggaran dan data gaji dari bulan sebelumnya?</p>
              <div className="flex gap-3">
                <button 
                  onClick={() => initializeMonth(true)}
                  className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white py-2 rounded-lg font-medium transition-colors"
                >
                  Salin Data
                </button>
                <button 
                  onClick={() => initializeMonth(false)}
                  className="flex-1 bg-slate-700 hover:bg-slate-600 text-white py-2 rounded-lg font-medium transition-colors"
                >
                  Buat Baru
                </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

