};

interface OthersCategoryProps {
  allocation: number;
  items: OtherBudgetItem[];
  onUpdateAllocation: (val: number) => void;
  onUpdateItems: (items: OtherBudgetItem[]) => void;
}

const OthersCategory: React.FC<OthersCategoryProps> = ({
  allocation,
  items,
  onUpdateAllocation,
  onUpdateItems
}) => {
  const [expanded, setExpanded] = useState(false);

  const catTotalActual = items.reduce((a, b) => a + b.actual, 0);
  const catRemaining = allocation - catTotalActual;
  const isCatOver = catTotalActual > allocation;
  const unrealizedCount = items.filter(i => i.actual === 0).length;

  const addItem = () => {
    const newItem: OtherBudgetItem = { id: Date.now().toString(), name: '', actual: 0 };
    onUpdateItems([...items, newItem]);
  };

  const updateItem = (id: string, field: keyof OtherBudgetItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onUpdateItems(newItems);
  };

  const deleteItem = (id: string) => {
    const newItems = items.filter(item => item.id !== id);
    onUpdateItems(newItems);
  };

  return (
    <div className="bg-slate-800/50 rounded-xl border border-purple-500/30 overflow-hidden mb-4">
      <div 
        className="p-4 flex justify-between items-center cursor-pointer hover:bg-slate-700/50 transition-colors"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-center gap-3">
           <div className="p-2 rounded-full bg-purple-500/20 text-purple-400">
              {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
           </div>
           <div>
             <h4 className="font-bold text-slate-200">Kebutuhan Lain-lain</h4>
             <div className="text-xs text-slate-400 flex flex-col sm:flex-row sm:gap-2">
               <span>Anggaran: {formatRupiah(allocation)} | Realisasi: {formatRupiah(catTotalActual)}</span>
               {unrealizedCount > 0 && (
                 <span className="text-yellow-500 font-medium flex items-center gap-1">
                   <Info size={10} /> {unrealizedCount} item belum direalisasi
                 </span>
               )}
             </div>
           </div>
        </div>
        <div className="text-right pl-2">
           <div className={`text-sm font-bold ${isCatOver ? 'text-red-400' : 'text-emerald-400'}`}>
             Sisa: {formatRupiah(catRemaining)}
           </div>
           {isCatOver && <span className="text-xs text-red-500 flex items-center justify-end gap-1"><AlertTriangle size={12}/> Overbudget</span>}
        </div>
      </div>

      {expanded && (
        <div className="p-4 bg-slate-900/50 border-t border-slate-700">
           <div className="mb-4 bg-purple-900/20 p-4 rounded-lg border border-purple-500/20">
             <CurrencyInput 
               label="Total Anggaran Lain-lain (Memotong Anggaran Utama)"
               value={allocation}
               onChange={onUpdateAllocation}
             />
           </div>

           {items.map((item) => (
             <div key={item.id} className="grid grid-cols-1 md:grid-cols-12 gap-2 mb-3 items-end p-3 bg-slate-800 rounded-lg border border-slate-700">
               <div className="md:col-span-7">
                 <label className="text-xs text-slate-400">Item Name</label>
                 <input 
                   type="text" 
                   value={item.name} 
                   onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                   className="w-full bg-slate-700 rounded p-2 text-white text-sm"
                   placeholder="Nama Item..."
                 />
               </div>
               <div className="md:col-span-3">
                 <CurrencyInput 
                   label="Realisasi" 
                   value={item.actual} 
                   onChange={(v) => updateItem(item.id, 'actual', v)}
                   className="text-sm"
                 />
               </div>
               <div className="md:col-span-2 flex justify-end pb-1">
                 <button onClick={() => deleteItem(item.id)} className="p-2 text-red-400 hover:bg-red-900/30 rounded">
                   <Trash2 size={18} />
                 </button>
               </div>
                {item.actual === 0 && (
                  <div className="col-span-12 text-xs text-yellow-500 italic mt-1">
                    * Belum ada realisasi
                  </div>
               )}
             </div>
           ))}

           <button 
             onClick={addItem}
             className="w-full py-2 border border-dashed border-purple-500/50 text-purple-400 rounded-lg hover:bg-purple-500/10 flex items-center justify-center gap-2 transition-colors"
           >
             <Plus size={16} /> Tambah Item Lain-lain
           </button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  // Helper to calculate totals
  const calcTotalBudget = () => {
    const needs = data.needs.items.reduce((acc, item) => acc + item.budget, 0);
    const savings = data.savings.items.reduce((acc, item) => acc + item.budget, 0);
    const debt = data.debt.items.reduce((acc, item) => acc + item.budget, 0);
    const others = data.others.allocation;
    return needs + savings + debt + others;
  };

  const calcTotalActual = () => {
    const needs = data.needs.items.reduce((acc, item) => acc + item.actual, 0);
    const savings = data.savings.items.reduce((acc, item) => acc + item.actual, 0);
    const debt = data.debt.items.reduce((acc, item) => acc + item.actual, 0);
    const others = data.others.items.reduce((acc, item) => acc + item.actual, 0);
    return needs + savings + debt + others;
  };

  const totalAllocated = calcTotalBudget();
  const totalActual = calcTotalActual();
  const balance = income - totalActual;

  const isOverBudget = totalAllocated > income;
  const isOverSpent = totalActual > totalAllocated;

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Summary Header */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-slate-800 p-4 rounded-xl border border-slate-700">
           <p className="text-slate-400 text-sm">Penghasilan (Net)</p>
           <h3 className="text-xl font-bold text-white">{formatRupiah(income)}</h3>
        </div>
        <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 relative overflow-hidden">
           <p className="text-slate-400 text-sm">Total Anggaran</p>
           <h3 className={`text-xl font-bold ${isOverBudget ? 'text-red-400' : 'text-blue-400'}`}>
             {formatRupiah(totalAllocated)}
           </h3>
           <div className="w-full bg-slate-700 h-1 mt-2 rounded-full overflow-hidden">
              <div 
                className={`h-full ${isOverBudget ? 'bg-red-500' : 'bg-blue-500'}`} 
                style={{ width: `${Math.min((totalAllocated / income) * 100, 100)}%` }} 
              />
           </div>
           {isOverBudget && <span className="text-[10px] text-red-400 absolute top-2 right-2 flex items-center gap-1"><AlertTriangle size={10}/> Over Budget</span>}
        </div>
        <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 relative">
           <p className="text-slate-400 text-sm">Total Realisasi</p>
           <h3 className={`text-xl font-bold ${isOverSpent ? 'text-red-400' : 'text-orange-400'}`}>
             {formatRupiah(totalActual)}
           </h3>
           <div className="w-full bg-slate-700 h-1 mt-2 rounded-full overflow-hidden">
              <div 
                className={`h-full ${isOverSpent ? 'bg-red-500' : 'bg-orange-500'}`} 
                style={{ width: `${Math.min((totalActual / totalAllocated) * 100, 100)}%` }} 
              />
           </div>
        </div>
        <div className={`bg-slate-800 p-4 rounded-xl border border-slate-700 ${balance < 0 ? 'border-red-500/50 bg-red-900/10' : 'border-emerald-500/50 bg-emerald-900/10'}`}>
           <p className="text-slate-400 text-sm">Sisa Saldo</p>
           <h3 className={`text-xl font-bold ${balance < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
             {formatRupiah(balance)}
           </h3>
           {balance > 0 && <span className="text-[10px] text-emerald-400 flex items-center gap-1 mt-1"><CheckCircle size={10}/> Safe</span>}
           {balance < 0 && <span className="text-[10px] text-red-400 flex items-center gap-1 mt-1"><AlertTriangle size={10}/> Deficit</span>}
        </div>
      </div>

      {/* Categories */}
      <div className="space-y-4">
        <CategorySection 
          title="Kebutuhan Pokok" 
          items={data.needs.items} 
          color="blue" 
          onUpdateItems={(items) => onChange({ ...data, needs: { items } })}
        />
        <CategorySection 
          title="Tabungan / Investasi" 
          items={data.savings.items} 
          color="emerald" 
          onUpdateItems={(items) => onChange({ ...data, savings: { items } })}
        />
        <CategorySection 
          title="Hutang / Cicilan" 
          items={data.debt.items} 
          color="red" 
          onUpdateItems={(items) => onChange({ ...data, debt: { items } })}
        />
        <OthersCategory 
          allocation={data.others.allocation} 
          items={data.others.items}
          onUpdateAllocation={(val) => onChange({ ...data, others: { ...data.others, allocation: val } })}
          onUpdateItems={(items) => onChange({ ...data, others: { ...data.others, items } })}
        />
      </div>
    </div>
  );
};

export default Budget;

