import React, { useState } from 'react';
import { BudgetData, BudgetItem, OtherBudgetItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, AlertTriangle, CheckCircle, Info, Wallet, PieChart, TrendingDown } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  color: string;
  onUpdateItems: (items: BudgetItem[]) => void;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems
}) => {
  const [expanded, setExpanded] = useState(false);

  const catTotalAllocated = items.reduce((a, b) => a + b.budget, 0);
  const catTotalActual = items.reduce((a, b) => a + b.actual, 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;
  const unrealizedCount = items.filter(i => i.actual === 0).length;

  const addItem = () => {
    const newItem: BudgetItem = { id: Date.now().toString(), name: '', budget: 0, actual: 0 };
    onUpdateItems([...items, newItem]);
  };

  const updateItem = (id: string, field: keyof BudgetItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onUpdateItems(newItems);
  };

  const deleteItem = (id: string) => {
    const newItems = items.filter(item => item.id !== id);
    onUpdateItems(newItems);
  };

  const getBorderColor = () => {
    if (color === 'blue') return 'border-blue-500/20';
    if (color === 'emerald') return 'border-emerald-500/20';
    if (color === 'red') return 'border-red-500/20';
    return 'border-slate-700';
  };

  const getIconColor = () => {
      if (color === 'blue') return 'text-blue-400 bg-blue-500/10';
      if (color === 'emerald') return 'text-emerald-400 bg-emerald-500/10';
      if (color === 'red') return 'text-red-400 bg-red-500/10';
      return 'text-slate-400';
  };

  return (
    <div className={`glass-panel rounded-2xl ${getBorderColor()} overflow-hidden mb-5 transition-all duration-300 hover:shadow-lg hover:shadow-${color}-500/5`}>
      <div 
        className="p-5 flex justify-between items-center cursor-pointer hover:bg-white/5 transition-colors"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-center gap-4">
           <div className={`p-3 rounded-xl ${getIconColor()} backdrop-blur-md`}>
              {expanded ? <ChevronUp size={22} /> : <ChevronDown size={22} />}
           </div>
           <div>
             <h4 className="font-bold text-lg text-white tracking-tight">{title}</h4>
             <div className="text-xs text-slate-400 flex flex-col sm:flex-row sm:gap-3 mt-1 font-medium">
               <span>{items.length} Item</span>
               <span className="hidden sm:inline">•</span>
               <span>Anggaran: <span className="text-slate-300">{formatRupiah(catTotalAllocated)}</span></span>
               <span className="hidden sm:inline">•</span>
               <span>Realisasi: <span className="text-slate-300">{formatRupiah(catTotalActual)}</span></span>

               {unrealizedCount > 0 && (
                 <span className="text-amber-400 font-medium flex items-center gap-1 sm:ml-2 bg-amber-500/10 px-2 rounded-full">
                   <Info size={10} /> {unrealizedCount} belum direalisasi
                 </span>
               )}
             </div>
           </div>
        </div>
        <div className="text-right pl-4">
           <div className="text-xs text-slate-500 uppercase font-semibold">Sisa Dana</div>
           <div className={`text-lg font-bold ${isCatOver ? 'text-rose-400' : 'text-emerald-400'}`}>
             {formatRupiah(catRemaining)}
           </div>
           {isCatOver && <span className="text-[10px] text-rose-500 flex items-center justify-end gap-1 bg-rose-500/10 px-2 py-0.5 rounded mt-1"><AlertTriangle size={10}/> Overbudget</span>}
        </div>
      </div>

      {expanded && (
        <div className="p-5 bg-slate-900/30 border-t border-white/5 backdrop-blur-sm">
           {items.map((item) => (
             <div key={item.id} className="grid grid-cols-1 md:grid-cols-12 gap-4 mb-4 items-end p-4 bg-[#0f172a] rounded-xl border border-white/5 hover:border-white/10 transition-colors">
               <div className="md:col-span-4">
                 <label className="text-xs text-slate-400 uppercase font-semibold ml-1 mb-1 block">Item Name</label>
                 <input 
                   type="text" 
                   value={item.name} 
                   onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                   className="w-full bg-slate-800/80 rounded-xl p-3 text-white text-sm border border-slate-700/50 focus:border-blue-500/50 focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
                   placeholder="Nama pengeluaran..."
                 />
               </div>
               <div className="md:col-span-3">
                 <CurrencyInput 
                   label="Anggaran" 
                   value={item.budget} 
                   onChange={(v) => updateItem(item.id, 'budget', v)}
                   className="text-sm"
                 />
               </div>
               <div className="md:col-span-3">
                 <CurrencyInput 
                   label="Realisasi" 
                   value={item.actual} 
                   onChange={(v) => updateItem(item.id, 'actual', v)}
                   className="text-sm"
                 />
               </div>
               <div className="md:col-span-2 flex justify-end pb-1.5">
                 <button onClick={() => deleteItem(item.id)} className="p-3 text-rose-400 hover:bg-rose-500/10 rounded-xl transition-colors border border-transparent hover:border-rose-500/20">
                   <Trash2 size={18} />
                 </button>
               </div>
               {item.budget > 0 && item.actual === 0 && (
                  <div className="col-span-12 text-xs text-amber-500/80 flex items-center gap-1 mt-[-8px]">
                    <div className="w-1.5 h-1.5 rounded-full bg-amber-500"></div> Belum ada realisasi
                  </div>
               )}
             </div>
           ))}

           <button 
             onClick={addItem}
             className={`w-full py-3 border border-dashed border-${color}-500/30 text-${color}-400 rounded-xl hover:bg-${color}-500/5 hover:border-${color}-500/60 flex items-center justify-center gap-2 transition-all font-medium text-sm mt-2`}
           >
             <Plus size={16} /> Tambah Item {title}
           </button>
        </div>
      )}
    </div>
  );
};

