const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const calcTotalBudget = () => {
    const needs = data.needs.items.reduce((acc, item) => acc + item.budget, 0);
    const savings = data.savings.items.reduce((acc, item) => acc + item.budget, 0);
    const debt = data.debt.items.reduce((acc, item) => acc + item.budget, 0);
    const others = data.others.allocation;
    return needs + savings + debt + others;
  };

  const calcTotalActual = () => {
    const needs = data.needs.items.reduce((acc, item) => acc + item.actual, 0);
    const savings = data.savings.items.reduce((acc, item) => acc + item.actual, 0);
    const debt = data.debt.items.reduce((acc, item) => acc + item.actual, 0);
    const others = data.others.items.reduce((acc, item) => acc + item.actual, 0);
    return needs + savings + debt + others;
  };

  const totalAllocated = calcTotalBudget();
  const totalActual = calcTotalActual();
  const balance = income - totalActual;

  const isOverBudget = totalAllocated > income;
  const isOverSpent = totalActual > totalAllocated;

  return (
    <div className="space-y-8 animate-fadeIn">
      {/* Summary Widgets */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {/* Income Card */}
        <div className="glass-panel p-5 rounded-2xl relative overflow-hidden group hover:-translate-y-1 transition-transform duration-300">
           <div className="absolute right-0 top-0 p-3 opacity-5 group-hover:opacity-10 transition-opacity">
              <Wallet size={64} className="text-white" />
           </div>
           <p className="text-slate-400 text-xs font-semibold uppercase tracking-wider mb-1">Penghasilan (Net)</p>
           <h3 className="text-xl md:text-2xl font-bold text-white tracking-tight">{formatRupiah(income)}</h3>
        </div>

        {/* Budget Card */}
        <div className="glass-panel p-5 rounded-2xl relative overflow-hidden hover:-translate-y-1 transition-transform duration-300">
           <p className="text-slate-400 text-xs font-semibold uppercase tracking-wider mb-1">Total Anggaran</p>
           <h3 className={`text-xl md:text-2xl font-bold tracking-tight ${isOverBudget ? 'text-rose-400' : 'text-blue-400'}`}>
             {formatRupiah(totalAllocated)}
           </h3>
           <div className="w-full bg-slate-700/50 h-1.5 mt-3 rounded-full overflow-hidden">
              <div 
                className={`h-full rounded-full ${isOverBudget ? 'bg-rose-500' : 'bg-blue-500'}`} 
                style={{ width: `${Math.min((totalAllocated / income) * 100, 100)}%` }} 
              />
           </div>
           {isOverBudget && <span className="text-[10px] text-rose-400 absolute top-4 right-4 flex items-center gap-1 bg-rose-500/10 px-2 py-1 rounded-full"><AlertTriangle size={10}/> Over</span>}
        </div>

        {/* Realization Card */}
        <div className="glass-panel p-5 rounded-2xl relative overflow-hidden hover:-translate-y-1 transition-transform duration-300">
           <p className="text-slate-400 text-xs font-semibold uppercase tracking-wider mb-1">Total Realisasi</p>
           <h3 className={`text-xl md:text-2xl font-bold tracking-tight ${isOverSpent ? 'text-rose-400' : 'text-amber-400'}`}>
             {formatRupiah(totalActual)}
           </h3>
           <div className="w-full bg-slate-700/50 h-1.5 mt-3 rounded-full overflow-hidden">
              <div 
                className={`h-full rounded-full ${isOverSpent ? 'bg-rose-500' : 'bg-amber-500'}`} 
                style={{ width: `${Math.min((totalActual / totalAllocated) * 100, 100)}%` }} 
              />
           </div>
        </div>

        {/* Balance Card */}
        <div className={`glass-panel p-5 rounded-2xl border transition-all duration-300 hover:-translate-y-1 ${balance < 0 ? 'border-rose-500/40 bg-rose-900/10' : 'border-emerald-500/40 bg-emerald-900/10'}`}>
           <p className="text-slate-400 text-xs font-semibold uppercase tracking-wider mb-1">Sisa Saldo</p>
           <h3 className={`text-xl md:text-2xl font-bold tracking-tight ${balance < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>
             {formatRupiah(balance)}
           </h3>
           <div className="mt-3 flex items-center">
             {balance > 0 ? (
               <span className="text-[11px] text-emerald-300 bg-emerald-500/20 px-2 py-0.5 rounded-full flex items-center gap-1 font-medium"><CheckCircle size={10}/> Aman</span>
             ) : (
               <span className="text-[11px] text-rose-300 bg-rose-500/20 px-2 py-0.5 rounded-full flex items-center gap-1 font-medium"><AlertTriangle size={10}/> Defisit</span>
             )}
           </div>
        </div>
      </div>

      {/* Categories */}
      <div className="space-y-4">
        <CategorySection 
          title="Kebutuhan Pokok" 
          items={data.needs.items} 
          color="blue" 
          onUpdateItems={(items) => onChange({ ...data, needs: { items } })}
        />
        <CategorySection 
          title="Tabungan / Investasi" 
          items={data.savings.items} 
          color="emerald" 
          onUpdateItems={(items) => onChange({ ...data, savings: { items } })}
        />
        <CategorySection 
          title="Hutang / Cicilan" 
          items={data.debt.items} 
          color="red" 
          onUpdateItems={(items) => onChange({ ...data, debt: { items } })}
        />
        <OthersCategory 
          allocation={data.others.allocation} 
          items={data.others.items}
          onUpdateAllocation={(val) => onChange({ ...data, others: { ...data.others, allocation: val } })}
          onUpdateItems={(items) => onChange({ ...data, others: { ...data.others, items } })}
        />
      </div>
    </div>
  );
};

