  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Performance Bar Chart */}
      <div className="glass-panel p-6 rounded-2xl">
        <h3 className="text-lg font-bold text-white mb-6 border-l-4 border-emerald-500 pl-3">Kinerja Anggaran</h3>
        <div className="h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={barData} margin={{ top: 20, right: 30, left: 40, bottom: 5 }}>
              <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} />
              <YAxis 
                stroke="#64748b" 
                fontSize={12} 
                width={100}
                tickFormatter={(val) => formatRupiah(val)} 
                tickLine={false}
                axisLine={false}
              />
              <Tooltip content={<CustomTooltip />} cursor={{fill: 'rgba(255,255,255,0.05)'}} />
              <Legend wrapperStyle={{ paddingTop: '20px' }} />
              <Bar dataKey="Anggaran" fill="#3B82F6" radius={[6, 6, 0, 0]} maxBarSize={50} />
              <Bar dataKey="Aktual" fill="#10B981" radius={[6, 6, 0, 0]} maxBarSize={50} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Allocation Pie */}
        <div className="glass-panel p-6 rounded-2xl">
           <h3 className="text-lg font-bold text-white mb-6 border-l-4 border-blue-500 pl-3">Rencana Alokasi</h3>
           <div className="h-72">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieAllocData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={90}
                    dataKey="value"
                    labelLine={false}
                    paddingAngle={5}
                    stroke="none"
                  >
                    {pieAllocData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                  <Legend iconSize={10} layout="vertical" verticalAlign="middle" align="right"/>
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>

        {/* Realization Pie */}
        <div className="glass-panel p-6 rounded-2xl">
           <h3 className="text-lg font-bold text-white mb-6 border-l-4 border-amber-500 pl-3">Realisasi Pengeluaran</h3>
           <div className="h-72">
