            <div className="text-3xl font-bold text-rose-400 tracking-tight">{formatRupiah(totalExpense)}</div>
          </div>
          <div className="glass-panel p-6 rounded-2xl relative overflow-hidden">
             <div className="absolute top-0 right-0 w-24 h-24 bg-blue-500/10 rounded-full -mr-12 -mt-12 blur-xl"></div>
            <h4 className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-2">Net Profit {year}</h4>
            <div className={`text-3xl font-bold tracking-tight ${netProfit >= 0 ? 'text-blue-400' : 'text-rose-400'}`}>{formatRupiah(netProfit)}</div>
          </div>
       </div>

       {/* Trend Chart */}
       <div className="glass-panel p-6 rounded-2xl">
