                    >
                      {isActive && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-gradient-to-r from-emerald-500 to-cyan-500"></div>}
                      <Icon size={18} className={isActive ? 'text-emerald-400' : ''} />
                      {tab.label}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      </nav>

      {/* Content Area */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 pb-20">
        {activeTab === 'salary' && (
          <SalarySlip 
            data={currentData.salary} 
            onChange={(s) => updateCurrentData({ salary: s })} 
          />
        )}
        {activeTab === 'budget' && (
          <Budget 
            income={currentNetIncome} 
            data={currentData.budget} 
            onChange={(b) => updateCurrentData({ budget: b })} 
          />
        )}
        {activeTab === 'charts' && (
          <MonthlyCharts 
            budgetData={currentData.budget} 
            income={currentNetIncome} 
          />
        )}
        {activeTab === 'invest' && (
          <Investments 
            items={currentData.investments} 
            onChange={(i) => updateCurrentData({ investments: i })} 
          />
        )}
        {activeTab === 'year' && (
          <YearlySummary 
            appState={appState} 
            year={currentDate.getFullYear()} 
          />
        )}
      </main>

      {/* Copy Modal */}
      {showCopyModal && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="glass-panel p-8 rounded-3xl max-w-md w-full shadow-2xl animate-fadeIn border border-white/10">
              <h3 className="text-2xl font-bold text-white mb-2">Bulan Baru Terdeteksi</h3>
