                        flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs sm:text-sm font-semibold rounded-lg sm:rounded-xl whitespace-nowrap transition-all duration-200 relative overflow-hidden flex-1 justify-center sm:flex-none
                        ${isActive 
                          ? 'text-white bg-white/10 shadow-lg' 
                          : 'text-slate-400 hover:text-white hover:bg-white/5'}
                      `}
                    >
                      {isActive && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-gradient-to-r from-emerald-500 to-cyan-500"></div>}
                      <Icon size={16} className={isActive ? 'text-emerald-400' : ''} />
                      {tab.label}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      </nav>

      {/* Content Area */}
      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && (
          <SalarySlip 
            data={currentData.salary} 
            onChange={(s) => updateCurrentData({ salary: s })} 
          />
        )}
        {activeTab === 'budget' && (
          <Budget 
            income={currentNetIncome} 
            data={currentData.budget} 
            onChange={(b) => updateCurrentData({ budget: b })} 
          />
        )}
        {activeTab === 'charts' && (
          <MonthlyCharts 
            budgetData={currentData.budget} 
            income={currentNetIncome} 
          />
        )}
        {activeTab === 'invest' && (
          <Investments 
            items={currentData.investments} 
            onChange={(i) => updateCurrentData({ investments: i })} 
          />
        )}
        {activeTab === 'year' && (
          <YearlySummary 
            appState={appState} 
            year={currentDate.getFullYear()} 
          />
        )}
      </main>

      {/* Copy Modal */}
      {showCopyModal && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="glass-panel p-6 sm:p-8 rounded-3xl max-w-md w-full shadow-2xl animate-fadeIn border border-white/10">
              <h3 className="text-xl sm:text-2xl font-bold text-white mb-2">Bulan Baru</h3>
              <p className="text-slate-400 mb-8 leading-relaxed text-sm sm:text-base">Data bulan ini belum ada. Salin dari bulan lalu?</p>
              <div className="flex gap-4">
                <button 
                  onClick={() => initializeMonth(true)}
                  className="flex-1 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white py-3 rounded-xl font-bold transition-all shadow-lg text-sm sm:text-base"
                >
                  Salin Data
                </button>
                <button 
                  onClick={() => initializeMonth(false)}
                  className="flex-1 bg-slate-700/50 hover:bg-slate-700 text-white py-3 rounded-xl font-bold transition-colors border border-white/5 text-sm sm:text-base"
                >
                  Buat Baru
                </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

