import React, { useState } from 'react';
import { BudgetData, BudgetItem, OtherBudgetItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, AlertTriangle, CheckCircle, Info, Wallet } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  color: string;
  onUpdateItems: (items: BudgetItem[]) => void;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems
}) => {
  const [expanded, setExpanded] = useState(false);

  const catTotalAllocated = items.reduce((a, b) => a + b.budget, 0);
  const catTotalActual = items.reduce((a, b) => a + b.actual, 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;
  const unrealizedCount = items.filter(i => i.actual === 0).length;

  const addItem = () => {
    const newItem: BudgetItem = { id: Date.now().toString(), name: '', budget: 0, actual: 0 };
    onUpdateItems([...items, newItem]);
  };

  const updateItem = (id: string, field: keyof BudgetItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onUpdateItems(newItems);
  };

  const deleteItem = (id: string) => {
    const newItems = items.filter(item => item.id !== id);
    onUpdateItems(newItems);
  };

  const getBorderColor = () => {
    if (color === 'blue') return 'border-blue-500/20';
    if (color === 'emerald') return 'border-emerald-500/20';
    if (color === 'red') return 'border-red-500/20';
    return 'border-slate-700';
  };

  const getIconColor = () => {
      if (color === 'blue') return 'text-blue-400 bg-blue-500/10';
      if (color === 'emerald') return 'text-emerald-400 bg-emerald-500/10';
      if (color === 'red') return 'text-red-400 bg-red-500/10';
      return 'text-slate-400';
  };

  return (
    <div className={`glass-panel rounded-2xl ${getBorderColor()} overflow-hidden mb-4 sm:mb-5 transition-all duration-300 hover:shadow-lg hover:shadow-${color}-500/5`}>
      <div 
        className="p-4 sm:p-5 flex justify-between items-center cursor-pointer hover:bg-white/5 transition-colors"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-center gap-3 sm:gap-4">
           <div className={`p-2.5 sm:p-3 rounded-xl ${getIconColor()} backdrop-blur-md`}>
              {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
           </div>
           <div className="flex-1 min-w-0">
             <h4 className="font-bold text-base sm:text-lg text-white tracking-tight truncate">{title}</h4>
             <div className="text-xs text-slate-400 flex flex-col sm:flex-row sm:gap-3 mt-0.5 sm:mt-1 font-medium">
               <div className="flex items-center gap-2">
                 <span>{items.length} Item</span>
                 {unrealizedCount > 0 && (
                   <span className="text-amber-400 font-medium flex items-center gap-1 bg-amber-500/10 px-1.5 rounded-full text-[10px]">
                     <Info size={8} /> {unrealizedCount}
                   </span>
                 )}
               </div>
               <div className="hidden sm:block">
                  <span>Alloc: <span className="text-slate-300">{formatRupiah(catTotalAllocated)}</span></span>
                  <span className="mx-2">•</span>
                  <span>Act: <span className="text-slate-300">{formatRupiah(catTotalActual)}</span></span>
               </div>
             </div>
           </div>
        </div>
        <div className="text-right pl-2">
           <div className="text-[10px] sm:text-xs text-slate-500 uppercase font-semibold">Sisa</div>
           <div className={`text-base sm:text-lg font-bold ${isCatOver ? 'text-rose-400' : 'text-emerald-400'}`}>
             {formatRupiah(catRemaining)}
           </div>
           {isCatOver && <span className="text-[9px] sm:text-[10px] text-rose-500 flex items-center justify-end gap-1 bg-rose-500/10 px-2 py-0.5 rounded mt-1"><AlertTriangle size={8}/> Over</span>}
        </div>
      </div>

      {expanded && (
        <div className="p-3 sm:p-5 bg-slate-900/30 border-t border-white/5 backdrop-blur-sm">
           {items.map((item) => (
             <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 sm:gap-4 mb-3 items-end p-3 sm:p-4 bg-[#0f172a] rounded-xl border border-white/5 hover:border-white/10 transition-colors">
               {/* Name Input - Full width on mobile */}
               <div className="col-span-2 md:col-span-4">
                 <label className="text-[10px] sm:text-xs text-slate-400 uppercase font-semibold ml-1 mb-1 block">Item Name</label>
                 <input 
                   type="text" 
                   value={item.name} 
                   onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                   className="w-full bg-slate-800/80 rounded-xl p-2.5 sm:p-3 text-white text-sm border border-slate-700/50 focus:border-blue-500/50 focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
                   placeholder="Nama pengeluaran..."
                 />
               </div>

               {/* Budget & Actual - Side by side on mobile */}
               <div className="col-span-1 md:col-span-3">
                 <CurrencyInput 
                   label="Anggaran" 
                   value={item.budget} 
                   onChange={(v) => updateItem(item.id, 'budget', v)}
                   className="text-sm"
                 />
               </div>
               <div className="col-span-1 md:col-span-3">
                 <CurrencyInput 
                   label="Realisasi" 
                   value={item.actual} 
                   onChange={(v) => updateItem(item.id, 'actual', v)}
                   className="text-sm"
                 />
               </div>

               {/* Delete Button */}
               <div className="col-span-2 md:col-span-2 flex justify-end pb-0 sm:pb-1.5">
                 <button onClick={() => deleteItem(item.id)} className="w-full sm:w-auto p-2 sm:p-3 text-rose-400 hover:bg-rose-500/10 rounded-xl transition-colors border border-rose-500/10 hover:border-rose-500/20 flex items-center justify-center">
                   <Trash2 size={18} />
                   <span className="sm:hidden ml-2 text-sm font-medium">Hapus Item</span>
                 </button>
               </div>

               {/* Alert */}
               {item.budget > 0 && item.actual === 0 && (
                  <div className="col-span-2 md:col-span-12 text-xs text-amber-500/80 flex items-center gap-1 mt-1 sm:mt-[-8px]">
                    <div className="w-1.5 h-1.5 rounded-full bg-amber-500"></div> Belum ada realisasi
                  </div>
               )}
             </div>
           ))}

           <button 
             onClick={addItem}
             className={`w-full py-3 border border-dashed border-${color}-500/30 text-${color}-400 rounded-xl hover:bg-${color}-500/5 hover:border-${color}-500/60 flex items-center justify-center gap-2 transition-all font-medium text-sm mt-2`}
           >
             <Plus size={16} /> Tambah Item
           </button>
        </div>
      )}
    </div>
  );
};

