import { calculateGrossIncome, calculateTax, formatRupiah } from '../utils';
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';

interface YearlySummaryProps {
  appState: AppState;
  year: number;
}

const YearlySummary: React.FC<YearlySummaryProps> = ({ appState, year }) => {
  const summaryData = useMemo(() => {
    const months = Array.from({ length: 12 }, (_, i) => {
      const monthNum = i + 1;
      const monthKey = `${year}-${String(monthNum).padStart(2, '0')}`;
      const data = appState[monthKey];

      if (!data) {
        return {
          month: new Date(year, i).toLocaleString('id-ID', { month: 'short' }),
          income: 0,
          expense: 0,
          margin: 0,
          profit: 0
        };
      }

      // Calculate Income
      const { salary } = data;
      const otRupiah = ((salary.basicSalary + salary.housingAllowance) / 173) * salary.overtimeHours;
      const bonusRupiah = (salary.basicSalary + salary.housingAllowance) * salary.bonusMultiplier;
      const gross = calculateGrossIncome(
        salary.basicSalary, 
        salary.housingAllowance, 
        salary.shiftAllowance, 
        otRupiah, 
        bonusRupiah, 
        salary.thr, 
        salary.leavePay
      );
      const tax = calculateTax(gross, salary.taxRate);
      const netIncome = gross - tax - salary.otherDeductions;

      // Calculate Expense (Actuals)
      const { budget } = data;
      const expense = 
        budget.needs.items.reduce((a, b) => a + b.actual, 0) +
        budget.savings.items.reduce((a, b) => a + b.actual, 0) + 
        budget.debt.items.reduce((a, b) => a + b.actual, 0) +
        budget.others.items.reduce((a, b) => a + b.actual, 0);

      const profit = netIncome - expense;
      const margin = netIncome > 0 ? (profit / netIncome) * 100 : 0;

      return {
        month: new Date(year, i).toLocaleString('id-ID', { month: 'short' }),
        income: netIncome,
        expense: expense,
        margin: margin,
        profit: profit
      };
    });
    return months;
  }, [appState, year]);

  const totalIncome = summaryData.reduce((acc, curr) => acc + curr.income, 0);
  const totalExpense = summaryData.reduce((acc, curr) => acc + curr.expense, 0);
  const netProfit = totalIncome - totalExpense;

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white border border-slate-200 p-4 rounded-xl shadow-xl">
          <p className="font-bold text-slate-800 mb-2">{label} {year}</p>
          <div className="space-y-1">
             <p className="text-emerald-600 text-sm">Income: {formatRupiah(payload[0].value)}</p>
             <p className="text-rose-500 text-sm">Expense: {formatRupiah(payload[1].value)}</p>
             <div className="border-t border-slate-100 pt-1 mt-1">
                <p className="text-indigo-600 text-sm font-bold">Profit: {formatRupiah(payload[0].value - payload[1].value)}</p>
             </div>
          </div>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 animate-fadeIn">
       {/* Cards */}
       <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="glass-panel p-6 rounded-2xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-500/10 rounded-full -mr-12 -mt-12 blur-xl"></div>
            <h4 className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-2">Total Pendapatan {year}</h4>
            <div className="text-3xl font-bold text-slate-800 tracking-tight">{formatRupiah(totalIncome)}</div>
          </div>
          <div className="glass-panel p-6 rounded-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-24 h-24 bg-rose-500/10 rounded-full -mr-12 -mt-12 blur-xl"></div>
            <h4 className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-2">Total Pengeluaran {year}</h4>
            <div className="text-3xl font-bold text-rose-500 tracking-tight">{formatRupiah(totalExpense)}</div>
          </div>
          <div className="glass-panel p-6 rounded-2xl relative overflow-hidden">
             <div className="absolute top-0 right-0 w-24 h-24 bg-indigo-500/10 rounded-full -mr-12 -mt-12 blur-xl"></div>
            <h4 className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-2">Net Profit {year}</h4>
            <div className={`text-3xl font-bold tracking-tight ${netProfit >= 0 ? 'text-indigo-600' : 'text-rose-500'}`}>{formatRupiah(netProfit)}</div>
          </div>
       </div>

       {/* Trend Chart */}
       <div className="glass-panel p-6 rounded-2xl">
         <h3 className="text-lg font-bold text-slate-800 mb-6">Trend Keuangan</h3>
         <div className="h-80 w-full">
           <ResponsiveContainer width="100%" height="100%">
             <AreaChart data={summaryData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorIncome" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10B981" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#10B981" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorExpense" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#F43F5E" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#F43F5E" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <XAxis dataKey="month" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis stroke="#94a3b8" fontSize={12} tickFormatter={(val) => `${val/1000000}M`} tickLine={false} axisLine={false} />
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
                <Tooltip content={<CustomTooltip />} />
                <Area type="monotone" dataKey="income" stroke="#10B981" strokeWidth={3} fillOpacity={1} fill="url(#colorIncome)" />
                <Area type="monotone" dataKey="expense" stroke="#F43F5E" strokeWidth={3} fillOpacity={1} fill="url(#colorExpense)" />
             </AreaChart>
           </ResponsiveContainer>
         </div>
       </div>

       {/* Table */}
       <div className="glass-panel rounded-2xl overflow-hidden">
         <div className="p-6 border-b border-slate-100 bg-slate-50/50">
            <h3 className="text-lg font-bold text-slate-800">Ringkasan Detail</h3>
         </div>
         <div className="overflow-x-auto">
           <table className="w-full text-left text-sm text-slate-600">
             <thead className="bg-slate-50 text-slate-500 uppercase text-xs font-bold tracking-wider">
               <tr>
                 <th className="px-6 py-4">Bulan</th>
                 <th className="px-6 py-4 text-right">Pendapatan</th>
                 <th className="px-6 py-4 text-right">Pengeluaran</th>
                 <th className="px-6 py-4 text-right">Margin</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {summaryData.map((row) => (
                 <tr key={row.month} className="hover:bg-slate-50 transition-colors group">
                   <td className="px-6 py-4 font-medium text-slate-800 group-hover:text-indigo-600 transition-colors">{row.month}</td>
                   <td className="px-6 py-4 text-right text-emerald-600 font-mono">{formatRupiah(row.income)}</td>
                   <td className="px-6 py-4 text-right text-rose-500 font-mono">{formatRupiah(row.expense)}</td>
                   <td className="px-6 py-4 text-right">
                      <span className={`px-2.5 py-1 rounded-full text-xs font-bold ${row.margin > 20 ? 'bg-emerald-100 text-emerald-700 border border-emerald-200' : row.margin > 0 ? 'bg-amber-100 text-amber-700 border border-amber-200' : 'bg-rose-100 text-rose-700 border border-rose-200'}`}>
                        {row.margin.toFixed(1)}%
                      </span>
                   </td>
                 </tr>
               ))}
             </tbody>
           </table>
         </div>
       </div>
    </div>
  );
};

export default YearlySummary;

import React, { useState, useEffect } from 'react';
import { AppState, MonthlyData, DEFAULT_SALARY, DEFAULT_BUDGET } from './types';
import SalarySlip from './components/SalarySlip';
import Budget from './components/Budget';
import MonthlyCharts from './components/MonthlyCharts';
import Investments from './components/Investments';
import YearlySummary from './components/YearlySummary';
import { calculateGrossIncome, calculateTax, calculateOvertime, calculateBonus } from './utils';
import { Wallet, LayoutDashboard, PieChart, TrendingUp, Calendar, ChevronLeft, ChevronRight, Save } from 'lucide-react';

const TABS = [
  { id: 'salary', label: 'Gaji', icon: Wallet },
  { id: 'budget', label: 'Anggaran', icon: LayoutDashboard },
  { id: 'charts', label: 'Grafik', icon: PieChart },
  { id: 'invest', label: 'Aset', icon: TrendingUp },
  { id: 'year', label: 'Tahunan', icon: Calendar },
];

const App: React.FC = () => {
  // State
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('finance_app_data');
    return saved ? JSON.parse(saved) : {};
  });
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  // Derived State
  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;
  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  // Helper: Income Calculation for passing to props
  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     const tax = calculateTax(gross, salary.taxRate);
     return gross - tax - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  // Persist
  useEffect(() => {
    localStorage.setItem('finance_app_data', JSON.stringify(appState));
  }, [appState]);

  // Month Change Logic
  useEffect(() => {
    if (!appState[currentMonthKey]) {
      // Check if previous month exists
      const prevDate = new Date(currentDate);
      prevDate.setMonth(currentDate.getMonth() - 1);
      const pKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;

      if (appState[pKey]) {
        setPrevMonthKey(pKey);
        setShowCopyModal(true);
      } else {
        // Initialize default if no prev month
        initializeMonth(false);
      }
    }
  }, [currentMonthKey]);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      const prev = appState[prevMonthKey];
      newData = JSON.parse(JSON.stringify(prev));
      // Reset Actuals for budget items
      newData.budget.needs.items.forEach(i => i.actual = 0);
      newData.budget.savings.items.forEach(i => i.actual = 0);
      newData.budget.debt.items.forEach(i => i.actual = 0);
      newData.budget.others.items.forEach(i => i.actual = 0);

      // Reset fluctuating salary inputs?
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = {
        salary: { ...DEFAULT_SALARY },
        budget: { ...DEFAULT_BUDGET },
        investments: []
      };
    }

    setAppState(prev => ({
      ...prev,
      [currentMonthKey]: newData
    }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => ({
      ...prev,
      [currentMonthKey]: { ...currentData, ...newData }
    }));
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  return (
    <div className="min-h-screen font-sans selection:bg-indigo-500/30 selection:text-indigo-800">
      {/* Navbar - Floating Glass */}
      <nav className="sticky top-0 z-50 pt-2 px-2 sm:pt-4 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl bg-white/80">
          <div className="flex flex-col sm:flex-row items-center justify-between p-3 sm:px-6 sm:h-20 gap-3">
            {/* Header Top (Mobile: Row with Logo & Month) */}
            <div className="flex items-center justify-between w-full sm:w-auto">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-lg shadow-lg shadow-indigo-200">
                     <Wallet className="text-white h-5 w-5 sm:h-6 sm:w-6" />
                  </div>
                  <div>
                    <h1 className="text-sm sm:text-xl font-bold tracking-tight text-slate-800 leading-tight">ANIQ SUSILO</h1>
                    <p className="text-[9px] sm:text-[10px] text-indigo-500 font-bold tracking-[0.2em] uppercase">Premium Finance</p>
                  </div>
                </div>

                {/* Mobile Month Navigator (Visible only on mobile inside this flex) */}
                <div className="flex sm:hidden items-center bg-slate-100 rounded-lg p-1 border border-slate-200">
                   <button onClick={() => changeMonth(-1)} className="p-1.5 hover:bg-slate-200 rounded-md transition-colors text-slate-500">
                     <ChevronLeft size={16} />
                   </button>
                   <div className="px-2 font-mono font-bold text-indigo-600 text-xs text-center min-w-[80px]">
                     {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' })}
                   </div>
                   <button onClick={() => changeMonth(1)} className="p-1.5 hover:bg-slate-200 rounded-md transition-colors text-slate-500">
                     <ChevronRight size={16} />
                   </button>
                </div>
            </div>

            {/* Desktop Month Navigator (Hidden on Mobile) */}
            <div className="hidden sm:flex items-center bg-slate-50 rounded-xl p-1.5 border border-slate-200 shadow-sm">
               <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-white rounded-lg transition-colors text-slate-400 hover:text-indigo-600 hover:shadow-sm">
                 <ChevronLeft size={20} />
               </button>
               <div className="px-3 sm:px-6 font-mono font-bold text-indigo-600 w-32 sm:w-40 text-center text-sm sm:text-base">
                 {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' })}
               </div>
               <button onClick={() => changeMonth(1)} className="p-2 hover:bg-white rounded-lg transition-colors text-slate-400 hover:text-indigo-600 hover:shadow-sm">
                 <ChevronRight size={20} />
               </button>
            </div>
          </div>

          {/* Tab Navigation */}
          <div className="border-t border-slate-100">
            <div className="px-2 overflow-x-auto scrollbar-hide">
              <div className="flex space-x-1 py-1.5 sm:py-2">
                {TABS.map((tab) => {
                  const Icon = tab.icon;
                  const isActive = activeTab === tab.id;
                  return (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id)}
                      className={`
                        flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs sm:text-sm font-semibold rounded-lg sm:rounded-xl whitespace-nowrap transition-all duration-200 relative overflow-hidden flex-1 justify-center sm:flex-none
                        ${isActive 
                          ? 'text-white bg-indigo-600 shadow-lg shadow-indigo-200' 
                          : 'text-slate-500 hover:text-indigo-600 hover:bg-slate-50'}
                      `}
                    >
                      <Icon size={16} className={isActive ? 'text-white' : ''} />
                      {tab.label}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      </nav>

      {/* Content Area */}
      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && (
          <SalarySlip 
            data={currentData.salary} 
            onChange={(s) => updateCurrentData({ salary: s })} 
          />
        )}
        {activeTab === 'budget' && (
          <Budget 
            income={currentNetIncome} 
            data={currentData.budget} 
            onChange={(b) => updateCurrentData({ budget: b })} 
          />
        )}
        {activeTab === 'charts' && (
          <MonthlyCharts 
            budgetData={currentData.budget} 
            income={currentNetIncome} 
          />
        )}
        {activeTab === 'invest' && (
          <Investments 
            items={currentData.investments} 
            onChange={(i) => updateCurrentData({ investments: i })} 
          />
        )}
        {activeTab === 'year' && (
          <YearlySummary 
            appState={appState} 
            year={currentDate.getFullYear()} 
          />
        )}
      </main>

      {/* Copy Modal */}
      {showCopyModal && (
        <div className="fixed inset-0 bg-slate-900/40 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="bg-white p-6 sm:p-8 rounded-3xl max-w-md w-full shadow-2xl animate-fadeIn border border-slate-200">
              <h3 className="text-xl sm:text-2xl font-bold text-slate-800 mb-2">Bulan Baru</h3>
              <p className="text-slate-500 mb-8 leading-relaxed text-sm sm:text-base">Data bulan ini belum ada. Salin dari bulan lalu?</p>
              <div className="flex gap-4">
                <button 
                  onClick={() => initializeMonth(true)}
                  className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white py-3 rounded-xl font-bold transition-all shadow-lg shadow-indigo-200 text-sm sm:text-base"
                >
                  Salin Data
                </button>
                <button 
                  onClick={() => initializeMonth(false)}
                  className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-700 py-3 rounded-xl font-bold transition-colors border border-slate-200 text-sm sm:text-base"
                >
                  Buat Baru
                </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

