           </div>
        </div>

        {/* Progress Percentage Badge */}
        <div className="pl-2">
           <div className={`text-xs font-bold px-2 py-1 rounded-lg ${isCatOver ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>
              {allocation > 0 ? ((catTotalActual / allocation) * 100).toFixed(0) : 0}%
