const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const calcTotalBudget = () => {
    const needs = data.needs.items.reduce((acc, item) => acc + item.budget, 0);
    const savings = data.savings.items.reduce((acc, item) => acc + item.budget, 0);
    const debt = data.debt.items.reduce((acc, item) => acc + item.budget, 0);
    const others = data.others.allocation;
    return needs + savings + debt + others;
  };

  const calcTotalActual = () => {
    const needs = data.needs.items.reduce((acc, item) => acc + item.actual, 0);
    const savings = data.savings.items.reduce((acc, item) => acc + item.actual, 0);
    const debt = data.debt.items.reduce((acc, item) => acc + item.actual, 0);
    const others = data.others.items.reduce((acc, item) => acc + item.actual, 0);
    return needs + savings + debt + others;
  };

  const totalAllocated = calcTotalBudget();
  const totalActual = calcTotalActual();
  const balance = income - totalActual;

  const isOverBudget = totalAllocated > income;
  const isOverSpent = totalActual > totalAllocated;

  return (
    <div className="space-y-6 sm:space-y-8 animate-fadeIn">
      {/* Summary Widgets */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {/* Income Card */}
        <div className="glass-panel p-4 sm:p-5 rounded-2xl relative overflow-hidden group hover:-translate-y-1 transition-transform duration-300">
           <div className="absolute right-0 top-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity">
              <Wallet size={64} className="text-indigo-600" />
           </div>
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Penghasilan (Net)</p>
           <h3 className="text-xl md:text-2xl font-bold text-slate-800 tracking-tight">{formatRupiah(income)}</h3>
        </div>

        {/* Budget Card */}
        <div className="glass-panel p-4 sm:p-5 rounded-2xl relative overflow-hidden hover:-translate-y-1 transition-transform duration-300">
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Total Anggaran</p>
           <h3 className={`text-xl md:text-2xl font-bold tracking-tight ${isOverBudget ? 'text-rose-500' : 'text-blue-600'}`}>
             {formatRupiah(totalAllocated)}
           </h3>
           <div className="w-full bg-slate-100 h-1.5 mt-2 sm:mt-3 rounded-full overflow-hidden">
              <div 
                className={`h-full rounded-full ${isOverBudget ? 'bg-rose-500' : 'bg-blue-500'}`} 
                style={{ width: `${Math.min((totalAllocated / income) * 100, 100)}%` }} 
              />
           </div>
           {isOverBudget && <span className="text-[10px] text-rose-500 absolute top-4 right-4 flex items-center gap-1 bg-rose-50 px-2 py-1 rounded-full border border-rose-100"><AlertTriangle size={10}/> Over</span>}
        </div>

        {/* Realization Card */}
        <div className="glass-panel p-4 sm:p-5 rounded-2xl relative overflow-hidden hover:-translate-y-1 transition-transform duration-300">
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Total Realisasi</p>
           <h3 className={`text-xl md:text-2xl font-bold tracking-tight ${isOverSpent ? 'text-rose-500' : 'text-amber-500'}`}>
             {formatRupiah(totalActual)}
           </h3>
           <div className="w-full bg-slate-100 h-1.5 mt-2 sm:mt-3 rounded-full overflow-hidden">
              <div 
                className={`h-full rounded-full ${isOverSpent ? 'bg-rose-500' : 'bg-amber-500'}`} 
                style={{ width: `${Math.min((totalActual / totalAllocated) * 100, 100)}%` }} 
              />
           </div>
        </div>

        {/* Balance Card */}
        <div className={`glass-panel p-4 sm:p-5 rounded-2xl border transition-all duration-300 hover:-translate-y-1 ${balance < 0 ? 'border-rose-200 bg-rose-50' : 'border-emerald-200 bg-emerald-50'}`}>
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Sisa Saldo</p>
           <h3 className={`text-xl md:text-2xl font-bold tracking-tight ${balance < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
             {formatRupiah(balance)}
           </h3>
           <div className="mt-2 sm:mt-3 flex items-center">
             {balance > 0 ? (
               <span className="text-[10px] sm:text-[11px] text-emerald-700 bg-emerald-100 px-2 py-0.5 rounded-full flex items-center gap-1 font-medium"><CheckCircle size={10}/> Aman</span>
             ) : (
               <span className="text-[10px] sm:text-[11px] text-rose-700 bg-rose-100 px-2 py-0.5 rounded-full flex items-center gap-1 font-medium"><AlertTriangle size={10}/> Defisit</span>
             )}
           </div>
        </div>
      </div>

      {/* Categories */}
      <div className="space-y-4">
        <CategorySection 
          title="Kebutuhan Pokok" 
          items={data.needs.items} 
          color="blue" 
          onUpdateItems={(items) => onChange({ ...data, needs: { items } })}
        />
        <CategorySection 
          title="Tabungan / Investasi" 
          items={data.savings.items} 
          color="emerald" 
          onUpdateItems={(items) => onChange({ ...data, savings: { items } })}
        />
        <CategorySection 
          title="Hutang / Cicilan" 
          items={data.debt.items} 
          color="red" 
          onUpdateItems={(items) => onChange({ ...data, debt: { items } })}
        />
        <OthersCategory 
          allocation={data.others.allocation} 
          items={data.others.items}
          onUpdateAllocation={(val) => onChange({ ...data, others: { ...data.others, allocation: val } })}
          onUpdateItems={(items) => onChange({ ...data, others: { ...data.others, items } })}
        />
      </div>
    </div>
  );
};

export default Budget;

import React from 'react';
import { BudgetData } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { formatRupiah } from '../utils';

interface MonthlyChartsProps {
  budgetData: BudgetData;
  income: number;
}

const MonthlyCharts: React.FC<MonthlyChartsProps> = ({ budgetData, income }) => {
  // Aggregate data
  const needsAlloc = budgetData.needs.items.reduce((a, b) => a + b.budget, 0);
  const needsActual = budgetData.needs.items.reduce((a, b) => a + b.actual, 0);

  const savingsAlloc = budgetData.savings.items.reduce((a, b) => a + b.budget, 0);
  const savingsActual = budgetData.savings.items.reduce((a, b) => a + b.actual, 0);

  const debtAlloc = budgetData.debt.items.reduce((a, b) => a + b.budget, 0);
  const debtActual = budgetData.debt.items.reduce((a, b) => a + b.actual, 0);

  const othersAlloc = budgetData.others.allocation;
  const othersActual = budgetData.others.items.reduce((a, b) => a + b.actual, 0);

  const totalAllocated = needsAlloc + savingsAlloc + debtAlloc + othersAlloc;
  const totalActual = needsActual + savingsActual + debtActual + othersActual;

  const barData = [
    { name: 'Total', Anggaran: totalAllocated, Aktual: totalActual },
    { name: 'Pokok', Anggaran: needsAlloc, Aktual: needsActual },
    { name: 'Tabungan', Anggaran: savingsAlloc, Aktual: savingsActual },
    { name: 'Cicilan', Anggaran: debtAlloc, Aktual: debtActual },
    { name: 'Lainnya', Anggaran: othersAlloc, Aktual: othersActual },
  ];

  const pieAllocData = [
    { name: 'Pokok', value: needsAlloc },
    { name: 'Tabungan', value: savingsAlloc },
    { name: 'Cicilan', value: debtAlloc },
    { name: 'Lainnya', value: othersAlloc },
  ].filter(d => d.value > 0);

  const pieActualData = [
    { name: 'Pokok', value: needsActual },
    { name: 'Tabungan', value: savingsActual },
    { name: 'Cicilan', value: debtActual },
    { name: 'Lainnya', value: othersActual },
  ].filter(d => d.value > 0);

  // Vibrant Palette from Reference Image
  // Blue, Green, Orange, Purple
  const COLORS = ['#3B82F6', '#10B981', '#F97316', '#8B5CF6'];

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white border border-slate-200 p-3 sm:p-4 rounded-xl shadow-lg">
          <p className="font-bold text-slate-800 mb-2 border-b border-slate-100 pb-2 text-xs sm:text-sm">{label}</p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center gap-2 mb-1">
              <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }}></div>
              <span className="text-slate-500 text-[10px] sm:text-xs">{entry.name}:</span>
              <span className="text-slate-800 font-mono text-[10px] sm:text-xs font-bold">{formatRupiah(entry.value)}</span>
              <span className="text-slate-400 text-[10px] ml-1">
                ({(entry.value / (entry.payload.payload?.total || (entry.dataKey === 'value' ? payload.reduce((a:any,b:any)=>a+b.value,0) : 1)) * 100).toFixed(0)}%)
              </span>
            </div>
          ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Performance Bar Chart */}
      <div className="glass-panel p-4 sm:p-6 rounded-2xl">
        <h3 className="text-base sm:text-lg font-bold text-slate-800 mb-6 border-l-4 border-indigo-500 pl-3">Kinerja Anggaran</h3>
        <div className="h-64 sm:h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={barData} margin={{ top: 20, right: 10, left: 0, bottom: 5 }}>
              <XAxis dataKey="name" stroke="#94a3b8" fontSize={10} tickLine={false} axisLine={false} />
              <YAxis 
                stroke="#94a3b8" 
                fontSize={10} 
                width={80}
                tickFormatter={(val) => formatRupiah(val)} 
                tickLine={false}
                axisLine={false}
              />
              <Tooltip content={<CustomTooltip />} cursor={{fill: 'rgba(0,0,0,0.05)'}} />
              <Legend wrapperStyle={{ paddingTop: '20px', fontSize: '12px', color: '#475569' }} />
              <Bar dataKey="Anggaran" fill="#3B82F6" radius={[4, 4, 0, 0]} maxBarSize={40} />
              <Bar dataKey="Aktual" fill="#10B981" radius={[4, 4, 0, 0]} maxBarSize={40} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Allocation Pie */}
        <div className="glass-panel p-4 sm:p-6 rounded-2xl">
           <h3 className="text-base sm:text-lg font-bold text-slate-800 mb-6 border-l-4 border-blue-500 pl-3">Rencana Alokasi</h3>
           <div className="h-56 sm:h-72">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieAllocData}
                    cx="50%"
                    cy="50%"
                    innerRadius={50}
                    outerRadius={80}
                    dataKey="value"
                    labelLine={true}
                    label={({ percent }) => `${(percent * 100).toFixed(0)}%`}
                    paddingAngle={5}
                    stroke="none"
                  >
                    {pieAllocData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                  <Legend iconSize={10} layout="vertical" verticalAlign="middle" align="right" wrapperStyle={{ fontSize: '10px', color: '#475569' }}/>
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>

        {/* Realization Pie */}
        <div className="glass-panel p-4 sm:p-6 rounded-2xl">
           <h3 className="text-base sm:text-lg font-bold text-slate-800 mb-6 border-l-4 border-orange-500 pl-3">Realisasi Pengeluaran</h3>
           <div className="h-56 sm:h-72">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieActualData}
                    cx="50%"
                    cy="50%"
                    innerRadius={50}
                    outerRadius={80}
                    dataKey="value"
                    labelLine={true}
                    label={({ percent }) => `${(percent * 100).toFixed(0)}%`}
                    paddingAngle={5}
                    stroke="none"
                  >
                    {pieActualData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                  <Legend iconSize={10} layout="vertical" verticalAlign="middle" align="right" wrapperStyle={{ fontSize: '10px', color: '#475569' }}/>
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>
      </div>
    </div>
  );
};

