                    {totalItems} TOTAL
                 </span>

                 {isCatOver && (
                    <span className="animate-pulse flex items-center gap-1 bg-rose-500 text-white text-[10px] font-bold px-2 py-1 rounded-md">
                      <Bell size={10} /> OVER BUDGET
