                <div className="flex items-center gap-1">
                    <span>Alokasi:</span>
                    <span className="text-slate-700">{formatRupiah(catTotalAllocated)}</span>
                </div>
                <div className="flex items-center gap-1">
                    <span>Realisasi:</span>
                    <span className={`text-slate-700 ${isCatOver ? 'text-rose-500' : ''}`}>{formatRupiah(catTotalActual)}</span>
                </div>
                <div className="flex items-center gap-1">
