import React, { useState } from 'react';
import { BudgetData, BudgetItem, OtherBudgetItem, CustomBudgetCategory } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, AlertTriangle, CheckCircle, Info, Wallet, Bell, FolderPlus } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  color: string;
  onUpdateItems: (items: BudgetItem[]) => void;
  onDeleteCategory?: () => void;
  isCustom?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems,
  onDeleteCategory,
  isCustom = false
}) => {
  const [expanded, setExpanded] = useState(false);

  const catTotalAllocated = items.reduce((a, b) => a + b.budget, 0);
  const catTotalActual = items.reduce((a, b) => a + b.actual, 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;
  const totalItemsCount = items.length;

  const addItem = () => {
    const newItem: BudgetItem = { id: Date.now().toString(), name: '', budget: 0, actual: 0 };
    onUpdateItems([...items, newItem]);
  };

  const updateItem = (id: string, field: keyof BudgetItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onUpdateItems(newItems);
  };

  const deleteItem = (id: string) => {
    const newItems = items.filter(item => item.id !== id);
    onUpdateItems(newItems);
  };

  const getIconColor = () => {
      if (color === 'blue') return 'text-blue-600 bg-blue-50';
      if (color === 'emerald') return 'text-emerald-600 bg-emerald-50';
      if (color === 'red') return 'text-red-600 bg-red-50';
      if (color === 'purple') return 'text-purple-600 bg-purple-50';
      return 'text-slate-600';
  };

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden mb-4 sm:mb-5 transition-all duration-300 hover:shadow-lg ${isCatOver ? 'ring-2 ring-rose-500/20' : ''}`}>
      <div 
        className="p-4 sm:p-5 flex justify-between items-start sm:items-center cursor-pointer hover:bg-slate-50/50 transition-colors gap-2"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-start gap-3 sm:gap-4 flex-1">
           <div className={`p-2.5 sm:p-3 rounded-xl mt-0.5 sm:mt-0 ${getIconColor()}`}>
              {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
           </div>
           <div className="flex-1 min-w-0">
             <div className="flex items-center flex-wrap gap-2">
                 <h4 className="font-bold text-base sm:text-lg text-slate-800 tracking-tight truncate uppercase">{title}</h4>

                 <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded border border-slate-200 uppercase">
                    {totalItemsCount} TOTAL
                 </span>

                 {isCatOver && (
                    <span className="animate-pulse flex items-center gap-1 bg-rose-500 text-white text-[10px] font-bold px-2 py-0.5 rounded">
                      <Bell size={10} /> OVER BUDGET
                    </span>
                 )}

                 {isCustom && (
