  { id: 'invest', label: 'Aset', icon: TrendingUp },
  { id: 'year', label: 'Tahunan', icon: Calendar },
];

const App: React.FC = () => {
  // State
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');

  // App State is initially empty until loaded from DB
  const [appState, setAppState] = useState<AppState>({});

  // UI States
  const [isLoading, setIsLoading] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  // Derived State
  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  // --- DATABASE LOGIC START ---

  // 1. Load Data on Mount
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase
          .from('monthly_finance')
          .select('month_id, data');

        if (error) throw error;

        if (data) {
          const loadedState: AppState = {};
          data.forEach((row: any) => {
            loadedState[row.month_id] = row.data;
          });
          setAppState(loadedState);
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  // 2. Debounced Save Logic
  useEffect(() => {
    if (isLoading) return;
    if (!appState[currentMonthKey]) return;

    const saveData = async () => {
      setSaveStatus('saving');
      try {
        const { error } = await supabase
          .from('monthly_finance')
          .upsert({ 
            month_id: currentMonthKey, 
            data: appState[currentMonthKey],
            updated_at: new Date().toISOString()
          });

        if (error) throw error;
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } catch (err) {
        console.error("Error saving data:", err);
        setSaveStatus('error');
      }
    };

    const timeoutId = setTimeout(saveData, 1500);
    return () => clearTimeout(timeoutId);

  }, [appState, currentMonthKey, isLoading]);

  // Helper: Income Calculation
  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     const tax = calculateTax(gross, salary.taxRate);
     return gross - tax - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  // Month Change & Initialization Logic
  useEffect(() => {
    if (!isLoading && !appState[currentMonthKey]) {
      const prevDate = new Date(currentDate);
      prevDate.setMonth(currentDate.getMonth() - 1);
      const pKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;

      if (appState[pKey]) {
        setPrevMonthKey(pKey);
        setShowCopyModal(true);
      } else {
        initializeMonth(false);
      }
    }
  }, [currentMonthKey, isLoading]);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      const prev = appState[prevMonthKey];
      newData = JSON.parse(JSON.stringify(prev));
      newData.budget.needs.items.forEach(i => i.actual = 0);
      newData.budget.savings.items.forEach(i => i.actual = 0);
      newData.budget.debt.items.forEach(i => i.actual = 0);
      newData.budget.others.items.forEach(i => i.actual = 0);
      if (newData.budget.custom) {
        newData.budget.custom.forEach(cat => cat.items.forEach(i => i.actual = 0));
      }
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = {
        salary: { ...DEFAULT_SALARY },
        budget: { ...DEFAULT_BUDGET },
        investments: []
      };
    }

    setAppState(prev => ({
      ...prev,
      [currentMonthKey]: newData
    }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => {
      const existing = prev[currentMonthKey] || {
        salary: { ...DEFAULT_SALARY },
        budget: { ...DEFAULT_BUDGET },
        investments: []
      };
      return {
        ...prev,
        [currentMonthKey]: { ...existing, ...newData }
      };
    });
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F8FAFC]">
        <div className="flex flex-col items-center gap-3">
          <Loader2 className="w-10 h-10 text-indigo-600 animate-spin" />
          <p className="text-slate-500 font-medium animate-pulse">Menghubungkan Database...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen font-sans selection:bg-indigo-500/30 selection:text-indigo-800">
      <nav className="sticky top-0 z-50 pt-2 px-2 sm:pt-4 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl bg-white/80">
          <div className="flex flex-col sm:flex-row items-center justify-between p-3 sm:px-6 sm:h-20 gap-3">
            <div className="flex items-center justify-between w-full sm:w-auto">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-lg shadow-lg shadow-indigo-200">
                     <Wallet className="text-white h-5 w-5 sm:h-6 sm:w-6" />
                  </div>
                  <div>
                    <h1 className="text-sm sm:text-xl font-bold tracking-tight text-slate-800 leading-tight">ANIQ SUSILO</h1>
                    <p className="text-[9px] sm:text-[10px] text-indigo-500 font-bold tracking-[0.2em] uppercase">Monthly Finance</p>
                  </div>
                </div>

                <div className="flex sm:hidden items-center bg-slate-100 rounded-lg p-1 border border-slate-200">
                   <button onClick={() => changeMonth(-1)} className="p-1.5 hover:bg-slate-200 rounded-md transition-colors text-slate-500">
                     <ChevronLeft size={16} />
                   </button>
                   <div className="px-2 font-mono font-bold text-indigo-600 text-xs text-center min-w-[80px]">
                     {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' })}
                   </div>
                   <button onClick={() => changeMonth(1)} className="p-1.5 hover:bg-slate-200 rounded-md transition-colors text-slate-500">
                     <ChevronRight size={16} />
                   </button>
                </div>
            </div>

            <div className="flex items-center gap-4">
                <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100">
                  {saveStatus === 'saving' && (
                    <>
                      <Loader2 size={14} className="animate-spin text-indigo-500" />
                      <span className="text-xs text-slate-500 font-medium">Menyimpan...</span>
                    </>
                  )}
                  {saveStatus === 'saved' && (
                    <>
                      <CheckCircle2 size={14} className="text-emerald-500" />
                      <span className="text-xs text-emerald-600 font-medium">Tersimpan</span>
                    </>
                  )}
                  {saveStatus === 'error' && (
                    <span className="text-xs text-rose-500 font-medium">Gagal Simpan</span>
                  )}
                  {saveStatus === 'idle' && (
                     <span className="text-xs text-slate-400 font-medium flex items-center gap-1"><Cloud size={12}/> Online</span>
                  )}
                </div>

                <div className="hidden sm:flex items-center bg-slate-50 rounded-xl p-1.5 border border-slate-200 shadow-sm">
                  <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-white rounded-lg transition-colors text-slate-400 hover:text-indigo-600 hover:shadow-sm">
                    <ChevronLeft size={20} />
                  </button>
                  <div className="px-3 sm:px-6 font-mono font-bold text-indigo-600 w-32 sm:w-40 text-center text-sm sm:text-base">
                    {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' })}
                  </div>
                  <button onClick={() => changeMonth(1)} className="p-2 hover:bg-white rounded-lg transition-colors text-slate-400 hover:text-indigo-600 hover:shadow-sm">
                    <ChevronRight size={20} />
                  </button>
                </div>
            </div>
          </div>

          <div className="border-t border-slate-100">
            <div className="px-2 overflow-x-auto scrollbar-hide">
              <div className="flex space-x-1 py-1.5 sm:py-2">
                {TABS.map((tab) => {
                  const Icon = tab.icon;
                  const isActive = activeTab === tab.id;
                  return (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id)}
                      className={`
                        flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs sm:text-sm font-semibold rounded-lg sm:rounded-xl whitespace-nowrap transition-all duration-200 relative overflow-hidden flex-1 justify-center sm:flex-none
                        ${isActive 
                          ? 'text-white bg-indigo-600 shadow-lg shadow-indigo-200' 
                          : 'text-slate-500 hover:text-indigo-600 hover:bg-slate-50'}
                      `}
                    >
                      <Icon size={16} className={isActive ? 'text-white' : ''} />
                      {tab.label}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && (
          <SalarySlip 
            data={currentData.salary} 
            onChange={(s) => updateCurrentData({ salary: s })} 
          />
        )}
        {activeTab === 'budget' && (
          <Budget 
            income={currentNetIncome} 
            data={currentData.budget} 
            onChange={(b) => updateCurrentData({ budget: b })} 
          />
        )}
        {activeTab === 'charts' && (
          <MonthlyCharts 
            budgetData={currentData.budget} 
            income={currentNetIncome} 
          />
        )}
        {activeTab === 'invest' && (
          <Investments 
            items={currentData.investments} 
            onChange={(i) => updateCurrentData({ investments: i })} 
          />
        )}
        {activeTab === 'year' && (
          <YearlySummary 
            appState={appState} 
            year={currentDate.getFullYear()} 
          />
        )}
      </main>

      {showCopyModal && (
        <div className="fixed inset-0 bg-slate-900/40 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="bg-white p-6 sm:p-8 rounded-3xl max-w-md w-full shadow-2xl animate-fadeIn border border-slate-200">
              <h3 className="text-xl sm:text-2xl font-bold text-slate-800 mb-2">Bulan Baru</h3>
              <p className="text-slate-500 mb-8 leading-relaxed text-sm sm:text-base">Data bulan ini belum ada di Database. Salin dari bulan lalu?</p>
              <div className="flex gap-4">
                <button 
                  onClick={() => initializeMonth(true)}
                  className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white py-3 rounded-xl font-bold transition-all shadow-lg shadow-indigo-200 text-sm sm:text-base"
                >
                  Salin Data
                </button>
                <button 
                  onClick={() => initializeMonth(false)}
                  className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-700 py-3 rounded-xl font-bold transition-colors border border-slate-200 text-sm sm:text-base"
                >
                  Buat Baru
                </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { BudgetData, BudgetItem, OtherBudgetItem, CustomBudgetCategory } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, AlertTriangle, CheckCircle, Wallet, Bell, FolderPlus } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  color: string;
  onUpdateItems: (items: BudgetItem[]) => void;
  onDeleteCategory?: () => void;
  isCustom?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems,
  onDeleteCategory,
  isCustom = false
}) => {
  const [expanded, setExpanded] = useState(false);

  const catTotalAllocated = items.reduce((a, b) => a + b.budget, 0);
  const catTotalActual = items.reduce((a, b) => a + b.actual, 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;
  const totalItemsCount = items.length;

  const addItem = () => {
    const newItem: BudgetItem = { id: Date.now().toString(), name: '', budget: 0, actual: 0 };
    onUpdateItems([...items, newItem]);
  };

  const updateItem = (id: string, field: keyof BudgetItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onUpdateItems(newItems);
  };

  const deleteItem = (id: string) => {
    const newItems = items.filter(item => item.id !== id);
    onUpdateItems(newItems);
  };

  const getIconColor = () => {
      if (color === 'blue') return 'text-blue-600 bg-blue-50';
      if (color === 'emerald') return 'text-emerald-600 bg-emerald-50';
      if (color === 'red') return 'text-red-600 bg-red-50';
      if (color === 'purple') return 'text-purple-600 bg-purple-50';
      return 'text-slate-600';
  };

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden mb-4 sm:mb-5 transition-all duration-300 hover:shadow-lg ${isCatOver ? 'ring-2 ring-rose-500/20' : ''}`}>
      <div 
        className="p-4 sm:p-5 flex justify-between items-start sm:items-center cursor-pointer hover:bg-slate-50/50 transition-colors gap-2"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-start gap-3 sm:gap-4 flex-1">
           <div className={`p-2.5 sm:p-3 rounded-xl mt-0.5 sm:mt-0 ${getIconColor()}`}>
              {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
           </div>
           <div className="flex-1 min-w-0">
             <div className="flex items-center flex-wrap gap-2">
                 <h4 className="font-bold text-base sm:text-lg text-slate-800 tracking-tight truncate uppercase">{title}</h4>
                 <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded border border-slate-200 uppercase whitespace-nowrap">
                    {totalItemsCount} TOTAL
                 </span>
                 {isCatOver && (
                    <span className="animate-pulse flex items-center gap-1 bg-rose-500 text-white text-[10px] font-bold px-2 py-0.5 rounded">
                      <Bell size={10} /> OVER BUDGET
                    </span>
                 )}
                 {isCustom && (
                   <button 
                    onClick={(e) => { e.stopPropagation(); onDeleteCategory?.(); }}
                    className="p-1 text-slate-300 hover:text-rose-500 transition-colors"
                   >
                     <Trash2 size={14} />
                   </button>
                 )}
             </div>

             <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-1.5 text-[10px] sm:text-xs font-bold uppercase tracking-wider text-slate-400">
                <div className="flex items-center gap-1">
                    <span>ALOKASI:</span>
                    <span className="text-blue-600">{formatRupiah(catTotalAllocated)}</span>
                </div>
                <div className="flex items-center gap-1">
                    <span>REALISASI:</span>
                    <span className={isCatOver ? 'text-rose-500' : 'text-emerald-500'}>{formatRupiah(catTotalActual)}</span>
                </div>
                <div className="flex items-center gap-1">
                    <span>SISA:</span>
                    <span className="text-blue-600">{formatRupiah(catRemaining)}</span>
                </div>
             </div>
           </div>
        </div>
        <div className="pl-2">
           <div className={`text-xs font-bold px-3 py-1.5 rounded-xl ${isCatOver ? 'bg-rose-100 text-rose-600' : 'bg-slate-100 text-slate-600'}`}>
              {catTotalAllocated > 0 ? ((catTotalActual / catTotalAllocated) * 100).toFixed(0) : 0}%
           </div>
        </div>
      </div>

      {expanded && (
        <div className="p-3 sm:p-5 bg-slate-50 border-t border-slate-100">
           {items.map((item) => {
             const isOver = item.actual > item.budget;
             return (
               <div key={item.id} className={`grid grid-cols-2 md:grid-cols-12 gap-3 sm:gap-4 mb-3 items-end p-3 sm:p-4 bg-white rounded-xl border transition-all ${isOver ? 'border-rose-300 shadow-md ring-1 ring-rose-200' : 'border-slate-100 shadow-sm'}`}>
                 <div className="col-span-2 md:col-span-4">
                   <div className="flex items-center gap-2 mb-1">
                     <label className="text-[10px] sm:text-xs text-slate-400 uppercase font-semibold ml-1 block">Nama Item</label>
                     {isOver && <span className="flex items-center gap-1 text-[9px] font-bold text-rose-500 animate-pulse"><AlertTriangle size={8} /> OVER BUDGET</span>}
                   </div>
                   <input 
                     type="text" 
                     value={item.name} 
                     onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                     className="w-full bg-slate-50 rounded-xl p-2.5 sm:p-3 text-slate-800 text-sm border border-slate-200 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all"
                     placeholder="Nama pengeluaran..."
                   />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Anggaran" value={item.budget} onChange={(v) => updateItem(item.id, 'budget', v)} className="text-sm" />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => updateItem(item.id, 'actual', v)} className={`text-sm ${isOver ? 'text-rose-600' : ''}`} />
                 </div>
                 <div className="col-span-2 md:col-span-2 flex justify-end pb-0 sm:pb-1.5">
                   <button onClick={() => deleteItem(item.id)} className="w-full sm:w-auto p-2 sm:p-3 text-rose-400 hover:bg-rose-50 hover:text-rose-600 rounded-xl transition-colors"><Trash2 size={18} /></button>
                 </div>
               </div>
             );
           })}
           <button onClick={addItem} className={`w-full py-3 border border-dashed border-${color}-200 text-${color}-600 bg-white rounded-xl hover:bg-${color}-50 hover:border-${color}-300 flex items-center justify-center gap-2 transition-all font-medium text-sm mt-2`}><Plus size={16} /> Tambah Item</button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const calcTotalBudget = () => {
    const needs = (data.needs?.items || []).reduce((acc, item) => acc + item.budget, 0);
    const savings = (data.savings?.items || []).reduce((acc, item) => acc + item.budget, 0);
    const debt = (data.debt?.items || []).reduce((acc, item) => acc + item.budget, 0);
    const custom = (data.custom || []).reduce((acc, cat) => acc + cat.items.reduce((ia, ii) => ia + ii.budget, 0), 0);
    const others = data.others?.allocation || 0;
    return needs + savings + debt + others + custom;
  };

  const calcTotalActual = () => {
    const needs = (data.needs?.items || []).reduce((acc, item) => acc + item.actual, 0);
    const savings = (data.savings?.items || []).reduce((acc, item) => acc + item.actual, 0);
    const debt = (data.debt?.items || []).reduce((acc, item) => acc + item.actual, 0);
    const custom = (data.custom || []).reduce((acc, cat) => acc + cat.items.reduce((ia, ii) => ia + ii.actual, 0), 0);
    const others = (data.others?.items || []).reduce((acc, item) => acc + item.actual, 0);
    return needs + savings + debt + others + custom;
  };

  const handleAddCategory = () => {
    const name = prompt("Masukkan Nama Kategori Baru:");
    if (!name || name.trim() === "") return;

    const newCat: CustomBudgetCategory = {
      id: Date.now().toString(),
      name: name,
      items: []
    };

    onChange({
      ...data,
      custom: [...(data.custom || []), newCat]
    });
  };

  const updateCustomCategory = (id: string, items: BudgetItem[]) => {
    const newCustom = (data.custom || []).map(cat => cat.id === id ? { ...cat, items } : cat);
    onChange({ ...data, custom: newCustom });
  };

  const deleteCustomCategory = (id: string) => {
    if (!confirm("Hapus kategori ini beserta seluruh itemnya?")) return;
    const newCustom = (data.custom || []).filter(cat => cat.id !== id);
    onChange({ ...data, custom: newCustom });
  };

  const totalAllocated = calcTotalBudget();
  const totalActual = calcTotalActual();
  const balance = income - totalActual;
  const isOverBudget = totalAllocated > income;

  return (
    <div className="space-y-6 sm:space-y-8 animate-fadeIn">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="glass-panel p-4 sm:p-5 rounded-2xl relative overflow-hidden group hover:-translate-y-1 transition-transform duration-300">
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Penghasilan (Net)</p>
           <h3 className="text-xl md:text-2xl font-bold text-slate-800 tracking-tight">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 sm:p-5 rounded-2xl relative overflow-hidden hover:-translate-y-1 transition-transform duration-300">
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Total Anggaran</p>
           <h3 className={`text-xl md:text-2xl font-bold tracking-tight ${isOverBudget ? 'text-rose-500' : 'text-blue-600'}`}>{formatRupiah(totalAllocated)}</h3>
           {isOverBudget && <span className="text-[10px] text-rose-500 absolute top-4 right-4 flex items-center gap-1 bg-rose-50 px-2 py-1 rounded-full border border-rose-100 animate-pulse"><Bell size={10}/> OVER</span>}
        </div>
        <div className="glass-panel p-4 sm:p-5 rounded-2xl relative overflow-hidden hover:-translate-y-1 transition-transform duration-300">
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Total Realisasi</p>
           <h3 className="text-xl md:text-2xl font-bold tracking-tight text-amber-500">{formatRupiah(totalActual)}</h3>
        </div>
        <div className={`glass-panel p-4 sm:p-5 rounded-2xl border transition-all duration-300 hover:-translate-y-1 ${balance < 0 ? 'border-rose-200 bg-rose-50' : 'border-emerald-200 bg-emerald-50'}`}>
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Sisa Saldo</p>
           <h3 className={`text-xl md:text-2xl font-bold tracking-tight ${balance < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>{formatRupiah(balance)}</h3>
        </div>
      </div>

