};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const calcTotalBudget = () => {
    const needs = (data.needs?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const savings = (data.savings?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const debt = (data.debt?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const custom = (data.custom || []).reduce((acc, cat) => acc + (cat.items || []).reduce((ia, ii) => ia + (ii.budget || 0), 0), 0);
    const others = data.others?.allocation || 0;
    return needs + savings + debt + others + custom;
  };

  const calcTotalActual = () => {
    const needs = (data.needs?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const savings = (data.savings?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const debt = (data.debt?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const custom = (data.custom || []).reduce((acc, cat) => acc + (cat.items || []).reduce((ia, ii) => ia + (ii.actual || 0), 0), 0);
    const others = (data.others?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    return needs + savings + debt + others + custom;
  };

  const handleAddCategory = () => {
    const name = window.prompt("Masukkan Nama Kategori Baru:");
    if (!name || name.trim() === "") return;

    const newCat: CustomBudgetCategory = {
      id: Date.now().toString(),
      name: name.trim(),
      items: []
    };

    const currentCustom = Array.isArray(data.custom) ? [...data.custom] : [];

    onChange({
      ...data,
      custom: [...currentCustom, newCat]
    });
  };

  const updateCustomCategory = (id: string, items: BudgetItem[]) => {
    const currentCustom = Array.isArray(data.custom) ? data.custom : [];
    const newCustom = currentCustom.map(cat => cat.id === id ? { ...cat, items } : cat);
    onChange({ ...data, custom: newCustom });
  };

  const deleteCustomCategory = (id: string) => {
    if (!window.confirm("Hapus kategori ini beserta seluruh itemnya?")) return;
    const currentCustom = Array.isArray(data.custom) ? data.custom : [];
    const newCustom = currentCustom.filter(cat => cat.id !== id);
    onChange({ ...data, custom: newCustom });
  };

  const totalAllocated = calcTotalBudget();
  const totalActual = calcTotalActual();
  const balance = income - totalActual;
  const isOverBudget = totalAllocated > income;

  return (
    <div className="space-y-6 sm:space-y-8 animate-fadeIn">
      {/* Summary Widgets */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="glass-panel p-4 sm:p-5 rounded-2xl relative overflow-hidden group hover:-translate-y-1 transition-transform duration-300">
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Penghasilan (Net)</p>
           <h3 className="text-xl md:text-2xl font-bold text-slate-800 tracking-tight">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 sm:p-5 rounded-2xl relative overflow-hidden hover:-translate-y-1 transition-transform duration-300">
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Total Anggaran</p>
           <h3 className={`text-xl md:text-2xl font-bold tracking-tight ${isOverBudget ? 'text-rose-500' : 'text-blue-600'}`}>{formatRupiah(totalAllocated)}</h3>
           {isOverBudget && <span className="text-[10px] text-rose-500 absolute top-4 right-4 flex items-center gap-1 bg-rose-50 px-2 py-1 rounded-full border border-rose-100 animate-pulse"><Bell size={10}/> OVER</span>}
        </div>
        <div className="glass-panel p-4 sm:p-5 rounded-2xl relative overflow-hidden hover:-translate-y-1 transition-transform duration-300">
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Total Realisasi</p>
           <h3 className="text-xl md:text-2xl font-bold tracking-tight text-amber-500">{formatRupiah(totalActual)}</h3>
        </div>
        <div className={`glass-panel p-4 sm:p-5 rounded-2xl border transition-all duration-300 hover:-translate-y-1 ${balance < 0 ? 'border-rose-200 bg-rose-50' : 'border-emerald-200 bg-emerald-50'}`}>
           <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mb-1">Sisa Saldo</p>
           <h3 className={`text-xl md:text-2xl font-bold tracking-tight ${balance < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>{formatRupiah(balance)}</h3>
        </div>
      </div>

      {/* Header Utama dengan Tombol Tambah - DIPERBAIKI TOTAL */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 pt-4 border-b-2 border-slate-200 pb-5 mb-6 relative z-50">
         <div className="flex items-center gap-3">
            <div className="w-1.5 h-8 bg-indigo-600 rounded-full"></div>
            <h2 className="text-xl sm:text-2xl font-black text-slate-800 tracking-tighter uppercase">DAFTAR ANGGARAN</h2>
         </div>
         <button 
           type="button"
           onClick={handleAddCategory}
           className="w-full sm:w-auto px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl text-xs sm:text-sm font-black flex items-center justify-center gap-2 transition-all shadow-xl shadow-indigo-100 hover:-translate-y-1 active:scale-95 cursor-pointer select-none"
         >
           <FolderPlus size={20} className="stroke-[3]" /> TAMBAH KATEGORI BARU
         </button>
      </div>

      <div className="space-y-4">
        <CategorySection title="Kebutuhan Pokok" items={data.needs?.items || []} color="blue" onUpdateItems={(items) => onChange({ ...data, needs: { items } })} />
        <CategorySection title="Tabungan / Investasi" items={data.savings?.items || []} color="emerald" onUpdateItems={(items) => onChange({ ...data, savings: { items } })} />
        <CategorySection title="Hutang / Cicilan" items={data.debt?.items || []} color="red" onUpdateItems={(items) => onChange({ ...data, debt: { items } })} />

        {/* Render Custom Categories */}
        {(Array.isArray(data.custom) ? data.custom : []).map(cat => (
          <CategorySection 
            key={cat.id} 
            title={cat.name} 
            items={cat.items || []} 
            color="purple" 
            isCustom={true} 
            onUpdateItems={(items) => updateCustomCategory(cat.id, items)} 
            onDeleteCategory={() => deleteCustomCategory(cat.id)} 
          />
        ))}

        <div className="pt-4 mt-8 border-t border-slate-200">
           <OthersCategorySection 
             allocation={data.others?.allocation || 0}
             items={data.others?.items || []}
             onUpdateAllocation={(val) => onChange({ ...data, others: { ...data.others, allocation: val } })}
             onUpdateItems={(items) => onChange({ ...data, others: { ...data.others, items } })}
           />
        </div>
      </div>
    </div>
  );
};

const OthersCategorySection: React.FC<{
  allocation: number;
  items: OtherBudgetItem[];
  onUpdateAllocation: (v: number) => void;
  onUpdateItems: (i: OtherBudgetItem[]) => void;
}> = ({ allocation, items, onUpdateAllocation, onUpdateItems }) => {
  const [expanded, setExpanded] = useState(false);
