  return (
    <div className={`glass-panel rounded-2xl overflow-hidden transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/20' : ''}`}>
      <div className="p-4 sm:p-5 flex justify-between items-start sm:items-center cursor-pointer hover:bg-slate-50/50" onClick={() => setExpanded(!expanded)}>
        <div className="flex items-start gap-3 sm:gap-4 flex-1">
           <div className="p-2.5 sm:p-3 rounded-xl bg-violet-50 text-violet-600">{expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}</div>
           <div className="flex-1">
             <div className="flex items-center gap-2">
                 <h4 className="font-bold text-base sm:text-lg text-slate-800 uppercase">Lain-lain</h4>
                 <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded border border-slate-200 uppercase">{totalItemsCount} TOTAL</span>
                 {isCatOver && <span className="animate-pulse bg-rose-500 text-white text-[10px] font-bold px-2 py-0.5 rounded">OVER</span>}
             </div>
             <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-1.5 text-[10px] sm:text-xs font-bold uppercase tracking-wider text-slate-400">
                <div>ALOKASI: <span className="text-blue-600">{formatRupiah(allocation)}</span></div>
                <div>REALISASI: <span className={isCatOver ? 'text-rose-500' : 'text-emerald-500'}>{formatRupiah(catTotalActual)}</span></div>
                <div>SISA: <span className="text-blue-600">{formatRupiah(catRemaining)}</span></div>
             </div>
           </div>
        </div>
        <div className={`text-xs font-bold px-3 py-1.5 rounded-xl ${isCatOver ? 'bg-rose-100 text-rose-600' : 'bg-slate-100 text-slate-600'}`}>{allocation > 0 ? ((catTotalActual / allocation) * 100).toFixed(0) : 0}%</div>
      </div>
      {expanded && (
        <div className="p-4 bg-slate-50 border-t border-slate-100 space-y-4">
           <CurrencyInput label="Total Alokasi Lain-lain" value={allocation} onChange={onUpdateAllocation} />
           {items.map(item => (
             <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 p-3 bg-white rounded-xl border border-slate-100 shadow-sm items-end">
               <div className="col-span-2 md:col-span-7"><input value={item.name} onChange={e => onUpdateItems(items.map(i => i.id === item.id ? {...i, name: e.target.value} : i))} className="w-full bg-slate-50 rounded-lg p-2 text-sm border border-slate-200" placeholder="Item name..." /></div>
               <div className="col-span-1 md:col-span-3"><CurrencyInput label="Aktual" value={item.actual} onChange={v => onUpdateItems(items.map(i => i.id === item.id ? {...i, actual: v} : i))} className="text-xs" /></div>
               <div className="col-span-1 md:col-span-2 flex justify-end pb-1"><button onClick={() => onUpdateItems(items.filter(i => i.id !== item.id))} className="text-rose-400 hover:text-rose-600"><Trash2 size={16} /></button></div>
             </div>
           ))}
           <button onClick={() => onUpdateItems([...items, {id: Date.now().toString(), name: '', actual: 0}])} className="w-full py-2 border border-dashed border-violet-200 text-violet-600 bg-white rounded-lg text-sm font-medium"><Plus size={14} className="inline mr-1"/> Tambah Item</button>
        </div>
      )}
    </div>
  );
};

