                >
                  Salin Data
                </button>
                <button 
                  onClick={() => initializeMonth(false)}
                  className="flex-1 bg-slate-800 hover:bg-slate-700 text-slate-200 py-3 rounded-xl font-bold transition-colors border border-slate-700 text-sm sm:text-base uppercase"
                >
                  Buat Baru
                </button>
