  const filledCount = items.filter(i => (i.actual || 0) > 0).length;
  const unfilledCount = totalItems - filledCount;

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/40 shadow-xl' : 'hover:shadow-lg'}`}>
      <div className="p-4 sm:p-5 flex justify-between items-center cursor-pointer hover:bg-white/5" onClick={() => setExpanded(!expanded)}>
        <div className="flex items-start gap-4 flex-1">
           <div className="p-3 rounded-xl bg-violet-900/30 text-violet-400">{expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}</div>
           <div className="flex-1">
             <div className="flex items-center gap-2">
                <h4 className="font-bold text-sm sm:text-base text-slate-100 uppercase tracking-tight">Lain-lain / Hiburan</h4>
                <div className="flex gap-1">
                   <span className="text-[9px] font-extrabold text-violet-300 bg-violet-900/40 px-2 py-0.5 rounded border border-violet-500/30 flex items-center gap-1">
                     {totalItems} ITEM
                   </span>
                   {unfilledCount > 0 && (
                     <span className="text-[9px] font-extrabold text-amber-300 bg-amber-900/40 px-2 py-0.5 rounded border border-amber-500/30 flex items-center gap-1">
                       <Clock size={10} /> {unfilledCount} BELUM TERISI
                     </span>
                   )}
                </div>
             </div>
             <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-1 text-[9px] sm:text-[10px] font-bold uppercase tracking-wider text-slate-400">
                <div>PLAFON: <span className="text-blue-400">{formatRupiah(allocation)}</span></div>
                <div>REALISASI: <span className={isCatOver ? 'text-rose-400' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></div>
