  title: string;
  items: BudgetItem[];
  color: 'blue' | 'emerald' | 'red' | 'purple' | 'violet';
  onUpdateItems: (items: BudgetItem[]) => void;
  onDeleteCategory: () => void;
  isCustom?: boolean;
  defaultExpanded?: boolean;
  canDelete?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems,
  onDeleteCategory,
  isCustom = false,
  defaultExpanded = false,
  canDelete = true
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);

  const catTotalAllocated = items.reduce((a, b) => a + (b.budget || 0), 0);
  const catTotalActual = items.reduce((a, b) => a + (b.actual || 0), 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;

  // Realization stats
  const totalItemsCount = items.length;
  const filledCount = items.filter(i => (i.actual || 0) > 0).length;
  const unfilledCount = totalItemsCount - filledCount;

  const addItem = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newItem: BudgetItem = { id: Date.now().toString(), name: '', budget: 0, actual: 0 };
    onUpdateItems([...items, newItem]);
    setExpanded(true);
  };

  const updateItem = (id: string, field: keyof BudgetItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onUpdateItems(newItems);
  };

  const deleteItem = (id: string) => {
    const newItems = items.filter(item => item.id !== id);
    onUpdateItems(newItems);
  };

  const colorsMap = {
    blue: { icon: 'text-blue-400 bg-blue-900/30', button: 'border-blue-900/50 text-blue-400 hover:bg-blue-900/20' },
    emerald: { icon: 'text-emerald-400 bg-emerald-900/30', button: 'border-emerald-900/50 text-emerald-400 hover:bg-emerald-900/20' },
    red: { icon: 'text-red-400 bg-red-900/30', button: 'border-red-900/50 text-red-400 hover:bg-red-900/20' },
    purple: { icon: 'text-purple-400 bg-purple-900/30', button: 'border-purple-900/50 text-purple-400 hover:bg-purple-900/20' },
    violet: { icon: 'text-violet-400 bg-violet-900/30', button: 'border-violet-200 text-violet-400 hover:bg-violet-900/20' }
  };

  const selectedColor = colorsMap[color] || colorsMap.blue;

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden mb-4 transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/40 shadow-xl' : 'hover:shadow-lg hover:bg-slate-800/60'}`}>
      <div 
        className="p-4 sm:p-5 flex justify-between items-start sm:items-center cursor-pointer hover:bg-white/5 transition-colors"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-start gap-3 sm:gap-4 flex-1">
           <div className={`p-2.5 sm:p-3 rounded-xl ${selectedColor.icon}`}>
              {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
           </div>
           <div className="flex-1 min-w-0">
             <div className="flex items-center flex-wrap gap-2">
                 <h4 className="font-black text-sm sm:text-base text-slate-100 uppercase tracking-tight">{title}</h4>
                 <div className="flex gap-1">
                    <span className="text-[9px] font-black text-indigo-300 bg-indigo-900/40 px-2 py-0.5 rounded border border-indigo-500/30 flex items-center gap-1">
                      {totalItemsCount} ITEM
                    </span>
                    <span className="text-[9px] font-black text-emerald-300 bg-emerald-900/40 px-2 py-0.5 rounded border border-emerald-500/30 flex items-center gap-1">
                      {filledCount} REALISASI
                    </span>
                    {unfilledCount > 0 ? (
                      <span className="text-[9px] font-black text-amber-300 bg-amber-900/40 px-2 py-0.5 rounded border border-amber-500/30 flex items-center gap-1">
                        <Clock size={10} /> {unfilledCount} BELUM ISI
                      </span>
                    ) : totalItemsCount > 0 && (
                      <span className="text-[9px] font-black text-emerald-300 bg-emerald-900/40 px-2 py-0.5 rounded border border-emerald-500/30 flex items-center gap-1">
                        <CheckCircle2 size={10} /> PENUH
                      </span>
                    )}
                 </div>
                 {isCatOver && (
                    <span className="animate-pulse flex items-center gap-1 bg-rose-600 text-white text-[9px] font-black px-2 py-0.5 rounded uppercase shadow-lg shadow-rose-900/40">
                      Over Budget
                    </span>
                 )}
                 {canDelete && (
                   <button 
                    onClick={(e) => { e.stopPropagation(); if(confirm(`Hapus kategori "${title}"?`)) onDeleteCategory(); }}
                    className="ml-2 p-1 text-slate-500 hover:text-rose-400 transition-colors"
                   >
                     <Trash2 size={16} />
                   </button>
                 )}
             </div>

             <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-1.5 text-[9px] sm:text-[10px] font-black uppercase tracking-wider text-slate-400">
                <div>ALOKASI: <span className="text-blue-400">{formatRupiah(catTotalAllocated)}</span></div>
                <div>REALISASI: <span className={isCatOver ? 'text-rose-400' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></div>
                <div>SISA: <span className="text-indigo-400">{formatRupiah(catRemaining)}</span></div>
             </div>
           </div>
        </div>
        <div className="ml-2">
           <div className={`text-[10px] font-black px-2 py-1 rounded-lg ${isCatOver ? 'bg-rose-900/50 text-rose-300' : 'bg-indigo-900/50 text-indigo-300'}`}>
              {catTotalAllocated > 0 ? ((catTotalActual / catTotalAllocated) * 100).toFixed(0) : 0}%
           </div>
        </div>
      </div>

      {expanded && (
        <div className="p-3 sm:p-5 bg-slate-900/30 border-t border-slate-800">
           <div className="space-y-3">
             {items.map((item) => {
               const isOver = (item.actual || 0) > (item.budget || 0);
               const isUnfilled = (item.actual || 0) === 0;
               return (
                 <div key={item.id} className={`grid grid-cols-2 md:grid-cols-12 gap-3 p-3 sm:p-4 bg-slate-800/40 rounded-xl border transition-all ${isOver ? 'border-rose-500/50 shadow-lg shadow-rose-900/20' : isUnfilled ? 'border-amber-500/20' : 'border-emerald-500/20'}`}>
                   <div className="col-span-2 md:col-span-4">
                     <label className="text-[9px] uppercase font-black text-slate-500 mb-1 block ml-1">Nama Item</label>
                     <input 
                       type="text" 
                       value={item.name} 
                       onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                       className="w-full bg-slate-900/50 rounded-lg p-2 text-slate-100 text-sm border border-slate-700 focus:border-indigo-500 outline-none font-black"
                       placeholder="Misal: Listrik"
                     />
                   </div>
                   <div className="col-span-1 md:col-span-3">
                     <CurrencyInput label="Anggaran" value={item.budget} onChange={(v) => updateItem(item.id, 'budget', v)} className="text-sm" />
                   </div>
                   <div className="col-span-1 md:col-span-3">
                     <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => updateItem(item.id, 'actual', v)} className={`text-sm ${isOver ? 'text-rose-400' : isUnfilled ? 'text-amber-400/70' : 'text-emerald-400'}`} />
                   </div>
                   <div className="col-span-2 md:col-span-2 flex justify-end items-end pb-1">
                     <button onClick={() => deleteItem(item.id)} className="p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-colors"><Trash2 size={16} /></button>
                   </div>
                 </div>
               );
             })}
           </div>
           <button 
             onClick={addItem} 
             className={`w-full mt-4 py-3 border-2 border-dashed rounded-xl flex items-center justify-center gap-2 transition-all font-black text-xs uppercase tracking-widest ${selectedColor.button}`}
           >
             <Plus size={16} /> Tambah Item Ke {title}
           </button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState('');

  const calcTotalBudget = () => {
    const needs = (data.needs?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const savings = (data.savings?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const debt = (data.debt?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const custom = (data.custom || []).reduce((acc, cat) => (cat.items || []).reduce((ia, ii) => ia + (ii.budget || 0), acc), 0);
    const others = data.others?.allocation || 0;
    return needs + savings + debt + others + custom;
  };

  const calcTotalActual = () => {
    const needs = (data.needs?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const savings = (data.savings?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const debt = (data.debt?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const custom = (data.custom || []).reduce((acc, cat) => (cat.items || []).reduce((ia, ii) => ia + (ii.actual || 0), acc), 0);
    const others = (data.others?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    return needs + savings + debt + others + custom;
  };

  const confirmAddCategory = () => {
    if (!newCategoryName.trim()) {
      setIsAddingCategory(false);
      return;
    }

    const newCat: CustomBudgetCategory = {
      id: Date.now().toString(),
      name: newCategoryName.trim(),
      items: []
    };

    const currentCustom = Array.isArray(data.custom) ? [...data.custom] : [];
    onChange({
      ...data,
      custom: [...currentCustom, newCat]
    });

    setNewCategoryName('');
    setIsAddingCategory(false);
  };

  const updateCustomCategory = (id: string, items: BudgetItem[]) => {
    const currentCustom = Array.isArray(data.custom) ? data.custom : [];
    const newCustom = currentCustom.map(cat => cat.id === id ? { ...cat, items } : cat);
    onChange({ ...data, custom: newCustom });
  };

  const deleteCustomCategory = (id: string) => {
    const currentCustom = Array.isArray(data.custom) ? data.custom : [];
    const newCustom = currentCustom.filter(cat => cat.id !== id);
    onChange({ ...data, custom: newCustom });
  };

  const totalAllocated = calcTotalBudget();
  const totalActual = calcTotalActual();
  const balance = income - totalActual;
  const isOverBudget = totalAllocated > income;

  return (
    <div className="space-y-6 sm:space-y-8 animate-fadeIn pb-10">
      {/* Summary Widgets */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-indigo-500 shadow-indigo-900/20">
           <p className="text-slate-500 text-[9px] font-black uppercase tracking-widest mb-1">Income Netto</p>
           <h3 className="text-xl font-black text-slate-100">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-blue-500 shadow-blue-900/20">
           <p className="text-slate-500 text-[9px] font-black uppercase tracking-widest mb-1">Total Anggaran</p>
           <h3 className={`text-xl font-black ${isOverBudget ? 'text-rose-400' : 'text-blue-400'}`}>{formatRupiah(totalAllocated)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-amber-500 shadow-amber-900/20">
           <p className="text-slate-500 text-[9px] font-black uppercase tracking-widest mb-1">Realisasi</p>
           <h3 className="text-xl font-black text-amber-400">{formatRupiah(totalActual)}</h3>
        </div>
        <div className={`glass-panel p-4 rounded-2xl border-l-4 ${balance < 0 ? 'border-rose-500 bg-rose-900/20' : 'border-emerald-500 bg-emerald-900/20'}`}>
           <p className="text-slate-500 text-[9px] font-black uppercase tracking-widest mb-1">Saldo Akhir</p>
           <h3 className={`text-xl font-black ${balance < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>{formatRupiah(balance)}</h3>
        </div>
      </div>

      {/* Header Utama dengan Tambah Kategori */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 pt-4 border-b border-slate-800 pb-5">
         <h2 className="text-xl font-black text-white tracking-tighter uppercase flex items-center gap-2">
           <div className="w-2 h-6 bg-indigo-600 rounded-full"></div>
           DAFTAR ANGGARAN
         </h2>

         {!isAddingCategory ? (
           <button 
             onClick={() => setIsAddingCategory(true)}
             className="w-full sm:w-auto px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-black flex items-center justify-center gap-2 transition-all shadow-lg shadow-indigo-900/40 active:scale-95 uppercase tracking-widest"
           >
             <FolderPlus size={18} /> TAMBAH KATEGORI BARU
           </button>
         ) : (
           <div className="flex w-full sm:w-auto items-center gap-2 animate-fadeIn">
             <input 
               autoFocus
               type="text"
               value={newCategoryName}
               onChange={(e) => setNewCategoryName(e.target.value)}
               placeholder="Nama Kategori..."
               className="flex-1 sm:w-64 bg-slate-800 border-2 border-indigo-900/50 rounded-xl px-4 py-2 text-sm text-white focus:border-indigo-500 outline-none shadow-inner font-black"
               onKeyDown={(e) => e.key === 'Enter' && confirmAddCategory()}
             />
             <button onClick={confirmAddCategory} className="p-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-colors"><Check size={20}/></button>
             <button onClick={() => setIsAddingCategory(false)} className="p-2.5 bg-slate-700 text-slate-300 rounded-xl hover:bg-slate-600 transition-colors"><X size={20}/></button>
           </div>
         )}
      </div>

      <div className="space-y-4">
        <CategorySection title="Kebutuhan Pokok" items={data.needs?.items || []} color="blue" onDeleteCategory={() => onChange({ ...data, needs: { items: [] } })} onUpdateItems={(items) => onChange({ ...data, needs: { items } })} defaultExpanded={false} />
        <CategorySection title="Tabungan & Investasi" items={data.savings?.items || []} color="emerald" onDeleteCategory={() => onChange({ ...data, savings: { items: [] } })} onUpdateItems={(items) => onChange({ ...data, savings: { items } })} defaultExpanded={false} />
        <CategorySection title="Hutang & Cicilan" items={data.debt?.items || []} color="red" onDeleteCategory={() => onChange({ ...data, debt: { items: [] } })} onUpdateItems={(items) => onChange({ ...data, debt: { items } })} defaultExpanded={false} />

        {/* Custom Categories */}
        {(Array.isArray(data.custom) ? data.custom : []).map(cat => (
          <CategorySection 
            key={cat.id} 
            title={cat.name} 
            items={cat.items || []} 
            color="purple" 
            isCustom={true} 
            defaultExpanded={false}
            onUpdateItems={(items) => updateCustomCategory(cat.id, items)} 
            onDeleteCategory={() => deleteCustomCategory(cat.id)} 
          />
        ))}

        <div className="pt-6">
           <OthersCategorySection 
             allocation={data.others?.allocation || 0}
             items={data.others?.items || []}
             onUpdateAllocation={(val) => onChange({ ...data, others: { ...data.others, allocation: val } })}
             onUpdateItems={(items) => onChange({ ...data, others: { ...data.others, items } })}
           />
        </div>
      </div>
    </div>
  );
};

