import React from 'react';
import { BudgetData } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell, CartesianGrid } from 'recharts';
import { formatRupiah } from '../utils';

interface MonthlyChartsProps {
  budgetData: BudgetData;
  income: number;
}

const MonthlyCharts: React.FC<MonthlyChartsProps> = ({ budgetData, income }) => {
  // Aggregate data
  const needsAlloc = budgetData.needs?.items.reduce((a, b) => a + (b.budget || 0), 0) || 0;
  const needsActual = budgetData.needs?.items.reduce((a, b) => a + (b.actual || 0), 0) || 0;

  const savingsAlloc = budgetData.savings?.items.reduce((a, b) => a + (b.budget || 0), 0) || 0;
  const savingsActual = budgetData.savings?.items.reduce((a, b) => a + (b.actual || 0), 0) || 0;

  const debtAlloc = budgetData.debt?.items.reduce((a, b) => a + (b.budget || 0), 0) || 0;
  const debtActual = budgetData.debt?.items.reduce((a, b) => a + (b.actual || 0), 0) || 0;

  const othersAlloc = budgetData.others.allocation || 0;
  const othersActual = budgetData.others.items.reduce((a, b) => a + (b.actual || 0), 0);

  const totalAllocated = needsAlloc + savingsAlloc + debtAlloc + othersAlloc;
  const totalActual = needsActual + savingsActual + debtActual + othersActual;

  const barData = [
    { name: 'Pokok', Anggaran: needsAlloc, Aktual: needsActual },
    { name: 'Tabungan', Anggaran: savingsAlloc, Aktual: savingsActual },
    { name: 'Cicilan', Anggaran: debtAlloc, Aktual: debtActual },
    { name: 'Lainnya', Anggaran: othersAlloc, Aktual: othersActual },
  ];

  const pieAllocData = [
    { name: 'Pokok', value: needsAlloc },
    { name: 'Tabungan', value: savingsAlloc },
    { name: 'Cicilan', value: debtAlloc },
    { name: 'Lainnya', value: othersAlloc },
  ].filter(d => d.value > 0);

  const pieActualData = [
    { name: 'Pokok', value: needsActual },
    { name: 'Tabungan', value: savingsActual },
    { name: 'Cicilan', value: debtActual },
    { name: 'Lainnya', value: othersActual },
  ].filter(d => d.value > 0);

  // High contrast vibrant palette for dark mode
  const COLORS = ['#3B82F6', '#10B981', '#F59E0B', '#8B5CF6'];

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-slate-900 border border-slate-700 p-3 sm:p-4 rounded-xl shadow-2xl">
          <p className="font-bold text-white mb-2 border-b border-slate-800 pb-2 text-xs sm:text-sm uppercase tracking-wider">{label || 'Data'}</p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center gap-2 mb-1">
              <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color || entry.payload.fill }}></div>
              <span className="text-slate-400 text-[10px] sm:text-xs">{entry.name}:</span>
              <span className="text-white font-mono text-[10px] sm:text-xs font-bold">{formatRupiah(entry.value)}</span>
            </div>
          ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Performance Bar Chart */}
      <div className="glass-panel p-4 sm:p-6 rounded-2xl border border-slate-800 shadow-xl">
        <h3 className="text-base sm:text-lg font-bold text-white mb-6 border-l-4 border-indigo-500 pl-3 uppercase tracking-tight">Kinerja Anggaran Bulanan</h3>
        <div className="h-64 sm:h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={barData} margin={{ top: 20, right: 10, left: 0, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
              <XAxis dataKey="name" stroke="#94a3b8" fontSize={10} tickLine={false} axisLine={false} />
              <YAxis 
                stroke="#94a3b8" 
                fontSize={10} 
                width={80}
                tickFormatter={(val) => formatRupiah(val)} 
                tickLine={false}
                axisLine={false}
              />
              <Tooltip content={<CustomTooltip />} cursor={{fill: 'rgba(255,255,255,0.05)'}} />
              <Legend wrapperStyle={{ paddingTop: '20px', fontSize: '11px', color: '#94a3b8', fontWeight: 'bold', textTransform: 'uppercase' }} />
              <Bar dataKey="Anggaran" fill="#3B82F6" radius={[6, 6, 0, 0]} maxBarSize={40} />
              <Bar dataKey="Aktual" fill="#10B981" radius={[6, 6, 0, 0]} maxBarSize={40} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Allocation Pie */}
        <div className="glass-panel p-4 sm:p-6 rounded-2xl border border-slate-800">
           <h3 className="text-base sm:text-lg font-bold text-white mb-6 border-l-4 border-blue-500 pl-3 uppercase tracking-tight">Rencana Alokasi</h3>
           <div className="h-64 sm:h-80">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart margin={{ right: 30, left: 30 }}>
                  <Pie
                    data={pieAllocData}
                    cx="50%"
                    cy="50%"
                    innerRadius={50}
                    outerRadius={75}
                    dataKey="value"
                    stroke="#0f172a"
                    strokeWidth={2}
                    filter="url(#shadow3d)"
                    labelLine={{ stroke: '#94a3b8', strokeWidth: 1.5 }}
                    label={({ percent }) => `${(percent * 100).toFixed(0)}%`}
                    paddingAngle={5}
                  >
                    {pieAllocData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                  <Legend iconSize={10} layout="horizontal" verticalAlign="bottom" align="center" wrapperStyle={{ fontSize: '10px', color: '#94a3b8', textTransform: 'uppercase', paddingTop: '10px' }}/>
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>

        {/* Realization Pie */}
        <div className="glass-panel p-4 sm:p-6 rounded-2xl border border-slate-800">
           <h3 className="text-base sm:text-lg font-bold text-white mb-6 border-l-4 border-orange-500 pl-3 uppercase tracking-tight">Realisasi Pengeluaran</h3>
           <div className="h-64 sm:h-80">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart margin={{ right: 30, left: 30 }}>
                  <Pie
                    data={pieActualData}
                    cx="50%"
                    cy="50%"
                    innerRadius={50}
                    outerRadius={75}
                    dataKey="value"
                    stroke="#0f172a"
                    strokeWidth={2}
                    filter="url(#shadow3d)"
                    labelLine={{ stroke: '#94a3b8', strokeWidth: 1.5 }}
                    label={({ percent }) => `${(percent * 100).toFixed(0)}%`}
                    paddingAngle={5}
                  >
                    {pieActualData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                  <Legend iconSize={10} layout="horizontal" verticalAlign="bottom" align="center" wrapperStyle={{ fontSize: '10px', color: '#94a3b8', textTransform: 'uppercase', paddingTop: '10px' }}/>
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>
      </div>
    </div>
  );
};

export default MonthlyCharts;

import React, { useState } from 'react';
import { BudgetData, BudgetItem, OtherBudgetItem, CustomBudgetCategory } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, FolderPlus, X, Check, CheckCircle2, Clock, AlertCircle } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  color: 'blue' | 'emerald' | 'red' | 'purple' | 'violet';
  onUpdateItems: (items: BudgetItem[]) => void;
  onDeleteCategory: () => void;
  isCustom?: boolean;
  defaultExpanded?: boolean;
  canDelete?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems,
  onDeleteCategory,
  isCustom = false,
  defaultExpanded = false,
  canDelete = true
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);

  const catTotalAllocated = items.reduce((a, b) => a + (b.budget || 0), 0);
  const catTotalActual = items.reduce((a, b) => a + (b.actual || 0), 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;

  const totalItemsCount = items.length;
  const filledCount = items.filter(i => (i.actual || 0) > 0).length;
  const unfilledCount = totalItemsCount - filledCount;

  const addItem = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newItem: BudgetItem = { id: (Date.now() + Math.random()).toString(), name: '', budget: 0, actual: 0 };
    onUpdateItems([...items, newItem]);
    setExpanded(true);
  };

  const updateItem = (id: string, field: keyof BudgetItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onUpdateItems(newItems);
  };

  const deleteItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('Hapus item ini?')) {
      const newItems = items.filter(item => item.id !== id);
      onUpdateItems(newItems);
    }
  };

  const handleDeleteCategoryAction = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm(`Apakah Anda yakin ingin menghapus kategori "${title}"?`)) {
      onDeleteCategory();
    }
  };

  const colorsMap = {
    blue: { icon: 'text-blue-400 bg-blue-900/30', button: 'border-blue-900/50 text-blue-400 hover:bg-blue-900/20' },
    emerald: { icon: 'text-emerald-400 bg-emerald-900/30', button: 'border-emerald-900/50 text-emerald-400 hover:bg-emerald-900/20' },
    red: { icon: 'text-red-400 bg-red-900/30', button: 'border-red-900/50 text-red-400 hover:bg-red-900/20' },
    purple: { icon: 'text-purple-400 bg-purple-900/30', button: 'border-purple-900/50 text-purple-400 hover:bg-purple-900/20' },
    violet: { icon: 'text-violet-400 bg-violet-900/30', button: 'border-violet-200 text-violet-400 hover:bg-violet-900/20' }
  };

  const selectedColor = colorsMap[color] || colorsMap.blue;

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden mb-4 transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/40 shadow-xl' : 'hover:shadow-lg hover:bg-slate-800/60'}`}>
      <div 
        className="p-4 sm:p-5 flex justify-between items-start sm:items-center cursor-pointer hover:bg-white/5 transition-colors"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-start gap-3 sm:gap-4 flex-1">
           <div className={`p-2.5 sm:p-3 rounded-xl ${selectedColor.icon}`}>
              {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
           </div>
           <div className="flex-1 min-w-0">
             <div className="flex items-center flex-wrap gap-2">
                 <h4 className="font-black text-sm sm:text-base text-slate-100 uppercase tracking-tight">{title}</h4>
                 <div className="flex gap-1">
                    <span className="text-[9px] font-black text-indigo-300 bg-indigo-900/40 px-2 py-0.5 rounded border border-indigo-500/30">
                      {totalItemsCount} ITEM
                    </span>
                    {unfilledCount > 0 ? (
                      <span className="text-[9px] font-black text-amber-300 bg-amber-900/40 px-2 py-0.5 rounded border border-amber-500/30 flex items-center gap-1">
                        <Clock size={10} /> {unfilledCount} BELUM ISI
                      </span>
                    ) : totalItemsCount > 0 && (
                      <span className="text-[9px] font-black text-emerald-300 bg-emerald-900/40 px-2 py-0.5 rounded border border-emerald-500/30 flex items-center gap-1">
                        <CheckCircle2 size={10} /> PENUH
                      </span>
                    )}
                 </div>
                 {canDelete && (
                   <button 
                    onClick={handleDeleteCategoryAction}
