                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => updateItem(item.id, 'actual', v)} className="text-sm" />
                 </div>
                 <div className="col-span-2 md:col-span-2 flex justify-end items-end pb-1">
                   <button onClick={(e) => deleteItem(e, item.id)} className="p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-colors" title="Hapus Item"><Trash2 size={16} /></button>
                 </div>
               </div>
             ))}
