             <Plus size={14} className="inline mr-1"/> Tambah Pengeluaran Lainnya
           </button>
        </div>
      )}
    </div>
  );
};

export default Budget;

import React, { useState } from 'react';
import { BudgetData, BudgetItem, OtherBudgetItem, CustomBudgetCategory } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, FolderPlus, X, Check, CheckCircle2, Clock } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  color: 'blue' | 'emerald' | 'red' | 'purple' | 'violet';
  onUpdateItems: (items: BudgetItem[]) => void;
  onDeleteCategory: () => void;
  isCustom?: boolean;
  defaultExpanded?: boolean;
  canDelete?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems,
  onDeleteCategory,
  isCustom = false,
  defaultExpanded = false,
  canDelete = true
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);

  const catTotalAllocated = items.reduce((a, b) => a + (b.budget || 0), 0);
  const catTotalActual = items.reduce((a, b) => a + (b.actual || 0), 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;

  const totalItemsCount = items.length;
  const filledCount = items.filter(i => (i.actual || 0) > 0).length;
  const unfilledCount = totalItemsCount - filledCount;

  const addItem = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newItem: BudgetItem = { id: (Date.now() + Math.random()).toString(), name: '', budget: 0, actual: 0 };
    onUpdateItems([...items, newItem]);
    setExpanded(true);
  };

  const updateItem = (id: string, field: keyof BudgetItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onUpdateItems(newItems);
  };

  const deleteItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm('Hapus item ini dari daftar?')) {
      const newItems = items.filter(item => item.id !== id);
      onUpdateItems(newItems);
    }
  };

  const handleDeleteCategoryAction = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    if (window.confirm(`Apakah Anda yakin ingin menghapus kategori "${title}" beserta seluruh isinya?`)) {
      onDeleteCategory();
    }
  };

  const colorsMap = {
    blue: { icon: 'text-blue-400 bg-blue-900/30', button: 'border-blue-900/50 text-blue-400 hover:bg-blue-900/20' },
    emerald: { icon: 'text-emerald-400 bg-emerald-900/30', button: 'border-emerald-900/50 text-emerald-400 hover:bg-emerald-900/20' },
    red: { icon: 'text-red-400 bg-red-900/30', button: 'border-red-900/50 text-red-400 hover:bg-red-900/20' },
    purple: { icon: 'text-purple-400 bg-purple-900/30', button: 'border-purple-900/50 text-purple-400 hover:bg-purple-900/20' },
    violet: { icon: 'text-violet-400 bg-violet-900/30', button: 'border-violet-200 text-violet-400 hover:bg-violet-900/20' }
  };

  const selectedColor = colorsMap[color] || colorsMap.blue;

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden mb-4 transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/40 shadow-xl' : 'hover:shadow-lg hover:bg-slate-800/60'}`}>
      <div 
        className="p-4 sm:p-5 flex justify-between items-start sm:items-center cursor-pointer hover:bg-white/5 transition-colors"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-start gap-3 sm:gap-4 flex-1">
           <div className={`p-2.5 sm:p-3 rounded-xl ${selectedColor.icon}`}>
              {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
           </div>
           <div className="flex-1 min-w-0">
             <div className="flex items-center flex-wrap gap-2">
                 <h4 className="font-black text-sm sm:text-base text-slate-100 uppercase tracking-tight">{title}</h4>
                 <div className="flex gap-1">
                    <span className="text-[9px] font-black text-indigo-300 bg-indigo-900/40 px-2 py-0.5 rounded border border-indigo-500/30">
                      {totalItemsCount} ITEM
                    </span>
                    {unfilledCount > 0 && (
                      <span className="text-[9px] font-black text-amber-300 bg-amber-900/40 px-2 py-0.5 rounded border border-amber-500/30 flex items-center gap-1">
                        <Clock size={10} /> {unfilledCount} BELUM ISI
                      </span>
                    )}
                 </div>
                 {canDelete && (
                   <button 
                    onClick={handleDeleteCategoryAction}
                    className="ml-2 p-1.5 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-all flex items-center gap-1"
                    title="Hapus Kategori"
                   >
                     <Trash2 size={16} />
                     <span className="text-[9px] font-black uppercase hidden sm:inline">Hapus</span>
                   </button>
                 )}
             </div>

             <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-1.5 text-[9px] sm:text-[10px] font-black uppercase tracking-wider text-slate-400">
                <div>ALOKASI: <span className="text-blue-400">{formatRupiah(catTotalAllocated)}</span></div>
                <div>REALISASI: <span className={isCatOver ? 'text-rose-400' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></div>
                <div>SISA: <span className="text-indigo-400">{formatRupiah(catRemaining)}</span></div>
             </div>
           </div>
        </div>
        <div className="ml-2">
           <div className={`text-[10px] font-black px-2 py-1 rounded-lg ${isCatOver ? 'bg-rose-900/50 text-rose-300' : 'bg-indigo-900/50 text-indigo-300'}`}>
              {catTotalAllocated > 0 ? ((catTotalActual / catTotalAllocated) * 100).toFixed(0) : 0}%
           </div>
        </div>
      </div>

      {expanded && (
        <div className="p-3 sm:p-5 bg-slate-900/30 border-t border-slate-800">
           <div className="space-y-3">
             {items.map((item) => (
               <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 p-3 sm:p-4 bg-slate-800/40 rounded-xl border border-slate-700/50">
                 <div className="col-span-2 md:col-span-4">
                   <label className="text-[9px] uppercase font-black text-slate-500 mb-1 block">Nama Item</label>
                   <input 
                     type="text" 
                     value={item.name} 
                     onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                     className="w-full bg-slate-900/50 rounded-lg p-2 text-slate-100 text-sm border border-slate-700 focus:border-indigo-500 outline-none font-black"
                   />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Anggaran" value={item.budget} onChange={(v) => updateItem(item.id, 'budget', v)} className="text-sm" />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => updateItem(item.id, 'actual', v)} className="text-sm" />
                 </div>
                 <div className="col-span-2 md:col-span-2 flex justify-end items-end pb-1">
                   <button onClick={(e) => deleteItem(e, item.id)} className="p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-colors" title="Hapus Item"><Trash2 size={16} /></button>
                 </div>
               </div>
             ))}
           </div>
           <button 
             onClick={addItem} 
             className={`w-full mt-4 py-3 border-2 border-dashed rounded-xl flex items-center justify-center gap-2 transition-all font-black text-xs uppercase tracking-widest ${selectedColor.button}`}
           >
             <Plus size={16} /> Tambah Item Ke {title}
           </button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState('');

  const calcTotalBudget = () => {
    const needs = (data.needs?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const savings = (data.savings?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const debt = (data.debt?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const custom = (data.custom || []).reduce((acc, cat) => (cat.items || []).reduce((ia, ii) => ia + (ii.budget || 0), acc), 0);
    const others = data.others?.allocation || 0;
    return needs + savings + debt + others + custom;
  };

  const calcTotalActual = () => {
    const needs = (data.needs?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const savings = (data.savings?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const debt = (data.debt?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const custom = (data.custom || []).reduce((acc, cat) => (cat.items || []).reduce((ia, ii) => ia + (ii.actual || 0), acc), 0);
    const others = (data.others?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    return needs + savings + debt + others + custom;
  };

  const confirmAddCategory = () => {
    if (!newCategoryName.trim()) {
      setIsAddingCategory(false);
      return;
    }
    const newCat: CustomBudgetCategory = { id: (Date.now() + Math.random()).toString(), name: newCategoryName.trim(), items: [] };
    const currentCustom = Array.isArray(data.custom) ? [...data.custom] : [];
    onChange({ ...data, custom: [...currentCustom, newCat] });
    setNewCategoryName('');
    setIsAddingCategory(false);
  };

  const updateCustomCategory = (id: string, items: BudgetItem[]) => {
    const currentCustom = Array.isArray(data.custom) ? data.custom : [];
    const newCustom = currentCustom.map(cat => cat.id === id ? { ...cat, items } : cat);
    onChange({ ...data, custom: newCustom });
  };

  // Fungsi hapus kategori kustom diperbaiki dengan spread operator yang aman
  const deleteCustomCategory = (id: string) => {
    const currentCustom = Array.isArray(data.custom) ? data.custom : [];
    const newCustom = currentCustom.filter(cat => cat.id !== id);
    onChange({ ...data, custom: newCustom });
  };

  // Fungsi pembantu untuk menghapus kategori standar
  const removeStandardCategory = (key: 'needs' | 'savings' | 'debt' | 'others') => {
    const newData = { ...data };
    delete newData[key];
    onChange(newData);
  };

  const totalAllocated = calcTotalBudget();
  const totalActual = calcTotalActual();
  const balance = income - totalActual;
  const isOverBudget = totalAllocated > income;

  return (
    <div className="space-y-6 sm:space-y-8 animate-fadeIn pb-10">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-indigo-500">
           <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Income Netto</p>
           <h3 className="text-xl font-black text-slate-100">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-blue-500">
           <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Total Anggaran</p>
           <h3 className={`text-xl font-black ${isOverBudget ? 'text-rose-400' : 'text-blue-400'}`}>{formatRupiah(totalAllocated)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-amber-500">
           <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Realisasi</p>
           <h3 className="text-xl font-black text-amber-400">{formatRupiah(totalActual)}</h3>
        </div>
        <div className={`glass-panel p-4 rounded-2xl border-l-4 ${balance < 0 ? 'border-rose-500' : 'border-emerald-500'}`}>
           <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Saldo Akhir</p>
           <h3 className={`text-xl font-black ${balance < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>{formatRupiah(balance)}</h3>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 pt-4 border-b border-slate-800 pb-5">
         <h2 className="text-xl font-black text-white uppercase flex items-center gap-2">
           <div className="w-2 h-6 bg-indigo-600 rounded-full"></div> DAFTAR ANGGARAN
         </h2>
         {!isAddingCategory ? (
           <button onClick={() => setIsAddingCategory(true)} className="w-full sm:w-auto px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-black flex items-center justify-center gap-2 transition-all uppercase tracking-widest">
             <FolderPlus size={18} /> TAMBAH KATEGORI BARU
           </button>
         ) : (
           <div className="flex w-full sm:w-auto items-center gap-2 animate-fadeIn">
             <input autoFocus type="text" value={newCategoryName} onChange={(e) => setNewCategoryName(e.target.value)} placeholder="Nama Kategori..." className="flex-1 sm:w-64 bg-slate-800 border-2 border-indigo-900/50 rounded-xl px-4 py-2 text-sm text-white focus:border-indigo-500 outline-none font-black" onKeyDown={(e) => e.key === 'Enter' && confirmAddCategory()} />
             <button onClick={confirmAddCategory} className="p-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-colors"><Check size={20}/></button>
             <button onClick={() => setIsAddingCategory(false)} className="p-2.5 bg-slate-700 text-slate-300 rounded-xl hover:bg-slate-600 transition-colors"><X size={20}/></button>
           </div>
         )}
      </div>

      <div className="space-y-4">
        {data.needs && (
          <CategorySection 
            title="Kebutuhan Pokok" 
            items={data.needs.items || []} 
            color="blue" 
            onDeleteCategory={() => removeStandardCategory('needs')} 
            onUpdateItems={(items) => onChange({ ...data, needs: { items } })} 
            defaultExpanded={false} 
          />
        )}
        {data.savings && (
          <CategorySection 
            title="Tabungan & Investasi" 
            items={data.savings.items || []} 
            color="emerald" 
            onDeleteCategory={() => removeStandardCategory('savings')} 
            onUpdateItems={(items) => onChange({ ...data, savings: { items } })} 
            defaultExpanded={false} 
          />
        )}
        {data.debt && (
          <CategorySection 
            title="Hutang & Cicilan" 
            items={data.debt.items || []} 
            color="red" 
            onDeleteCategory={() => removeStandardCategory('debt')} 
            onUpdateItems={(items) => onChange({ ...data, debt: { items } })} 
            defaultExpanded={false} 
          />
        )}
        {(Array.isArray(data.custom) ? data.custom : []).map(cat => (
          <CategorySection 
            key={cat.id} 
            title={cat.name} 
            items={cat.items || []} 
            color="purple" 
            isCustom={true} 
            defaultExpanded={false} 
            onUpdateItems={(items) => updateCustomCategory(cat.id, items)} 
            onDeleteCategory={() => deleteCustomCategory(cat.id)} 
          />
        ))}

        {data.others && (
          <div className="pt-6">
            <OthersCategorySection 
              allocation={data.others.allocation || 0}
              items={data.others.items || []}
              onUpdateAllocation={(val) => onChange({ ...data, others: { ...data.others!, allocation: val } })}
              onUpdateItems={(items) => onChange({ ...data, others: { ...data.others!, items } })}
              onDeleteCategory={() => removeStandardCategory('others')}
            />
          </div>
        )}

        {!data.needs && !data.savings && !data.debt && !data.others && (!data.custom || data.custom.length === 0) && (
          <div className="text-center py-20 glass-panel rounded-3xl border-dashed border-2 border-slate-700">
             <p className="text-slate-500 font-black uppercase tracking-widest text-sm mb-4">Daftar Anggaran Kosong</p>
             <button 
               onClick={() => onChange({ needs: { items: [] }, savings: { items: [] }, debt: { items: [] }, others: { allocation: 0, items: [] }, custom: [] })}
               className="px-6 py-3 bg-slate-800 text-white rounded-xl font-black text-xs uppercase hover:bg-slate-700 transition-all"
             >
               Reset Kategori Standar
             </button>
          </div>
        )}
      </div>
    </div>
  );
};

const OthersCategorySection: React.FC<{
  allocation: number;
  items: OtherBudgetItem[];
  onUpdateAllocation: (v: number) => void;
  onUpdateItems: (i: OtherBudgetItem[]) => void;
  onDeleteCategory: () => void;
}> = ({ allocation, items, onUpdateAllocation, onUpdateItems, onDeleteCategory }) => {
  const [expanded, setExpanded] = useState(false);
  const catTotalActual = items.reduce((a, b) => a + (b.actual || 0), 0);
  const catRemaining = allocation - catTotalActual;
  const isCatOver = catTotalActual > allocation;

  const totalItemsCount = items.length;
  const filledCount = items.filter(i => (i.actual || 0) > 0).length;
  const unfilledCount = totalItemsCount - filledCount;
  const realizationPercentage = allocation > 0 ? (catTotalActual / allocation) * 100 : 0;
  const isFull = totalItemsCount > 0 && unfilledCount === 0;

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    if (window.confirm('Apakah Anda yakin ingin menghapus kategori "Lain-lain / Hiburan"?')) {
      onDeleteCategory();
    }
  };

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/40 shadow-xl' : 'hover:shadow-lg'}`}>
      <div className="p-4 sm:p-5 flex justify-between items-center cursor-pointer hover:bg-white/5" onClick={() => setExpanded(!expanded)}>
        <div className="flex items-start gap-4 flex-1">
           <div className="p-3 rounded-xl bg-violet-900/30 text-violet-400">{expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}</div>
           <div className="flex-1">
             <div className="flex items-center gap-2 flex-wrap">
                <h4 className="font-black text-sm sm:text-base text-slate-100 uppercase tracking-tight">Lain-lain / Hiburan</h4>
                <div className="flex gap-1 flex-wrap">
                   <span className="text-[9px] font-black text-violet-300 bg-violet-900/40 px-2 py-0.5 rounded border border-violet-500/30 flex items-center gap-1">
                     {totalItemsCount} ITEM
                   </span>
                </div>
                <button 
                  onClick={handleDelete}
                  className="ml-2 p-1.5 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-all flex items-center gap-1"
                  title="Hapus Kategori"
                >
                  <Trash2 size={16} />
                  <span className="text-[9px] font-black uppercase hidden sm:inline">Hapus</span>
                </button>
             </div>
             <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-1 text-[9px] sm:text-[10px] font-black uppercase tracking-wider text-slate-400">
                <div>PLAFON: <span className="text-blue-400">{formatRupiah(allocation)}</span></div>
                <div>REALISASI: <span className={isCatOver ? 'text-rose-400' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></div>
                <div>SISA: <span className="text-indigo-400">{formatRupiah(catRemaining)}</span></div>
             </div>
           </div>
        </div>
        <div className="ml-2">
           <div className={`text-[10px] font-black px-2 py-1 rounded-lg ${isCatOver ? 'bg-rose-900/50 text-rose-300' : 'bg-indigo-900/50 text-indigo-300'}`}>
              {realizationPercentage.toFixed(0)}%
           </div>
        </div>
      </div>
      {expanded && (
        <div className="p-4 bg-slate-900/30 border-t border-slate-800 space-y-4">
           <CurrencyInput label="Set Alokasi Dana Lain-lain" value={allocation} onChange={onUpdateAllocation} />
           <div className="space-y-3">
             {items.map(item => (
               <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 p-3 bg-slate-800/40 rounded-xl border border-slate-700/50 items-end">
                 <div className="col-span-2 md:col-span-7">
                   <input value={item.name} onChange={e => onUpdateItems(items.map(i => i.id === item.id ? {...i, name: e.target.value} : i))} className="w-full bg-slate-900/50 rounded-lg p-2 text-sm text-white border border-slate-700 focus:border-indigo-500 font-black" placeholder="Nama pengeluaran..." />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Jumlah" value={item.actual} onChange={v => onUpdateItems(items.map(i => i.id === item.id ? {...i, actual: v} : i))} className="text-xs" />
                 </div>
                 <div className="col-span-1 md:col-span-2 flex justify-end pb-1">
                   <button onClick={() => { if(window.confirm('Hapus item ini?')) onUpdateItems(items.filter(i => i.id !== item.id)); }} className="p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-colors"><Trash2 size={16} /></button>
                 </div>
               </div>
             ))}
           </div>
           <button onClick={() => onUpdateItems([...items, {id: (Date.now() + Math.random()).toString(), name: '', actual: 0}])} className="w-full py-3 border-2 border-dashed border-violet-900/50 text-violet-400 bg-violet-900/10 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-violet-900/20 transition-all">
             <Plus size={14} className="inline mr-1"/> Tambah Pengeluaran Lainnya
           </button>
        </div>
      )}
    </div>
