import React, { useState, useEffect, useCallback } from 'react';
import { AppState, MonthlyData, DEFAULT_SALARY, DEFAULT_BUDGET } from './types';
import SalarySlip from './components/SalarySlip';
import Budget from './components/Budget';
import MonthlyCharts from './components/MonthlyCharts';
import Investments from './components/Investments';
import YearlySummary from './components/YearlySummary';
import { calculateGrossIncome, calculateTax, calculateOvertime, calculateBonus } from './utils';
import { Wallet, LayoutDashboard, PieChart, TrendingUp, Calendar, ChevronLeft, ChevronRight, Cloud, Loader2, CheckCircle2 } from 'lucide-react';
import { supabase } from './supabaseClient';

const TABS = [
  { id: 'salary', label: 'Gaji', icon: Wallet },
  { id: 'budget', label: 'Anggaran', icon: LayoutDashboard },
  { id: 'charts', label: 'Grafik', icon: PieChart },
  { id: 'invest', label: 'Aset', icon: TrendingUp },
  { id: 'year', label: 'Tahunan', icon: Calendar },
];

const App: React.FC = () => {
  // State
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');

  // App State is initially empty until loaded from DB
  const [appState, setAppState] = useState<AppState>({});

  // UI States
  const [isLoading, setIsLoading] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  // Derived State
  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  // --- DATABASE LOGIC START ---

  // 1. Load Data on Mount
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase
          .from('monthly_finance')
          .select('month_id, data');

        if (error) throw error;

        if (data) {
          const loadedState: AppState = {};
          data.forEach((row: any) => {
            loadedState[row.month_id] = row.data;
          });
          setAppState(loadedState);
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  // 2. Debounced Save Logic - Accelerated to 800ms
  useEffect(() => {
    if (isLoading) return;
    if (!appState[currentMonthKey]) return;

    const saveData = async () => {
      setSaveStatus('saving');
      try {
        const { error } = await supabase
          .from('monthly_finance')
          .upsert({ 
            month_id: currentMonthKey, 
            data: appState[currentMonthKey],
            updated_at: new Date().toISOString()
          });

        if (error) throw error;
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } catch (err) {
        console.error("Error saving data:", err);
        setSaveStatus('error');
      }
    };

    const timeoutId = setTimeout(saveData, 800);
    return () => clearTimeout(timeoutId);

  }, [appState, currentMonthKey, isLoading]);

  // Helper: Income Calculation
  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     const tax = calculateTax(gross, salary.taxRate);
     return gross - tax - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  // Month Change & Initialization Logic
  useEffect(() => {
    if (!isLoading && !appState[currentMonthKey]) {
      const prevDate = new Date(currentDate);
      prevDate.setMonth(currentDate.getMonth() - 1);
      const pKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;

      if (appState[pKey]) {
        setPrevMonthKey(pKey);
        setShowCopyModal(true);
      } else {
        initializeMonth(false);
      }
    }
  }, [currentMonthKey, isLoading]);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      const prev = appState[prevMonthKey];
      newData = JSON.parse(JSON.stringify(prev));
      // Reset actual values when copying
      if (newData.budget.needs) newData.budget.needs.items.forEach(i => i.actual = 0);
      if (newData.budget.savings) newData.budget.savings.items.forEach(i => i.actual = 0);
      if (newData.budget.debt) newData.budget.debt.items.forEach(i => i.actual = 0);
      if (newData.budget.others) newData.budget.others.items.forEach(i => i.actual = 0);
      if (newData.budget.custom) {
        newData.budget.custom.forEach(cat => cat.items.forEach(i => i.actual = 0));
      }
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = {
        salary: { ...DEFAULT_SALARY },
        budget: { ...DEFAULT_BUDGET },
        investments: []
      };
    }

    setAppState(prev => ({
      ...prev,
      [currentMonthKey]: newData
    }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => {
      const existing = prev[currentMonthKey] || {
        salary: { ...DEFAULT_SALARY },
        budget: { ...DEFAULT_BUDGET },
        investments: []
      };

      // LOGIKA KRUSIAL: Jika newData memiliki key 'budget', 
      // kita harus mengganti objek budget tersebut sepenuhnya (bukan merge property-by-property),
      // agar properti yang dihapus di level Budget.tsx benar-benar hilang.
      return {
        ...prev,
        [currentMonthKey]: { ...existing, ...newData }
      };
    });
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#0f172a]">
        <div className="flex flex-col items-center gap-3">
          <Loader2 className="w-10 h-10 text-indigo-400 animate-spin" />
          <p className="text-slate-400 font-black uppercase tracking-widest animate-pulse">Menghubungkan Database...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0f172a] font-sans selection:bg-indigo-500/30 selection:text-indigo-200">
      <nav className="sticky top-0 z-50 pt-2 px-2 sm:pt-4 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl border border-white/5">
          <div className="flex flex-col sm:flex-row items-center justify-between p-3 sm:px-6 sm:h-20 gap-3">
            <div className="flex items-center justify-between w-full sm:w-auto">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-lg shadow-lg shadow-indigo-900/50">
                     <Wallet className="text-white h-5 w-5 sm:h-6 sm:w-6" />
                  </div>
                  <div>
                    <h1 className="text-sm sm:text-xl font-black tracking-tight text-white leading-tight uppercase">ANIQ SUSILO</h1>
                    <p className="text-[9px] sm:text-[10px] text-indigo-400 font-black tracking-[0.2em] uppercase">Finance Monthly</p>
                  </div>
                </div>

                <div className="flex sm:hidden items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
                   <button onClick={() => changeMonth(-1)} className="p-1.5 hover:bg-slate-700 rounded-md transition-colors text-slate-400">
                     <ChevronLeft size={16} />
                   </button>
                   <div className="px-2 font-mono font-black text-indigo-400 text-xs text-center min-w-[80px]">
                     {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' }).toUpperCase()}
                   </div>
                   <button onClick={() => changeMonth(1)} className="p-1.5 hover:bg-slate-700 rounded-md transition-colors text-slate-400">
                     <ChevronRight size={16} />
                   </button>
                </div>
            </div>

            <div className="flex items-center gap-4">
                <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-slate-800/50 rounded-lg border border-slate-700/50">
                  {saveStatus === 'saving' && (
                    <>
                      <Loader2 size={14} className="animate-spin text-indigo-400" />
                      <span className="text-xs text-slate-400 font-black uppercase">Simpan...</span>
                    </>
                  )}
                  {saveStatus === 'saved' && (
                    <>
                      <CheckCircle2 size={14} className="text-emerald-400" />
                      <span className="text-xs text-emerald-400 font-black uppercase">Selesai</span>
                    </>
                  )}
                  {saveStatus === 'error' && (
                    <span className="text-xs text-rose-400 font-black uppercase">Error</span>
                  )}
                  {saveStatus === 'idle' && (
                     <span className="text-xs text-slate-500 font-black flex items-center gap-1 uppercase tracking-tighter"><Cloud size={12}/> Sinkronisasi</span>
                  )}
                </div>

                <div className="hidden sm:flex items-center bg-slate-800/80 rounded-xl p-1.5 border border-slate-700 shadow-sm">
                  <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-700 rounded-lg transition-colors text-slate-500 hover:text-indigo-400">
                    <ChevronLeft size={20} />
                  </button>
                  <div className="px-3 sm:px-6 font-mono font-black text-indigo-400 w-32 sm:w-48 text-center text-sm sm:text-base uppercase tracking-wider">
                    {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' }).toUpperCase()}
                  </div>
                  <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-700 rounded-lg transition-colors text-slate-500 hover:text-indigo-400">
                    <ChevronRight size={20} />
                  </button>
                </div>
            </div>
          </div>

          <div className="border-t border-slate-700/50">
            <div className="px-2 overflow-x-auto scrollbar-hide">
              <div className="flex space-x-1 py-1.5 sm:py-2">
                {TABS.map((tab) => {
                  const Icon = tab.icon;
                  const isActive = activeTab === tab.id;
                  return (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id)}
                      className={`
                        flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs sm:text-sm font-black rounded-lg sm:rounded-xl whitespace-nowrap transition-all duration-200 relative overflow-hidden flex-1 justify-center sm:flex-none uppercase tracking-widest
                        ${isActive 
                          ? 'text-white bg-indigo-600 shadow-lg shadow-indigo-900/40' 
                          : 'text-slate-400 hover:text-white hover:bg-slate-800'}
                      `}
                    >
                      <Icon size={16} className={isActive ? 'text-white' : ''} />
                      {tab.label}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && (
          <SalarySlip 
            data={currentData.salary} 
            onChange={(s) => updateCurrentData({ salary: s })} 
          />
        )}
        {activeTab === 'budget' && (
          <Budget 
            income={currentNetIncome} 
            data={currentData.budget} 
            onChange={(b) => updateCurrentData({ budget: b })} 
          />
        )}
        {activeTab === 'charts' && (
          <MonthlyCharts 
            budgetData={currentData.budget} 
            income={currentNetIncome} 
          />
        )}
        {activeTab === 'invest' && (
          <Investments 
            items={currentData.investments} 
            onChange={(i) => updateCurrentData({ investments: i })} 
          />
        )}
        {activeTab === 'year' && (
          <YearlySummary 
            appState={appState} 
            year={currentDate.getFullYear()} 
          />
        )}
      </main>

      {showCopyModal && (
        <div className="fixed inset-0 bg-slate-950/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="bg-slate-900 p-6 sm:p-8 rounded-3xl max-w-md w-full shadow-2xl animate-fadeIn border border-slate-800">
              <h3 className="text-xl sm:text-2xl font-black text-white mb-2 uppercase tracking-tight">Bulan Baru</h3>
              <p className="text-slate-400 mb-8 leading-relaxed text-sm sm:text-base font-black">Data bulan ini belum ada di Database. Salin template dari bulan sebelumnya?</p>
              <div className="flex gap-4">
                <button 
                  onClick={() => initializeMonth(true)}
                  className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white py-3 rounded-xl font-black transition-all shadow-lg shadow-indigo-900/50 text-sm sm:text-base uppercase tracking-widest"
                >
                  Salin Data
                </button>
                <button 
                  onClick={() => initializeMonth(false)}
                  className="flex-1 bg-slate-800 hover:bg-slate-700 text-slate-200 py-3 rounded-xl font-black transition-colors border border-slate-700 text-sm sm:text-base uppercase tracking-widest"
                >
                  Buat Baru
                </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { BudgetData, BudgetItem, OtherBudgetItem, CustomBudgetCategory } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, FolderPlus, X, Check, CheckCircle2, Clock, AlertCircle } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  color: 'blue' | 'emerald' | 'red' | 'purple' | 'violet';
  onUpdateItems: (items: BudgetItem[]) => void;
  onDeleteCategory: () => void;
  isCustom?: boolean;
  defaultExpanded?: boolean;
  canDelete?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems,
  onDeleteCategory,
  isCustom = false,
  defaultExpanded = false,
  canDelete = true
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);

  const catTotalAllocated = items.reduce((a, b) => a + (b.budget || 0), 0);
  const catTotalActual = items.reduce((a, b) => a + (b.actual || 0), 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;

  const totalItemsCount = items.length;

  const addItem = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newItem: BudgetItem = { id: (Date.now() + Math.random()).toString(), name: '', budget: 0, actual: 0 };
    onUpdateItems([...items, newItem]);
    setExpanded(true);
  };

  const updateItem = (id: string, field: keyof BudgetItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onUpdateItems(newItems);
  };

  const handleDeleteItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    e.preventDefault();
    if (window.confirm('Hapus item ini dari daftar anggaran?')) {
      const newItems = items.filter(item => item.id !== id);
      onUpdateItems(newItems);
    }
  };

  const handleDeleteCategory = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    if (window.confirm(`HAPUS SELURUH KATEGORI: "${title}"?\n\nSemua data di dalamnya akan hilang permanen.`)) {
      onDeleteCategory();
    }
  };

  const colorsMap = {
    blue: { icon: 'text-blue-400 bg-blue-900/30', button: 'border-blue-900/50 text-blue-400 hover:bg-blue-900/20' },
    emerald: { icon: 'text-emerald-400 bg-emerald-900/30', button: 'border-emerald-900/50 text-emerald-400 hover:bg-emerald-900/20' },
    red: { icon: 'text-red-400 bg-red-900/30', button: 'border-red-900/50 text-red-400 hover:bg-red-900/20' },
    purple: { icon: 'text-purple-400 bg-purple-900/30', button: 'border-purple-900/50 text-purple-400 hover:bg-purple-900/20' },
    violet: { icon: 'text-violet-400 bg-violet-900/30', button: 'border-violet-200 text-violet-400 hover:bg-violet-900/20' }
  };

  const selectedColor = colorsMap[color] || colorsMap.blue;

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden mb-4 transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/40 shadow-xl' : 'hover:shadow-lg'}`}>
      {/* Container Header - SEPARATED INTERACTIONS */}
      <div className="flex items-stretch border-b border-slate-800/30">
        {/* Toggle Area */}
        <div 
          className="flex-1 p-4 sm:p-5 flex items-center gap-3 sm:gap-4 cursor-pointer hover:bg-white/5 transition-colors"
          onClick={() => setExpanded(!expanded)}
        >
          <div className={`p-2.5 rounded-xl ${selectedColor.icon}`}>
            {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
          </div>
          <div className="flex-1 min-w-0">
             <div className="flex items-center gap-2">
                <h4 className="font-black text-sm sm:text-base text-slate-100 uppercase tracking-tight truncate">{title}</h4>
                <span className="text-[9px] font-black text-slate-500 bg-slate-900/50 px-2 py-0.5 rounded border border-slate-700/50">
                  {totalItemsCount} ITEM
                </span>
             </div>
             <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-1 text-[9px] font-black uppercase tracking-wider text-slate-400">
                <span>AKTUAL: <span className={isCatOver ? 'text-rose-400' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></span>
                <span>SISA: <span className="text-indigo-400">{formatRupiah(catRemaining)}</span></span>
             </div>
          </div>
        </div>

        {/* Action Area (Hapus) */}
        {canDelete && (
          <div className="flex items-center px-3 sm:px-4 border-l border-slate-800/50 bg-slate-900/20">
            <button 
              onClick={handleDeleteCategory}
              className="p-3 text-slate-500 hover:text-rose-400 hover:bg-rose-900/30 rounded-xl transition-all flex items-center gap-2 group/del"
              title="Hapus Kategori"
            >
              <Trash2 size={18} className="pointer-events-none group-hover/del:scale-110 transition-transform" />
              <span className="hidden lg:inline text-[10px] font-black uppercase tracking-widest">Hapus</span>
            </button>
          </div>
        )}
      </div>

      {expanded && (
        <div className="p-3 sm:p-5 bg-slate-900/30">
           <div className="space-y-3">
             {items.map((item) => (
               <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 p-3 sm:p-4 bg-slate-800/40 rounded-xl border border-slate-700/50">
                 <div className="col-span-2 md:col-span-4">
                   <label className="text-[9px] uppercase font-black text-slate-500 mb-1 block">Nama Item</label>
                   <input 
                     type="text" 
                     value={item.name} 
                     onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                     className="w-full bg-slate-900/50 rounded-lg p-2 text-slate-100 text-sm border border-slate-700 focus:border-indigo-500 outline-none font-black"
                   />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Anggaran" value={item.budget} onChange={(v) => updateItem(item.id, 'budget', v)} className="text-sm" />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => updateItem(item.id, 'actual', v)} className="text-sm" />
                 </div>
                 <div className="col-span-2 md:col-span-2 flex justify-end items-end pb-1">
                   <button 
                     onClick={(e) => handleDeleteItem(e, item.id)} 
                     className="p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-colors" 
                     title="Hapus Item"
                   >
                     <Trash2 size={16} className="pointer-events-none" />
                   </button>
                 </div>
               </div>
             ))}
           </div>
           <button 
             onClick={addItem} 
             className={`w-full mt-4 py-3 border-2 border-dashed rounded-xl flex items-center justify-center gap-2 transition-all font-black text-xs uppercase tracking-widest ${selectedColor.button}`}
           >
             <Plus size={16} /> Tambah Item Ke {title}
           </button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState('');

  const calcTotalBudget = () => {
    const needs = (data.needs?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const savings = (data.savings?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const debt = (data.debt?.items || []).reduce((acc, item) => acc + (item.budget || 0), 0);
    const custom = (data.custom || []).reduce((acc, cat) => (cat.items || []).reduce((ia, ii) => ia + (ii.budget || 0), acc), 0);
    const others = data.others?.allocation || 0;
    return needs + savings + debt + others + custom;
  };

  const calcTotalActual = () => {
    const needs = (data.needs?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const savings = (data.savings?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const debt = (data.debt?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    const custom = (data.custom || []).reduce((acc, cat) => (cat.items || []).reduce((ia, ii) => ia + (ii.actual || 0), acc), 0);
    const others = (data.others?.items || []).reduce((acc, item) => acc + (item.actual || 0), 0);
    return needs + savings + debt + others + custom;
  };

  const confirmAddCategory = () => {
    if (!newCategoryName.trim()) {
      setIsAddingCategory(false);
      return;
    }
    const newCat: CustomBudgetCategory = { id: (Date.now() + Math.random()).toString(), name: newCategoryName.trim(), items: [] };
    const currentCustom = Array.isArray(data.custom) ? [...data.custom] : [];
    onChange({ ...data, custom: [...currentCustom, newCat] });
    setNewCategoryName('');
    setIsAddingCategory(false);
  };

  const updateCustomCategory = (id: string, items: BudgetItem[]) => {
    const currentCustom = Array.isArray(data.custom) ? data.custom : [];
    const newCustom = currentCustom.map(cat => cat.id === id ? { ...cat, items } : cat);
    onChange({ ...data, custom: newCustom });
  };

  const deleteCustomCategory = (id: string) => {
    const currentCustom = Array.isArray(data.custom) ? data.custom : [];
    const newCustom = currentCustom.filter(cat => cat.id !== id);
    onChange({ ...data, custom: newCustom });
  };

  const removeStandardCategory = (key: 'needs' | 'savings' | 'debt' | 'others') => {
    // CLONE & DELETE: This ensures the key is completely gone from the next state
    const newData = { ...data };
    delete newData[key];
    onChange(newData);
  };

  const totalAllocated = calcTotalBudget();
  const totalActual = calcTotalActual();
  const balance = income - totalActual;
  const isOverBudget = totalAllocated > income;

  const isBudgetEmpty = !data.needs && !data.savings && !data.debt && !data.others && (!data.custom || data.custom.length === 0);

  return (
    <div className="space-y-6 sm:space-y-8 animate-fadeIn pb-10">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-indigo-500">
           <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Income Netto</p>
           <h3 className="text-xl font-black text-slate-100">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-blue-500">
           <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Total Anggaran</p>
           <h3 className={`text-xl font-black ${isOverBudget ? 'text-rose-400' : 'text-blue-400'}`}>{formatRupiah(totalAllocated)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-amber-500">
           <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Realisasi</p>
           <h3 className="text-xl font-black text-amber-400">{formatRupiah(totalActual)}</h3>
        </div>
        <div className={`glass-panel p-4 rounded-2xl border-l-4 ${balance < 0 ? 'border-rose-500' : 'border-emerald-500'}`}>
           <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Saldo Akhir</p>
           <h3 className={`text-xl font-black ${balance < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>{formatRupiah(balance)}</h3>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 pt-4 border-b border-slate-800 pb-5">
         <h2 className="text-xl font-black text-white uppercase flex items-center gap-2">
           <div className="w-2 h-6 bg-indigo-600 rounded-full"></div> DAFTAR ANGGARAN
         </h2>
         {!isAddingCategory ? (
           <button onClick={() => setIsAddingCategory(true)} className="w-full sm:w-auto px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-black flex items-center justify-center gap-2 transition-all uppercase tracking-widest">
             <FolderPlus size={18} /> TAMBAH KATEGORI BARU
           </button>
         ) : (
           <div className="flex w-full sm:w-auto items-center gap-2 animate-fadeIn">
             <input autoFocus type="text" value={newCategoryName} onChange={(e) => setNewCategoryName(e.target.value)} placeholder="Nama Kategori..." className="flex-1 sm:w-64 bg-slate-800 border-2 border-indigo-900/50 rounded-xl px-4 py-2 text-sm text-white focus:border-indigo-500 outline-none font-black" onKeyDown={(e) => e.key === 'Enter' && confirmAddCategory()} />
             <button onClick={confirmAddCategory} className="p-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-colors"><Check size={20}/></button>
             <button onClick={() => setIsAddingCategory(false)} className="p-2.5 bg-slate-700 text-slate-300 rounded-xl hover:bg-slate-600 transition-colors"><X size={20}/></button>
           </div>
         )}
      </div>

      <div className="space-y-4">
        {data.needs && (
          <CategorySection 
            title="Kebutuhan Pokok" 
            items={data.needs.items || []} 
            color="blue" 
            onDeleteCategory={() => removeStandardCategory('needs')} 
            onUpdateItems={(items) => onChange({ ...data, needs: { items } })} 
            defaultExpanded={false} 
          />
        )}
        {data.savings && (
          <CategorySection 
            title="Tabungan & Investasi" 
            items={data.savings.items || []} 
            color="emerald" 
            onDeleteCategory={() => removeStandardCategory('savings')} 
            onUpdateItems={(items) => onChange({ ...data, savings: { items } })} 
            defaultExpanded={false} 
          />
        )}
        {data.debt && (
          <CategorySection 
            title="Hutang & Cicilan" 
            items={data.debt.items || []} 
            color="red" 
            onDeleteCategory={() => removeStandardCategory('debt')} 
            onUpdateItems={(items) => onChange({ ...data, debt: { items } })} 
            defaultExpanded={false} 
          />
        )}
        {(Array.isArray(data.custom) ? data.custom : []).map(cat => (
          <CategorySection 
            key={cat.id} 
            title={cat.name} 
            items={cat.items || []} 
            color="purple" 
            isCustom={true} 
            defaultExpanded={false} 
            onUpdateItems={(items) => updateCustomCategory(cat.id, items)} 
            onDeleteCategory={() => deleteCustomCategory(cat.id)} 
          />
        ))}

        {data.others && (
          <div className="pt-6">
            <OthersCategorySection 
              allocation={data.others.allocation || 0}
              items={data.others.items || []}
              onUpdateAllocation={(val) => onChange({ ...data, others: { ...data.others!, allocation: val } })}
              onUpdateItems={(items) => onChange({ ...data, others: { ...data.others!, items } })}
              onDeleteCategory={() => removeStandardCategory('others')}
            />
          </div>
        )}

        {isBudgetEmpty && (
          <div className="text-center py-16 px-6 glass-panel rounded-3xl border-dashed border-2 border-slate-700 animate-fadeIn">
             <div className="flex justify-center mb-4">
                <AlertCircle size={48} className="text-slate-600 opacity-30" />
             </div>
             <p className="text-slate-500 font-black uppercase tracking-widest text-sm mb-6">Daftar Anggaran Kosong</p>
             <button 
               onClick={() => onChange({ 
                 needs: { items: [] }, 
                 savings: { items: [] }, 
                 debt: { items: [] }, 
                 others: { allocation: 0, items: [] }, 
                 custom: [] 
               })}
               className="px-8 py-4 bg-indigo-600/20 text-indigo-400 border border-indigo-500/30 rounded-2xl font-black text-xs uppercase hover:bg-indigo-600 hover:text-white transition-all tracking-widest"
             >
               Reset Kategori Standar
             </button>
          </div>
        )}
      </div>
    </div>
  );
};

const OthersCategorySection: React.FC<{
  allocation: number;
  items: OtherBudgetItem[];
  onUpdateAllocation: (v: number) => void;
  onUpdateItems: (i: OtherBudgetItem[]) => void;
  onDeleteCategory: () => void;
}> = ({ allocation, items, onUpdateAllocation, onUpdateItems, onDeleteCategory }) => {
  const [expanded, setExpanded] = useState(false);
  const catTotalActual = items.reduce((a, b) => a + (b.actual || 0), 0);
  const catRemaining = allocation - catTotalActual;
  const isCatOver = catTotalActual > allocation;

  const totalItemsCount = items.length;

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    if (window.confirm('HAPUS KATEGORI: "Lain-lain / Hiburan"?\n\nSeluruh data pengeluaran lainnya akan dihapus.')) {
      onDeleteCategory();
    }
  };

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/40 shadow-xl' : 'hover:shadow-lg'}`}>
      <div className="flex items-stretch border-b border-slate-800/30">
        <div className="flex-1 p-4 sm:p-5 flex items-center gap-4 cursor-pointer hover:bg-white/5" onClick={() => setExpanded(!expanded)}>
           <div className="p-3 rounded-xl bg-violet-900/30 text-violet-400">{expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}</div>
           <div className="flex-1 min-w-0">
                <h4 className="font-black text-sm sm:text-base text-slate-100 uppercase tracking-tight">Lain-lain / Hiburan</h4>
                <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-1 text-[9px] font-black uppercase tracking-wider text-slate-400">
                  <span>PLAFON: <span className="text-blue-400">{formatRupiah(allocation)}</span></span>
                  <span>SISA: <span className="text-indigo-400">{formatRupiah(catRemaining)}</span></span>
                  <span className="text-violet-400">{totalItemsCount} ITEM</span>
                </div>
           </div>
        </div>
        <div className="flex items-center px-3 sm:px-4 bg-slate-900/20">
          <button 
            onClick={handleDelete}
            className="p-3 text-slate-500 hover:text-rose-400 hover:bg-rose-900/30 rounded-xl transition-all flex items-center gap-1 group/del"
            title="Hapus Kategori"
          >
            <Trash2 size={18} className="pointer-events-none group-hover/del:scale-110 transition-transform" />
          </button>
        </div>
      </div>

      {expanded && (
        <div className="p-4 bg-slate-900/30 space-y-4">
           <CurrencyInput label="Set Alokasi Dana Lain-lain" value={allocation} onChange={onUpdateAllocation} />
           <div className="space-y-3">
             {items.map(item => (
               <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 p-3 bg-slate-800/40 rounded-xl border border-slate-700/50 items-end">
                 <div className="col-span-2 md:col-span-7">
                   <input value={item.name} onChange={e => onUpdateItems(items.map(i => i.id === item.id ? {...i, name: e.target.value} : i))} className="w-full bg-slate-900/50 rounded-lg p-2 text-sm text-white border border-slate-700 focus:border-indigo-500 font-black" placeholder="Nama pengeluaran..." />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Jumlah" value={item.actual} onChange={v => onUpdateItems(items.map(i => i.id === item.id ? {...i, actual: v} : i))} className="text-xs" />
                 </div>
                 <div className="col-span-1 md:col-span-2 flex justify-end pb-1">
                   <button 
                    onClick={() => { if(window.confirm('Hapus item ini?')) onUpdateItems(items.filter(i => i.id !== item.id)); }} 
                    className="p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-colors"
                   >
                     <Trash2 size={16} className="pointer-events-none" />
                   </button>
                 </div>
               </div>
             ))}
           </div>
           <button onClick={() => onUpdateItems([...items, {id: (Date.now() + Math.random()).toString(), name: '', actual: 0}])} className="w-full py-3 border-2 border-dashed border-violet-900/50 text-violet-400 bg-violet-900/10 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-violet-900/20 transition-all">
             <Plus size={14} className="inline mr-1"/> Tambah Pengeluaran Lainnya
           </button>
        </div>
      )}
    </div>
  );
};

export default Budget;

import React from 'react';
import { InvestmentItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { Plus, Trash2, TrendingUp, Target, Briefcase, PieChart as PieChartIcon } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

interface InvestmentsProps {
  items: InvestmentItem[];
  onChange: (items: InvestmentItem[]) => void;
}

const COLORS = ['#6366F1', '#3B82F6', '#10B981', '#F59E0B', '#F43F5E', '#8B5CF6'];

const Investments: React.FC<InvestmentsProps> = ({ items, onChange }) => {
  const addItem = () => {
    const newItem: InvestmentItem = { id: Date.now().toString(), name: '', currentValue: 0, targetValue: 0 };
    onChange([...items, newItem]);
  };

  const updateItem = (id: string, field: keyof InvestmentItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onChange(newItems);
  };

  const handleDeleteItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    e.preventDefault();
    if (window.confirm('Hapus aset ini dari portofolio Anda?')) {
      const filtered = items.filter(item => item.id !== id);
      onChange(filtered);
    }
  };

  const totalPortfolio = items.reduce((acc, item) => acc + (item.currentValue || 0), 0);
  const totalTarget = items.reduce((acc, item) => acc + (item.targetValue || 0), 0);
  const progress = totalTarget > 0 ? (totalPortfolio / totalTarget) * 100 : 0;

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 sm:gap-6">
        <div className="glass-panel p-6 sm:p-8 rounded-2xl relative overflow-hidden border border-indigo-900/30">
           <div className="absolute top-0 right-0 p-4 sm:p-8 opacity-5">
              <TrendingUp size={140} className="text-indigo-400" />
           </div>
           <div className="relative z-10">
             <div className="flex items-center gap-2 mb-2">
               <div className="p-2 bg-indigo-900/30 rounded-lg text-indigo-400 border border-indigo-500/20"><Briefcase size={20} /></div>
               <h3 className="text-slate-400 font-black text-xs sm:text-sm uppercase tracking-wider">Total Aset</h3>
             </div>
             <div className="text-3xl sm:text-4xl md:text-5xl font-black text-white tracking-tight mb-4 sm:mb-6">{formatRupiah(totalPortfolio)}</div>
             <div className="bg-slate-800/50 p-3 sm:p-4 rounded-xl border border-slate-700 shadow-sm">
                <div className="flex justify-between text-[10px] sm:text-xs font-black uppercase tracking-wider text-slate-400 mb-2">
                  <span>Progress Target Global</span>
                  <span className="text-indigo-400">{progress.toFixed(1)}%</span>
                </div>
                <div className="w-full bg-slate-900 h-2 sm:h-2.5 rounded-full overflow-hidden border border-slate-800">
                  <div className="bg-gradient-to-r from-indigo-600 to-blue-500 h-full rounded-full transition-all duration-1000 ease-out shadow-lg" style={{ width: `${Math.min(progress, 100)}%` }}></div>
                </div>
             </div>
           </div>
        </div>

        <div className="glass-panel p-4 sm:p-6 rounded-2xl flex flex-col justify-center items-center relative min-h-[320px]">
