import React from 'react';
import { InvestmentItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { Plus, Trash2, TrendingUp, Target, Briefcase, PieChart as PieChartIcon } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

interface InvestmentsProps {
  items: InvestmentItem[];
  onChange: (items: InvestmentItem[]) => void;
}

const COLORS = ['#6366F1', '#3B82F6', '#10B981', '#F59E0B', '#F43F5E', '#8B5CF6'];

const Investments: React.FC<InvestmentsProps> = ({ items, onChange }) => {
  const addItem = () => {
    const newItem: InvestmentItem = { id: Date.now().toString(), name: '', currentValue: 0, targetValue: 0 };
    onChange([...items, newItem]);
  };

  const updateItem = (id: string, field: keyof InvestmentItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onChange(newItems);
  };

  const handleDeleteItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    e.preventDefault();
    const itemToDelete = items.find(i => i.id === id);
    if (window.confirm(`Hapus aset "${itemToDelete?.name || 'ini'}" dari portofolio Anda?`)) {
      const filtered = items.filter(item => item.id !== id);
      onChange(filtered);
    }
  };

  const totalPortfolio = items.reduce((acc, item) => acc + (item.currentValue || 0), 0);
  const totalTarget = items.reduce((acc, item) => acc + (item.targetValue || 0), 0);
  const progress = totalTarget > 0 ? (totalPortfolio / totalTarget) * 100 : 0;

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 sm:gap-6">
        <div className="glass-panel p-6 sm:p-8 rounded-2xl relative overflow-hidden border border-indigo-900/30">
           <div className="absolute top-0 right-0 p-4 sm:p-8 opacity-5">
              <TrendingUp size={140} className="text-indigo-400" />
           </div>
           <div className="relative z-10">
             <div className="flex items-center gap-2 mb-2">
               <div className="p-2 bg-indigo-900/30 rounded-lg text-indigo-400 border border-indigo-500/20"><Briefcase size={20} /></div>
               <h3 className="text-slate-400 font-black text-xs sm:text-sm uppercase tracking-wider">Total Aset</h3>
             </div>
             <div className="text-3xl sm:text-4xl md:text-5xl font-black text-white tracking-tight mb-4 sm:mb-6">{formatRupiah(totalPortfolio)}</div>
             <div className="bg-slate-800/50 p-3 sm:p-4 rounded-xl border border-slate-700 shadow-sm">
                <div className="flex justify-between text-[10px] sm:text-xs font-black uppercase tracking-wider text-slate-400 mb-2">
                  <span>Progress Target Global</span>
                  <span className="text-indigo-400">{progress.toFixed(1)}%</span>
                </div>
                <div className="w-full bg-slate-900 h-2 sm:h-2.5 rounded-full overflow-hidden border border-slate-800">
                  <div className="bg-gradient-to-r from-indigo-600 to-blue-500 h-full rounded-full transition-all duration-1000 ease-out shadow-lg" style={{ width: `${Math.min(progress, 100)}%` }}></div>
                </div>
             </div>
           </div>
        </div>

        <div className="glass-panel p-4 sm:p-6 rounded-2xl flex flex-col justify-center items-center relative min-h-[320px]">
          <h3 className="absolute top-4 left-4 sm:top-6 sm:left-6 text-slate-400 font-black text-xs sm:text-sm uppercase tracking-wider">Distribusi Aset</h3>
          <div className="w-full h-full mt-12 flex items-center justify-center">
            {items.length > 0 && totalPortfolio > 0 ? (
              <ResponsiveContainer width="100%" height={260}>
                <PieChart margin={{ top: 10, right: 60, bottom: 10, left: 60 }}>
                  <Pie
                    data={items.filter(i => (i.currentValue || 0) > 0)}
                    cx="50%"
                    cy="50%"
                    innerRadius={45}
                    outerRadius={65} 
                    paddingAngle={5}
                    dataKey="currentValue"
                    stroke="#1e293b"
                    strokeWidth={2}
                    label={({ percent }) => `${(percent * 100).toFixed(0)}%`}
                    labelLine={{ stroke: '#94a3b8', strokeWidth: 1.5, length: 20 }}
                  >
                    {items.filter(i => (i.currentValue || 0) > 0).map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip 
                    formatter={(value: number) => formatRupiah(value)}
                    contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.5)', color: '#f8fafc' }}
                  />
                </PieChart>
              </ResponsiveContainer>
            ) : (
               <div className="flex flex-col items-center justify-center text-slate-500 gap-2">
                 <PieChartIcon size={40} className="opacity-20" />
                 <span className="text-xs sm:text-sm font-black uppercase tracking-widest">Belum ada data visualisasi</span>
               </div>
            )}
          </div>
        </div>
      </div>

      <div className="glass-panel rounded-2xl overflow-hidden border border-slate-800">
         <div className="p-4 sm:p-6 border-b border-slate-800 flex justify-between items-center bg-slate-800/30">
