            <button type="button" onClick={addItem} className="px-3 py-2 sm:px-5 sm:py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl flex items-center gap-2 text-xs sm:text-sm font-bold transition-all shadow-lg shadow-indigo-900/40 uppercase tracking-widest"><Plus size={16} /> Tambah</button>
