                  </div>
                  <div className="col-span-2 md:col-span-3">
                    <CurrencyInput label="Target Dana" value={item.targetValue} onChange={(v) => updateItem(item.id, 'targetValue', v)} className="text-sm" />
                  </div>
                  <div className="col-span-2 md:col-span-2 flex justify-between items-center pl-2 pt-2 sm:pt-0">
                    <div className="text-xs text-slate-500">
                       {item.targetValue > 0 && (
                         <span className="flex items-center gap-1.5 bg-slate-900/50 px-2 py-1 rounded-lg border border-indigo-500/20">
                           <Target size={12} className="text-indigo-400" /> 
                           <span className="font-mono font-black text-indigo-400">{((item.currentValue / item.targetValue) * 100).toFixed(0)}%</span>
                         </span>
