             <button onClick={()=>setIsAdding(false)} className="p-2.5 bg-slate-700 text-slate-300 rounded-xl hover:bg-slate-600 transition-colors"><X size={20}/></button>
           </div>
         )}
      </div>

      <div className="space-y-4">
        {data.needs && <CategorySection title="Kebutuhan Pokok" items={data.needs.items} color="blue" onDeleteCategory={()=>removeStandard('needs')} onUpdateItems={i=>onChange({...data, needs: {items: i}})} />}
        {data.savings && <CategorySection title="Tabungan & Investasi" items={data.savings.items} color="emerald" onDeleteCategory={()=>removeStandard('savings')} onUpdateItems={i=>onChange({...data, savings: {items: i}})} />}
        {data.debt && <CategorySection title="Hutang & Cicilan" items={data.debt.items} color="red" onDeleteCategory={()=>removeStandard('debt')} onUpdateItems={i=>onChange({...data, debt: {items: i}})} />}

        {(data.custom||[]).map(cat => (
          <CategorySection 
            key={cat.id} 
            title={cat.name} 
            items={cat.items} 
            color="purple" 
            onDeleteCategory={()=> {
              const updatedCustom = (data.custom || []).filter(c => c.id !== cat.id);
              onChange({...data, custom: updatedCustom});
            }} 
            onUpdateItems={i=> {
              const updatedCustom = (data.custom || []).map(c => c.id === cat.id ? {...c, items: i} : c);
              onChange({...data, custom: updatedCustom});
            }} 
          />
        ))}

        {data.others && <OthersSection data={data.others} onUpdate={o=>onChange({...data, others: o})} onDelete={()=>removeStandard('others')} />}

