  const [appState, setAppState] = useState<AppState>({});
  const [isLoading, setIsLoading] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase.from('monthly_finance').select('month_id, data');
        if (error) throw error;
        if (data) {
          const loadedState: AppState = {};
          data.forEach((row: any) => { loadedState[row.month_id] = row.data; });
          setAppState(loadedState);
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (isLoading || !appState[currentMonthKey]) return;
    const saveData = async () => {
      setSaveStatus('saving');
      try {
        const { error } = await supabase.from('monthly_finance').upsert({ 
          month_id: currentMonthKey, 
          data: appState[currentMonthKey],
          updated_at: new Date().toISOString()
        });
        if (error) throw error;
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } catch (err) {
        console.error("Error saving data:", err);
        setSaveStatus('error');
      }
    };
    const timeoutId = setTimeout(saveData, 800);
    return () => clearTimeout(timeoutId);
  }, [appState, currentMonthKey, isLoading]);

  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     return gross - calculateTax(gross, salary.taxRate) - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  useEffect(() => {
    if (!isLoading && !appState[currentMonthKey]) {
      const prevDate = new Date(currentDate);
      prevDate.setMonth(currentDate.getMonth() - 1);
      const pKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
      if (appState[pKey]) {
        setPrevMonthKey(pKey);
        setShowCopyModal(true);
      } else {
        initializeMonth(false);
      }
    }
  }, [currentMonthKey, isLoading]);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      newData = JSON.parse(JSON.stringify(appState[prevMonthKey]));
      if (newData.budget.needs) newData.budget.needs.items.forEach(i => i.actual = 0);
      if (newData.budget.savings) newData.budget.savings.items.forEach(i => i.actual = 0);
      if (newData.budget.debt) newData.budget.debt.items.forEach(i => i.actual = 0);
      if (newData.budget.others) newData.budget.others.items.forEach(i => i.actual = 0);
      if (newData.budget.custom) newData.budget.custom.forEach(cat => cat.items.forEach(i => i.actual = 0));
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = { salary: { ...DEFAULT_SALARY }, budget: { ...DEFAULT_BUDGET }, investments: [] };
    }
    setAppState(prev => ({ ...prev, [currentMonthKey]: newData }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => {
      const existing = prev[currentMonthKey] || { 
        salary: { ...DEFAULT_SALARY }, 
        budget: { ...DEFAULT_BUDGET }, 
        investments: [] 
      };
      // Menjamin referensi objek baru untuk mendeteksi penghapusan key di dalam budget
      return { 
        ...prev, 
        [currentMonthKey]: { ...existing, ...newData } 
      };
    });
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  if (isLoading) return <div className="min-h-screen flex items-center justify-center bg-[#0f172a]"><Loader2 className="w-10 h-10 text-indigo-400 animate-spin" /></div>;

  return (
    <div className="min-h-screen bg-[#0f172a] font-sans selection:bg-indigo-500/30 selection:text-indigo-200">
      <nav className="sticky top-0 z-50 pt-2 px-2 sm:pt-4 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl border border-white/5">
          <div className="flex flex-col sm:flex-row items-center justify-between p-3 sm:px-6 sm:h-20 gap-3">
            <div className="flex items-center justify-between w-full sm:w-auto">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-lg shadow-lg">
                     <Wallet className="text-white h-5 w-5 sm:h-6 sm:w-6" />
                  </div>
                  <div>
                    <h1 className="text-sm sm:text-xl font-black text-white uppercase tracking-tight leading-tight">ANIQ SUSILO - FINANCE MONTHLY</h1>
                  </div>
                </div>
                <div className="flex sm:hidden items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
                   <button onClick={() => changeMonth(-1)} className="p-1.5"><ChevronLeft size={16} /></button>
                   <div className="px-2 font-mono font-black text-indigo-400 text-xs uppercase">
                     {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' })}
                   </div>
                   <button onClick={() => changeMonth(1)} className="p-1.5"><ChevronRight size={16} /></button>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-slate-800/50 rounded-lg border border-slate-700/50">
                  {saveStatus === 'saving' ? <Loader2 size={14} className="animate-spin text-indigo-400" /> : saveStatus === 'saved' ? <CheckCircle2 size={14} className="text-emerald-400" /> : <Cloud size={12} className="text-slate-500"/>}
                  <span className="text-[10px] font-black uppercase text-slate-400">{saveStatus === 'saving' ? 'Saving' : saveStatus === 'saved' ? 'Saved' : 'Synced'}</span>
                </div>
                <div className="hidden sm:flex items-center bg-slate-800/80 rounded-xl p-1.5 border border-slate-700 shadow-sm">
                  <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-700 rounded-lg transition-colors text-slate-400"><ChevronLeft size={20} /></button>
                  <div className="px-6 font-mono font-black text-indigo-400 w-48 text-center text-sm uppercase tracking-wider">
                    {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' }).toUpperCase()}
                  </div>
                  <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-700 rounded-lg transition-colors text-slate-400"><ChevronRight size={20} /></button>
                </div>
            </div>
          </div>
          <div className="border-t border-slate-700/50 px-2 overflow-x-auto scrollbar-hide">
            <div className="flex space-x-1 py-1.5 sm:py-2">
              {TABS.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs font-black rounded-lg transition-all flex-1 justify-center sm:flex-none uppercase tracking-widest ${isActive ? 'text-white bg-indigo-600 shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
                    <Icon size={16} />{tab.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </nav>
      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && <SalarySlip data={currentData.salary} onChange={(s) => updateCurrentData({ salary: s })} />}
        {activeTab === 'budget' && <Budget income={currentNetIncome} data={currentData.budget} onChange={(b) => updateCurrentData({ budget: b })} />}
        {activeTab === 'charts' && <MonthlyCharts budgetData={currentData.budget} income={currentNetIncome} />}
        {activeTab === 'invest' && <Investments items={currentData.investments} onChange={(i) => updateCurrentData({ investments: i })} />}
        {activeTab === 'year' && <YearlySummary appState={appState} year={currentDate.getFullYear()} />}
      </main>
      {showCopyModal && (
        <div className="fixed inset-0 bg-slate-950/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="bg-slate-900 p-8 rounded-3xl max-w-md w-full border border-slate-800 shadow-2xl animate-fadeIn">
              <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Bulan Baru</h3>
              <p className="text-slate-400 mb-8 font-black">Data bulan ini belum ada. Salin template dari bulan sebelumnya?</p>
              <div className="flex gap-4">
                <button onClick={() => initializeMonth(true)} className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-900/50">Salin</button>
                <button onClick={() => initializeMonth(false)} className="flex-1 bg-slate-800 text-slate-200 py-3 rounded-xl font-black uppercase tracking-widest hover:bg-slate-700 transition-all">Baru</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { BudgetData, BudgetItem, OtherBudgetItem, CustomBudgetCategory } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, FolderPlus, X, Check, AlertCircle } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  color: 'blue' | 'emerald' | 'red' | 'purple' | 'violet';
  onUpdateItems: (items: BudgetItem[]) => void;
  onDeleteCategory: () => void;
  defaultExpanded?: boolean;
  canDelete?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems,
  onDeleteCategory,
  defaultExpanded = false,
  canDelete = true
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const catTotalAllocated = items.reduce((a, b) => a + (b.budget || 0), 0);
  const catTotalActual = items.reduce((a, b) => a + (b.actual || 0), 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;

  const colorsMap = {
    blue: { icon: 'text-blue-400 bg-blue-900/30', btn: 'border-blue-900/50 text-blue-400 hover:bg-blue-900/20' },
    emerald: { icon: 'text-emerald-400 bg-emerald-900/30', btn: 'border-emerald-900/50 text-emerald-400 hover:bg-emerald-900/20' },
    red: { icon: 'text-red-400 bg-red-900/30', btn: 'border-red-900/50 text-red-400 hover:bg-red-900/20' },
    purple: { icon: 'text-purple-400 bg-purple-900/30', btn: 'border-purple-900/50 text-purple-400 hover:bg-purple-900/20' },
    violet: { icon: 'text-violet-400 bg-violet-900/30', btn: 'border-violet-900/50 text-violet-400 hover:bg-violet-900/20' }
  };
  const theme = colorsMap[color];

  // FUNGSI HAPUS ITEM (DENGAN PROTEKSI TOTAL)
  const handleDeleteItem = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation(); // Menghindari klik masuk ke elemen parent
    const item = items.find(i => i.id === id);
    if (window.confirm(`Hapus item "${item?.name || 'ini'}" dari daftar?`)) {
      const filtered = items.filter(i => i.id !== id);
      onUpdateItems(filtered);
    }
  };

  // FUNGSI HAPUS KATEGORI (DENGAN PROTEKSI TOTAL)
  const handleDeleteCat = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation(); // Mencegah folder tertutup otomatis saat klik hapus
    if (window.confirm(`HAPUS KATEGORI: "${title}"?\nSemua isi di dalamnya akan ikut terhapus secara permanen.`)) {
      onDeleteCategory();
    }
  };

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden mb-4 transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/40 shadow-xl' : 'hover:shadow-lg'}`}>
      {/* HEADER DIBAGI DUA ZONA UNTUK MENGHINDARI KONFLIK KLIK */}
      <div className="flex items-stretch border-b border-slate-800/30">
        {/* Zona 1: Toggle Expand */}
        <div 
          className="flex-1 p-4 sm:p-5 flex items-center gap-4 cursor-pointer hover:bg-white/5 transition-colors"
          onClick={() => setExpanded(!expanded)}
        >
          <div className={`p-2.5 rounded-xl ${theme.icon}`}>
            {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
          </div>
          <div className="flex-1 min-w-0">
             <div className="flex items-center gap-2">
                <h4 className="font-black text-sm sm:text-base text-slate-100 uppercase tracking-tight truncate">{title}</h4>
                <span className="text-[9px] font-black text-slate-500 bg-slate-900/50 px-2 py-0.5 rounded border border-slate-700/50">{items.length} ITEM</span>
             </div>
             <div className="flex gap-3 mt-1 text-[9px] font-black uppercase text-slate-400">
                <span>AKTUAL: <span className={isCatOver ? 'text-rose-400' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></span>
                <span>SISA: <span className="text-indigo-400">{formatRupiah(catRemaining)}</span></span>
             </div>
          </div>
        </div>

        {/* Zona 2: Tombol Delete (Isolasi Fisik) */}
        {canDelete && (
          <div className="flex items-center px-2 bg-slate-900/40 border-l border-slate-800/50">
            <button 
              type="button" 
              onClick={handleDeleteCat}
              className="p-3 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-xl transition-all group/del"
              title="Hapus Kategori"
            >
              <Trash2 size={20} className="pointer-events-none group-hover/del:scale-110 transition-transform" />
            </button>
          </div>
        )}
      </div>

      {expanded && (
        <div className="p-4 sm:p-5 bg-slate-900/30 space-y-3">
           {items.map((item) => (
             <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 p-3 bg-slate-800/40 rounded-xl border border-slate-700/50 group/item">
               <div className="col-span-2 md:col-span-4">
                 <label className="text-[9px] uppercase font-black text-slate-500 block mb-1">Nama Item</label>
                 <input type="text" value={item.name} onChange={(e) => onUpdateItems(items.map(i => i.id === item.id ? {...i, name: e.target.value} : i))} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-sm text-white font-black outline-none focus:border-indigo-500" />
               </div>
               <div className="col-span-1 md:col-span-3">
                 <CurrencyInput label="Anggaran" value={item.budget} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, budget: v} : i))} className="text-sm" />
               </div>
               <div className="col-span-1 md:col-span-3">
                 <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, actual: v} : i))} className="text-sm" />
               </div>
               <div className="col-span-2 md:col-span-2 flex justify-end items-end pb-1">
                 <button 
                    type="button" 
                    onClick={(e) => handleDeleteItem(e, item.id)} 
                    className="p-2.5 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-all group/itdel"
                    title="Hapus Item"
                 >
                   <Trash2 size={18} className="pointer-events-none group-hover/itdel:scale-110 transition-transform"/>
                 </button>
               </div>
             </div>
           ))}
           <button 
             type="button" 
             onClick={() => onUpdateItems([...items, {id: Date.now().toString() + Math.random().toString(36).substr(2, 5), name: '', budget: 0, actual: 0}])} 
             className={`w-full py-3 border-2 border-dashed rounded-xl flex items-center justify-center gap-2 font-black text-xs uppercase tracking-widest transition-all ${theme.btn}`}
           >
             <Plus size={16} /> Tambah Item Ke {title}
           </button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newName, setNewName] = useState('');

  const totalAlloc = (data.needs?.items.reduce((a,b)=>a+b.budget,0)||0) + 
                     (data.savings?.items.reduce((a,b)=>a+b.budget,0)||0) + 
                     (data.debt?.items.reduce((a,b)=>a+b.budget,0)||0) + 
                     (data.others?.allocation||0) + 
                     (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+ii.budget,0),0)||0);

  const totalAct = (data.needs?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.savings?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.debt?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.others?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+ii.actual,0),0)||0);

  const removeStandard = (key: keyof BudgetData) => {
    const newData = { ...data };
    delete newData[key];
    onChange(newData);
  };

  const addCustom = () => {
    if (!newName.trim()) return setIsAdding(false);
    const updated = { 
      ...data, 
      custom: [...(data.custom||[]), {id: Date.now().toString(), name: newName.trim(), items: []}] 
    };
    onChange(updated);
    setNewName(''); setIsAdding(false);
  };

  return (
    <div className="space-y-6 pb-10">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-indigo-500">
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Income Netto</p>
          <h3 className="text-xl font-black">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-blue-500">
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Total Anggaran</p>
          <h3 className="text-xl font-black">{formatRupiah(totalAlloc)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-amber-500">
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Realisasi</p>
          <h3 className="text-xl font-black text-amber-400">{formatRupiah(totalAct)}</h3>
        </div>
        <div className={`glass-panel p-4 rounded-2xl border-l-4 ${income-totalAct < 0 ? 'border-rose-500' : 'border-emerald-500'}`}>
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Saldo Akhir</p>
          <h3 className={`text-xl font-black ${income-totalAct < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>{formatRupiah(income-totalAct)}</h3>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between gap-4 pt-4 border-b border-slate-800 pb-5">
         <h2 className="text-xl font-black text-white uppercase flex items-center gap-2">
            <div className="w-2 h-6 bg-indigo-600 rounded-full"></div> DAFTAR ANGGARAN
         </h2>
         {!isAdding ? (
           <button onClick={() => setIsAdding(true)} className="px-6 py-3 bg-indigo-600 text-white rounded-xl text-xs font-black flex items-center gap-2 uppercase tracking-widest transition-all hover:bg-indigo-700 shadow-lg shadow-indigo-900/50">
             <FolderPlus size={18} /> TAMBAH KATEGORI BARU
           </button>
         ) : (
           <div className="flex items-center gap-2 animate-fadeIn">
             <input autoFocus value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addCustom()} placeholder="Nama Kategori..." className="bg-slate-800 border-2 border-slate-700 rounded-xl px-4 py-2 text-sm text-white font-black outline-none focus:border-indigo-500" />
             <button onClick={addCustom} className="p-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-colors"><Check size={20}/></button>
             <button onClick={()=>setIsAdding(false)} className="p-2.5 bg-slate-700 text-slate-300 rounded-xl hover:bg-slate-600 transition-colors"><X size={20}/></button>
           </div>
         )}
      </div>

      <div className="space-y-4">
        {data.needs && <CategorySection title="Kebutuhan Pokok" items={data.needs.items} color="blue" onDeleteCategory={()=>removeStandard('needs')} onUpdateItems={i=>onChange({...data, needs: {items: i}})} />}
        {data.savings && <CategorySection title="Tabungan & Investasi" items={data.savings.items} color="emerald" onDeleteCategory={()=>removeStandard('savings')} onUpdateItems={i=>onChange({...data, savings: {items: i}})} />}
        {data.debt && <CategorySection title="Hutang & Cicilan" items={data.debt.items} color="red" onDeleteCategory={()=>removeStandard('debt')} onUpdateItems={i=>onChange({...data, debt: {items: i}})} />}

        {(data.custom||[]).map(cat => (
          <CategorySection 
            key={cat.id} 
            title={cat.name} 
            items={cat.items} 
            color="purple" 
            onDeleteCategory={()=> {
              const updatedCustom = (data.custom || []).filter(c => c.id !== cat.id);
              onChange({...data, custom: updatedCustom});
            }} 
            onUpdateItems={i=> {
              const updatedCustom = (data.custom || []).map(c => c.id === cat.id ? {...c, items: i} : c);
              onChange({...data, custom: updatedCustom});
            }} 
          />
        ))}

        {data.others && <OthersSection data={data.others} onUpdate={o=>onChange({...data, others: o})} onDelete={()=>removeStandard('others')} />}

        {(!data.needs && !data.savings && !data.debt && !data.others && (!data.custom || data.custom.length === 0)) && (
          <div className="text-center py-16 glass-panel rounded-3xl border-2 border-dashed border-slate-700 opacity-50">
             <AlertCircle size={40} className="mx-auto text-slate-600 mb-4" />
             <p className="text-slate-500 font-black uppercase tracking-widest text-sm">Belum ada kategori anggaran aktif</p>
          </div>
        )}
      </div>
    </div>
  );
};

const OthersSection: React.FC<{data: any, onUpdate: (d: any)=>void, onDelete: ()=>void}> = ({data, onUpdate, onDelete}) => {
  const [expanded, setExpanded] = useState(false);
  const totalAct = data.items.reduce((a:any, b:any)=>a+b.actual, 0);

  const handleDeleteCat = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if(window.confirm('Hapus kategori "Lain-lain / Hiburan"?')) {
      onDelete();
    }
  };

  return (
    <div className="glass-panel rounded-2xl overflow-hidden border border-slate-800 transition-all hover:shadow-lg">
      <div className="flex items-stretch border-b border-slate-800/30">
        <div 
          className="flex-1 p-4 sm:p-5 flex items-center gap-4 cursor-pointer hover:bg-white/5 transition-colors" 
          onClick={() => setExpanded(!expanded)}
        >
           <div className="p-3 rounded-xl bg-violet-900/30 text-violet-400">
             {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
           </div>
           <div className="flex-1 min-w-0">
                <h4 className="font-black text-sm text-slate-100 uppercase tracking-tight">Lain-lain / Hiburan</h4>
                <div className="flex gap-4 mt-1 text-[9px] font-black uppercase text-slate-400">
                  <span>LIMIT: <span className="text-blue-400">{formatRupiah(data.allocation)}</span></span>
                  <span>SISA: <span className="text-indigo-400">{formatRupiah(data.allocation - totalAct)}</span></span>
                </div>
           </div>
        </div>
        <div className="flex items-center px-2 bg-slate-900/40 border-l border-slate-800/50">
          <button 
            type="button" 
            onClick={handleDeleteCat} 
            className="p-3 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-xl transition-all group/othdel"
            title="Hapus Kategori"
          >
            <Trash2 size={20} className="pointer-events-none group-hover/othdel:scale-110 transition-transform" />
          </button>
        </div>
      </div>

      {expanded && (
        <div className="p-4 bg-slate-900/30 space-y-4">
           <CurrencyInput label="Limit Alokasi Dana" value={data.allocation} onChange={v=>onUpdate({...data, allocation: v})} />
           <div className="space-y-3">
             {data.items.map((item:any) => (
               <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 p-3 bg-slate-800/40 rounded-xl border border-slate-700/50 items-end group/item">
                 <div className="col-span-2 md:col-span-7">
                   <label className="text-[9px] uppercase font-black text-slate-500 block mb-1">Keterangan</label>
                   <input 
                     value={item.name} 
                     onChange={e=>onUpdate({...data, items: data.items.map((i:any)=>i.id===item.id?{...i, name: e.target.value}:i)})} 
                     className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-sm text-white font-black outline-none focus:border-indigo-500" 
                     placeholder="Nama pengeluaran..." 
                   />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Jumlah" value={item.actual} onChange={v=>onUpdate({...data, items: data.items.map((i:any)=>i.id===item.id?{...i, actual: v}:i)})} className="text-xs" />
                 </div>
                 <div className="col-span-1 md:col-span-2 flex justify-end pb-1">
                   <button 
                    type="button" 
                    onClick={(e)=>{
                      e.preventDefault();
                      e.stopPropagation();
                      if(window.confirm(`Hapus "${item.name || 'item'}"?`)) {
                        onUpdate({...data, items: data.items.filter((i:any)=>i.id!==item.id)});
                      }
                    }} 
                    className="p-2.5 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-all group/itdel"
                   >
                     <Trash2 size={16} className="pointer-events-none group-hover/itdel:scale-110 transition-transform"/>
                   </button>
                 </div>
               </div>
             ))}
           </div>
           <button 
             type="button" 
             onClick={()=>onUpdate({...data, items: [...data.items, {id: Date.now().toString(), name: '', actual: 0}]})} 
             className="w-full py-3 border-2 border-dashed border-violet-900/50 text-violet-400 bg-violet-900/10 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-violet-900/20 transition-all"
           >
             <Plus size={14} className="inline mr-1"/> Tambah Pengeluaran Lainnya
           </button>
        </div>
      )}
    </div>
  );
};

