const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems,
  onDeleteCategory,
  defaultExpanded = false,
  canDelete = true
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const catTotalAllocated = items.reduce((a, b) => a + (b.budget || 0), 0);
  const catTotalActual = items.reduce((a, b) => a + (b.actual || 0), 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;

  const colorsMap = {
    blue: { icon: 'text-blue-400 bg-blue-900/30', btn: 'border-blue-900/50 text-blue-400 hover:bg-blue-900/20' },
    emerald: { icon: 'text-emerald-400 bg-emerald-900/30', btn: 'border-emerald-900/50 text-emerald-400 hover:bg-emerald-900/20' },
    red: { icon: 'text-red-400 bg-red-900/30', btn: 'border-red-900/50 text-red-400 hover:bg-red-900/20' },
    purple: { icon: 'text-purple-400 bg-purple-900/30', btn: 'border-purple-900/50 text-purple-400 hover:bg-purple-900/20' },
    violet: { icon: 'text-violet-400 bg-violet-900/30', btn: 'border-violet-900/50 text-violet-400 hover:bg-violet-900/20' }
  };
  const theme = colorsMap[color];

  // FUNGSI HAPUS ITEM (DIPERKUAT)
  const handleDeleteItem = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation(); // PENTING: Menghentikan event naik ke atas
    if (window.confirm(`Hapus item ini dari daftar?`)) {
      onUpdateItems(items.filter(i => i.id !== id));
    }
  };

  // FUNGSI HAPUS KATEGORI (DIPERKUAT)
  const handleDeleteCat = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation(); // PENTING: Menghentikan klik agar tidak memicu buka/tutup menu
    if (window.confirm(`Yakin ingin menghapus seluruh kategori "${title}"?`)) {
      onDeleteCategory();
    }
  };

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden mb-4 transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/40 shadow-xl' : 'hover:shadow-lg'}`}>
      {/* HEADER DIBAGI DUA ZONA FISIK UNTUK MENGHINDARI KONFLIK KLIK */}
      <div className="flex items-stretch border-b border-slate-800/30">
        {/* ZONA 1: KLIK UNTUK BUKA/TUTUP (90% AREA) */}
        <div 
          className="flex-1 p-4 sm:p-5 flex items-center gap-4 cursor-pointer hover:bg-white/5 transition-colors"
          onClick={() => setExpanded(!expanded)}
        >
          <div className={`p-2.5 rounded-xl ${theme.icon}`}>
            {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
          </div>
          <div className="flex-1 min-w-0">
             <div className="flex items-center gap-2">
                <h4 className="font-black text-sm sm:text-base text-slate-100 uppercase tracking-tight truncate">{title}</h4>
                <span className="text-[9px] font-black text-slate-500 bg-slate-900/50 px-2 py-0.5 rounded border border-slate-700/50">{items.length} ITEM</span>
             </div>
             <div className="flex gap-3 mt-1 text-[9px] font-black uppercase text-slate-400">
                <span>AKTUAL: <span className={isCatOver ? 'text-rose-400' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></span>
                <span>SISA: <span className="text-indigo-400">{formatRupiah(catRemaining)}</span></span>
             </div>
          </div>
        </div>

        {/* ZONA 2: TOMBOL DELETE TERISOLASI (10% AREA) */}
        {canDelete && (
          <div className="flex items-center px-2 bg-slate-900/40 border-l border-slate-800/50">
            <button 
              type="button" 
              onClick={handleDeleteCat}
              className="p-3 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-xl transition-all group/btndel"
              title="Hapus Kategori"
            >
              <Trash2 size={22} className="pointer-events-none group-hover/btndel:scale-110" />
            </button>
          </div>
        )}
      </div>

      {expanded && (
        <div className="p-4 sm:p-5 bg-slate-900/30 space-y-3">
           {items.map((item) => (
             <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 p-3 bg-slate-800/40 rounded-xl border border-slate-700/50 group/item">
               <div className="col-span-2 md:col-span-4">
                 <label className="text-[9px] uppercase font-black text-slate-500 block mb-1">Nama Item</label>
                 <input type="text" value={item.name} onChange={(e) => onUpdateItems(items.map(i => i.id === item.id ? {...i, name: e.target.value} : i))} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-sm text-white font-black outline-none focus:border-indigo-500" />
               </div>
               <div className="col-span-1 md:col-span-3">
                 <CurrencyInput label="Anggaran" value={item.budget} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, budget: v} : i))} className="text-sm" />
               </div>
               <div className="col-span-1 md:col-span-3">
                 <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, actual: v} : i))} className="text-sm" />
               </div>
               <div className="col-span-2 md:col-span-2 flex justify-end items-end pb-1">
                 <button 
                    type="button" 
                    onClick={(e) => handleDeleteItem(e, item.id)} 
                    className="p-2.5 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-all group/trash"
                    title="Hapus Item"
                 >
                   <Trash2 size={20} className="pointer-events-none group-hover/trash:scale-110"/>
                 </button>
               </div>
             </div>
           ))}
           <button 
             type="button" 
             onClick={() => onUpdateItems([...items, {id: Date.now().toString() + Math.random().toString(36).substr(2, 5), name: '', budget: 0, actual: 0}])} 
             className={`w-full py-3 border-2 border-dashed rounded-xl flex items-center justify-center gap-2 font-black text-xs uppercase tracking-widest transition-all ${theme.btn}`}
           >
             <Plus size={16} /> Tambah Item Ke {title}
           </button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newName, setNewName] = useState('');

  const totalAlloc = (data.needs?.items.reduce((a,b)=>a+b.budget,0)||0) + 
                     (data.savings?.items.reduce((a,b)=>a+b.budget,0)||0) + 
                     (data.debt?.items.reduce((a,b)=>a+b.budget,0)||0) + 
                     (data.others?.allocation||0) + 
                     (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+ii.budget,0),0)||0);

  const totalAct = (data.needs?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.savings?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.debt?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.others?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+ii.actual,0),0)||0);

  const removeStandard = (key: keyof BudgetData) => {
    const newData = { ...data };
    delete newData[key];
    onChange(newData);
  };

  const addCustom = () => {
    if (!newName.trim()) return setIsAdding(false);
    const updated = { 
      ...data, 
      custom: [...(data.custom||[]), {id: Date.now().toString(), name: newName.trim(), items: []}] 
    };
    onChange(updated);
    setNewName(''); setIsAdding(false);
  };

  return (
    <div className="space-y-6 pb-10">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-indigo-500">
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Income Netto</p>
          <h3 className="text-xl font-black">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-blue-500">
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Total Anggaran</p>
          <h3 className="text-xl font-black">{formatRupiah(totalAlloc)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-amber-500">
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Realisasi</p>
          <h3 className="text-xl font-black text-amber-400">{formatRupiah(totalAct)}</h3>
        </div>
        <div className={`glass-panel p-4 rounded-2xl border-l-4 ${income-totalAct < 0 ? 'border-rose-500' : 'border-emerald-500'}`}>
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Saldo Akhir</p>
          <h3 className={`text-xl font-black ${income-totalAct < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>{formatRupiah(income-totalAct)}</h3>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between gap-4 pt-4 border-b border-slate-800 pb-5">
         <h2 className="text-xl font-black text-white uppercase flex items-center gap-2">
            <div className="w-2 h-6 bg-indigo-600 rounded-full"></div> DAFTAR ANGGARAN
         </h2>
         {!isAdding ? (
           <button onClick={() => setIsAdding(true)} className="px-6 py-3 bg-indigo-600 text-white rounded-xl text-xs font-black flex items-center gap-2 uppercase tracking-widest transition-all hover:bg-indigo-700 shadow-lg">
             <FolderPlus size={18} /> TAMBAH KATEGORI BARU
           </button>
         ) : (
           <div className="flex items-center gap-2">
             <input autoFocus value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addCustom()} placeholder="Nama Kategori..." className="bg-slate-800 border-2 border-slate-700 rounded-xl px-4 py-2 text-sm text-white font-black outline-none focus:border-indigo-500" />
             <button onClick={addCustom} className="p-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-colors"><Check size={20}/></button>
             <button onClick={()=>setIsAdding(false)} className="p-2.5 bg-slate-700 text-slate-300 rounded-xl hover:bg-slate-600 transition-colors"><X size={20}/></button>
           </div>
         )}
      </div>

      <div className="space-y-4">
        {data.needs && <CategorySection title="Kebutuhan Pokok" items={data.needs.items} color="blue" onDeleteCategory={()=>removeStandard('needs')} onUpdateItems={i=>onChange({...data, needs: {items: i}})} />}
        {data.savings && <CategorySection title="Tabungan & Investasi" items={data.savings.items} color="emerald" onDeleteCategory={()=>removeStandard('savings')} onUpdateItems={i=>onChange({...data, savings: {items: i}})} />}
        {data.debt && <CategorySection title="Hutang & Cicilan" items={data.debt.items} color="red" onDeleteCategory={()=>removeStandard('debt')} onUpdateItems={i=>onChange({...data, debt: {items: i}})} />}

        {(data.custom||[]).map(cat => (
          <CategorySection 
            key={cat.id} 
            title={cat.name} 
            items={cat.items} 
            color="purple" 
            onDeleteCategory={()=> {
              const updatedCustom = (data.custom || []).filter(c => c.id !== cat.id);
              onChange({...data, custom: updatedCustom});
            }} 
            onUpdateItems={i=> {
              const updatedCustom = (data.custom || []).map(c => c.id === cat.id ? {...c, items: i} : c);
              onChange({...data, custom: updatedCustom});
            }} 
          />
        ))}

        {data.others && <OthersSection data={data.others} onUpdate={o=>onChange({...data, others: o})} onDelete={()=>removeStandard('others')} />}

        {(!data.needs && !data.savings && !data.debt && !data.others && (!data.custom || data.custom.length === 0)) && (
          <div className="text-center py-16 glass-panel rounded-3xl border-2 border-dashed border-slate-700 opacity-50">
             <AlertCircle size={40} className="mx-auto text-slate-600 mb-4" />
             <p className="text-slate-500 font-black uppercase tracking-widest text-sm">Belum ada kategori anggaran aktif</p>
          </div>
        )}
      </div>
    </div>
  );
};

const OthersSection: React.FC<{data: any, onUpdate: (d: any)=>void, onDelete: ()=>void}> = ({data, onUpdate, onDelete}) => {
  const [expanded, setExpanded] = useState(false);
  const totalAct = data.items.reduce((a:any, b:any)=>a+b.actual, 0);

  const handleDeleteCat = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if(window.confirm('Hapus kategori "Lain-lain / Hiburan"?')) {
      onDelete();
    }
  };

  return (
    <div className="glass-panel rounded-2xl overflow-hidden border border-slate-800 transition-all hover:shadow-lg">
      <div className="flex items-stretch border-b border-slate-800/30">
        <div 
          className="flex-1 p-4 sm:p-5 flex items-center gap-4 cursor-pointer hover:bg-white/5 transition-colors" 
          onClick={() => setExpanded(!expanded)}
        >
           <div className="p-3 rounded-xl bg-violet-900/30 text-violet-400">
             {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
           </div>
           <div className="flex-1 min-w-0">
                <h4 className="font-black text-sm text-slate-100 uppercase tracking-tight">Lain-lain / Hiburan</h4>
                <div className="flex gap-4 mt-1 text-[9px] font-black uppercase text-slate-400">
                  <span>LIMIT: <span className="text-blue-400">{formatRupiah(data.allocation)}</span></span>
                  <span>SISA: <span className="text-indigo-400">{formatRupiah(data.allocation - totalAct)}</span></span>
                </div>
           </div>
        </div>
        <div className="flex items-center px-2 bg-slate-900/40 border-l border-slate-800/50">
          <button 
            type="button" 
            onClick={handleDeleteCat} 
            className="p-3 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-xl transition-all group/btndel2"
            title="Hapus Kategori"
          >
            <Trash2 size={22} className="pointer-events-none group-hover/btndel2:scale-110" />
          </button>
        </div>
      </div>

      {expanded && (
        <div className="p-4 bg-slate-900/30 space-y-4">
           <CurrencyInput label="Limit Alokasi Dana" value={data.allocation} onChange={v=>onUpdate({...data, allocation: v})} />
           <div className="space-y-3">
             {data.items.map((item:any) => (
               <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 p-3 bg-slate-800/40 rounded-xl border border-slate-700/50 items-end group">
                 <div className="col-span-2 md:col-span-7">
                   <label className="text-[9px] uppercase font-black text-slate-500 block mb-1">Keterangan</label>
                   <input 
                     value={item.name} 
                     onChange={e=>onUpdate({...data, items: data.items.map((i:any)=>i.id===item.id?{...i, name: e.target.value}:i)})} 
                     className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-sm text-white font-black outline-none focus:border-indigo-500" 
                     placeholder="Nama pengeluaran..." 
                   />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Jumlah" value={item.actual} onChange={v=>onUpdate({...data, items: data.items.map((i:any)=>i.id===item.id?{...i, actual: v}:i)})} className="text-xs" />
                 </div>
                 <div className="col-span-1 md:col-span-2 flex justify-end pb-1">
                   <button 
                    type="button" 
                    onClick={(e)=>{
                      e.preventDefault();
                      e.stopPropagation();
                      if(window.confirm(`Hapus "${item.name || 'item'}"?`)) {
                        onUpdate({...data, items: data.items.filter((i:any)=>i.id!==item.id)});
                      }
                    }} 
                    className="p-2.5 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-all group/trash2"
                   >
                     <Trash2 size={20} className="pointer-events-none group-hover/trash2:scale-110"/>
                   </button>
                 </div>
               </div>
             ))}
           </div>
           <button 
             type="button" 
             onClick={()=>onUpdate({...data, items: [...data.items, {id: Date.now().toString(), name: '', actual: 0}]})} 
             className="w-full py-3 border-2 border-dashed border-violet-900/50 text-violet-400 bg-violet-900/10 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-violet-900/20 transition-all"
           >
             <Plus size={14} className="inline mr-1"/> Tambah Pengeluaran Lainnya
           </button>
        </div>
      )}
    </div>
  );
};

export default Budget;

import React from 'react';
import { InvestmentItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import { formatRupiah } from '../utils';
import { Plus, Trash2, TrendingUp, Target, Briefcase, PieChart as PieChartIcon } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

interface InvestmentsProps {
  items: InvestmentItem[];
  onChange: (items: InvestmentItem[]) => void;
}

const COLORS = ['#6366F1', '#3B82F6', '#10B981', '#F59E0B', '#F43F5E', '#8B5CF6'];

const Investments: React.FC<InvestmentsProps> = ({ items, onChange }) => {
  const addItem = () => {
    const newItem: InvestmentItem = { id: Date.now().toString() + Math.random().toString(36).substr(2, 5), name: '', currentValue: 0, targetValue: 0 };
    onChange([...items, newItem]);
  };

  const updateItem = (id: string, field: keyof InvestmentItem, val: any) => {
    const newItems = items.map(item => item.id === id ? { ...item, [field]: val } : item);
    onChange(newItems);
  };

  // FUNGSI HAPUS ASET (DIISOLASI)
  const handleDeleteItem = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    const itemToDelete = items.find(i => i.id === id);
    if (window.confirm(`Hapus aset "${itemToDelete?.name || 'ini'}" dari daftar?`)) {
      onChange(items.filter(item => item.id !== id));
    }
  };

  const totalPortfolio = items.reduce((acc, item) => acc + (item.currentValue || 0), 0);
  const totalTarget = items.reduce((acc, item) => acc + (item.targetValue || 0), 0);
  const progress = totalTarget > 0 ? (totalPortfolio / totalTarget) * 100 : 0;

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 sm:gap-6">
        <div className="glass-panel p-6 sm:p-8 rounded-2xl relative overflow-hidden border border-indigo-900/30">
           <div className="absolute top-0 right-0 p-8 opacity-5">
              <TrendingUp size={140} className="text-indigo-400" />
           </div>
           <div className="relative z-10">
             <div className="flex items-center gap-2 mb-2">
               <Briefcase size={20} className="text-indigo-400" />
               <h3 className="text-slate-400 font-black text-xs uppercase tracking-wider">Total Nilai Aset</h3>
             </div>
             <div className="text-3xl sm:text-4xl font-black text-white mb-6 tracking-tight">{formatRupiah(totalPortfolio)}</div>
             <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700">
                <div className="flex justify-between text-[10px] font-black uppercase text-slate-400 mb-2">
                  <span>Target Keseluruhan</span>
                  <span className="text-indigo-400">{progress.toFixed(1)}%</span>
                </div>
                <div className="w-full bg-slate-900 h-2.5 rounded-full overflow-hidden">
                  <div 
                    className="bg-gradient-to-r from-indigo-600 to-blue-500 h-full transition-all duration-1000 shadow-lg" 
                    style={{ width: `${Math.min(progress, 100)}%` }}
                  ></div>
                </div>
             </div>
           </div>
        </div>

        <div className="glass-panel p-6 rounded-2xl flex flex-col items-center justify-center min-h-[300px] border border-slate-800">
          <h3 className="w-full text-left text-slate-400 font-black text-xs uppercase tracking-wider mb-4 pl-2">Alokasi Aset</h3>
          {items.length > 0 && totalPortfolio > 0 ? (
            <ResponsiveContainer width="100%" height={250}>
              <PieChart>
                <Pie 
                  data={items.filter(i => (i.currentValue || 0) > 0)} 
                  cx="50%" 
                  cy="50%" 
                  innerRadius={50} 
                  outerRadius={80} 
                  dataKey="currentValue" 
                  stroke="#0f172a" 
                  strokeWidth={2} 
                  labelLine={false} 
                  label={({percent})=>`${(percent*100).toFixed(0)}%`}
                >
                  {items.map((_, index) => <Cell key={index} fill={COLORS[index % COLORS.length]} />)}
                </Pie>
                <Tooltip formatter={(v:any)=>formatRupiah(v)} contentStyle={{backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px'}} />
              </PieChart>
            </ResponsiveContainer>
          ) : (
            <div className="flex flex-col items-center justify-center text-slate-500 gap-3 opacity-30 py-10">
              <PieChartIcon size={48} />
              <span className="font-black uppercase text-xs tracking-widest">Belum ada data visualisasi</span>
            </div>
          )}
        </div>
      </div>

      <div className="glass-panel rounded-2xl overflow-hidden border border-slate-800 shadow-xl">
         <div className="p-4 sm:p-6 border-b border-slate-800 flex justify-between items-center bg-slate-800/30">
            <h3 className="font-black text-base sm:text-lg text-white uppercase tracking-tight flex items-center gap-2">
               <div className="w-1.5 h-5 bg-indigo-500 rounded-full"></div> DAFTAR ASET & INVESTASI
            </h3>
            <button 
              type="button"
              onClick={addItem} 
              className="px-5 py-2.5 bg-indigo-600 text-white rounded-xl flex items-center gap-2 text-xs font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg"
            >
              <Plus size={16} /> TAMBAH ASET
            </button>
         </div>
         <div className="p-4 sm:p-6 space-y-4">
            {items.map((item) => (
              <div key={item.id} className="bg-slate-800/40 p-4 sm:p-5 rounded-2xl border border-slate-700/50 grid grid-cols-2 md:grid-cols-12 gap-4 items-end transition-colors hover:border-slate-600 group/asset">
                  <div className="col-span-2 md:col-span-4">
                    <label className="text-[10px] text-slate-500 uppercase font-black mb-1.5 block">Nama Aset</label>
                    <input 
                      type="text" 
                      value={item.name} 
                      onChange={(e) => updateItem(item.id, 'name', e.target.value)} 
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-white text-sm font-black outline-none focus:border-indigo-500" 
                      placeholder="Misal: Saham BBCA" 
                    />
                  </div>
                  <div className="col-span-2 md:col-span-3">
                    <CurrencyInput label="Nilai Saldo" value={item.currentValue} onChange={(v) => updateItem(item.id, 'currentValue', v)} className="text-sm" />
                  </div>
                  <div className="col-span-2 md:col-span-3">
                    <CurrencyInput label="Target Nilai" value={item.targetValue} onChange={(v) => updateItem(item.id, 'targetValue', v)} className="text-sm" />
                  </div>
                  <div className="col-span-2 md:col-span-2 flex justify-between items-center pt-2">
                    <div className="bg-slate-900 px-3 py-1.5 rounded-lg border border-slate-700 flex items-center gap-2">
                      <Target size={12} className="text-indigo-400" />
                      <span className="text-[10px] font-mono font-black text-indigo-400">
                        {item.targetValue > 0 ? ((item.currentValue/item.targetValue)*100).toFixed(0) : 0}%
                      </span>
                    </div>
                    <button 
                      type="button" 
                      onClick={(e) => handleDeleteItem(e, item.id)} 
                      className="p-3 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-xl transition-all group/adel"
                      title="Hapus Aset"
                    >
                      <Trash2 size={22} className="pointer-events-none group-hover/adel:scale-110" />
                    </button>
                  </div>
              </div>
            ))}
            {items.length === 0 && (
              <div className="text-center py-12 text-slate-500 flex flex-col items-center gap-4 opacity-30">
                <Briefcase size={32} />
                <p className="text-xs font-black uppercase tracking-widest">Belum ada aset terdaftar</p>
              </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default Investments;

import React, { useState, useEffect } from 'react';
import { X, AlertTriangle } from 'lucide-react';

interface DeleteModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  title: string;
  itemName: string;
  confirmWord?: string;
}

const DeleteModal: React.FC<DeleteModalProps> = ({
  isOpen,
  onClose,
  onConfirm,
  title,
  itemName,
  confirmWord = "HAPUS"
}) => {
  const [inputValue, setInputValue] = useState('');

  // Reset input saat modal dibuka
  useEffect(() => {
    if (isOpen) setInputValue('');
  }, [isOpen]);

  if (!isOpen) return null;

  const isConfirmed = inputValue.trim().toUpperCase() === confirmWord;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-950/80 backdrop-blur-md animate-fadeIn"
        onClick={onClose}
      />

      {/* Modal Card */}
      <div className="relative w-full max-w-md bg-slate-900 border border-slate-800 rounded-3xl shadow-2xl overflow-hidden animate-fadeIn">
        <div className="p-6 sm:p-8">
          <div className="flex items-center gap-4 mb-6">
            <div className="bg-rose-500/10 p-3 rounded-2xl">
              <AlertTriangle className="text-rose-500 w-8 h-8" />
            </div>
            <div>
              <h3 className="text-xl font-black text-white uppercase tracking-tight">{title}</h3>
              <p className="text-slate-400 text-sm font-bold">Tindakan ini tidak dapat dibatalkan.</p>
            </div>
          </div>

          <div className="bg-slate-800/50 p-4 rounded-2xl border border-slate-700/50 mb-6">
            <p className="text-xs text-slate-500 font-black uppercase mb-1">Objek yang akan dihapus:</p>
            <p className="text-white font-black text-lg break-words">"{itemName}"</p>
          </div>

          <div className="space-y-4">
            <p className="text-xs text-slate-400 font-bold leading-relaxed">
              Ketik kata <span className="text-rose-400 font-black">"{confirmWord}"</span> di bawah ini untuk mengonfirmasi penghapusan:
            </p>

            <input
              autoFocus
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder={`Ketik ${confirmWord}...`}
              className="w-full bg-slate-950 border-2 border-slate-800 rounded-xl py-3 px-4 text-white font-black uppercase tracking-widest outline-none focus:border-rose-500/50 transition-all text-center"
            />
          </div>

          <div className="flex gap-3 mt-8">
            <button
              onClick={onClose}
              className="flex-1 py-4 bg-slate-800 text-slate-300 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-slate-700 transition-all"
            >
              Batal
            </button>
            <button
              disabled={!isConfirmed}
              onClick={() => {
                onConfirm();
                onClose();
              }}
              className={`flex-1 py-4 rounded-2xl font-black uppercase text-xs tracking-widest transition-all shadow-lg ${
                isConfirmed 
                ? 'bg-rose-600 text-white hover:bg-rose-700 shadow-rose-900/20' 
                : 'bg-slate-800 text-slate-600 cursor-not-allowed'
              }`}
            >
              Ya, Hapus
            </button>
          </div>
        </div>

        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-slate-500 hover:text-white transition-colors"
        >
          <X size={20} />
        </button>
      </div>
    </div>
  );
};

export default DeleteModal;

import React, { useState } from 'react';
import { BudgetData, BudgetItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import DeleteModal from './ui/DeleteModal';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, FolderPlus, X, Check, AlertCircle } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  color: 'blue' | 'emerald' | 'red' | 'purple' | 'violet';
  onUpdateItems: (items: BudgetItem[]) => void;
  onRequestDeleteCategory: () => void;
  onRequestDeleteItem: (id: string, name: string) => void;
  defaultExpanded?: boolean;
  canDelete?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  color,
  onUpdateItems,
  onRequestDeleteCategory,
  onRequestDeleteItem,
  defaultExpanded = false,
  canDelete = true
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const catTotalAllocated = items.reduce((a, b) => a + (b.budget || 0), 0);
  const catTotalActual = items.reduce((a, b) => a + (b.actual || 0), 0);
  const catRemaining = catTotalAllocated - catTotalActual;
  const isCatOver = catTotalActual > catTotalAllocated;

  const colorsMap = {
    blue: { icon: 'text-blue-400 bg-blue-900/30', btn: 'border-blue-900/50 text-blue-400 hover:bg-blue-900/20' },
    emerald: { icon: 'text-emerald-400 bg-emerald-900/30', btn: 'border-emerald-900/50 text-emerald-400 hover:bg-emerald-900/20' },
    red: { icon: 'text-red-400 bg-red-900/30', btn: 'border-red-900/50 text-red-400 hover:bg-red-900/20' },
    purple: { icon: 'text-purple-400 bg-purple-900/30', btn: 'border-purple-900/50 text-purple-400 hover:bg-purple-900/20' },
    violet: { icon: 'text-violet-400 bg-violet-900/30', btn: 'border-violet-900/50 text-violet-400 hover:bg-violet-900/20' }
  };
  const theme = colorsMap[color];

  return (
    <div className={`glass-panel rounded-2xl overflow-hidden mb-4 transition-all duration-300 ${isCatOver ? 'ring-2 ring-rose-500/40 shadow-xl' : 'hover:shadow-lg'}`}>
      <div className="flex items-stretch border-b border-slate-800/30">
        <div 
          className="flex-1 p-4 sm:p-5 flex items-center gap-4 cursor-pointer hover:bg-white/5 transition-colors"
          onClick={() => setExpanded(!expanded)}
        >
          <div className={`p-2.5 rounded-xl ${theme.icon}`}>
            {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
          </div>
          <div className="flex-1 min-w-0">
             <div className="flex items-center gap-2">
                <h4 className="font-black text-sm sm:text-base text-slate-100 uppercase tracking-tight truncate">{title}</h4>
                <span className="text-[9px] font-black text-slate-500 bg-slate-900/50 px-2 py-0.5 rounded border border-slate-700/50">{items.length} ITEM</span>
             </div>
             <div className="flex gap-3 mt-1 text-[9px] font-black uppercase text-slate-400">
                <span>AKTUAL: <span className={isCatOver ? 'text-rose-400' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></span>
                <span>SISA: <span className="text-indigo-400">{formatRupiah(catRemaining)}</span></span>
             </div>
          </div>
        </div>

        {canDelete && (
          <div className="flex items-center px-2 bg-slate-900/40 border-l border-slate-800/50">
            <button 
              type="button" 
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                onRequestDeleteCategory();
              }}
              className="p-3 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-xl transition-all group/btndel"
              title="Hapus Kategori"
            >
              <Trash2 size={22} className="pointer-events-none group-hover/btndel:scale-110 transition-transform" />
            </button>
          </div>
        )}
      </div>

      {expanded && (
        <div className="p-4 sm:p-5 bg-slate-900/30 space-y-3">
           {items.map((item) => (
             <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 p-3 bg-slate-800/40 rounded-xl border border-slate-700/50 group/item">
               <div className="col-span-2 md:col-span-4">
                 <label className="text-[9px] uppercase font-black text-slate-500 block mb-1">Nama Item</label>
                 <input type="text" value={item.name} onChange={(e) => onUpdateItems(items.map(i => i.id === item.id ? {...i, name: e.target.value} : i))} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-sm text-white font-black outline-none focus:border-indigo-500" />
               </div>
               <div className="col-span-1 md:col-span-3">
                 <CurrencyInput label="Anggaran" value={item.budget} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, budget: v} : i))} className="text-sm" />
               </div>
               <div className="col-span-1 md:col-span-3">
                 <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, actual: v} : i))} className="text-sm" />
               </div>
               <div className="col-span-2 md:col-span-2 flex justify-end items-end pb-1">
                 <button 
                    type="button" 
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      onRequestDeleteItem(item.id, item.name);
                    }} 
                    className="p-2.5 text-slate-500 hover:text-rose-400 hover:bg-rose-900/20 rounded-lg transition-all group/trash"
                    title="Hapus Item"
                 >
                   <Trash2 size={20} className="pointer-events-none group-hover/trash:scale-110 transition-transform"/>
                 </button>
               </div>
             </div>
           ))}
           <button 
             type="button" 
             onClick={() => onUpdateItems([...items, {id: Date.now().toString() + Math.random().toString(36).substr(2, 5), name: '', budget: 0, actual: 0}])} 
             className={`w-full py-3 border-2 border-dashed rounded-xl flex items-center justify-center gap-2 font-black text-xs uppercase tracking-widest transition-all ${theme.btn}`}
           >
             <Plus size={16} /> Tambah Item Ke {title}
           </button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newName, setNewName] = useState('');

  // State untuk modal hapus
  const [deleteTarget, setDeleteTarget] = useState<{
    type: 'category' | 'item';
    id: string;
    name: string;
    categoryKey?: keyof BudgetData | string;
  } | null>(null);

  const totalAlloc = (data.needs?.items.reduce((a,b)=>a+b.budget,0)||0) + 
                     (data.savings?.items.reduce((a,b)=>a+b.budget,0)||0) + 
                     (data.debt?.items.reduce((a,b)=>a+b.budget,0)||0) + 
                     (data.others?.allocation||0) + 
                     (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+ii.budget,0),0)||0);

  const totalAct = (data.needs?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.savings?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.debt?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.others?.items.reduce((a,b)=>a+b.actual,0)||0) + 
                    (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+ii.actual,0),0)||0);

  const confirmDelete = () => {
    if (!deleteTarget) return;

    if (deleteTarget.type === 'category') {
      const key = deleteTarget.categoryKey as keyof BudgetData;
      if (key === 'custom') {
        const updatedCustom = (data.custom || []).filter(c => c.id !== deleteTarget.id);
        onChange({ ...data, custom: updatedCustom });
      } else {
        const newData = { ...data };
        delete newData[key];
        onChange(newData);
      }
    } else if (deleteTarget.type === 'item') {
      const categoryKey = deleteTarget.categoryKey as string;

      if (['needs', 'savings', 'debt'].includes(categoryKey)) {
        const key = categoryKey as keyof BudgetData;
        const cat = data[key] as any;
        const updatedItems = cat.items.filter((i: any) => i.id !== deleteTarget.id);
        onChange({ ...data, [key]: { ...cat, items: updatedItems } });
      } else {
        // Custom categories
        const updatedCustom = (data.custom || []).map(cat => {
          if (cat.id === categoryKey) {
            return { ...cat, items: cat.items.filter(i => i.id !== deleteTarget.id) };
          }
          return cat;
        });
        onChange({ ...data, custom: updatedCustom });
      }
    }

    setDeleteTarget(null);
  };

  const addCustom = () => {
    if (!newName.trim()) return setIsAdding(false);
    const updated = { 
      ...data, 
      custom: [...(data.custom||[]), {id: Date.now().toString(), name: newName.trim(), items: []}] 
    };
    onChange(updated);
    setNewName(''); setIsAdding(false);
  };

  return (
    <div className="space-y-6 pb-10">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-indigo-500">
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Income Netto</p>
          <h3 className="text-xl font-black">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-blue-500">
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Total Anggaran</p>
          <h3 className="text-xl font-black">{formatRupiah(totalAlloc)}</h3>
        </div>
        <div className="glass-panel p-4 rounded-2xl border-l-4 border-amber-500">
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Realisasi</p>
          <h3 className="text-xl font-black text-amber-400">{formatRupiah(totalAct)}</h3>
        </div>
        <div className={`glass-panel p-4 rounded-2xl border-l-4 ${income-totalAct < 0 ? 'border-rose-500' : 'border-emerald-500'}`}>
          <p className="text-slate-500 text-[9px] font-black uppercase mb-1">Saldo Akhir</p>
          <h3 className={`text-xl font-black ${income-totalAct < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>{formatRupiah(income-totalAct)}</h3>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between gap-4 pt-4 border-b border-slate-800 pb-5">
         <h2 className="text-xl font-black text-white uppercase flex items-center gap-2">
            <div className="w-2 h-6 bg-indigo-600 rounded-full"></div> DAFTAR ANGGARAN
         </h2>
         {!isAdding ? (
           <button onClick={() => setIsAdding(true)} className="px-6 py-3 bg-indigo-600 text-white rounded-xl text-xs font-black flex items-center gap-2 uppercase tracking-widest transition-all hover:bg-indigo-700 shadow-lg">
             <FolderPlus size={18} /> TAMBAH KATEGORI BARU
           </button>
         ) : (
           <div className="flex items-center gap-2 animate-fadeIn">
             <input autoFocus value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addCustom()} placeholder="Nama Kategori..." className="bg-slate-800 border-2 border-slate-700 rounded-xl px-4 py-2 text-sm text-white font-black outline-none focus:border-indigo-500" />
             <button onClick={addCustom} className="p-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-colors"><Check size={20}/></button>
             <button onClick={()=>setIsAdding(false)} className="p-2.5 bg-slate-700 text-slate-300 rounded-xl hover:bg-slate-600 transition-colors"><X size={20}/></button>
           </div>
         )}
      </div>

      <div className="space-y-4">
        {data.needs && (
          <CategorySection 
            title="Kebutuhan Pokok" 
            items={data.needs.items} 
            color="blue" 
            onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'needs', name: 'Kebutuhan Pokok', categoryKey: 'needs' })} 
            onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'needs' })}
            onUpdateItems={i => onChange({ ...data, needs: { items: i } })} 
          />
        )}

        {data.savings && (
          <CategorySection 
            title="Tabungan & Investasi" 
            items={data.savings.items} 
            color="emerald" 
            onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'savings', name: 'Tabungan & Investasi', categoryKey: 'savings' })} 
            onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'savings' })}
            onUpdateItems={i => onChange({ ...data, savings: { items: i } })} 
          />
        )}

        {data.debt && (
          <CategorySection 
            title="Hutang & Cicilan" 
            items={data.debt.items} 
            color="red" 
            onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'debt', name: 'Hutang & Cicilan', categoryKey: 'debt' })} 
            onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'debt' })}
            onUpdateItems={i => onChange({ ...data, debt: { items: i } })} 
          />
        )}

        {(data.custom||[]).map(cat => (
          <CategorySection 
            key={cat.id} 
            title={cat.name} 
            items={cat.items} 
            color="purple" 
            onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: cat.id, name: cat.name, categoryKey: 'custom' })} 
            onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: cat.id })}
            onUpdateItems={i => {
              const updatedCustom = (data.custom || []).map(c => c.id === cat.id ? { ...c, items: i } : c);
              onChange({ ...data, custom: updatedCustom });
            }} 
          />
        ))}

        {data.others && <OthersSection data={data.others} onUpdate={o=>onChange({...data, others: o})} onRequestDelete={()=>setDeleteTarget({ type: 'category', id: 'others', name: 'Lain-lain / Hiburan', categoryKey: 'others' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'others-items' })} />}

        {(!data.needs && !data.savings && !data.debt && !data.others && (!data.custom || data.custom.length === 0)) && (
          <div className="text-center py-16 glass-panel rounded-3xl border-2 border-dashed border-slate-700 opacity-50">
             <AlertCircle size={40} className="mx-auto text-slate-600 mb-4" />
             <p className="text-slate-500 font-black uppercase tracking-widest text-sm">Belum ada kategori anggaran aktif</p>
          </div>
        )}
      </div>

      {/* MODAL HAPUS SENTRAL */}
      <DeleteModal
        isOpen={!!deleteTarget}
        title={deleteTarget?.type === 'category' ? 'Hapus Kategori' : 'Hapus Item Anggaran'}
        itemName={deleteTarget?.name || ''}
        onClose={() => setDeleteTarget(null)}
        onConfirm={confirmDelete}
      />
    </div>
  );
};

const OthersSection: React.FC<{data: any, onUpdate: (d: any)=>void, onRequestDelete: ()=>void, onRequestDeleteItem: (id: string, name: string) => void}> = ({data, onUpdate, onRequestDelete, onRequestDeleteItem}) => {
  const [expanded, setExpanded] = useState(false);
  const totalAct = data.items.reduce((a:any, b:any)=>a+b.actual, 0);

