import React from 'react';
import { BudgetData } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell, CartesianGrid } from 'recharts';
import { formatRupiah } from '../utils';

interface MonthlyChartsProps {
  budgetData: BudgetData;
  income: number;
}

const COLORS = [
  '#3B82F6', // Blue
  '#10B981', // Emerald
  '#F59E0B', // Amber
  '#8B5CF6', // Violet
  '#F43F5E', // Rose
  '#06B6D4', // Cyan
  '#6366F1', // Indigo
  '#EC4899', // Pink
  '#14B8A6', // Teal
  '#F97316', // Orange
];

const MonthlyCharts: React.FC<MonthlyChartsProps> = ({ budgetData, income }) => {
  // 1. Agregasi Data Dinamis
  const categories: { name: string, Anggaran: number, Aktual: number }[] = [];

  // Tambahkan kategori standar jika ada datanya
  if (budgetData.needs && budgetData.needs.items.length > 0) {
    categories.push({
      name: 'Pokok',
      Anggaran: budgetData.needs.items.reduce((a, b) => a + (b.budget || 0), 0),
      Aktual: budgetData.needs.items.reduce((a, b) => a + (b.actual || 0), 0)
    });
  }

  if (budgetData.savings && budgetData.savings.items.length > 0) {
    categories.push({
      name: 'Tabungan',
      Anggaran: budgetData.savings.items.reduce((a, b) => a + (b.budget || 0), 0),
      Aktual: budgetData.savings.items.reduce((a, b) => a + (b.actual || 0), 0)
    });
  }

  if (budgetData.debt && budgetData.debt.items.length > 0) {
    categories.push({
      name: 'Cicilan',
      Anggaran: budgetData.debt.items.reduce((a, b) => a + (b.budget || 0), 0),
      Aktual: budgetData.debt.items.reduce((a, b) => a + (b.actual || 0), 0)
    });
  }

  // Tambahkan kategori kustom secara dinamis
  if (budgetData.custom && budgetData.custom.length > 0) {
    budgetData.custom.forEach(cat => {
      const totalBudget = cat.items.reduce((a, b) => a + (b.budget || 0), 0);
      const totalActual = cat.items.reduce((a, b) => a + (b.actual || 0), 0);

      if (totalBudget > 0 || totalActual > 0) {
        categories.push({
          name: cat.name,
          Anggaran: totalBudget,
          Aktual: totalActual
        });
      }
    });
  }

  // Tambahkan kategori Lain-lain
  if (budgetData.others) {
    categories.push({
      name: 'Lainnya',
      Anggaran: budgetData.others.allocation || 0,
      Aktual: budgetData.others.items.reduce((a, b) => a + (b.actual || 0), 0)
    });
  }

  const pieAllocData = categories
    .map(c => ({ name: c.name, value: c.Anggaran }))
    .filter(d => d.value > 0);

  const pieActualData = categories
    .map(c => ({ name: c.name, value: c.Aktual }))
    .filter(d => d.value > 0);

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      const isOver = payload.length >= 2 && payload[1].value > payload[0].value;
      return (
        <div className="bg-slate-900 border border-slate-700 p-4 rounded-2xl shadow-2xl backdrop-blur-xl">
          <p className="font-black text-white mb-3 border-b border-slate-800 pb-2 text-xs uppercase tracking-widest">{label || 'Detail Kategori'}</p>
          <div className="space-y-2">
            {payload.map((entry: any, index: number) => (
              <div key={index} className="flex items-center justify-between gap-8">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color || entry.payload.fill || COLORS[index % COLORS.length] }}></div>
                  <span className="text-slate-400 text-[10px] font-black uppercase">{entry.name}:</span>
                </div>
                <span className="text-white font-mono text-xs font-black">{formatRupiah(entry.value)}</span>
              </div>
            ))}
            {payload.length >= 2 && (
               <div className="pt-2 border-t border-slate-800 mt-2 flex justify-between items-center gap-4">
                  <span className="text-[9px] font-black text-slate-500 uppercase">Efisiensi:</span>
                  <span className={`text-[10px] font-black uppercase ${isOver ? 'text-rose-400' : 'text-emerald-400'}`}>
                    {((payload[1].value / (payload[0].value || 1)) * 100).toFixed(1)}% Terpakai
                  </span>
               </div>
            )}
          </div>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Bar Chart: Comparison */}
      <div className="glass-panel p-4 sm:p-6 rounded-3xl border border-slate-800 shadow-xl overflow-hidden">
        <div className="flex items-center gap-3 mb-8">
           <div className="w-1.5 h-6 bg-indigo-500 rounded-full"></div>
           <h3 className="text-base font-black text-white uppercase tracking-tight">Perbandingan Anggaran vs Realisasi</h3>
        </div>
        <div className="h-72 sm:h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={categories} margin={{ top: 20, right: 10, left: 0, bottom: 20 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
              <XAxis 
                dataKey="name" 
                stroke="#64748b" 
                fontSize={9} 
                tickLine={false} 
                axisLine={false} 
                tick={{fontWeight: 900}} 
                interval={0}
                angle={-45}
                textAnchor="end"
                height={60}
              />
              <YAxis 
                stroke="#64748b" 
                fontSize={9} 
                width={70} 
                tickFormatter={(val) => `Rp${val/1000000}M`} 
                tickLine={false} 
                axisLine={false} 
                tick={{fontWeight: 900}}
              />
              <Tooltip content={<CustomTooltip />} cursor={{fill: 'rgba(255,255,255,0.03)'}} />
              <Legend 
                verticalAlign="top" 
                align="right" 
                wrapperStyle={{ paddingTop: '0', paddingBottom: '30px', fontSize: '10px', fontWeight: '900', textTransform: 'uppercase' }} 
              />
              <Bar name="Anggaran" dataKey="Anggaran" fill="#312e81" radius={[4, 4, 0, 0]} maxBarSize={30} />
              <Bar name="Aktual" dataKey="Aktual" fill="#6366f1" radius={[4, 4, 0, 0]} maxBarSize={30} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Pie Chart: Allocation */}
        <div className="glass-panel p-6 rounded-3xl border border-slate-800 relative overflow-hidden">
           <div className="flex items-center gap-3 mb-6 relative z-10">
              <div className="w-1.5 h-6 bg-blue-500 rounded-full"></div>
              <h3 className="text-sm font-black text-white uppercase tracking-tight">Komposisi Rencana Anggaran</h3>
           </div>
           <div className="h-72 sm:h-80 relative z-10">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie 
                    data={pieAllocData} 
                    cx="50%" 
                    cy="50%" 
                    innerRadius={60} 
                    outerRadius={85} 
                    dataKey="value" 
                    stroke="#0f172a" 
                    strokeWidth={4} 
                    labelLine={{ stroke: '#475569', strokeWidth: 1 }} 
                    label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                    paddingAngle={4}
                  >
                    {pieAllocData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>

        {/* Pie Chart: Actuals */}
        <div className="glass-panel p-6 rounded-3xl border border-slate-800 relative overflow-hidden">
           <div className="flex items-center gap-3 mb-6 relative z-10">
              <div className="w-1.5 h-6 bg-emerald-500 rounded-full"></div>
              <h3 className="text-sm font-black text-white uppercase tracking-tight">Distribusi Pengeluaran Nyata</h3>
           </div>
           <div className="h-72 sm:h-80 relative z-10">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie 
                    data={pieActualData} 
                    cx="50%" 
                    cy="50%" 
                    innerRadius={60} 
                    outerRadius={85} 
                    dataKey="value" 
                    stroke="#0f172a" 
                    strokeWidth={4} 
                    labelLine={{ stroke: '#475569', strokeWidth: 1 }} 
                    label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                    paddingAngle={4}
                  >
                    {pieActualData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>
      </div>
    </div>
  );
};

export default MonthlyCharts;

import React, { useMemo } from 'react';
import { AppState } from '../types';
import { calculateGrossIncome, calculateTax, formatRupiah } from '../utils';
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';

interface YearlySummaryProps {
  appState: AppState;
  year: number;
}

const YearlySummary: React.FC<YearlySummaryProps> = ({ appState, year }) => {
  const summaryData = useMemo(() => {
    const months = Array.from({ length: 12 }, (_, i) => {
      const monthNum = i + 1;
      const monthKey = `${year}-${String(monthNum).padStart(2, '0')}`;
      const data = appState[monthKey];

      if (!data) {
        return {
          month: new Date(year, i).toLocaleString('id-ID', { month: 'short' }),
          income: 0,
          expense: 0,
          margin: 0,
          profit: 0
        };
      }

      // Calculate Income
      const { salary } = data;
      const otRupiah = ((salary.basicSalary + salary.housingAllowance) / 173) * salary.overtimeHours;
      const bonusRupiah = (salary.basicSalary + salary.housingAllowance) * salary.bonusMultiplier;
      const gross = calculateGrossIncome(
        salary.basicSalary, 
        salary.housingAllowance, 
        salary.shiftAllowance, 
        otRupiah, 
        bonusRupiah, 
        salary.thr, 
        salary.leavePay
      );
      const tax = calculateTax(gross, salary.taxRate);
      const netIncome = gross - tax - salary.otherDeductions;

      // Calculate Expense (Actuals) - Fixed with optional chaining
      const { budget } = data;
      const expense = 
        (budget.needs?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0) +
        (budget.savings?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0) + 
        (budget.debt?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0) +
        (budget.others?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0) +
        (budget.custom || []).reduce((acc, cat) => acc + (cat.items?.reduce((ia, ii) => ia + (ii.actual || 0), 0) || 0), 0);

      const profit = netIncome - expense;
      const margin = netIncome > 0 ? (profit / netIncome) * 100 : 0;

      return {
        month: new Date(year, i).toLocaleString('id-ID', { month: 'short' }),
        income: netIncome,
        expense: expense,
        margin: margin,
        profit: profit
      };
    });
    return months;
  }, [appState, year]);

  const totalIncome = summaryData.reduce((acc, curr) => acc + curr.income, 0);
  const totalExpense = summaryData.reduce((acc, curr) => acc + curr.expense, 0);
  const netProfit = totalIncome - totalExpense;

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-slate-900 border border-slate-700 p-4 rounded-xl shadow-2xl">
          <p className="font-black text-white mb-2 uppercase tracking-widest border-b border-slate-800 pb-2">{label} {year}</p>
          <div className="space-y-1">
             <p className="text-emerald-400 text-sm font-black uppercase">Income: {formatRupiah(payload[0].value)}</p>
             <p className="text-rose-400 text-sm font-black uppercase">Expense: {formatRupiah(payload[1].value)}</p>
             <div className="border-t border-slate-800 pt-1 mt-1">
                <p className="text-indigo-400 text-sm font-black uppercase">Profit: {formatRupiah(payload[0].value - payload[1].value)}</p>
             </div>
          </div>
        </div>
      );
    }
    return null;
  };

  return (
