import React from 'react';
import { BudgetData } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell, CartesianGrid } from 'recharts';
import { formatRupiah } from '../utils';

interface MonthlyChartsProps {
  budgetData: BudgetData;
  income: number;
}

// Palet warna yang lebih luas dan kontras untuk membedakan kategori baru
const COLORS = [
  '#6366F1', // Indigo
  '#10B981', // Emerald
  '#F59E0B', // Amber
  '#3B82F6', // Blue
  '#F43F5E', // Rose
  '#8B5CF6', // Violet
  '#06B6D4', // Cyan
  '#EC4899', // Pink
  '#14B8A6', // Teal
  '#F97316', // Orange
  '#A855F7', // Purple
  '#22C55E', // Green
  '#EAB308', // Yellow
  '#EF4444', // Red
  '#0EA5E9', // Sky
];

const MonthlyCharts: React.FC<MonthlyChartsProps> = ({ budgetData, income }) => {
  // Agregasi Data Dinamis: Mengumpulkan semua kategori yang memiliki data secara otomatis
  const categories: { name: string, Anggaran: number, Aktual: number }[] = [];

  // 1. Kebutuhan Pokok
  if (budgetData.needs?.items && budgetData.needs.items.length > 0) {
    categories.push({
      name: 'Pokok',
      Anggaran: budgetData.needs.items.reduce((a, b) => a + (b.budget || 0), 0),
      Aktual: budgetData.needs.items.reduce((a, b) => a + (b.actual || 0), 0)
    });
  }

  // 2. Tabungan
  if (budgetData.savings?.items && budgetData.savings.items.length > 0) {
    categories.push({
      name: 'Tabungan',
      Anggaran: budgetData.savings.items.reduce((a, b) => a + (b.budget || 0), 0),
      Aktual: budgetData.savings.items.reduce((a, b) => a + (b.actual || 0), 0)
    });
  }

  // 3. Cicilan
  if (budgetData.debt?.items && budgetData.debt.items.length > 0) {
    categories.push({
      name: 'Cicilan',
      Anggaran: budgetData.debt.items.reduce((a, b) => a + (b.budget || 0), 0),
      Aktual: budgetData.debt.items.reduce((a, b) => a + (b.actual || 0), 0)
    });
  }

  // 4. Kategori Kustom (Dinamis: Langsung Sinkron)
  if (budgetData.custom && budgetData.custom.length > 0) {
    budgetData.custom.forEach(cat => {
      if (cat.items) {
        const totalBudget = cat.items.reduce((a, b) => a + (b.budget || 0), 0);
        const totalActual = cat.items.reduce((a, b) => a + (b.actual || 0), 0);

        if (totalBudget > 0 || totalActual > 0) {
          categories.push({
            name: cat.name || 'Custom',
            Anggaran: totalBudget,
            Aktual: totalActual
          });
        }
      }
    });
  }

  // 5. Lain-lain
  if (budgetData.others) {
    const totalActualOthers = budgetData.others.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0;
    if (budgetData.others.allocation > 0 || totalActualOthers > 0) {
      categories.push({
        name: 'Lainnya',
        Anggaran: budgetData.others.allocation || 0,
        Aktual: totalActualOthers
      });
    }
  }

  const pieAllocData = categories
    .map(c => ({ name: c.name, value: c.Anggaran }))
    .filter(d => d.value > 0);

  const pieActualData = categories
    .map(c => ({ name: c.name, value: c.Aktual }))
    .filter(d => d.value > 0);

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      const isOver = payload.length >= 2 && payload[1].value > payload[0].value;
      return (
        <div className="bg-slate-900 border border-slate-700 p-4 rounded-2xl shadow-2xl backdrop-blur-xl">
          <p className="font-black text-white mb-3 border-b border-slate-800 pb-2 text-xs uppercase tracking-widest">{label || 'Detail'}</p>
          <div className="space-y-2">
            {payload.map((entry: any, index: number) => (
              <div key={index} className="flex items-center justify-between gap-8">
                <div className="flex items-center gap-2">
                  <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: entry.color || entry.payload.fill || COLORS[index % COLORS.length] }}></div>
                  <span className="text-slate-400 text-[10px] font-black uppercase">{entry.name}:</span>
                </div>
                <span className="text-white font-mono text-xs font-black">{formatRupiah(entry.value)}</span>
              </div>
            ))}
            {payload.length >= 2 && (
               <div className="pt-2 border-t border-slate-800 mt-2 flex justify-between items-center gap-4">
                  <span className="text-[9px] font-black text-slate-500 uppercase">Status:</span>
                  <span className={`text-[10px] font-black uppercase ${isOver ? 'text-rose-400' : 'text-emerald-400'}`}>
                    {((payload[1].value / (payload[0].value || 1)) * 100).toFixed(1)}% Terpakai
                  </span>
               </div>
            )}
          </div>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Bar Chart: Comparison */}
      <div className="glass-panel p-4 sm:p-6 rounded-3xl border border-slate-800 shadow-xl overflow-hidden">
        <div className="flex items-center gap-3 mb-8">
           <div className="w-1.5 h-6 bg-indigo-500 rounded-full"></div>
           <h3 className="text-base font-black text-white uppercase tracking-tight">Anggaran vs Realisasi Bulanan</h3>
        </div>
        <div className="h-72 sm:h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={categories} margin={{ top: 20, right: 10, left: 0, bottom: 20 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
              <XAxis 
                dataKey="name" 
                stroke="#64748b" 
                fontSize={9} 
                tickLine={false} 
                axisLine={false} 
                tick={{fontWeight: 900}} 
                interval={0}
                angle={-45}
                textAnchor="end"
                height={60}
              />
              <YAxis 
                stroke="#64748b" 
                fontSize={9} 
                width={70} 
                tickFormatter={(val) => `Rp${val/1000000}M`} 
                tickLine={false} 
                axisLine={false} 
                tick={{fontWeight: 900}}
              />
              <Tooltip content={<CustomTooltip />} cursor={{fill: 'rgba(255,255,255,0.03)'}} />
              <Legend 
                verticalAlign="top" 
                align="right" 
                wrapperStyle={{ paddingTop: '0', paddingBottom: '30px', fontSize: '10px', fontWeight: '900', textTransform: 'uppercase' }} 
              />
              <Bar name="Rencana" dataKey="Anggaran" fill="#1e1b4b" radius={[4, 4, 0, 0]} maxBarSize={32} />
              <Bar name="Aktual" dataKey="Aktual" fill="#6366f1" radius={[4, 4, 0, 0]} maxBarSize={32} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Pie Chart: Allocation */}
        <div className="glass-panel p-6 rounded-3xl border border-slate-800 relative overflow-hidden">
           <div className="flex items-center gap-3 mb-6 relative z-10">
              <div className="w-1.5 h-6 bg-blue-500 rounded-full"></div>
              <h3 className="text-sm font-black text-white uppercase tracking-tight">Rencana Alokasi</h3>
           </div>
           <div className="h-72 sm:h-80 relative z-10">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie 
                    data={pieAllocData} 
                    cx="50%" 
                    cy="50%" 
                    innerRadius={65} 
                    outerRadius={90} 
                    dataKey="value" 
                    stroke="#0f172a" 
                    strokeWidth={4} 
                    labelLine={{ stroke: '#475569', strokeWidth: 1 }} 
                    label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                    paddingAngle={4}
                  >
                    {pieAllocData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>

        {/* Pie Chart: Actuals */}
        <div className="glass-panel p-6 rounded-3xl border border-slate-800 relative overflow-hidden">
           <div className="flex items-center gap-3 mb-6 relative z-10">
              <div className="w-1.5 h-6 bg-emerald-500 rounded-full"></div>
              <h3 className="text-sm font-black text-white uppercase tracking-tight">Realisasi Pengeluaran</h3>
           </div>
           <div className="h-72 sm:h-80 relative z-10">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie 
                    data={pieActualData} 
                    cx="50%" 
                    cy="50%" 
                    innerRadius={65} 
                    outerRadius={90} 
                    dataKey="value" 
                    stroke="#0f172a" 
                    strokeWidth={4} 
                    labelLine={{ stroke: '#475569', strokeWidth: 1 }} 
                    label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                    paddingAngle={4}
                  >
                    {pieActualData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                  </Pie>
