import React from 'react';
import { BudgetData } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell, CartesianGrid } from 'recharts';
import { formatRupiah } from '../utils';
import { AlertTriangle } from 'lucide-react';

interface MonthlyChartsProps {
  budgetData: BudgetData;
  income: number;
}

// Palet warna yang luas untuk kategori
const COLORS = [
  '#6366F1', // Indigo
  '#10B981', // Emerald
  '#F59E0B', // Amber
  '#3B82F6', // Blue
  '#8B5CF6', // Violet
  '#06B6D4', // Cyan
  '#EC4899', // Pink
  '#14B8A6', // Teal
  '#F97316', // Orange
  '#A855F7', // Purple
  '#22C55E', // Green
  '#EAB308', // Yellow
  '#0EA5E9', // Sky
  '#64748B', // Slate
];

const OVER_BUDGET_COLOR = '#F43F5E'; // Rose/Red for Warning

const MonthlyCharts: React.FC<MonthlyChartsProps> = ({ budgetData, income }) => {
  // Agregasi Data Dinamis
  const categories: { name: string, Anggaran: number, Aktual: number, isOver: boolean }[] = [];

  const addCategory = (name: string, budget: number, actual: number) => {
    if (budget > 0 || actual > 0) {
      categories.push({
        name,
        Anggaran: budget,
        Aktual: actual,
        isOver: actual > budget
      });
    }
  };

  // 1. Kebutuhan Pokok
  addCategory(
    'Pokok',
    budgetData.needs?.items?.reduce((a, b) => a + (b.budget || 0), 0) || 0,
    budgetData.needs?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0
  );

  // 2. Tabungan
  addCategory(
    'Tabungan',
    budgetData.savings?.items?.reduce((a, b) => a + (b.budget || 0), 0) || 0,
    budgetData.savings?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0
  );

  // 3. Cicilan
  addCategory(
    'Cicilan',
    budgetData.debt?.items?.reduce((a, b) => a + (b.budget || 0), 0) || 0,
    budgetData.debt?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0
  );

  // 4. Kategori Kustom
  budgetData.custom?.forEach(cat => {
    addCategory(
      cat.name || 'Custom',
      cat.items?.reduce((a, b) => a + (b.budget || 0), 0) || 0,
      cat.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0
    );
  });

  // 5. Lain-lain
  addCategory(
    'Lainnya',
    budgetData.others?.allocation || 0,
    budgetData.others?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0
  );

  const pieAllocData = categories
    .map(c => ({ name: c.name, value: c.Anggaran, isOver: c.isOver }))
    .filter(d => d.value > 0);

  const pieActualData = categories
    .map(c => ({ name: c.name, value: c.Aktual, isOver: c.isOver }))
    .filter(d => d.value > 0);

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      const budgetVal = payload.find((p: any) => p.name === 'Rencana')?.value || 0;
      const actualVal = payload.find((p: any) => p.name === 'Aktual')?.value || 0;
      const isOver = actualVal > budgetVal && budgetVal > 0;

      return (
        <div className="bg-slate-900 border border-slate-700 p-4 rounded-2xl shadow-2xl backdrop-blur-xl min-w-[200px]">
          <div className="flex justify-between items-center mb-3 border-b border-slate-800 pb-2">
            <p className="font-black text-white text-xs uppercase tracking-widest">{label || 'Detail'}</p>
            {isOver && <AlertTriangle size={14} className="text-rose-500 animate-pulse" />}
          </div>

          <div className="space-y-2">
            {payload.map((entry: any, index: number) => {
              const isActualField = entry.name === 'Aktual';
              const color = (isActualField && isOver) ? OVER_BUDGET_COLOR : (entry.color || entry.payload.fill || COLORS[index % COLORS.length]);

              return (
                <div key={index} className="flex items-center justify-between gap-6">
                  <div className="flex items-center gap-2">
                    <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: color }}></div>
                    <span className="text-slate-400 text-[10px] font-black uppercase">{entry.name}:</span>
                  </div>
                  <span className={`font-mono text-xs font-black ${isActualField && isOver ? 'text-rose-400' : 'text-white'}`}>
                    {formatRupiah(entry.value)}
                  </span>
                </div>
              );
            })}

