                  <Pie 
                    data={categories.filter(c => c.Anggaran > 0)} 
                    cx="50%" 
                    cy="50%" 
                    innerRadius={80} 
                    outerRadius={110} 
                    dataKey="Anggaran" 
                    stroke="#0f172a" 
                    strokeWidth={6} 
                    paddingAngle={8}
