                    label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                    isAnimationActive={true}
                    animationBegin={200}
                    animationDuration={1500}
                  >
                    {categories.filter(c => c.Anggaran > 0).map((entry, index) => (
                      <Cell 
                        key={`pie-alloc-${index}`} 
