  income: number;
}

// Map warna yang sinkron dengan Budget.tsx
const CATEGORY_COLORS: { [key: string]: string } = {
  'Pokok': '#6366F1',     // Indigo
  'Tabungan': '#10B981',  // Emerald
  'Cicilan': '#F43F5E',   // Rose
  'Lainnya': '#8B5CF6',   // Violet
};

const EXTRA_COLORS = [
  '#F59E0B', // Amber
  '#06B6D4', // Cyan
