          </div>

          <div className="space-y-3">
            {payload.map((entry: any, index: number) => (
              <div key={index} className="flex items-center justify-between gap-6">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 rounded-full shadow-[0_0_10px_rgba(255,255,255,0.2)]" style={{ backgroundColor: entry.color || entry.payload.fill }}></div>
                  <span className="text-slate-400 text-[10px] font-black uppercase tracking-wider">{entry.name}</span>
                </div>
                <span className={`font-mono text-sm font-black ${entry.name === 'Aktual' && isOver ? 'text-rose-400' : 'text-white'}`}>
