                      {((actualVal / budgetVal) * 100).toFixed(1)}%
                    </span>
                  </div>
                  <div className="w-full bg-slate-800 h-1.5 rounded-full mt-2 overflow-hidden">
                    <div 
                      className={`h-full transition-all duration-1000 ${isOver ? 'bg-rose-500' : 'bg-emerald-500'}`}
                      style={{ width: `${Math.min((actualVal / budgetVal) * 100, 100)}%` }}
                    ></div>
                  </div>
               </div>
            )}
          </div>
        </div>
      );
    }
    return null;
  };

  // Formatter untuk Sumbu Y yang lebih jelas
  const yAxisFormatter = (val: number) => {
    if (val === 0) return 'Rp 0';
    if (val >= 1000000) return `Rp ${(val / 1000000).toFixed(1)}jt`;
    if (val >= 1000) return `Rp ${(val / 1000).toFixed(0)}rb`;
    return `Rp ${val}`;
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-20">
