              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded bg-[#6366F1] shadow-[0_0_15px_rgba(99,102,241,0.6)]"></div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-white">Aktual</span>
              </div>
           </div>
        </div>

        <div className="h-[400px] w-full relative z-10">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={categories} margin={{ top: 20, right: 30, left: 30, bottom: 60 }}>
              <defs>
                <linearGradient id="barGradientRencana" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#1e1b4b" stopOpacity={1}/>
                  <stop offset="100%" stopColor="#312e81" stopOpacity={0.8}/>
                </linearGradient>
                <linearGradient id="barGradientAktual" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#A5B4FC" stopOpacity={1}/>
                  <stop offset="100%" stopColor="#6366F1" stopOpacity={1}/>
                </linearGradient>
                <linearGradient id="barGradientOver" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#FF4D4D" stopOpacity={1}/>
                  <stop offset="100%" stopColor="#B22222" stopOpacity={1}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#334155" opacity={0.2} />
              <XAxis 
                dataKey="name" 
                stroke="#FFFFFF" 
                fontSize={11} 
                tickLine={false} 
                axisLine={false} 
                tick={{fontWeight: 900, fill: '#FFFFFF'}} 
                interval={0}
                angle={-30}
                textAnchor="end"
                height={70}
              />
              <YAxis 
                stroke="#94a3b8" 
                fontSize={10} 
                width={100} 
                tickFormatter={yAxisFormatter} 
                tickLine={false} 
                axisLine={false} 
                tick={{fontWeight: 900, fill: '#94a3b8'}}
              />
              <Tooltip content={<CustomTooltip />} cursor={{fill: 'rgba(255,255,255,0.05)'}} />
              <Bar 
                name="Rencana" 
                dataKey="Anggaran" 
                fill="url(#barGradientRencana)" 
                radius={[12, 12, 4, 4]} 
                maxBarSize={35} 
                isAnimationActive={true}
                animationDuration={1500}
                animationEasing="ease-out"
              />
              <Bar 
                name="Aktual" 
                dataKey="Aktual" 
                radius={[12, 12, 4, 4]} 
                maxBarSize={35}
                isAnimationActive={true}
                animationDuration={2000}
                animationEasing="ease-out"
              >
                {categories.map((entry, index) => (
                  <Cell 
                    key={`bar-cell-${index}`} 
                    fill={entry.isOver ? 'url(#barGradientOver)' : 'url(#barGradientAktual)'}
