                    isAnimationActive={true}
                    animationBegin={200}
                    animationDuration={1500}
                  >
                    {categories.filter(c => c.Anggaran > 0).map((entry, index) => (
                      <Cell 
                        key={`pie-alloc-${index}`} 
                        fill={entry.color} 
                        style={{ filter: 'drop-shadow(0 0 8px rgba(0,0,0,0.3))' }}
                      />
                    ))}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>

        {/* 3D Pie: Actuals */}
        <div className="glass-panel p-8 rounded-[2.5rem] border border-white/10 relative overflow-hidden">
           <div className="flex items-center gap-4 mb-8">
              <div className="w-2 h-6 bg-emerald-500 rounded-full shadow-[0_0_10px_rgba(16,185,129,0.5)]"></div>
              <h3 className="text-sm font-black text-white uppercase tracking-[0.2em]">Realisasi Pengeluaran</h3>
           </div>
           <div className="h-[350px]">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie 
                    data={categories.filter(c => c.Aktual > 0)} 
                    cx="50%" 
                    cy="50%" 
                    innerRadius={80} 
                    outerRadius={110} 
                    dataKey="Aktual" 
                    stroke="#0f172a" 
                    strokeWidth={6} 
                    paddingAngle={8}
                    labelLine={false} 
                    // Set fill label menjadi Putih (#FFFFFF) agar kontras - Fix: Return SVG text element instead of object to match expected PieLabel type
                    label={(props: any) => (
                      <text x={props.x} y={props.y} fill="#FFFFFF" textAnchor={props.textAnchor} dominantBaseline={props.dominantBaseline} fontSize={10} fontWeight="bold">
                        {`${props.name}${props.isOver ? ' ⚠️' : ''} ${(props.percent * 100).toFixed(0)}%`}
                      </text>
                    )}
                    isAnimationActive={true}
                    animationBegin={500}
                    animationDuration={1500}
                  >
                    {categories.filter(c => c.Aktual > 0).map((entry, index) => (
                      <Cell 
                        key={`pie-actual-${index}`} 
                        fill={entry.isOver ? '#FF4D4D' : entry.color} 
                        style={{ filter: entry.isOver ? 'drop-shadow(0 0 12px rgba(255,77,77,0.4))' : 'drop-shadow(0 0 8px rgba(0,0,0,0.3))' }}
                        stroke={entry.isOver ? '#FFFFFF' : '#0f172a'}
                        strokeWidth={entry.isOver ? 2 : 6}
                      />
                    ))}
                  </Pie>
                  <Tooltip content={<CustomTooltip />} />
                </PieChart>
             </ResponsiveContainer>
           </div>
        </div>
      </div>
    </div>
  );
};

