                 </div>
                 <div className="col-span-1 md:col-span-1 flex justify-end">
                   <button type="button" onClick={()=>onRequestDeleteItem(item.id, item.name)} className="p-3 text-slate-600 hover:text-rose-500"><Trash2 size={20} /></button>
