  thr: 0,
  leavePay: 0,
  taxRate: 0,
  otherDeductions: 0,
};

export const DEFAULT_BUDGET: BudgetData = {
  needs: { items: [], name: 'Kebutuhan Pokok' },
  savings: { items: [], name: 'Tabungan & Investasi' },
  debt: { items: [], name: 'Hutang & Cicilan' },
