import React from 'react';
import { BudgetData } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, CartesianGrid } from 'recharts';
import { formatRupiah } from '../utils';
import { AlertTriangle } from 'lucide-react';

interface MonthlyChartsProps {
  budgetData: BudgetData;
  income: number;
}

const CATEGORY_COLORS: { [key: string]: string } = {
  'Pokok': '#6366F1',     // Indigo
  'Tabungan': '#10B981',  // Emerald
  'Cicilan': '#F43F5E',   // Rose
  'Lainnya': '#8B5CF6',   // Violet
};

const EXTRA_COLORS = [
  '#F59E0B', '#06B6D4', '#EC4899', '#14B8A6', '#F97316'
];

const chunkArray = (arr: any[], size: number) => {
  const chunks = [];
  for (let i = 0; i < arr.length; i += size) {
    chunks.push(arr.slice(i, i + size));
  }
  return chunks;
};

const MonthlyCharts: React.FC<MonthlyChartsProps> = ({ budgetData, income }) => {
  const categories: { name: string, Anggaran: number, Aktual: number, isOver: boolean, color: string }[] = [];

  const addCategory = (name: string, budget: number, actual: number, defaultColor: string) => {
    if (budget > 0 || actual > 0) {
      categories.push({
        name,
        Anggaran: budget,
        Aktual: actual,
        isOver: actual > budget,
        color: defaultColor
      });
    }
  };

  addCategory(budgetData.needs?.name || 'Pokok', budgetData.needs?.items?.reduce((a, b) => a + (b.budget || 0), 0) || 0, budgetData.needs?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0, CATEGORY_COLORS['Pokok']);
  addCategory(budgetData.savings?.name || 'Tabungan', budgetData.savings?.items?.reduce((a, b) => a + (b.budget || 0), 0) || 0, budgetData.savings?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0, CATEGORY_COLORS['Tabungan']);
  addCategory(budgetData.debt?.name || 'Cicilan', budgetData.debt?.items?.reduce((a, b) => a + (b.budget || 0), 0) || 0, budgetData.debt?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0, CATEGORY_COLORS['Cicilan']);

  budgetData.custom?.forEach((cat, idx) => {
    addCategory(cat.name || 'Custom', cat.items?.reduce((a, b) => a + (b.budget || 0), 0) || 0, cat.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0, EXTRA_COLORS[idx % EXTRA_COLORS.length]);
  });

  addCategory('Lainnya', budgetData.others?.allocation || 0, budgetData.others?.items?.reduce((a, b) => a + (b.actual || 0), 0) || 0, CATEGORY_COLORS['Lainnya']);

  const categoryChunks = chunkArray(categories, 4);

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      const budgetVal = payload.find((p: any) => p.name === 'Rencana' || p.name === 'Anggaran')?.value || 0;
      const actualVal = payload.find((p: any) => p.name === 'Aktual')?.value || 0;
      const isOver = actualVal > budgetVal && budgetVal > 0;

      return (
        <div className="bg-slate-900 border-2 border-slate-700 p-3 rounded-xl shadow-2xl backdrop-blur-xl min-w-[160px]">
          <p className="font-black text-white text-[10px] uppercase mb-2 border-b border-slate-800 pb-1">{label || payload[0]?.name}</p>
          <div className="space-y-1.5">
            {payload.map((entry: any, index: number) => (
              <div key={index} className="flex items-center justify-between gap-3">
                <div className="flex items-center gap-1.5">
                  <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }}></div>
                  <span className="text-slate-400 text-[9px] font-black uppercase">{entry.name}</span>
                </div>
                <span className={`font-mono text-[9px] font-black ${entry.name === 'Aktual' && isOver ? 'text-rose-400' : 'text-white'}`}>
                  {formatRupiah(entry.value)}
                </span>
              </div>
            ))}
          </div>
        </div>
      );
    }
    return null;
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = outerRadius + 20;
    const x = cx + radius * Math.cos(-midAngle * RADIAN);
    const y = cy + radius * Math.sin(-midAngle * RADIAN);

    return (
      <text 
        x={x} 
        y={y} 
        fill="white" 
        textAnchor={x > cx ? 'start' : 'end'} 
        dominantBaseline="central" 
        fontSize={10} 
        fontWeight="900"
      >
        {`${(percent * 100).toFixed(0)}%`}
      </text>
    );
  };

  const yAxisFormatter = (val: number) => {
    if (val === 0) return 'Rp 0';
    if (val >= 1000000) return `Rp ${(val / 1000000).toFixed(1)}j`;
    return `Rp ${(val / 1000).toFixed(0)}k`;
  };

  const RenderLegend = ({ data }: { data: any[] }) => (
    <div className="mt-6 flex flex-wrap justify-center gap-x-4 gap-y-2 px-2">
      {data.map((item, idx) => {
        return (
          <div key={idx} className="flex items-center gap-1.5 bg-slate-900/50 px-3 py-1.5 rounded-xl border border-white/5">
            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: item.color || item.fill }}></div>
            <span className="text-[9px] font-black uppercase tracking-wider" style={{ color: item.color || item.fill }}>
              {item.name}
            </span>
          </div>
        );
      })}
    </div>
  );

  return (
    <div className="space-y-6 sm:space-y-8 animate-fadeIn pb-10">
      <div className="glass-panel p-4 sm:p-8 rounded-[2rem] border border-white/10 shadow-2xl overflow-hidden relative">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
           <div className="flex items-center gap-3">
              <div className="w-1.5 h-6 bg-amber-400 rounded-full shadow-[0_0_10px_rgba(251,191,36,0.5)]"></div>
              <h3 className="text-base sm:text-xl font-black text-white uppercase tracking-tighter">Budget Performance</h3>
           </div>
           <div className="flex items-center gap-3 bg-slate-900/50 p-2 rounded-xl border border-slate-800">
              <div className="flex items-center gap-1">
                <div className="w-2.5 h-2.5 rounded bg-amber-400"></div>
                <span className="text-[8px] font-black text-slate-400 uppercase">Rencana</span>
              </div>
              <div className="flex items-center gap-1">
                <div className="w-2.5 h-2.5 rounded bg-emerald-500"></div>
                <span className="text-[8px] font-black text-slate-400 uppercase text-emerald-400">Aktual</span>
              </div>
           </div>
        </div>

        <div className="space-y-10">
          {categoryChunks.map((chunk, chunkIdx) => (
            <div key={chunkIdx} className="h-[250px] sm:h-[350px] w-full border-b border-slate-800/30 pb-4 last:border-0 last:pb-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chunk} margin={{ top: 5, right: 5, left: 5, bottom: 5 }}>
                  <defs>
                    <linearGradient id={`planGrad-${chunkIdx}`} x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="#FDE047" stopOpacity={1}/>
                      <stop offset="100%" stopColor="#EAB308" stopOpacity={1}/>
                    </linearGradient>
                    <linearGradient id={`actualGrad-${chunkIdx}`} x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="#A7F3D0" stopOpacity={1}/>
                      <stop offset="100%" stopColor="#10B981" stopOpacity={1}/>
                    </linearGradient>
                    <linearGradient id={`overGrad-${chunkIdx}`} x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="#FDA4AF" stopOpacity={1}/>
                      <stop offset="100%" stopColor="#F43F5E" stopOpacity={1}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#334155" opacity={0.1} />
                  <XAxis 
                    dataKey="name" 
                    stroke="#FFFFFF" 
                    fontSize={8} 
                    tickLine={false} 
                    axisLine={false} 
                    tick={{fontWeight: 900, fill: '#FFFFFF'}} 
                    interval={0}
                    angle={0}
                    textAnchor="middle"
                  />
                  <YAxis 
                    stroke="#94a3b8" 
                    fontSize={8} 
                    width={55} 
                    tickFormatter={yAxisFormatter} 
                    tickLine={false} 
                    axisLine={false} 
                  />
                  <Tooltip 
                    content={<CustomTooltip />} 
                    cursor={{fill: 'rgba(255,255,255,0.03)'}} 
                  />
                  <Bar dataKey="Anggaran" name="Rencana" fill={`url(#planGrad-${chunkIdx})`} radius={[4, 4, 0, 0]} maxBarSize={25} />
                  <Bar dataKey="Aktual" name="Aktual" radius={[4, 4, 0, 0]} maxBarSize={25}>
                    {chunk.map((entry, index) => (
                      <Cell key={`bar-${index}`} fill={entry.isOver ? `url(#overGrad-${chunkIdx})` : `url(#actualGrad-${chunkIdx})`} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="glass-panel p-6 sm:p-8 rounded-[2rem] border border-white/10 flex flex-col items-center">
           <h3 className="w-full text-xs font-black text-white uppercase tracking-widest mb-6 border-b border-slate-800 pb-2">Rencana Alokasi (%)</h3>
           <div className="h-[280px] w-full">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie 
                    data={categories.filter(c => c.Anggaran > 0)} 
                    cx="50%" cy="50%" 
                    innerRadius={50} 
                    outerRadius={80} 
                    dataKey="Anggaran" 
                    stroke="#0f172a" 
                    strokeWidth={4} 
                    paddingAngle={3}
                    labelLine={{ stroke: 'rgba(255,255,255,0.3)', strokeWidth: 1 }}
                    label={renderCustomLabel}
                  >
                    {categories.filter(c => c.Anggaran > 0).map((entry, index) => <Cell key={`p1-${index}`} fill={entry.color} />)}
                  </Pie>
                  <Tooltip 
                    content={<CustomTooltip />} 
                  />
                </PieChart>
             </ResponsiveContainer>
           </div>
           <RenderLegend data={categories.filter(c => c.Anggaran > 0)} />
        </div>

        <div className="glass-panel p-6 sm:p-8 rounded-[2rem] border border-white/10 flex flex-col items-center">
           <h3 className="w-full text-xs font-black text-white uppercase tracking-widest mb-6 border-b border-slate-800 pb-2">Realisasi Pengeluaran (%)</h3>
           <div className="h-[280px] w-full">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie 
                    data={categories.filter(c => c.Aktual > 0)} 
                    cx="50%" cy="50%" 
                    innerRadius={50} 
                    outerRadius={80} 
                    dataKey="Aktual" 
                    stroke="#0f172a" 
                    strokeWidth={4} 
                    paddingAngle={3}
                    labelLine={{ stroke: 'rgba(255,255,255,0.3)', strokeWidth: 1 }}
                    label={renderCustomLabel}
                  >
                    {categories.filter(c => c.Aktual > 0).map((entry, index) => <Cell key={`p2-${index}`} fill={entry.isOver ? '#F43F5E' : entry.color} />)}
                  </Pie>
                  <Tooltip 
                    content={<CustomTooltip />} 
                  />
                </PieChart>
             </ResponsiveContainer>
           </div>
           <RenderLegend 
            data={categories.filter(c => c.Aktual > 0).map(cat => ({...cat, color: cat.isOver ? '#F43F5E' : cat.color}))} 
           />
        </div>
      </div>
    </div>
  );
};

export default MonthlyCharts;

import React, { useState } from 'react';
import { BudgetData, BudgetItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import DeleteModal from './ui/DeleteModal';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, FolderPlus, X, Check, AlertTriangle, Pencil, BellRing } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  colorHex: string;
  onUpdateItems: (items: BudgetItem[]) => void;
  onRequestDeleteCategory: () => void;
  onRequestDeleteItem: (id: string, name: string) => void;
  onRenameCategory: (newName: string) => void;
  defaultExpanded?: boolean;
  canDelete?: boolean;
  canRename?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  colorHex,
  onUpdateItems,
  onRequestDeleteCategory,
  onRequestDeleteItem,
  onRenameCategory,
  defaultExpanded = false,
  canDelete = true,
  canRename = true
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [tempTitle, setTempTitle] = useState(title);

  const catTotalAllocated = items?.reduce((a, b) => a + (b.budget || 0), 0) || 0;
  const catTotalActual = items?.reduce((a, b) => a + (b.actual || 0), 0) || 0;
  const isCatOver = catTotalActual > catTotalAllocated;
  const catRemaining = catTotalAllocated - catTotalActual;
  const catProgress = catTotalAllocated > 0 ? (catTotalActual / catTotalAllocated) * 100 : 0;

  const filledCount = items?.filter(item => (item.actual || 0) > 0).length || 0;
  const totalCount = items?.length || 0;
  const isIncomplete = items?.some(item => (item.budget || 0) > 0 && (item.actual || 0) === 0);

  const handleRename = () => {
    if (tempTitle.trim() && tempTitle !== title) {
      onRenameCategory(tempTitle.trim());
    } else {
      setTempTitle(title);
    }
    setIsEditingTitle(false);
  };

  return (
    <div 
      className={`glass-panel rounded-[2rem] overflow-hidden mb-6 transition-all duration-500 ${isCatOver ? 'ring-2 ring-rose-500 shadow-[0_0_30px_rgba(244,63,94,0.3)]' : 'hover:shadow-2xl hover:border-white/20'}`}
      style={{ borderLeft: `6px solid ${colorHex}` }}
    >
      <div className="flex items-stretch border-b border-white/5">
        <div 
          className="flex-1 p-5 sm:p-6 flex items-center gap-4 sm:gap-5 cursor-pointer hover:bg-white/5 transition-colors"
          onClick={() => !isEditingTitle && setExpanded(!expanded)}
        >
          <div className="p-3 rounded-2xl bg-slate-900 shadow-inner shrink-0" style={{ color: isCatOver ? '#F43F5E' : colorHex }}>
            {expanded ? <ChevronUp size={20} className="sm:w-6 sm:h-6" /> : <ChevronDown size={20} className="sm:w-6 sm:h-6" />}
          </div>
          <div className="flex-1 min-w-0">
             <div className="flex flex-wrap items-center gap-2 sm:gap-3">
                {isEditingTitle ? (
                  <div className="flex items-center gap-2 bg-slate-900 rounded-lg p-1 border border-indigo-500/50" onClick={e => e.stopPropagation()}>
                    <input 
                      value={tempTitle} 
                      onChange={e => setTempTitle(e.target.value)} 
                      onKeyDown={e => e.key === 'Enter' && handleRename()}
                      autoFocus
                      className="bg-transparent border-none outline-none text-white font-black text-sm sm:text-lg uppercase px-2 w-40 sm:w-64" 
                    />
                    <button onClick={handleRename} className="p-1 bg-indigo-600 rounded text-white"><Check size={14}/></button>
                  </div>
                ) : (
                  <div className="flex items-center gap-2 group/title">
                    <h4 className="font-black text-sm sm:text-lg text-white uppercase tracking-tighter truncate">{title}</h4>
                    {canRename && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); setIsEditingTitle(true); }}
                        className="p-1.5 text-slate-500 hover:text-indigo-400 opacity-0 group-hover/title:opacity-100 transition-opacity"
                      >
                        <Pencil size={14} />
                      </button>
                    )}
                  </div>
                )}
                <div className="flex items-center gap-2 flex-wrap">
                   <span className="text-[9px] sm:text-[10px] font-black text-slate-400 bg-slate-900 px-2 sm:px-3 py-1 rounded-full border border-slate-700 whitespace-nowrap uppercase">{filledCount}/{totalCount} TERISI</span>
                   {isCatOver && (
                     <span className="flex items-center gap-1 text-[8px] sm:text-[9px] font-black text-white bg-rose-600 px-2.5 py-1 rounded-full border border-rose-400/50 animate-pulse whitespace-nowrap shadow-[0_0_15px_rgba(244,63,94,0.5)]">
                        <BellRing size={10} /> ALARM OVERBUDGET
                     </span>
                   )}
                   {isIncomplete && !isCatOver && (
                     <span className="flex items-center gap-1 text-[8px] sm:text-[9px] font-black text-amber-400 bg-amber-400/10 px-2 py-1 rounded-full border border-amber-400/20 whitespace-nowrap">
                        <AlertTriangle size={10} /> BELUM LENGKAP
                     </span>
                   )}
                </div>
             </div>
             <div className="flex flex-wrap gap-x-4 gap-y-1.5 mt-2.5 text-[9px] sm:text-[10px] font-black uppercase tracking-widest text-slate-500 border-t border-white/5 pt-2">
                <span className="flex items-center gap-1.5">BUDGET: <span className="text-white">{formatRupiah(catTotalAllocated)}</span></span>
                <span className="flex items-center gap-1.5">AKTUAL: <span className={isCatOver ? 'text-rose-400 font-black' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></span>
                <span className="flex items-center gap-1.5 border-l border-white/10 pl-3">SISA: <span className={catRemaining < 0 ? 'text-rose-400' : 'text-emerald-400 font-black'}>{formatRupiah(catRemaining)}</span></span>
                <span className="flex items-center gap-1.5 border-l border-white/10 pl-3">PROGRES: <span className={isCatOver ? 'text-rose-400' : 'text-indigo-400'}>{catProgress.toFixed(0)}%</span></span>
             </div>
          </div>
        </div>

        {canDelete && (
          <div className="flex items-center px-3 sm:px-4 bg-slate-950/20 border-l border-white/5">
            <button 
              type="button" 
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                onRequestDeleteCategory();
              }}
              className="p-3 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all"
            >
              <Trash2 size={20} />
            </button>
          </div>
        )}
      </div>

      {expanded && (
        <div className="p-4 sm:p-8 bg-slate-950/40 space-y-4 animate-fadeIn">
           {(items || []).map((item) => {
             const isItemOver = (item.actual || 0) > (item.budget || 0);
             return (
               <div key={item.id} className={`grid grid-cols-2 md:grid-cols-12 gap-3 sm:gap-4 p-4 bg-slate-900/60 rounded-2xl border ${isItemOver ? 'border-rose-500/30 bg-rose-900/5' : 'border-white/5'} items-end transition-all`}>
                 <div className="col-span-2 md:col-span-5">
                   <label className="text-[9px] uppercase font-black text-slate-500 block mb-2 tracking-widest">Detail Item</label>
                   <input type="text" value={item.name} onChange={(e) => onUpdateItems(items.map(i => i.id === item.id ? {...i, name: e.target.value} : i))} className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm text-white font-black outline-none focus:border-indigo-500 shadow-inner" placeholder="Nama item..." />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Budget" value={item.budget} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, budget: v} : i))} />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, actual: v} : i))} />
                   <div className="flex justify-between mt-1 px-1">
                      <span className="text-[8px] font-black uppercase text-slate-500">SISA: <span className={(item.budget-item.actual) < 0 ? 'text-rose-400' : 'text-slate-400'}>{formatRupiah(item.budget-item.actual)}</span></span>
                   </div>
                 </div>
                 <div className="col-span-2 md:col-span-1 flex justify-end">
                   <button 
                      type="button" 
                      onClick={() => onRequestDeleteItem(item.id, item.name)} 
                      className="p-3 text-slate-600 hover:text-rose-500"
                   >
                     <Trash2 size={20} />
                   </button>
                 </div>
               </div>
             );
           })}
           <button 
             type="button" 
             onClick={() => onUpdateItems([...(items || []), {id: Date.now().toString(), name: '', budget: 0, actual: 0}])} 
             className="w-full py-4 border-2 border-dashed border-slate-700 rounded-2xl flex items-center justify-center gap-3 font-black text-[10px] uppercase tracking-[0.2em] text-slate-500 hover:text-white transition-all"
           >
             <Plus size={16} /> TAMBAH ITEM
           </button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newName, setNewName] = useState('');
  const [deleteTarget, setDeleteTarget] = useState<any>(null);

  const CATEGORY_COLORS = {
    needs: '#6366F1',
    savings: '#10B981',
    debt: '#F43F5E',
    others: '#8B5CF6',
    extra: ['#F59E0B', '#06B6D4', '#EC4899', '#14B8A6', '#F97316']
  };

  const totalAlloc = (data.needs?.items?.reduce((a,b)=>a+(b.budget||0),0)||0) + 
                     (data.savings?.items?.reduce((a,b)=>a+(b.budget||0),0)||0) + 
                     (data.debt?.items?.reduce((a,b)=>a+(b.budget||0),0)||0) + 
                     (data.others?.allocation||0) + 
                     (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+(ii.budget||0),0),0)||0);

  const totalAct = (data.needs?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.savings?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.debt?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.others?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+(ii.actual||0),0),0)||0);

  const confirmDelete = () => {
    if (!deleteTarget) return;
    if (deleteTarget.type === 'category') {
      const { categoryKey, id } = deleteTarget;
      if (categoryKey === 'custom') {
        onChange({ ...data, custom: (data.custom || []).filter(c => c.id !== id) });
      } else {
        const newData = { ...data };
        delete (newData as any)[categoryKey];
        onChange(newData);
      }
    } else {
      const { categoryKey, id } = deleteTarget;
      if (['needs', 'savings', 'debt'].includes(categoryKey)) {
        const cat = (data as any)[categoryKey];
        onChange({ ...data, [categoryKey]: { ...cat, items: cat.items.filter((i:any) => i.id !== id) } });
      } else if (categoryKey === 'others-items') {
        onChange({ ...data, others: { ...data.others!, items: data.others!.items.filter(i => i.id !== id) } });
      } else {
        const updatedCustom = (data.custom || []).map(cat => cat.id === categoryKey ? { ...cat, items: cat.items.filter(i => i.id !== id) } : cat);
        onChange({ ...data, custom: updatedCustom });
      }
    }
    setDeleteTarget(null);
  };

  const handleRenameFixed = (key: 'needs' | 'savings' | 'debt', newName: string) => {
    const section = data[key];
    if (section) {
      onChange({ ...data, [key]: { ...section, name: newName } });
    }
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-20 animate-fadeIn">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 sm:gap-6">
        <div className="glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 border-indigo-600 shadow-xl">
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Net Income</p>
          <h3 className="text-sm sm:text-2xl font-black text-white tracking-tight">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 border-blue-500 shadow-xl">
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Anggaran</p>
          <h3 className="text-sm sm:text-2xl font-black text-white tracking-tight">{formatRupiah(totalAlloc)}</h3>
        </div>
        <div className="glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 border-amber-500 shadow-xl">
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Realisasi</p>
          <h3 className="text-sm sm:text-2xl font-black text-amber-500 tracking-tight">{formatRupiah(totalAct)}</h3>
        </div>
        <div className={`glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 shadow-xl ${income-totalAct < 0 ? 'border-rose-600' : 'border-emerald-600'}`}>
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Sisa</p>
          <h3 className={`text-sm sm:text-2xl font-black tracking-tight ${income-totalAct < 0 ? 'text-rose-500' : 'text-emerald-500'}`}>{formatRupiah(income-totalAct)}</h3>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-4 border-b border-white/5 pb-6">
         <h2 className="text-xl sm:text-2xl font-black text-white uppercase tracking-tighter flex items-center gap-3">
            <div className="w-2 h-6 sm:h-8 bg-indigo-600 rounded-full shadow-[0_0_10px_rgba(99,102,241,0.5)]"></div> 
            ALOKASI ANGGARAN
         </h2>
         {!isAdding ? (
           <button onClick={() => setIsAdding(true)} className="w-full sm:w-auto px-6 py-3 sm:px-8 sm:py-4 bg-indigo-600 text-white rounded-xl sm:rounded-2xl text-[10px] sm:text-xs font-black flex items-center justify-center gap-3 uppercase tracking-widest transition-all hover:bg-indigo-700 shadow-lg">
             <FolderPlus size={16} /> TAMBAH KATEGORI
           </button>
         ) : (
           <div className="flex items-center gap-2 bg-slate-900 p-2 rounded-xl border border-slate-700 w-full sm:w-auto">
             <input autoFocus value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==='Enter' && (()=>{if(newName.trim()){onChange({...data, custom: [...(data.custom||[]), {id: Date.now().toString(), name: newName.trim(), items: []}]}); setNewName(''); setIsAdding(false);}})()} placeholder="Nama Kategori..." className="bg-transparent border-none outline-none text-white font-black text-sm uppercase px-2 w-40 sm:w-64" />
             <button onClick={()=>{if(newName.trim()){onChange({...data, custom: [...(data.custom||[]), {id: Date.now().toString(), name: newName.trim(), items: []}]}); setNewName(''); setIsAdding(false);}}} className="p-2 bg-indigo-600 text-white rounded-lg"><Check size={18}/></button>
             <button onClick={()=>setIsAdding(false)} className="p-2 bg-slate-800 text-slate-400 rounded-lg"><X size={18}/></button>
           </div>
         )}
      </div>

      <div className="space-y-4">
        {data.needs && <CategorySection title={data.needs.name || "Kebutuhan Pokok"} items={data.needs.items} colorHex={CATEGORY_COLORS.needs} onRenameCategory={(val) => handleRenameFixed('needs', val)} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'needs', name: data.needs?.name || 'Kebutuhan Pokok', categoryKey: 'needs' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'needs' })} onUpdateItems={i => onChange({ ...data, needs: { ...data.needs, items: i } })} canDelete={true} canRename={true} />}

        {data.savings && <CategorySection title={data.savings.name || "Tabungan & Investasi"} items={data.savings.items} colorHex={CATEGORY_COLORS.savings} onRenameCategory={(val) => handleRenameFixed('savings', val)} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'savings', name: data.savings?.name || 'Tabungan & Investasi', categoryKey: 'savings' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'savings' })} onUpdateItems={i => onChange({ ...data, savings: { ...data.savings, items: i } })} canDelete={true} canRename={true} />}

        {data.debt && <CategorySection title={data.debt.name || "Hutang & Cicilan"} items={data.debt.items} colorHex={CATEGORY_COLORS.debt} onRenameCategory={(val) => handleRenameFixed('debt', val)} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'debt', name: data.debt?.name || 'Hutang & Cicilan', categoryKey: 'debt' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'debt' })} onUpdateItems={i => onChange({ ...data, debt: { ...data.debt, items: i } })} canDelete={true} canRename={true} />}

        {(data.custom||[]).map((cat, idx) => (
          <CategorySection key={cat.id} title={cat.name} items={cat.items} colorHex={CATEGORY_COLORS.extra[idx % CATEGORY_COLORS.extra.length]} onRenameCategory={(newTitle) => onChange({...data, custom: data.custom!.map(c => c.id === cat.id ? {...c, name: newTitle} : c)})} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: cat.id, name: cat.name, categoryKey: 'custom' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: cat.id })} onUpdateItems={i => onChange({ ...data, custom: data.custom!.map(c => c.id === cat.id ? { ...c, items: i } : c) })} />
        ))}

        {data.others && <OthersSection data={data.others} onUpdate={o=>onChange({...data, others: o})} onRequestDelete={()=>setDeleteTarget({ type: 'category', id: 'others', name: 'Lain-lain', categoryKey: 'others' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'others-items' })} />}
      </div>

      <DeleteModal isOpen={!!deleteTarget} title={deleteTarget?.type === 'category' ? 'Hapus Kategori' : 'Hapus Item'} itemName={deleteTarget?.name || ''} onClose={() => setDeleteTarget(null)} onConfirm={confirmDelete} />
    </div>
  );
};

const OthersSection: React.FC<{data: any, onUpdate: (d: any)=>void, onRequestDelete: ()=>void, onRequestDeleteItem: (id: string, name: string) => void}> = ({data, onUpdate, onRequestDelete, onRequestDeleteItem}) => {
  const [expanded, setExpanded] = useState(false);
  const totalAct = data.items?.reduce((a:any, b:any)=>a+(b.actual||0), 0) || 0;
  const totalAlloc = data.allocation || 0;
  const isOver = totalAct > totalAlloc;
  const remaining = totalAlloc - totalAct;
  const progress = totalAlloc > 0 ? (totalAct / totalAlloc) * 100 : 0;

  const itemsWithActual = data.items?.filter((item:any) => (item.actual || 0) > 0).length || 0;
  const totalItems = data.items?.length || 0;

  return (
    <div className={`glass-panel rounded-[2rem] overflow-hidden mb-6 transition-all ${isOver ? 'ring-2 ring-rose-500 shadow-[0_0_20px_rgba(244,63,94,0.3)]' : 'hover:shadow-2xl'}`} style={{ borderLeft: '6px solid #8B5CF6' }}>
      <div className="flex items-stretch border-b border-white/5">
        <div className="flex-1 p-5 sm:p-6 flex items-center gap-4 sm:gap-5 cursor-pointer hover:bg-white/5 transition-colors" onClick={() => setExpanded(!expanded)}>
           <div className="p-3 rounded-2xl bg-slate-900 text-[#8B5CF6] shrink-0">
             {expanded ? <ChevronUp size={20} className="sm:w-6 sm:h-6" /> : <ChevronDown size={20} className="sm:w-6 sm:h-6" />}
           </div>
           <div className="flex-1">
                <div className="flex flex-wrap items-center gap-2 sm:gap-3">
                  <h4 className="font-black text-sm sm:text-lg text-white uppercase tracking-tighter">Lain-lain / Hiburan</h4>
                  <div className="flex gap-2">
                    <span className="text-[9px] sm:text-[10px] font-black text-slate-400 bg-slate-900 px-2 sm:px-3 py-1 rounded-full border border-slate-700 uppercase">{itemsWithActual}/{totalItems} TERISI</span>
                    {isOver && (
                      <span className="flex items-center gap-1 text-[8px] sm:text-[9px] font-black text-white bg-rose-600 px-2.5 py-1 rounded-full animate-pulse shadow-lg shadow-rose-900/40">
                        <BellRing size={10} /> ALARM
                      </span>
                    )}
                  </div>
                </div>
                <div className="flex flex-wrap gap-x-4 gap-y-1.5 mt-2.5 text-[9px] sm:text-[10px] font-black uppercase text-slate-500 tracking-widest pt-2 border-t border-white/5">
