import React, { useState, useEffect } from 'react';
import { AppState, MonthlyData, DEFAULT_SALARY, DEFAULT_BUDGET } from './types';
import SalarySlip from './components/SalarySlip';
import Budget from './components/Budget';
import MonthlyCharts from './components/MonthlyCharts';
import Investments from './components/Investments';
import YearlySummary from './components/YearlySummary';
import AIAnalysis from './components/AIAnalysis';
import { calculateGrossIncome, calculateTax, calculateOvertime, calculateBonus } from './utils';
import { Wallet, LayoutDashboard, PieChart, TrendingUp, Calendar, ChevronLeft, ChevronRight, Cloud, Loader2, CheckCircle2, Sparkles } from 'lucide-react';
import { supabase } from './supabaseClient';

const TABS = [
  { id: 'salary', label: 'Gaji', icon: Wallet },
  { id: 'budget', label: 'Anggaran', icon: LayoutDashboard },
  { id: 'charts', label: 'Grafik', icon: PieChart },
  { id: 'invest', label: 'Aset', icon: TrendingUp },
  { id: 'year', label: 'Tahunan', icon: Calendar },
  { id: 'ai', label: 'AI Analisis', icon: Sparkles },
];

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');
  const [appState, setAppState] = useState<AppState>({});
  const [isLoading, setIsLoading] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase.from('monthly_finance').select('month_id, data');
        if (error) throw error;
        if (data) {
          const loadedState: AppState = {};
          data.forEach((row: any) => { loadedState[row.month_id] = row.data; });
          setAppState(loadedState);
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (isLoading || !appState[currentMonthKey]) return;
    const saveData = async () => {
      setSaveStatus('saving');
      try {
        const { error } = await supabase.from('monthly_finance').upsert({ 
          month_id: currentMonthKey, 
          data: appState[currentMonthKey],
          updated_at: new Date().toISOString()
        });
        if (error) throw error;
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } catch (err) {
        console.error("Error saving data:", err);
        setSaveStatus('error');
      }
    };
    const timeoutId = setTimeout(saveData, 800);
    return () => clearTimeout(timeoutId);
  }, [appState, currentMonthKey, isLoading]);

  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     return gross - calculateTax(gross, salary.taxRate) - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  useEffect(() => {
    if (!isLoading && !appState[currentMonthKey]) {
      const prevDate = new Date(currentDate);
      prevDate.setMonth(currentDate.getMonth() - 1);
      const pKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
      if (appState[pKey]) {
        setPrevMonthKey(pKey);
        setShowCopyModal(true);
      } else {
        initializeMonth(false);
      }
    }
  }, [currentMonthKey, isLoading]);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      newData = JSON.parse(JSON.stringify(appState[prevMonthKey]));
      if (newData.budget.needs) newData.budget.needs.items.forEach(i => i.actual = 0);
      if (newData.budget.savings) newData.budget.savings.items.forEach(i => i.actual = 0);
      if (newData.budget.debt) newData.budget.debt.items.forEach(i => i.actual = 0);
      if (newData.budget.others) newData.budget.others.items.forEach(i => i.actual = 0);
      if (newData.budget.custom) newData.budget.custom.forEach(cat => cat.items.forEach(i => i.actual = 0));
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = { salary: { ...DEFAULT_SALARY }, budget: { ...DEFAULT_BUDGET }, investments: [] };
    }
    setAppState(prev => ({ ...prev, [currentMonthKey]: newData }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => {
      const existing = prev[currentMonthKey] || { 
        salary: { ...DEFAULT_SALARY }, 
        budget: { ...DEFAULT_BUDGET }, 
        investments: [] 
      };
      const updatedMonth = { ...existing, ...newData };
      return { 
        ...prev, 
        [currentMonthKey]: updatedMonth 
      };
    });
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  if (isLoading) return <div className="min-h-screen flex items-center justify-center bg-[#0f172a]"><Loader2 className="w-10 h-10 text-indigo-400 animate-spin" /></div>;

  return (
    <div className="min-h-screen bg-[#0f172a] font-sans selection:bg-indigo-500/30 selection:text-indigo-200">
      <nav className="sticky top-0 z-50 pt-2 px-2 sm:pt-4 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl border border-white/5">
          <div className="flex flex-col sm:flex-row items-center justify-between p-3 sm:px-6 sm:h-20 gap-3">
            <div className="flex items-center justify-between w-full sm:w-auto">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-lg shadow-lg">
                     <Wallet className="text-white h-5 w-5 sm:h-6 sm:w-6" />
                  </div>
                  <div>
                    <h1 className="text-sm sm:text-xl font-black text-white uppercase tracking-tight leading-tight">ANIQ SUSILO</h1>
                    <p className="text-[10px] sm:text-xs font-black text-indigo-400 uppercase tracking-widest mt-0.5">FINANCE MONTHLY</p>
                  </div>
                </div>
                <div className="flex sm:hidden items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
                   <button onClick={() => changeMonth(-1)} className="p-1.5"><ChevronLeft size={16} /></button>
                   <div className="px-2 font-mono font-black text-indigo-400 text-xs uppercase">
                     {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' })}
                   </div>
                   <button onClick={() => changeMonth(1)} className="p-1.5"><ChevronRight size={16} /></button>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-slate-800/50 rounded-lg border border-slate-700/50">
                  {saveStatus === 'saving' ? <Loader2 size={14} className="animate-spin text-indigo-400" /> : saveStatus === 'saved' ? <CheckCircle2 size={14} className="text-emerald-400" /> : <Cloud size={12} className="text-slate-500"/>}
                  <span className="text-[10px] font-black uppercase text-slate-400">{saveStatus === 'saving' ? 'Saving' : saveStatus === 'saved' ? 'Saved' : 'Synced'}</span>
                </div>
                <div className="hidden sm:flex items-center bg-slate-800/80 rounded-xl p-1.5 border border-slate-700 shadow-sm">
                  <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronLeft size={20} /></button>
                  <div className="px-6 font-mono font-black text-indigo-400 w-48 text-center text-sm uppercase tracking-wider">
                    {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' }).toUpperCase()}
                  </div>
                  <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronRight size={20} /></button>
                </div>
            </div>
          </div>
          <div className="border-t border-slate-700/50 px-2 overflow-x-auto scrollbar-hide">
            <div className="flex space-x-1 py-1.5 sm:py-2">
              {TABS.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs font-black rounded-lg transition-all flex-1 justify-center sm:flex-none uppercase tracking-widest ${isActive ? 'text-white bg-indigo-600 shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
                    <Icon size={16} />{tab.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </nav>
      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && <SalarySlip data={currentData.salary} onChange={(s) => updateCurrentData({ salary: s })} />}
        {activeTab === 'budget' && <Budget income={currentNetIncome} data={currentData.budget} onChange={(b) => updateCurrentData({ budget: b })} />}
        {activeTab === 'charts' && <MonthlyCharts budgetData={currentData.budget} income={currentNetIncome} />}
        {activeTab === 'invest' && <Investments items={currentData.investments} onChange={(i) => updateCurrentData({ investments: i })} />}
        {activeTab === 'year' && <YearlySummary appState={appState} year={currentDate.getFullYear()} />}
        {activeTab === 'ai' && <AIAnalysis currentMonthData={currentData} netIncome={currentNetIncome} />}
      </main>
      {showCopyModal && (
        <div className="fixed inset-0 bg-slate-950/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="bg-slate-900 p-8 rounded-3xl max-w-md w-full border border-slate-800 shadow-2xl">
              <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Bulan Baru</h3>
              <p className="text-slate-400 mb-8 font-black">Data bulan ini belum ada. Salin template dari bulan sebelumnya?</p>
              <div className="flex gap-4">
                <button onClick={() => initializeMonth(true)} className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg">Salin</button>
                <button onClick={() => initializeMonth(false)} className="flex-1 bg-slate-800 text-slate-200 py-3 rounded-xl font-black uppercase tracking-widest hover:bg-slate-700 transition-all">Baru</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MonthlyData } from '../types';
import { formatRupiah } from '../utils';
import { Sparkles, BrainCircuit, RefreshCw, TrendingUp, AlertCircle, CheckCircle2 } from 'lucide-react';

interface AIAnalysisProps {
  currentMonthData: MonthlyData;
  netIncome: number;
}

const AIAnalysis: React.FC<AIAnalysisProps> = ({ currentMonthData, netIncome }) => {
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const generateAnalysis = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const budgetDetails = JSON.stringify({
        income: formatRupiah(netIncome),
        needs: currentMonthData.budget.needs?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        savings: currentMonthData.budget.savings?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        debt: currentMonthData.budget.debt?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        others: currentMonthData.budget.others?.items.map(i => ({ name: i.name, actual: i.actual })),
        investments: currentMonthData.investments.map(i => ({ name: i.name, value: i.currentValue, target: i.targetValue }))
      });

      const prompt = `Bertindaklah sebagai Konsultan Keuangan Pribadi Profesional. Analisis data keuangan berikut untuk bulan ini dan berikan wawasan mendalam dalam Bahasa Indonesia.

      Data Keuangan:
      ${budgetDetails}

      Format respon Anda harus meliputi:
      1. Ringkasan Singkat Kesehatan Keuangan (Gunakan nada yang menyemangati).
      2. Analisis Efisiensi Anggaran (Soroti area yang hemat atau overbudget).
      3. Analisis Aset & Investasi (Seberapa dekat dengan target).
      4. 3 Saran Praktis untuk bulan depan agar kondisi keuangan Aniq Susilo semakin kuat.

      Berikan respon dalam format Markdown yang rapi dengan heading dan poin-poin. Jangan gunakan teknis yang terlalu rumit, buatlah mudah dipahami dan berorientasi pada tindakan.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });

      setAnalysis(response.text || "Maaf, AI gagal memberikan respon.");
    } catch (err) {
      console.error("AI Analysis Error:", err);
      setError("Gagal menghubungkan ke server AI. Pastikan Anda memiliki koneksi internet yang stabil.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      <div className="glass-panel p-6 sm:p-10 rounded-[2.5rem] border border-indigo-500/20 shadow-2xl relative overflow-hidden group">
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-indigo-600/10 rounded-full blur-3xl group-hover:bg-indigo-600/20 transition-all"></div>

        <div className="relative z-10 flex flex-col items-center text-center">
          <div className="bg-gradient-to-br from-indigo-500 to-blue-600 p-4 rounded-3xl shadow-xl mb-6">
            <BrainCircuit className="text-white w-8 h-8 sm:w-12 sm:h-12" />
          </div>
          <h2 className="text-2xl sm:text-4xl font-black text-white uppercase tracking-tighter mb-4">Financial AI Intelligence</h2>
          <p className="text-slate-400 max-w-lg font-bold text-sm sm:text-base leading-relaxed mb-8">
            Dapatkan analisis cerdas dan rekomendasi strategis berdasarkan data keuangan Anda bulan ini menggunakan teknologi AI terbaru.
          </p>

          <button 
            onClick={generateAnalysis}
            disabled={isLoading}
            className={`flex items-center gap-3 px-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black uppercase tracking-widest transition-all shadow-lg shadow-indigo-900/40 disabled:opacity-50 disabled:cursor-not-allowed`}
          >
            {isLoading ? (
              <>
                <RefreshCw className="w-5 h-5 animate-spin" />
                Menganalisis...
              </>
            ) : (
              <>
                <Sparkles className="w-5 h-5" />
                Mulai Analisis AI
              </>
            )}
          </button>
        </div>
      </div>

      {error && (
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-rose-500 flex items-center gap-4 bg-rose-500/5">
          <AlertCircle className="text-rose-500 shrink-0" size={24} />
          <p className="text-rose-200 text-sm font-black">{error}</p>
        </div>
      )}

      {analysis && !isLoading && (
        <div className="glass-panel p-6 sm:p-10 rounded-[2.5rem] border border-white/5 shadow-xl animate-fadeIn">
          <div className="flex items-center gap-3 mb-8 border-b border-white/5 pb-4">
            <div className="w-1.5 h-6 bg-emerald-500 rounded-full"></div>
            <h3 className="text-lg font-black text-white uppercase tracking-widest">Laporan Analisis Cerdas</h3>
          </div>
          <div className="prose prose-invert max-w-none">
            <div className="text-slate-300 leading-relaxed font-medium space-y-4 whitespace-pre-wrap">
              {analysis.split('\n').map((line, i) => {
                if (line.startsWith('#')) {
                  return <h3 key={i} className="text-xl font-black text-indigo-400 mt-6 mb-3 uppercase border-l-2 border-indigo-500 pl-3">{line.replace(/#/g, '').trim()}</h3>;
                }
                if (line.trim().startsWith('-') || line.trim().startsWith('*')) {
                  return (
                    <div key={i} className="flex gap-3 items-start ml-2 mb-2">
                      <div className="mt-1.5 bg-indigo-500/30 rounded-full p-0.5">
                        <CheckCircle2 size={12} className="text-indigo-400" />
                      </div>
                      <span className="text-slate-200 font-bold">{line.replace(/[-*]/, '').trim()}</span>
                    </div>
                  );
                }
                return <p key={i} className="mb-2 font-bold">{line}</p>;
              })}
            </div>
          </div>

          <div className="mt-12 pt-8 border-t border-white/5 flex flex-col sm:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-500 tracking-widest">
              <TrendingUp size={14} className="text-indigo-500" />
              Dianalisis secara real-time oleh Gemini Flash
            </div>
            <button onClick={generateAnalysis} className="text-xs font-black uppercase tracking-widest text-indigo-400 hover:text-white transition-colors flex items-center gap-2">
              <RefreshCw size={14} /> Refresh Analisis
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AIAnalysis;

import React, { useState } from 'react';
import { BudgetData, BudgetItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import DeleteModal from './ui/DeleteModal';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, FolderPlus, X, Check, AlertTriangle, Pencil, BellRing, OctagonAlert } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  colorHex: string;
  onUpdateItems: (items: BudgetItem[]) => void;
  onRequestDeleteCategory: () => void;
  onRequestDeleteItem: (id: string, name: string) => void;
  onRenameCategory: (newName: string) => void;
  defaultExpanded?: boolean;
  canDelete?: boolean;
  canRename?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  colorHex,
  onUpdateItems,
  onRequestDeleteCategory,
  onRequestDeleteItem,
  onRenameCategory,
  defaultExpanded = false,
  canDelete = true,
  canRename = true
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [tempTitle, setTempTitle] = useState(title);

  const catTotalAllocated = items?.reduce((a, b) => a + (b.budget || 0), 0) || 0;
  const catTotalActual = items?.reduce((a, b) => a + (b.actual || 0), 0) || 0;
  const isCatOver = catTotalActual > catTotalAllocated;
  const catRemaining = catTotalAllocated - catTotalActual;
  const catProgress = catTotalAllocated > 0 ? (catTotalActual / catTotalAllocated) * 100 : 0;

  const filledCount = items?.filter(item => (item.actual || 0) > 0).length || 0;
  const totalCount = items?.length || 0;
  const isIncomplete = items?.some(item => (item.budget || 0) > 0 && (item.actual || 0) === 0);

  const handleRename = () => {
    if (tempTitle.trim() && tempTitle !== title) {
      onRenameCategory(tempTitle.trim());
    } else {
      setTempTitle(title);
    }
    setIsEditingTitle(false);
  };

  return (
    <div 
      className={`glass-panel rounded-[2rem] overflow-hidden mb-6 transition-all duration-500 ${isCatOver ? 'ring-2 ring-rose-500 shadow-[0_0_30px_rgba(244,63,94,0.3)]' : 'hover:shadow-2xl hover:border-white/20'}`}
      style={{ borderLeft: `6px solid ${colorHex}` }}
    >
      <div className="flex items-stretch border-b border-white/5">
        <div 
          className="flex-1 p-5 sm:p-6 flex items-center gap-4 sm:gap-5 cursor-pointer hover:bg-white/5 transition-colors"
          onClick={() => !isEditingTitle && setExpanded(!expanded)}
        >
          <div className="p-3 rounded-2xl bg-slate-900 shadow-inner shrink-0" style={{ color: isCatOver ? '#F43F5E' : colorHex }}>
            {expanded ? <ChevronUp size={20} className="sm:w-6 sm:h-6" /> : <ChevronDown size={20} className="sm:w-6 sm:h-6" />}
          </div>
          <div className="flex-1 min-w-0">
             <div className="flex flex-wrap items-center gap-2 sm:gap-3">
                {isEditingTitle ? (
                  <div className="flex items-center gap-2 bg-slate-900 rounded-lg p-1 border border-indigo-500/50" onClick={e => e.stopPropagation()}>
                    <input 
                      value={tempTitle} 
                      onChange={e => setTempTitle(e.target.value)} 
                      onKeyDown={e => e.key === 'Enter' && handleRename()}
                      autoFocus
                      className="bg-transparent border-none outline-none text-white font-black text-sm sm:text-lg uppercase px-2 w-40 sm:w-64" 
                    />
                    <button onClick={handleRename} className="p-1 bg-indigo-600 rounded text-white"><Check size={14}/></button>
                  </div>
                ) : (
                  <div className="flex items-center gap-2 group/title">
                    <h4 className="font-black text-sm sm:text-lg text-white uppercase tracking-tighter truncate">{title}</h4>
                    {canRename && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); setIsEditingTitle(true); }}
                        className="p-1.5 text-slate-500 hover:text-indigo-400 opacity-0 group-hover/title:opacity-100 transition-opacity"
                      >
                        <Pencil size={14} />
                      </button>
                    )}
                  </div>
                )}
                <div className="flex items-center gap-2 flex-wrap">
                   <span className="text-[9px] sm:text-[10px] font-black text-slate-400 bg-slate-900 px-2 sm:px-3 py-1 rounded-full border border-slate-700 whitespace-nowrap uppercase">{filledCount}/{totalCount} TERISI</span>
                   {isCatOver && (
                     <span className="flex items-center gap-1 text-[8px] sm:text-[9px] font-black text-white bg-rose-600 px-2.5 py-1 rounded-full border border-rose-400/50 animate-pulse whitespace-nowrap shadow-[0_0_15px_rgba(244,63,94,0.5)]">
                        <BellRing size={10} /> ALARM OVERBUDGET
                     </span>
                   )}
                   {isIncomplete && !isCatOver && (
                     <span className="flex items-center gap-1 text-[8px] sm:text-[9px] font-black text-amber-400 bg-amber-400/10 px-2 py-1 rounded-full border border-amber-400/20 whitespace-nowrap">
                        <AlertTriangle size={10} /> BELUM LENGKAP
                     </span>
                   )}
                </div>
             </div>
             <div className="flex flex-wrap gap-x-4 gap-y-1.5 mt-2.5 text-[9px] sm:text-[10px] font-black uppercase tracking-widest text-slate-500 border-t border-white/5 pt-2">
                <span className="flex items-center gap-1.5">BUDGET: <span className="text-white">{formatRupiah(catTotalAllocated)}</span></span>
                <span className="flex items-center gap-1.5">AKTUAL: <span className={isCatOver ? 'text-rose-400 font-black' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></span>
                <span className="flex items-center gap-1.5 border-l border-white/10 pl-3">SISA: <span className={catRemaining < 0 ? 'text-rose-400' : 'text-emerald-400 font-black'}>{formatRupiah(catRemaining)}</span></span>
                <span className="flex items-center gap-1.5 border-l border-white/10 pl-3">PROGRES: <span className={isCatOver ? 'text-rose-400' : 'text-indigo-400'}>{catProgress.toFixed(0)}%</span></span>
             </div>
          </div>
        </div>

        {canDelete && (
          <div className="flex items-center px-3 sm:px-4 bg-slate-950/20 border-l border-white/5">
            <button 
              type="button" 
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                onRequestDeleteCategory();
              }}
              className="p-3 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all"
            >
              <Trash2 size={20} />
            </button>
          </div>
        )}
      </div>

      {expanded && (
        <div className="p-4 sm:p-8 bg-slate-950/40 space-y-4 animate-fadeIn">
           {(items || []).map((item) => {
             const isItemOver = (item.actual || 0) > (item.budget || 0);
             return (
               <div key={item.id} className={`grid grid-cols-2 md:grid-cols-12 gap-3 sm:gap-4 p-4 bg-slate-900/60 rounded-2xl border ${isItemOver ? 'border-rose-500/30 bg-rose-900/5' : 'border-white/5'} items-end transition-all`}>
                 <div className="col-span-2 md:col-span-5">
                   <label className="text-[9px] uppercase font-black text-slate-500 block mb-2 tracking-widest">Detail Item</label>
                   <input type="text" value={item.name} onChange={(e) => onUpdateItems(items.map(i => i.id === item.id ? {...i, name: e.target.value} : i))} className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm text-white font-black outline-none focus:border-indigo-500 shadow-inner" placeholder="Nama item..." />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Budget" value={item.budget} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, budget: v} : i))} />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, actual: v} : i))} />
                   <div className="flex justify-between mt-1 px-1">
                      <span className="text-[8px] font-black uppercase text-slate-500">SISA: <span className={(item.budget-item.actual) < 0 ? 'text-rose-400' : 'text-slate-400'}>{formatRupiah(item.budget-item.actual)}</span></span>
                   </div>
                 </div>
                 <div className="col-span-2 md:col-span-1 flex justify-end">
                   <button 
                      type="button" 
                      onClick={() => onRequestDeleteItem(item.id, item.name)} 
                      className="p-3 text-slate-600 hover:text-rose-500"
                   >
                     <Trash2 size={20} />
                   </button>
                 </div>
               </div>
             );
           })}
           <button 
             type="button" 
             onClick={() => onUpdateItems([...(items || []), {id: Date.now().toString(), name: '', budget: 0, actual: 0}])} 
             className="w-full py-4 border-2 border-dashed border-slate-700 rounded-2xl flex items-center justify-center gap-3 font-black text-[10px] uppercase tracking-[0.2em] text-slate-500 hover:text-white transition-all"
           >
             <Plus size={16} /> TAMBAH ITEM
           </button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newName, setNewName] = useState('');
  const [deleteTarget, setDeleteTarget] = useState<any>(null);

  const CATEGORY_COLORS = {
    needs: '#6366F1',
    savings: '#10B981',
    debt: '#F43F5E',
    others: '#8B5CF6',
    extra: ['#F59E0B', '#06B6D4', '#EC4899', '#14B8A6', '#F97316']
  };

  const totalAlloc = (data.needs?.items?.reduce((a,b)=>a+(b.budget||0),0)||0) + 
                     (data.savings?.items?.reduce((a,b)=>a+(b.budget||0),0)||0) + 
                     (data.debt?.items?.reduce((a,b)=>a+(b.budget||0),0)||0) + 
                     (data.others?.allocation||0) + 
                     (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+(ii.budget||0),0),0)||0);

  const totalAct = (data.needs?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.savings?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.debt?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.others?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+(ii.actual||0),0),0)||0);

  // Global overbudget check
  const checkOver = (items: BudgetItem[] | undefined, limit?: number) => {
    if (limit !== undefined) {
      const act = items?.reduce((a, b) => a + (b.actual || 0), 0) || 0;
      return act > limit;
    }
    const alloc = items?.reduce((a, b) => a + (b.budget || 0), 0) || 0;
    const act = items?.reduce((a, b) => a + (b.actual || 0), 0) || 0;
    return act > alloc;
  };

  const isAnyOver = 
    checkOver(data.needs?.items) || 
    checkOver(data.savings?.items) || 
    checkOver(data.debt?.items) || 
    checkOver(data.others?.items, data.others?.allocation) ||
    (data.custom?.some(c => checkOver(c.items)) || false);

  const confirmDelete = () => {
    if (!deleteTarget) return;
    if (deleteTarget.type === 'category') {
      const { categoryKey, id } = deleteTarget;
      if (categoryKey === 'custom') {
        onChange({ ...data, custom: (data.custom || []).filter(c => c.id !== id) });
      } else {
        const newData = { ...data };
        delete (newData as any)[categoryKey];
        onChange(newData);
      }
    } else {
      const { categoryKey, id } = deleteTarget;
      if (['needs', 'savings', 'debt'].includes(categoryKey)) {
        const cat = (data as any)[categoryKey];
        onChange({ ...data, [categoryKey]: { ...cat, items: cat.items.filter((i:any) => i.id !== id) } });
      } else if (categoryKey === 'others-items') {
        onChange({ ...data, others: { ...data.others!, items: data.others!.items.filter(i => i.id !== id) } });
      } else {
        const updatedCustom = (data.custom || []).map(cat => cat.id === categoryKey ? { ...cat, items: cat.items.filter(i => i.id !== id) } : cat);
        onChange({ ...data, custom: updatedCustom });
      }
    }
    setDeleteTarget(null);
  };

  const handleRenameFixed = (key: 'needs' | 'savings' | 'debt', newName: string) => {
    const section = data[key];
    if (section) {
      onChange({ ...data, [key]: { ...section, name: newName } });
    }
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-20 animate-fadeIn">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 sm:gap-6">
        <div className="glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 border-indigo-600 shadow-xl">
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Net Income</p>
          <h3 className="text-sm sm:text-2xl font-black text-white tracking-tight">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 border-blue-500 shadow-xl">
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Anggaran</p>
          <h3 className="text-sm sm:text-2xl font-black text-white tracking-tight">{formatRupiah(totalAlloc)}</h3>
        </div>
        <div className="glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 border-amber-500 shadow-xl">
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Realisasi</p>
          <h3 className="text-sm sm:text-2xl font-black text-amber-500 tracking-tight">{formatRupiah(totalAct)}</h3>
        </div>
        <div className={`glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 shadow-xl ${income-totalAct < 0 ? 'border-rose-600' : 'border-emerald-600'}`}>
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Sisa</p>
          <h3 className={`text-sm sm:text-2xl font-black tracking-tight ${income-totalAct < 0 ? 'text-rose-500' : 'text-emerald-500'}`}>{formatRupiah(income-totalAct)}</h3>
        </div>
      </div>

      {/* GLOBAL OVERBUDGET ALARM BANNER */}
      {isAnyOver && (
        <div className="animate-bounce-slow mt-4">
          <div className="bg-gradient-to-r from-rose-600 to-rose-800 p-4 sm:p-5 rounded-[1.5rem] border border-rose-400 shadow-[0_0_40px_rgba(244,63,94,0.4)] flex items-center justify-between gap-4">
            <div className="flex items-center gap-4">
              <div className="bg-white/20 p-2 sm:p-3 rounded-xl">
                <OctagonAlert className="text-white w-6 h-6 sm:w-8 sm:h-8" />
              </div>
              <div>
                <h4 className="text-white text-xs sm:text-base font-black uppercase tracking-tight">Perhatian: Overbudget Terdeteksi!</h4>
                <p className="text-rose-100 text-[9px] sm:text-[11px] font-bold uppercase tracking-widest">Ada kategori yang melampaui batas anggaran yang telah ditetapkan.</p>
              </div>
            </div>
            <div className="hidden sm:block">
               <BellRing className="text-white/40 animate-pulse" size={32} />
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-4 border-b border-white/5 pb-6">
         <h2 className="text-xl sm:text-2xl font-black text-white uppercase tracking-tighter flex items-center gap-3">
            <div className="w-2 h-6 sm:h-8 bg-indigo-600 rounded-full shadow-[0_0_10px_rgba(99,102,241,0.5)]"></div> 
            ALOKASI ANGGARAN
         </h2>
         {!isAdding ? (
           <button onClick={() => setIsAdding(true)} className="w-full sm:w-auto px-6 py-3 sm:px-8 sm:py-4 bg-indigo-600 text-white rounded-xl sm:rounded-2xl text-[10px] sm:text-xs font-black flex items-center justify-center gap-3 uppercase tracking-widest transition-all hover:bg-indigo-700 shadow-lg">
             <FolderPlus size={16} /> TAMBAH KATEGORI
           </button>
         ) : (
           <div className="flex items-center gap-2 bg-slate-900 p-2 rounded-xl border border-slate-700 w-full sm:w-auto">
             <input autoFocus value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==='Enter' && (()=>{if(newName.trim()){onChange({...data, custom: [...(data.custom||[]), {id: Date.now().toString(), name: newName.trim(), items: []}]}); setNewName(''); setIsAdding(false);}})()} placeholder="Nama Kategori..." className="bg-transparent border-none outline-none text-white font-black text-sm uppercase px-2 w-40 sm:w-64" />
             <button onClick={()=>{if(newName.trim()){onChange({...data, custom: [...(data.custom||[]), {id: Date.now().toString(), name: newName.trim(), items: []}]}); setNewName(''); setIsAdding(false);}}} className="p-2 bg-indigo-600 text-white rounded-lg"><Check size={18}/></button>
             <button onClick={()=>setIsAdding(false)} className="p-2 bg-slate-800 text-slate-400 rounded-lg"><X size={18}/></button>
           </div>
         )}
      </div>

      <div className="space-y-4">
        {data.needs && <CategorySection title={data.needs.name || "Kebutuhan Pokok"} items={data.needs.items} colorHex={CATEGORY_COLORS.needs} onRenameCategory={(val) => handleRenameFixed('needs', val)} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'needs', name: data.needs?.name || 'Kebutuhan Pokok', categoryKey: 'needs' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'needs' })} onUpdateItems={i => onChange({ ...data, needs: { ...data.needs, items: i } })} canDelete={true} canRename={true} />}

        {data.savings && <CategorySection title={data.savings.name || "Tabungan & Investasi"} items={data.savings.items} colorHex={CATEGORY_COLORS.savings} onRenameCategory={(val) => handleRenameFixed('savings', val)} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'savings', name: data.savings?.name || 'Tabungan & Investasi', categoryKey: 'savings' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'savings' })} onUpdateItems={i => onChange({ ...data, savings: { ...data.savings, items: i } })} canDelete={true} canRename={true} />}

        {data.debt && <CategorySection title={data.debt.name || "Hutang & Cicilan"} items={data.debt.items} colorHex={CATEGORY_COLORS.debt} onRenameCategory={(val) => handleRenameFixed('debt', val)} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'debt', name: data.debt?.name || 'Hutang & Cicilan', categoryKey: 'debt' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'debt' })} onUpdateItems={i => onChange({ ...data, debt: { ...data.debt, items: i } })} canDelete={true} canRename={true} />}

        {(data.custom||[]).map((cat, idx) => (
          <CategorySection key={cat.id} title={cat.name} items={cat.items} colorHex={CATEGORY_COLORS.extra[idx % CATEGORY_COLORS.extra.length]} onRenameCategory={(newTitle) => onChange({...data, custom: data.custom!.map(c => c.id === cat.id ? {...c, name: newTitle} : c)})} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: cat.id, name: cat.name, categoryKey: 'custom' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: cat.id })} onUpdateItems={i => onChange({ ...data, custom: data.custom!.map(c => c.id === cat.id ? { ...c, items: i } : c) })} />
        ))}

        {data.others && <OthersSection data={data.others} onUpdate={o=>onChange({...data, others: o})} onRequestDelete={()=>setDeleteTarget({ type: 'category', id: 'others', name: 'Lain-lain', categoryKey: 'others' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'others-items' })} />}
      </div>

      <DeleteModal isOpen={!!deleteTarget} title={deleteTarget?.type === 'category' ? 'Hapus Kategori' : 'Hapus Item'} itemName={deleteTarget?.name || ''} onClose={() => setDeleteTarget(null)} onConfirm={confirmDelete} />
    </div>
  );
};

const OthersSection: React.FC<{data: any, onUpdate: (d: any)=>void, onRequestDelete: ()=>void, onRequestDeleteItem: (id: string, name: string) => void}> = ({data, onUpdate, onRequestDelete, onRequestDeleteItem}) => {
  const [expanded, setExpanded] = useState(false);
  const totalAct = data.items?.reduce((a:any, b:any)=>a+(b.actual||0), 0) || 0;
  const totalAlloc = data.allocation || 0;
  const isOver = totalAct > totalAlloc;
  const remaining = totalAlloc - totalAct;
  const progress = totalAlloc > 0 ? (totalAct / totalAlloc) * 100 : 0;

  const itemsWithActual = data.items?.filter((item:any) => (item.actual || 0) > 0).length || 0;
  const totalItems = data.items?.length || 0;

  return (
    <div className={`glass-panel rounded-[2rem] overflow-hidden mb-6 transition-all ${isOver ? 'ring-2 ring-rose-500 shadow-[0_0_20px_rgba(244,63,94,0.3)]' : 'hover:shadow-2xl'}`} style={{ borderLeft: '6px solid #8B5CF6' }}>
      <div className="flex items-stretch border-b border-white/5">
        <div className="flex-1 p-5 sm:p-6 flex items-center gap-4 sm:gap-5 cursor-pointer hover:bg-white/5 transition-colors" onClick={() => setExpanded(!expanded)}>
           <div className="p-3 rounded-2xl bg-slate-900 text-[#8B5CF6] shrink-0">
             {expanded ? <ChevronUp size={20} className="sm:w-6 sm:h-6" /> : <ChevronDown size={20} className="sm:w-6 sm:h-6" />}
           </div>
           <div className="flex-1">
                <div className="flex flex-wrap items-center gap-2 sm:gap-3">
                  <h4 className="font-black text-sm sm:text-lg text-white uppercase tracking-tighter">Lain-lain / Hiburan</h4>
                  <div className="flex gap-2">
                    <span className="text-[9px] sm:text-[10px] font-black text-slate-400 bg-slate-900 px-2 sm:px-3 py-1 rounded-full border border-slate-700 uppercase">{itemsWithActual}/{totalItems} TERISI</span>
                    {isOver && (
                      <span className="flex items-center gap-1 text-[8px] sm:text-[9px] font-black text-white bg-rose-600 px-2.5 py-1 rounded-full animate-pulse shadow-lg shadow-rose-900/40">
                        <BellRing size={10} /> ALARM
                      </span>
                    )}
                  </div>
                </div>
                <div className="flex flex-wrap gap-x-4 gap-y-1.5 mt-2.5 text-[9px] sm:text-[10px] font-black uppercase text-slate-500 tracking-widest pt-2 border-t border-white/5">
                  <span>LIMIT: <span className="text-white">{formatRupiah(totalAlloc)}</span></span>
                  <span>AKTUAL: <span className={isOver ? 'text-rose-400' : 'text-violet-400'}>{formatRupiah(totalAct)}</span></span>
                  <span className="border-l border-white/10 pl-3">SISA: <span className={remaining < 0 ? 'text-rose-400' : 'text-emerald-400 font-black'}>{formatRupiah(remaining)}</span></span>
                  <span className="border-l border-white/10 pl-3">PROGRES: <span className={isOver ? 'text-rose-400' : 'text-indigo-400'}>{progress.toFixed(0)}%</span></span>
                </div>
           </div>
        </div>
        <div className="flex items-center px-3 sm:px-4 bg-slate-950/20 border-l border-white/5">
          <button type="button" onClick={onRequestDelete} className="p-3 text-slate-600 hover:text-rose-500"><Trash2 size={20} /></button>
        </div>
      </div>
      {expanded && (
        <div className="p-4 sm:p-8 bg-slate-950/40 space-y-6 animate-fadeIn">
           <CurrencyInput label="Limit Anggaran Hiburan" value={data.allocation} onChange={v=>onUpdate({...data, allocation: v})} />
           <div className="space-y-4 pt-4 border-t border-white/5">
             {(data.items || []).map((item:any) => (
               <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 sm:gap-4 p-4 bg-slate-900/60 rounded-2xl border border-white/5 items-end">
                 <div className="col-span-2 md:col-span-7">
                   <label className="text-[9px] uppercase font-black text-slate-500 block mb-2 tracking-widest">Keterangan</label>
                   <input value={item.name} onChange={e=>onUpdate({...data, items: data.items.map((i:any)=>i.id===item.id?{...i, name: e.target.value}:i)})} className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm text-white font-black outline-none focus:border-indigo-500 shadow-inner" placeholder="Misal: Bioskop..." />
                 </div>
                 <div className="col-span-1 md:col-span-4">
                   <CurrencyInput label="Nominal" value={item.actual} onChange={v=>onUpdate({...data, items: data.items.map((i:any)=>i.id===item.id?{...i, actual: v}:i)})} />
                 </div>
                 <div className="col-span-1 md:col-span-1 flex justify-end">
                   <button type="button" onClick={()=>onRequestDeleteItem(item.id, item.name)} className="p-3 text-slate-600 hover:text-rose-500"><Trash2 size={20} /></button>
                 </div>
               </div>
             ))}
           </div>
           <button type="button" onClick={()=>onUpdate({...data, items: [...(data.items || []), {id: Date.now().toString(), name: '', actual: 0}]})} className="w-full py-4 border-2 border-dashed border-violet-900/40 text-violet-400 bg-violet-900/5 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-violet-900/10 transition-all">
             <Plus size={16} /> TAMBAH PENGELUARAN
           </button>
        </div>
      )}
    </div>
  );
};

export default Budget;

import React, { useState } from 'react';
import { BudgetData, BudgetItem } from '../types';
import CurrencyInput from './ui/CurrencyInput';
import DeleteModal from './ui/DeleteModal';
import { formatRupiah } from '../utils';
import { ChevronDown, ChevronUp, Plus, Trash2, FolderPlus, X, Check, AlertTriangle, Pencil, BellRing, OctagonAlert } from 'lucide-react';

interface BudgetProps {
  income: number;
  data: BudgetData;
  onChange: (data: BudgetData) => void;
}

interface CategorySectionProps {
  title: string;
  items: BudgetItem[];
  colorHex: string;
  onUpdateItems: (items: BudgetItem[]) => void;
  onRequestDeleteCategory: () => void;
  onRequestDeleteItem: (id: string, name: string) => void;
  onRenameCategory: (newName: string) => void;
  defaultExpanded?: boolean;
  canDelete?: boolean;
  canRename?: boolean;
}

const CategorySection: React.FC<CategorySectionProps> = ({ 
  title, 
  items, 
  colorHex,
  onUpdateItems,
  onRequestDeleteCategory,
  onRequestDeleteItem,
  onRenameCategory,
  defaultExpanded = false,
  canDelete = true,
  canRename = true
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [tempTitle, setTempTitle] = useState(title);

  const catTotalAllocated = items?.reduce((a, b) => a + (b.budget || 0), 0) || 0;
  const catTotalActual = items?.reduce((a, b) => a + (b.actual || 0), 0) || 0;
  const isCatOver = catTotalActual > catTotalAllocated;
  const catRemaining = catTotalAllocated - catTotalActual;
  const catProgress = catTotalAllocated > 0 ? (catTotalActual / catTotalAllocated) * 100 : 0;

  const filledCount = items?.filter(item => (item.actual || 0) > 0).length || 0;
  const totalCount = items?.length || 0;
  const isIncomplete = items?.some(item => (item.budget || 0) > 0 && (item.actual || 0) === 0);

  const handleRename = () => {
    if (tempTitle.trim() && tempTitle !== title) {
      onRenameCategory(tempTitle.trim());
    } else {
      setTempTitle(title);
    }
    setIsEditingTitle(false);
  };

  return (
    <div 
      className={`glass-panel rounded-[2rem] overflow-hidden mb-6 transition-all duration-500 ${isCatOver ? 'ring-2 ring-rose-500 shadow-[0_0_30px_rgba(244,63,94,0.3)]' : 'hover:shadow-2xl hover:border-white/20'}`}
      style={{ borderLeft: `6px solid ${colorHex}` }}
    >
      <div className="flex items-stretch border-b border-white/5">
        <div 
          className="flex-1 p-5 sm:p-6 flex items-center gap-4 sm:gap-5 cursor-pointer hover:bg-white/5 transition-colors"
          onClick={() => !isEditingTitle && setExpanded(!expanded)}
        >
          <div className="p-3 rounded-2xl bg-slate-900 shadow-inner shrink-0" style={{ color: isCatOver ? '#F43F5E' : colorHex }}>
            {expanded ? <ChevronUp size={20} className="sm:w-6 sm:h-6" /> : <ChevronDown size={20} className="sm:w-6 sm:h-6" />}
          </div>
          <div className="flex-1 min-w-0">
             <div className="flex flex-wrap items-center gap-2 sm:gap-3">
                {isEditingTitle ? (
                  <div className="flex items-center gap-2 bg-slate-900 rounded-lg p-1 border border-indigo-500/50" onClick={e => e.stopPropagation()}>
                    <input 
                      value={tempTitle} 
                      onChange={e => setTempTitle(e.target.value)} 
                      onKeyDown={e => e.key === 'Enter' && handleRename()}
                      autoFocus
                      className="bg-transparent border-none outline-none text-white font-black text-sm sm:text-lg uppercase px-2 w-40 sm:w-64" 
                    />
                    <button onClick={handleRename} className="p-1 bg-indigo-600 rounded text-white"><Check size={14}/></button>
                  </div>
                ) : (
                  <div className="flex items-center gap-2 group/title">
                    <h4 className="font-black text-sm sm:text-lg text-white uppercase tracking-tighter truncate">{title}</h4>
                    {canRename && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); setIsEditingTitle(true); }}
                        className="p-1.5 text-slate-500 hover:text-indigo-400 opacity-0 group-hover/title:opacity-100 transition-opacity"
                      >
                        <Pencil size={14} />
                      </button>
                    )}
                  </div>
                )}
                <div className="flex items-center gap-2 flex-wrap">
                   <span className="text-[9px] sm:text-[10px] font-black text-slate-400 bg-slate-900 px-2 sm:px-3 py-1 rounded-full border border-slate-700 whitespace-nowrap uppercase">{filledCount}/{totalCount} TERISI</span>
                   {isCatOver && (
                     <span className="flex items-center gap-1 text-[8px] sm:text-[9px] font-black text-white bg-rose-600 px-2.5 py-1 rounded-full border border-rose-400/50 animate-pulse whitespace-nowrap shadow-[0_0_15px_rgba(244,63,94,0.5)]">
                        <BellRing size={10} /> ALARM OVERBUDGET
                     </span>
                   )}
                   {isIncomplete && !isCatOver && (
                     <span className="flex items-center gap-1 text-[8px] sm:text-[9px] font-black text-amber-400 bg-amber-400/10 px-2 py-1 rounded-full border border-amber-400/20 whitespace-nowrap">
                        <AlertTriangle size={10} /> BELUM LENGKAP
                     </span>
                   )}
                </div>
             </div>
             <div className="flex flex-wrap gap-x-4 gap-y-1.5 mt-2.5 text-[9px] sm:text-[10px] font-black uppercase tracking-widest text-slate-500 border-t border-white/5 pt-2">
                <span className="flex items-center gap-1.5">BUDGET: <span className="text-white">{formatRupiah(catTotalAllocated)}</span></span>
                <span className="flex items-center gap-1.5">AKTUAL: <span className={isCatOver ? 'text-rose-400 font-black' : 'text-emerald-400'}>{formatRupiah(catTotalActual)}</span></span>
                <span className="flex items-center gap-1.5 border-l border-white/10 pl-3">SISA: <span className={catRemaining < 0 ? 'text-rose-400' : 'text-emerald-400 font-black'}>{formatRupiah(catRemaining)}</span></span>
                <span className="flex items-center gap-1.5 border-l border-white/10 pl-3">PROGRES: <span className={isCatOver ? 'text-rose-400' : 'text-indigo-400'}>{catProgress.toFixed(0)}%</span></span>
             </div>
          </div>
        </div>

        {canDelete && (
          <div className="flex items-center px-3 sm:px-4 bg-slate-950/20 border-l border-white/5">
            <button 
              type="button" 
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                onRequestDeleteCategory();
              }}
              className="p-3 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all"
            >
              <Trash2 size={20} />
            </button>
          </div>
        )}
      </div>

      {expanded && (
        <div className="p-4 sm:p-8 bg-slate-950/40 space-y-4 animate-fadeIn">
           {(items || []).map((item) => {
             const isItemOver = (item.actual || 0) > (item.budget || 0);
             return (
               <div key={item.id} className={`grid grid-cols-2 md:grid-cols-12 gap-3 sm:gap-4 p-4 bg-slate-900/60 rounded-2xl border ${isItemOver ? 'border-rose-500/30 bg-rose-900/5' : 'border-white/5'} items-end transition-all`}>
                 <div className="col-span-2 md:col-span-5">
                   <label className="text-[9px] uppercase font-black text-slate-500 block mb-2 tracking-widest">Detail Item</label>
                   <input type="text" value={item.name} onChange={(e) => onUpdateItems(items.map(i => i.id === item.id ? {...i, name: e.target.value} : i))} className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm text-white font-black outline-none focus:border-indigo-500 shadow-inner" placeholder="Nama item..." />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Budget" value={item.budget} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, budget: v} : i))} />
                 </div>
                 <div className="col-span-1 md:col-span-3">
                   <CurrencyInput label="Realisasi" value={item.actual} onChange={(v) => onUpdateItems(items.map(i => i.id === item.id ? {...i, actual: v} : i))} />
                   <div className="flex justify-between mt-1 px-1">
                      <span className="text-[8px] font-black uppercase text-slate-500">SISA: <span className={(item.budget-item.actual) < 0 ? 'text-rose-400' : 'text-slate-400'}>{formatRupiah(item.budget-item.actual)}</span></span>
                   </div>
                 </div>
                 <div className="col-span-2 md:col-span-1 flex justify-end">
                   <button 
                      type="button" 
                      onClick={() => onRequestDeleteItem(item.id, item.name)} 
                      className="p-3 text-slate-600 hover:text-rose-500"
                   >
                     <Trash2 size={20} />
                   </button>
                 </div>
               </div>
             );
           })}
           <button 
             type="button" 
             onClick={() => onUpdateItems([...(items || []), {id: Date.now().toString(), name: '', budget: 0, actual: 0}])} 
             className="w-full py-4 border-2 border-dashed border-slate-700 rounded-2xl flex items-center justify-center gap-3 font-black text-[10px] uppercase tracking-[0.2em] text-slate-500 hover:text-white transition-all"
           >
             <Plus size={16} /> TAMBAH ITEM
           </button>
        </div>
      )}
    </div>
  );
};

const Budget: React.FC<BudgetProps> = ({ income, data, onChange }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newName, setNewName] = useState('');
  const [deleteTarget, setDeleteTarget] = useState<any>(null);

  const CATEGORY_COLORS = {
    needs: '#6366F1',
    savings: '#10B981',
    debt: '#F43F5E',
    others: '#8B5CF6',
    extra: ['#F59E0B', '#06B6D4', '#EC4899', '#14B8A6', '#F97316']
  };

  const totalAlloc = (data.needs?.items?.reduce((a,b)=>a+(b.budget||0),0)||0) + 
                     (data.savings?.items?.reduce((a,b)=>a+(b.budget||0),0)||0) + 
                     (data.debt?.items?.reduce((a,b)=>a+(b.budget||0),0)||0) + 
                     (data.others?.allocation||0) + 
                     (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+(ii.budget||0),0),0)||0);

  const totalAct = (data.needs?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.savings?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.debt?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.others?.items?.reduce((a,b)=>a+(b.actual||0),0)||0) + 
                    (data.custom?.reduce((a,c)=>a+c.items.reduce((ia,ii)=>ia+(ii.actual||0),0),0)||0);

  // Global overbudget check
  // Fix: changed parameter type to accept items with optional budget property to support both BudgetItem and OtherBudgetItem
  const checkOver = (items: { actual: number; budget?: number }[] | undefined, limit?: number) => {
    if (limit !== undefined) {
      const act = items?.reduce((a, b) => a + (b.actual || 0), 0) || 0;
      return act > limit;
    }
    const alloc = items?.reduce((a, b) => a + (b.budget || 0), 0) || 0;
    const act = items?.reduce((a, b) => a + (b.actual || 0), 0) || 0;
    return act > alloc;
  };

  const isAnyOver = 
    checkOver(data.needs?.items) || 
    checkOver(data.savings?.items) || 
    checkOver(data.debt?.items) || 
    checkOver(data.others?.items, data.others?.allocation) ||
    (data.custom?.some(c => checkOver(c.items)) || false);

  const confirmDelete = () => {
    if (!deleteTarget) return;
    if (deleteTarget.type === 'category') {
      const { categoryKey, id } = deleteTarget;
      if (categoryKey === 'custom') {
        onChange({ ...data, custom: (data.custom || []).filter(c => c.id !== id) });
      } else {
        const newData = { ...data };
        delete (newData as any)[categoryKey];
        onChange(newData);
      }
    } else {
      const { categoryKey, id } = deleteTarget;
      if (['needs', 'savings', 'debt'].includes(categoryKey)) {
        const cat = (data as any)[categoryKey];
        onChange({ ...data, [categoryKey]: { ...cat, items: cat.items.filter((i:any) => i.id !== id) } });
      } else if (categoryKey === 'others-items') {
        onChange({ ...data, others: { ...data.others!, items: data.others!.items.filter(i => i.id !== id) } });
      } else {
        const updatedCustom = (data.custom || []).map(cat => cat.id === categoryKey ? { ...cat, items: cat.items.filter(i => i.id !== id) } : cat);
        onChange({ ...data, custom: updatedCustom });
      }
    }
    setDeleteTarget(null);
  };

  const handleRenameFixed = (key: 'needs' | 'savings' | 'debt', newName: string) => {
    const section = data[key];
    if (section) {
      onChange({ ...data, [key]: { ...section, name: newName } });
    }
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-20 animate-fadeIn">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 sm:gap-6">
        <div className="glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 border-indigo-600 shadow-xl">
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Net Income</p>
          <h3 className="text-sm sm:text-2xl font-black text-white tracking-tight">{formatRupiah(income)}</h3>
        </div>
        <div className="glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 border-blue-500 shadow-xl">
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Anggaran</p>
          <h3 className="text-sm sm:text-2xl font-black text-white tracking-tight">{formatRupiah(totalAlloc)}</h3>
        </div>
        <div className="glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 border-amber-500 shadow-xl">
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Realisasi</p>
          <h3 className="text-sm sm:text-2xl font-black text-amber-500 tracking-tight">{formatRupiah(totalAct)}</h3>
        </div>
        <div className={`glass-panel p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] border-l-4 sm:border-l-8 shadow-xl ${income-totalAct < 0 ? 'border-rose-600' : 'border-emerald-600'}`}>
          <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-widest mb-1">Sisa</p>
          <h3 className={`text-sm sm:text-2xl font-black tracking-tight ${income-totalAct < 0 ? 'text-rose-500' : 'text-emerald-500'}`}>{formatRupiah(income-totalAct)}</h3>
        </div>
      </div>

      {/* GLOBAL OVERBUDGET ALARM BANNER */}
      {isAnyOver && (
        <div className="animate-bounce-slow mt-4">
          <div className="bg-gradient-to-r from-rose-600 to-rose-800 p-4 sm:p-5 rounded-[1.5rem] border border-rose-400 shadow-[0_0_40px_rgba(244,63,94,0.4)] flex items-center justify-between gap-4">
            <div className="flex items-center gap-4">
              <div className="bg-white/20 p-2 sm:p-3 rounded-xl">
                <OctagonAlert className="text-white w-6 h-6 sm:w-8 sm:h-8" />
              </div>
              <div>
                <h4 className="text-white text-xs sm:text-base font-black uppercase tracking-tight">Perhatian: Overbudget Terdeteksi!</h4>
                <p className="text-rose-100 text-[9px] sm:text-[11px] font-bold uppercase tracking-widest">Ada kategori yang melampaui batas anggaran yang telah ditetapkan.</p>
              </div>
            </div>
            <div className="hidden sm:block">
               <BellRing className="text-white/40 animate-pulse" size={32} />
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-4 border-b border-white/5 pb-6">
         <h2 className="text-xl sm:text-2xl font-black text-white uppercase tracking-tighter flex items-center gap-3">
            <div className="w-2 h-6 sm:h-8 bg-indigo-600 rounded-full shadow-[0_0_10px_rgba(99,102,241,0.5)]"></div> 
            ALOKASI ANGGARAN
         </h2>
         {!isAdding ? (
           <button onClick={() => setIsAdding(true)} className="w-full sm:w-auto px-6 py-3 sm:px-8 sm:py-4 bg-indigo-600 text-white rounded-xl sm:rounded-2xl text-[10px] sm:text-xs font-black flex items-center justify-center gap-3 uppercase tracking-widest transition-all hover:bg-indigo-700 shadow-lg">
             <FolderPlus size={16} /> TAMBAH KATEGORI
           </button>
         ) : (
           <div className="flex items-center gap-2 bg-slate-900 p-2 rounded-xl border border-slate-700 w-full sm:w-auto">
             <input autoFocus value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==='Enter' && (()=>{if(newName.trim()){onChange({...data, custom: [...(data.custom||[]), {id: Date.now().toString(), name: newName.trim(), items: []}]}); setNewName(''); setIsAdding(false);}})()} placeholder="Nama Kategori..." className="bg-transparent border-none outline-none text-white font-black text-sm uppercase px-2 w-40 sm:w-64" />
             <button onClick={()=>{if(newName.trim()){onChange({...data, custom: [...(data.custom||[]), {id: Date.now().toString(), name: newName.trim(), items: []}]}); setNewName(''); setIsAdding(false);}}} className="p-2 bg-indigo-600 text-white rounded-lg"><Check size={18}/></button>
             <button onClick={()=>setIsAdding(false)} className="p-2 bg-slate-800 text-slate-400 rounded-lg"><X size={18}/></button>
           </div>
         )}
      </div>

      <div className="space-y-4">
        {data.needs && <CategorySection title={data.needs.name || "Kebutuhan Pokok"} items={data.needs.items} colorHex={CATEGORY_COLORS.needs} onRenameCategory={(val) => handleRenameFixed('needs', val)} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'needs', name: data.needs?.name || 'Kebutuhan Pokok', categoryKey: 'needs' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'needs' })} onUpdateItems={i => onChange({ ...data, needs: { ...data.needs, items: i } })} canDelete={true} canRename={true} />}

        {data.savings && <CategorySection title={data.savings.name || "Tabungan & Investasi"} items={data.savings.items} colorHex={CATEGORY_COLORS.savings} onRenameCategory={(val) => handleRenameFixed('savings', val)} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'savings', name: data.savings?.name || 'Tabungan & Investasi', categoryKey: 'savings' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'savings' })} onUpdateItems={i => onChange({ ...data, savings: { ...data.savings, items: i } })} canDelete={true} canRename={true} />}

        {data.debt && <CategorySection title={data.debt.name || "Hutang & Cicilan"} items={data.debt.items} colorHex={CATEGORY_COLORS.debt} onRenameCategory={(val) => handleRenameFixed('debt', val)} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: 'debt', name: data.debt?.name || 'Hutang & Cicilan', categoryKey: 'debt' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'debt' })} onUpdateItems={i => onChange({ ...data, debt: { ...data.debt, items: i } })} canDelete={true} canRename={true} />}

        {(data.custom||[]).map((cat, idx) => (
          <CategorySection key={cat.id} title={cat.name} items={cat.items} colorHex={CATEGORY_COLORS.extra[idx % CATEGORY_COLORS.extra.length]} onRenameCategory={(newTitle) => onChange({...data, custom: data.custom!.map(c => c.id === cat.id ? {...c, name: newTitle} : c)})} onRequestDeleteCategory={() => setDeleteTarget({ type: 'category', id: cat.id, name: cat.name, categoryKey: 'custom' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: cat.id })} onUpdateItems={i => onChange({ ...data, custom: data.custom!.map(c => c.id === cat.id ? { ...c, items: i } : c) })} />
        ))}

        {data.others && <OthersSection data={data.others} onUpdate={o=>onChange({...data, others: o})} onRequestDelete={()=>setDeleteTarget({ type: 'category', id: 'others', name: 'Lain-lain', categoryKey: 'others' })} onRequestDeleteItem={(id, name) => setDeleteTarget({ type: 'item', id, name, categoryKey: 'others-items' })} />}
      </div>

      <DeleteModal isOpen={!!deleteTarget} title={deleteTarget?.type === 'category' ? 'Hapus Kategori' : 'Hapus Item'} itemName={deleteTarget?.name || ''} onClose={() => setDeleteTarget(null)} onConfirm={confirmDelete} />
    </div>
  );
};

const OthersSection: React.FC<{data: any, onUpdate: (d: any)=>void, onRequestDelete: ()=>void, onRequestDeleteItem: (id: string, name: string) => void}> = ({data, onUpdate, onRequestDelete, onRequestDeleteItem}) => {
  const [expanded, setExpanded] = useState(false);
  const totalAct = data.items?.reduce((a:any, b:any)=>a+(b.actual||0), 0) || 0;
  const totalAlloc = data.allocation || 0;
  const isOver = totalAct > totalAlloc;
  const remaining = totalAlloc - totalAct;
  const progress = totalAlloc > 0 ? (totalAct / totalAlloc) * 100 : 0;

  const itemsWithActual = data.items?.filter((item:any) => (item.actual || 0) > 0).length || 0;
  const totalItems = data.items?.length || 0;

  return (
    <div className={`glass-panel rounded-[2rem] overflow-hidden mb-6 transition-all ${isOver ? 'ring-2 ring-rose-500 shadow-[0_0_20px_rgba(244,63,94,0.3)]' : 'hover:shadow-2xl'}`} style={{ borderLeft: '6px solid #8B5CF6' }}>
      <div className="flex items-stretch border-b border-white/5">
        <div className="flex-1 p-5 sm:p-6 flex items-center gap-4 sm:gap-5 cursor-pointer hover:bg-white/5 transition-colors" onClick={() => setExpanded(!expanded)}>
           <div className="p-3 rounded-2xl bg-slate-900 text-[#8B5CF6] shrink-0">
             {expanded ? <ChevronUp size={20} className="sm:w-6 sm:h-6" /> : <ChevronDown size={20} className="sm:w-6 sm:h-6" />}
           </div>
           <div className="flex-1">
                <div className="flex flex-wrap items-center gap-2 sm:gap-3">
                  <h4 className="font-black text-sm sm:text-lg text-white uppercase tracking-tighter">Lain-lain / Hiburan</h4>
                  <div className="flex gap-2">
                    <span className="text-[9px] sm:text-[10px] font-black text-slate-400 bg-slate-900 px-2 sm:px-3 py-1 rounded-full border border-slate-700 uppercase">{itemsWithActual}/{totalItems} TERISI</span>
                    {isOver && (
                      <span className="flex items-center gap-1 text-[8px] sm:text-[9px] font-black text-white bg-rose-600 px-2.5 py-1 rounded-full animate-pulse shadow-lg shadow-rose-900/40">
                        <BellRing size={10} /> ALARM
                      </span>
                    )}
                  </div>
                </div>
                <div className="flex flex-wrap gap-x-4 gap-y-1.5 mt-2.5 text-[9px] sm:text-[10px] font-black uppercase text-slate-500 tracking-widest pt-2 border-t border-white/5">
                  <span>LIMIT: <span className="text-white">{formatRupiah(totalAlloc)}</span></span>
                  <span>AKTUAL: <span className={isOver ? 'text-rose-400' : 'text-violet-400'}>{formatRupiah(totalAct)}</span></span>
                  <span className="border-l border-white/10 pl-3">SISA: <span className={remaining < 0 ? 'text-rose-400' : 'text-emerald-400 font-black'}>{formatRupiah(remaining)}</span></span>
                  <span className="border-l border-white/10 pl-3">PROGRES: <span className={isOver ? 'text-rose-400' : 'text-indigo-400'}>{progress.toFixed(0)}%</span></span>
                </div>
           </div>
        </div>
        <div className="flex items-center px-3 sm:px-4 bg-slate-950/20 border-l border-white/5">
          <button type="button" onClick={onRequestDelete} className="p-3 text-slate-600 hover:text-rose-500"><Trash2 size={20} /></button>
        </div>
      </div>
      {expanded && (
        <div className="p-4 sm:p-8 bg-slate-950/40 space-y-6 animate-fadeIn">
           <CurrencyInput label="Limit Anggaran Hiburan" value={data.allocation} onChange={v=>onUpdate({...data, allocation: v})} />
           <div className="space-y-4 pt-4 border-t border-white/5">
             {(data.items || []).map((item:any) => (
               <div key={item.id} className="grid grid-cols-2 md:grid-cols-12 gap-3 sm:gap-4 p-4 bg-slate-900/60 rounded-2xl border border-white/5 items-end">
                 <div className="col-span-2 md:col-span-7">
                   <label className="text-[9px] uppercase font-black text-slate-500 block mb-2 tracking-widest">Keterangan</label>
                   <input value={item.name} onChange={e=>onUpdate({...data, items: data.items.map((i:any)=>i.id===item.id?{...i, name: e.target.value}:i)})} className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm text-white font-black outline-none focus:border-indigo-500 shadow-inner" placeholder="Misal: Bioskop..." />
                 </div>
                 <div className="col-span-1 md:col-span-4">
                   <CurrencyInput label="Nominal" value={item.actual} onChange={v=>onUpdate({...data, items: data.items.map((i:any)=>i.id===item.id?{...i, actual: v}:i)})} />
                 </div>
                 <div className="col-span-1 md:col-span-1 flex justify-end">
                   <button type="button" onClick={()=>onRequestDeleteItem(item.id, item.name)} className="p-3 text-slate-600 hover:text-rose-500"><Trash2 size={20} /></button>
                 </div>
               </div>
             ))}
           </div>
           <button type="button" onClick={()=>onUpdate({...data, items: [...(data.items || []), {id: Date.now().toString(), name: '', actual: 0}]})} className="w-full py-4 border-2 border-dashed border-violet-900/40 text-violet-400 bg-violet-900/5 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-violet-900/10 transition-all">
             <Plus size={16} /> TAMBAH PENGELUARAN
           </button>
        </div>
      )}
    </div>
  );
};

export default Budget;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MonthlyData } from '../types';
import { formatRupiah } from '../utils';
import { Sparkles, BrainCircuit, RefreshCw, TrendingUp, AlertCircle, CheckCircle2, Wifi, WifiOff } from 'lucide-react';

interface AIAnalysisProps {
  currentMonthData: MonthlyData;
  netIncome: number;
}

const AIAnalysis: React.FC<AIAnalysisProps> = ({ currentMonthData, netIncome }) => {
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const generateAnalysis = async () => {
    // Check local network status first
    if (!navigator.onLine) {
      setError("Perangkat Anda sedang offline. Mohon hubungkan ke internet untuk menggunakan fitur AI Analysis.");
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      // Ensure API Key exists
      if (!process.env.API_KEY) {
        throw new Error("API Key tidak ditemukan dalam sistem.");
      }

      // Initialize AI inside the function to ensure the latest context/key
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const budgetDetails = JSON.stringify({
        income: formatRupiah(netIncome),
        needs: currentMonthData.budget.needs?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        savings: currentMonthData.budget.savings?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        debt: currentMonthData.budget.debt?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        others: currentMonthData.budget.others?.items.map(i => ({ name: i.name, actual: i.actual })),
        investments: currentMonthData.investments.map(i => ({ name: i.name, value: i.currentValue, target: i.targetValue }))
      });

      const prompt = `Bertindaklah sebagai Konsultan Keuangan Pribadi Profesional. Analisis data keuangan berikut untuk bulan ini dan berikan wawasan mendalam dalam Bahasa Indonesia.

      Data Keuangan:
      ${budgetDetails}

      Format respon Anda harus meliputi:
      1. Ringkasan Singkat Kesehatan Keuangan (Gunakan nada yang menyemangati).
      2. Analisis Efisiensi Anggaran (Soroti area yang hemat atau overbudget).
      3. Analisis Aset & Investasi (Seberapa dekat dengan target).
      4. 3 Saran Praktis untuk bulan depan agar kondisi keuangan Aniq Susilo semakin kuat.

      Berikan respon dalam format Markdown yang rapi dengan heading dan poin-poin. Jangan gunakan teknis yang terlalu rumit, buatlah mudah dipahami dan berorientasi pada tindakan.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });

      if (!response || !response.text) {
        throw new Error("Server AI mengembalikan respon kosong.");
      }

      setAnalysis(response.text);
    } catch (err: any) {
      console.error("AI Analysis Error:", err);
      if (err.message?.includes('fetch') || err.name === 'TypeError') {
        setError("Gagal terhubung ke server AI. Periksa koneksi internet Anda atau coba lagi beberapa saat lagi.");
      } else if (err.message?.includes('403')) {
        setError("Akses ditolak (Error 403). Pastikan layanan AI tersedia di wilayah Anda.");
      } else {
        setError(`Error: ${err.message || "Terjadi kesalahan sistem saat menghubungi AI."}`);
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      <div className="glass-panel p-6 sm:p-10 rounded-[2.5rem] border border-indigo-500/20 shadow-2xl relative overflow-hidden group">
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-indigo-600/10 rounded-full blur-3xl group-hover:bg-indigo-600/20 transition-all"></div>

        <div className="relative z-10 flex flex-col items-center text-center">
          <div className="bg-gradient-to-br from-indigo-500 to-blue-600 p-4 rounded-3xl shadow-xl mb-6 relative">
            <BrainCircuit className="text-white w-8 h-8 sm:w-12 sm:h-12" />
            <div className={`absolute -bottom-1 -right-1 p-1 rounded-full border-2 border-slate-900 ${navigator.onLine ? 'bg-emerald-500' : 'bg-rose-500'}`}>
              {navigator.onLine ? <Wifi size={10} className="text-white" /> : <WifiOff size={10} className="text-white" />}
            </div>
          </div>
          <h2 className="text-2xl sm:text-4xl font-black text-white uppercase tracking-tighter mb-4">Financial AI Intelligence</h2>
          <p className="text-slate-400 max-w-lg font-bold text-sm sm:text-base leading-relaxed mb-8">
            Dapatkan analisis cerdas dan rekomendasi strategis berdasarkan data keuangan Anda menggunakan teknologi Gemini AI yang selalu online.
          </p>

          <button 
            onClick={generateAnalysis}
            disabled={isLoading}
            className={`flex items-center gap-3 px-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black uppercase tracking-widest transition-all shadow-lg shadow-indigo-900/40 disabled:opacity-50 disabled:cursor-not-allowed transform active:scale-95`}
          >
            {isLoading ? (
              <>
                <RefreshCw className="w-5 h-5 animate-spin" />
                Proses Analisis...
              </>
            ) : (
              <>
                <Sparkles className="w-5 h-5" />
                Mulai Analisis Online
              </>
            )}
          </button>
        </div>
      </div>

      {error && (
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-rose-500 flex items-center gap-4 bg-rose-500/10 animate-fadeIn">
          <AlertCircle className="text-rose-500 shrink-0" size={24} />
          <p className="text-rose-200 text-sm font-black">{error}</p>
        </div>
      )}

      {analysis && !isLoading && (
        <div className="glass-panel p-6 sm:p-10 rounded-[2.5rem] border border-white/5 shadow-xl animate-fadeIn">
          <div className="flex items-center gap-3 mb-8 border-b border-white/5 pb-4">
            <div className="w-1.5 h-6 bg-emerald-500 rounded-full"></div>
            <h3 className="text-lg font-black text-white uppercase tracking-widest">Laporan Analisis Cerdas</h3>
          </div>
          <div className="prose prose-invert max-w-none">
            <div className="text-slate-300 leading-relaxed font-medium space-y-4 whitespace-pre-wrap">
              {analysis.split('\n').map((line, i) => {
                const trimmed = line.trim();
                if (trimmed.startsWith('#')) {
                  const level = (line.match(/#/g) || []).length;
                  return <h3 key={i} className={`font-black text-indigo-400 mt-6 mb-3 uppercase border-l-2 border-indigo-500 pl-3 ${level === 1 ? 'text-2xl' : 'text-lg'}`}>{trimmed.replace(/#/g, '').trim()}</h3>;
                }
                if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
                  return (
                    <div key={i} className="flex gap-3 items-start ml-2 mb-2">
                      <div className="mt-1.5 bg-indigo-500/30 rounded-full p-0.5">
                        <CheckCircle2 size={12} className="text-indigo-400" />
                      </div>
                      <span className="text-slate-200 font-bold">{trimmed.replace(/[-*]/, '').trim()}</span>
                    </div>
                  );
                }
                if (!trimmed) return <div key={i} className="h-2"></div>;
                return <p key={i} className="mb-2 font-bold text-slate-300">{trimmed}</p>;
              })}
            </div>
          </div>

          <div className="mt-12 pt-8 border-t border-white/5 flex flex-col sm:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-500 tracking-widest">
              <TrendingUp size={14} className="text-indigo-500" />
              Dianalisis secara real-time melalui Jaringan Internet
            </div>
            <button onClick={generateAnalysis} className="text-xs font-black uppercase tracking-widest text-indigo-400 hover:text-white transition-colors flex items-center gap-2 group">
              <RefreshCw size={14} className="group-hover:rotate-180 transition-transform duration-500" /> Refresh Analisis
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AIAnalysis;

import React, { useState, useEffect } from 'react';
import { AppState, MonthlyData, DEFAULT_SALARY, DEFAULT_BUDGET } from './types';
import SalarySlip from './components/SalarySlip';
import Budget from './components/Budget';
import MonthlyCharts from './components/MonthlyCharts';
import Investments from './components/Investments';
import YearlySummary from './components/YearlySummary';
import AIAnalysis from './components/AIAnalysis';
import { calculateGrossIncome, calculateTax, calculateOvertime, calculateBonus } from './utils';
import { Wallet, LayoutDashboard, PieChart, TrendingUp, Calendar, ChevronLeft, ChevronRight, Cloud, Loader2, CheckCircle2, Sparkles, Sun, Moon } from 'lucide-react';
import { supabase } from './supabaseClient';

const TABS = [
  { id: 'salary', label: 'Gaji', icon: Wallet },
  { id: 'budget', label: 'Anggaran', icon: LayoutDashboard },
  { id: 'charts', label: 'Grafik', icon: PieChart },
  { id: 'invest', label: 'Aset', icon: TrendingUp },
  { id: 'year', label: 'Tahunan', icon: Calendar },
  { id: 'ai', label: 'AI Analisis', icon: Sparkles },
];

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');
  const [appState, setAppState] = useState<AppState>({});
  const [isLoading, setIsLoading] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  // Theme state
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('app-theme') as 'dark' | 'light') || 'dark';
  });

  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('app-theme', theme);
  }, [theme]);

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase.from('monthly_finance').select('month_id, data');
        if (error) throw error;
        if (data) {
          const loadedState: AppState = {};
          data.forEach((row: any) => { loadedState[row.month_id] = row.data; });
          setAppState(loadedState);
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (isLoading || !appState[currentMonthKey]) return;
    const saveData = async () => {
      setSaveStatus('saving');
      try {
        const { error } = await supabase.from('monthly_finance').upsert({ 
          month_id: currentMonthKey, 
          data: appState[currentMonthKey],
          updated_at: new Date().toISOString()
        });
        if (error) throw error;
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } catch (err) {
        console.error("Error saving data:", err);
        setSaveStatus('error');
      }
    };
    const timeoutId = setTimeout(saveData, 800);
    return () => clearTimeout(timeoutId);
  }, [appState, currentMonthKey, isLoading]);

  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     return gross - calculateTax(gross, salary.taxRate) - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  useEffect(() => {
    if (!isLoading && !appState[currentMonthKey]) {
      const prevDate = new Date(currentDate);
      prevDate.setMonth(currentDate.getMonth() - 1);
      const pKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
      if (appState[pKey]) {
        setPrevMonthKey(pKey);
        setShowCopyModal(true);
      } else {
        initializeMonth(false);
      }
    }
  }, [currentMonthKey, isLoading]);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      newData = JSON.parse(JSON.stringify(appState[prevMonthKey]));
      if (newData.budget.needs) newData.budget.needs.items.forEach(i => i.actual = 0);
      if (newData.budget.savings) newData.budget.savings.items.forEach(i => i.actual = 0);
      if (newData.budget.debt) newData.budget.debt.items.forEach(i => i.actual = 0);
      if (newData.budget.others) newData.budget.others.items.forEach(i => i.actual = 0);
      if (newData.budget.custom) newData.budget.custom.forEach(cat => cat.items.forEach(i => i.actual = 0));
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = { salary: { ...DEFAULT_SALARY }, budget: { ...DEFAULT_BUDGET }, investments: [] };
    }
    setAppState(prev => ({ ...prev, [currentMonthKey]: newData }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => {
      const existing = prev[currentMonthKey] || { 
        salary: { ...DEFAULT_SALARY }, 
        budget: { ...DEFAULT_BUDGET }, 
        investments: [] 
      };
      const updatedMonth = { ...existing, ...newData };
      return { 
        ...prev, 
        [currentMonthKey]: updatedMonth 
      };
    });
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  if (isLoading) return <div className="min-h-screen flex items-center justify-center bg-[#0f172a]"><Loader2 className="w-10 h-10 text-indigo-400 animate-spin" /></div>;

  return (
    <div className="min-h-screen font-sans selection:bg-indigo-500/30 selection:text-indigo-200 theme-transition">
      <nav className="sticky top-0 z-50 pt-2 px-2 sm:pt-4 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl border border-white/5">
          <div className="flex flex-col sm:flex-row items-center justify-between p-3 sm:px-6 sm:h-20 gap-3">
            <div className="flex items-center justify-between w-full sm:w-auto">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-lg shadow-lg">
                     <Wallet className="text-white h-5 w-5 sm:h-6 sm:w-6" />
                  </div>
                  <div>
                    <h1 className="text-sm sm:text-xl font-black text-white uppercase tracking-tight leading-tight">ANIQ SUSILO</h1>
                    <p className="text-[10px] sm:text-xs font-black text-indigo-400 uppercase tracking-widest mt-0.5">FINANCE MONTHLY</p>
                  </div>
                </div>
                <div className="flex sm:hidden items-center gap-2">
                   <button onClick={toggleTheme} className="p-2 bg-slate-800 rounded-lg border border-slate-700 text-amber-400">
                     {theme === 'dark' ? <Sun size={16} /> : <Moon size={16} className="text-indigo-400" />}
                   </button>
                   <div className="flex items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
                      <button onClick={() => changeMonth(-1)} className="p-1.5"><ChevronLeft size={16} /></button>
                      <div className="px-2 font-mono font-black text-indigo-400 text-xs uppercase">
                        {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' })}
                      </div>
                      <button onClick={() => changeMonth(1)} className="p-1.5"><ChevronRight size={16} /></button>
                   </div>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button 
                  onClick={toggleTheme}
                  className="hidden sm:flex items-center gap-2 px-4 py-2 bg-slate-800/80 rounded-xl border border-slate-700 shadow-sm hover:bg-slate-700 transition-colors"
                  title="Ganti Tema"
                >
                  {theme === 'dark' ? (
                    <><Sun size={18} className="text-amber-400" /><span className="text-[10px] font-black uppercase text-slate-300">Tema Terang</span></>
                  ) : (
                    <><Moon size={18} className="text-indigo-400" /><span className="text-[10px] font-black uppercase text-slate-600">Tema Gelap</span></>
                  )}
                </button>
                <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-slate-800/50 rounded-lg border border-slate-700/50">
                  {saveStatus === 'saving' ? <Loader2 size={14} className="animate-spin text-indigo-400" /> : saveStatus === 'saved' ? <CheckCircle2 size={14} className="text-emerald-400" /> : <Cloud size={12} className="text-slate-500"/>}
                  <span className="text-[10px] font-black uppercase text-slate-400">{saveStatus === 'saving' ? 'Saving' : saveStatus === 'saved' ? 'Saved' : 'Synced'}</span>
                </div>
                <div className="hidden sm:flex items-center bg-slate-800/80 rounded-xl p-1.5 border border-slate-700 shadow-sm">
                  <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronLeft size={20} /></button>
                  <div className="px-6 font-mono font-black text-indigo-400 w-48 text-center text-sm uppercase tracking-wider">
                    {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' }).toUpperCase()}
                  </div>
                  <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronRight size={20} /></button>
                </div>
            </div>
          </div>
          <div className="border-t border-slate-700/50 px-2 overflow-x-auto scrollbar-hide">
            <div className="flex space-x-1 py-1.5 sm:py-2">
              {TABS.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs font-black rounded-lg transition-all flex-1 justify-center sm:flex-none uppercase tracking-widest ${isActive ? 'text-white bg-indigo-600 shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
                    <Icon size={16} />{tab.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </nav>
      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && <SalarySlip data={currentData.salary} onChange={(s) => updateCurrentData({ salary: s })} />}
        {activeTab === 'budget' && <Budget income={currentNetIncome} data={currentData.budget} onChange={(b) => updateCurrentData({ budget: b })} />}
        {activeTab === 'charts' && <MonthlyCharts budgetData={currentData.budget} income={currentNetIncome} />}
        {activeTab === 'invest' && <Investments items={currentData.investments} onChange={(i) => updateCurrentData({ investments: i })} />}
        {activeTab === 'year' && <YearlySummary appState={appState} year={currentDate.getFullYear()} />}
        {activeTab === 'ai' && <AIAnalysis currentMonthData={currentData} netIncome={currentNetIncome} />}
      </main>
      {showCopyModal && (
        <div className="fixed inset-0 bg-slate-950/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="bg-slate-900 p-8 rounded-3xl max-w-md w-full border border-slate-800 shadow-2xl">
              <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Bulan Baru</h3>
              <p className="text-slate-400 mb-8 font-black">Data bulan ini belum ada. Salin template dari bulan sebelumnya?</p>
              <div className="flex gap-4">
                <button onClick={() => initializeMonth(true)} className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg">Salin</button>
                <button onClick={() => initializeMonth(false)} className="flex-1 bg-slate-800 text-slate-200 py-3 rounded-xl font-black uppercase tracking-widest hover:bg-slate-700 transition-all">Baru</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

