import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MonthlyData } from '../types';
import { formatRupiah } from '../utils';
import { Sparkles, BrainCircuit, RefreshCw, TrendingUp, AlertCircle, CheckCircle2, Wifi, WifiOff, Key } from 'lucide-react';

interface AIAnalysisProps {
  currentMonthData: MonthlyData;
  netIncome: number;
}

const AIAnalysis: React.FC<AIAnalysisProps> = ({ currentMonthData, netIncome }) => {
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasKey, setHasKey] = useState<boolean>(!!process.env.API_KEY);

  // Cek ketersediaan API Key saat komponen dimuat
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio?.hasSelectedApiKey) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected || !!process.env.API_KEY);
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
      // Asumsikan pemilihan berhasil sesuai instruksi teknis
      setHasKey(true);
      setError(null);
    } else {
      setError("Fitur pemilihan API Key tidak tersedia di browser ini. Pastikan Anda menggunakan lingkungan yang mendukung.");
    }
  };

  const generateAnalysis = async () => {
    // 1. Cek Koneksi Internet
    if (!navigator.onLine) {
      setError("Perangkat Anda sedang offline. Mohon hubungkan ke internet untuk menggunakan fitur AI Analysis.");
      return;
    }

    // 2. Cek API Key
    if (!process.env.API_KEY && !hasKey) {
      setError("API Key diperlukan untuk analisis. Silakan hubungkan API Key Anda.");
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      // Inisialisasi AI tepat sebelum digunakan untuk mengambil kunci terbaru
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const budgetDetails = JSON.stringify({
        income: formatRupiah(netIncome),
        needs: currentMonthData.budget.needs?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        savings: currentMonthData.budget.savings?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        debt: currentMonthData.budget.debt?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        others: currentMonthData.budget.others?.items.map(i => ({ name: i.name, actual: i.actual })),
        investments: currentMonthData.investments.map(i => ({ name: i.name, value: i.currentValue, target: i.targetValue }))
      });

      const prompt = `Bertindaklah sebagai Konsultan Keuangan Pribadi Profesional. Analisis data keuangan berikut untuk bulan ini dan berikan wawasan mendalam dalam Bahasa Indonesia.

      Data Keuangan:
      ${budgetDetails}

      Format respon Anda harus meliputi:
      1. Ringkasan Singkat Kesehatan Keuangan (Gunakan nada yang menyemangati).
      2. Analisis Efisiensi Anggaran (Soroti area yang hemat atau overbudget).
      3. Analisis Aset & Investasi (Seberapa dekat dengan target).
      4. 3 Saran Praktis untuk bulan depan agar kondisi keuangan Aniq Susilo semakin kuat.

      Berikan respon dalam format Markdown yang rapi dengan heading dan poin-poin.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });

      if (!response || !response.text) {
        throw new Error("Server AI mengembalikan respon kosong.");
      }

      setAnalysis(response.text);
    } catch (err: any) {
      console.error("AI Analysis Error:", err);
      if (err.message?.includes('entity was not found') || err.message?.includes('404')) {
        setHasKey(false);
        setError("API Key tidak valid atau telah kedaluwarsa. Silakan hubungkan kembali.");
      } else {
        setError(`Terjadi kendala: ${err.message || "Gagal menghubungi AI. Pastikan internet Anda stabil."}`);
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      <div className="glass-panel p-6 sm:p-10 rounded-[2.5rem] border border-indigo-500/20 shadow-2xl relative overflow-hidden group">
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-indigo-600/10 rounded-full blur-3xl group-hover:bg-indigo-600/20 transition-all"></div>

        <div className="relative z-10 flex flex-col items-center text-center">
          <div className="bg-gradient-to-br from-indigo-500 to-blue-600 p-4 rounded-3xl shadow-xl mb-6 relative">
            <BrainCircuit className="text-white w-8 h-8 sm:w-12 sm:h-12" />
            <div className={`absolute -bottom-1 -right-1 p-1 rounded-full border-2 border-slate-900 ${navigator.onLine ? 'bg-emerald-500' : 'bg-rose-500'}`}>
              {navigator.onLine ? <Wifi size={10} className="text-white" /> : <WifiOff size={10} className="text-white" />}
            </div>
          </div>
          <h2 className="text-2xl sm:text-4xl font-black text-white uppercase tracking-tighter mb-4">Financial AI Intelligence</h2>
          <p className="text-slate-400 max-w-lg font-bold text-sm sm:text-base leading-relaxed mb-8">
            Dapatkan analisis cerdas dan rekomendasi strategis berdasarkan data keuangan Anda menggunakan teknologi Gemini AI yang selalu online.
          </p>

          <div className="flex flex-col gap-4">
            {!hasKey && (
              <button 
                onClick={handleOpenKeySelector}
                className="flex items-center gap-3 px-8 py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-2xl font-black uppercase tracking-widest transition-all border border-slate-700"
              >
                <Key className="w-5 h-5 text-indigo-400" />
                Hubungkan API Key
              </button>
            )}

            <button 
              onClick={generateAnalysis}
              disabled={isLoading || (!hasKey && !process.env.API_KEY)}
              className={`flex items-center gap-3 px-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black uppercase tracking-widest transition-all shadow-lg shadow-indigo-900/40 disabled:opacity-50 disabled:cursor-not-allowed transform active:scale-95`}
            >
              {isLoading ? (
                <>
                  <RefreshCw className="w-5 h-5 animate-spin" />
                  Proses Analisis...
                </>
              ) : (
                <>
                  <Sparkles className="w-5 h-5" />
                  Mulai Analisis Online
                </>
              )}
            </button>

            {!hasKey && !process.env.API_KEY && (
              <p className="text-[10px] text-amber-500 font-black uppercase tracking-widest animate-pulse">
                Silakan hubungkan API Key untuk mengaktifkan AI
              </p>
            )}
          </div>
        </div>
      </div>

      {error && (
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-rose-500 flex items-center gap-4 bg-rose-500/10 animate-fadeIn">
          <AlertCircle className="text-rose-500 shrink-0" size={24} />
          <p className="text-rose-200 text-sm font-black">{error}</p>
        </div>
      )}

      {analysis && !isLoading && (
        <div className="glass-panel p-6 sm:p-10 rounded-[2.5rem] border border-white/5 shadow-xl animate-fadeIn">
          <div className="flex items-center gap-3 mb-8 border-b border-white/5 pb-4">
            <div className="w-1.5 h-6 bg-emerald-500 rounded-full"></div>
            <h3 className="text-lg font-black text-white uppercase tracking-widest">Laporan Analisis Cerdas</h3>
          </div>
          <div className="prose prose-invert max-w-none">
            <div className="text-slate-300 leading-relaxed font-medium space-y-4 whitespace-pre-wrap">
              {analysis.split('\n').map((line, i) => {
                const trimmed = line.trim();
                if (trimmed.startsWith('#')) {
                  const level = (line.match(/#/g) || []).length;
                  return <h3 key={i} className={`font-black text-indigo-400 mt-6 mb-3 uppercase border-l-2 border-indigo-500 pl-3 ${level === 1 ? 'text-2xl' : 'text-lg'}`}>{trimmed.replace(/#/g, '').trim()}</h3>;
                }
                if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
                  return (
                    <div key={i} className="flex gap-3 items-start ml-2 mb-2">
                      <div className="mt-1.5 bg-indigo-500/30 rounded-full p-0.5">
                        <CheckCircle2 size={12} className="text-indigo-400" />
                      </div>
                      <span className="text-slate-200 font-bold">{trimmed.replace(/[-*]/, '').trim()}</span>
                    </div>
                  );
                }
                if (!trimmed) return <div key={i} className="h-2"></div>;
                return <p key={i} className="mb-2 font-bold text-slate-300">{trimmed}</p>;
              })}
            </div>
          </div>

          <div className="mt-12 pt-8 border-t border-white/5 flex flex-col sm:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-500 tracking-widest">
              <TrendingUp size={14} className="text-indigo-500" />
              Dianalisis secara real-time melalui Jaringan Internet
            </div>
            <button onClick={generateAnalysis} className="text-xs font-black uppercase tracking-widest text-indigo-400 hover:text-white transition-colors flex items-center gap-2 group">
              <RefreshCw size={14} className="group-hover:rotate-180 transition-transform duration-500" /> Refresh Analisis
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AIAnalysis;

import React, { useState, useEffect } from 'react';
import { AppState, MonthlyData, DEFAULT_SALARY, DEFAULT_BUDGET } from './types';
import SalarySlip from './components/SalarySlip';
import Budget from './components/Budget';
import MonthlyCharts from './components/MonthlyCharts';
import Investments from './components/Investments';
import YearlySummary from './components/YearlySummary';
import AIAnalysis from './components/AIAnalysis';
import { calculateGrossIncome, calculateTax, calculateOvertime, calculateBonus } from './utils';
import { Wallet, LayoutDashboard, PieChart, TrendingUp, Calendar, ChevronLeft, ChevronRight, Cloud, Loader2, CheckCircle2, Sparkles, Sun, Moon } from 'lucide-react';
import { supabase } from './supabaseClient';

const TABS = [
  { id: 'salary', label: 'Gaji', icon: Wallet },
  { id: 'budget', label: 'Anggaran', icon: LayoutDashboard },
  { id: 'charts', label: 'Grafik', icon: PieChart },
  { id: 'invest', label: 'Aset', icon: TrendingUp },
  { id: 'year', label: 'Tahunan', icon: Calendar },
  { id: 'ai', label: 'AI Analisis', icon: Sparkles },
];

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');
  const [appState, setAppState] = useState<AppState>({});
  const [isLoading, setIsLoading] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  // Theme state
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('app-theme') as 'dark' | 'light') || 'dark';
  });

  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  // Feature: Auto-close/reset when minimized or tab switched
  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'hidden') {
        // Force reload to clear memory and start from the beginning
        window.location.reload();
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('app-theme', theme);
  }, [theme]);

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase.from('monthly_finance').select('month_id, data');
        if (error) throw error;
        if (data) {
          const loadedState: AppState = {};
          data.forEach((row: any) => { loadedState[row.month_id] = row.data; });
          setAppState(loadedState);
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (isLoading || !appState[currentMonthKey]) return;
    const saveData = async () => {
      setSaveStatus('saving');
      try {
        const { error } = await supabase.from('monthly_finance').upsert({ 
          month_id: currentMonthKey, 
          data: appState[currentMonthKey],
          updated_at: new Date().toISOString()
        });
        if (error) throw error;
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } catch (err) {
        console.error("Error saving data:", err);
        setSaveStatus('error');
      }
    };
    const timeoutId = setTimeout(saveData, 800);
    return () => clearTimeout(timeoutId);
  }, [appState, currentMonthKey, isLoading]);

  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     return gross - calculateTax(gross, salary.taxRate) - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  useEffect(() => {
    if (!isLoading && !appState[currentMonthKey]) {
      const prevDate = new Date(currentDate);
      prevDate.setMonth(currentDate.getMonth() - 1);
      const pKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
      if (appState[pKey]) {
        setPrevMonthKey(pKey);
        setShowCopyModal(true);
      } else {
        initializeMonth(false);
      }
    }
  }, [currentMonthKey, isLoading]);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      newData = JSON.parse(JSON.stringify(appState[prevMonthKey]));
      if (newData.budget.needs) newData.budget.needs.items.forEach(i => i.actual = 0);
      if (newData.budget.savings) newData.budget.savings.items.forEach(i => i.actual = 0);
      if (newData.budget.debt) newData.budget.debt.items.forEach(i => i.actual = 0);
      if (newData.budget.others) newData.budget.others.items.forEach(i => i.actual = 0);
      if (newData.budget.custom) newData.budget.custom.forEach(cat => cat.items.forEach(i => i.actual = 0));
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = { salary: { ...DEFAULT_SALARY }, budget: { ...DEFAULT_BUDGET }, investments: [] };
    }
    setAppState(prev => ({ ...prev, [currentMonthKey]: newData }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => {
      const existing = prev[currentMonthKey] || { 
        salary: { ...DEFAULT_SALARY }, 
        budget: { ...DEFAULT_BUDGET }, 
        investments: [] 
      };
      const updatedMonth = { ...existing, ...newData };
      return { 
        ...prev, 
        [currentMonthKey]: updatedMonth 
      };
    });
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  if (isLoading) return <div className="min-h-screen flex items-center justify-center bg-[#0f172a]"><Loader2 className="w-10 h-10 text-indigo-400 animate-spin" /></div>;

  return (
    <div className="min-h-screen font-sans selection:bg-indigo-500/30 selection:text-indigo-200 theme-transition">
      <nav className="sticky top-0 z-50 pt-2 px-2 sm:pt-4 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl border border-white/5">
          <div className="flex flex-col sm:flex-row items-center justify-between p-3 sm:px-6 sm:h-20 gap-3">
            <div className="flex items-center justify-between w-full sm:w-auto">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-lg shadow-lg">
                     <Wallet className="text-white h-5 w-5 sm:h-6 sm:w-6" />
                  </div>
                  <div>
                    <h1 className="text-sm sm:text-xl font-black text-white uppercase tracking-tight leading-tight">ANIQ SUSILO</h1>
                    <p className="text-[10px] sm:text-xs font-black text-indigo-400 uppercase tracking-widest mt-0.5">FINANCE MONTHLY</p>
                  </div>
                </div>
                <div className="flex sm:hidden items-center gap-2">
                   <button onClick={toggleTheme} className="p-2 bg-slate-800 rounded-lg border border-slate-700 text-amber-400">
                     {theme === 'dark' ? <Sun size={16} /> : <Moon size={16} className="text-indigo-400" />}
                   </button>
                   <div className="flex items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
                      <button onClick={() => changeMonth(-1)} className="p-1.5"><ChevronLeft size={16} /></button>
                      <div className="px-2 font-mono font-black text-indigo-400 text-xs uppercase">
                        {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' })}
                      </div>
                      <button onClick={() => changeMonth(1)} className="p-1.5"><ChevronRight size={16} /></button>
                   </div>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button 
                  onClick={toggleTheme}
                  className="hidden sm:flex items-center gap-2 px-4 py-2 bg-slate-800/80 rounded-xl border border-slate-700 shadow-sm hover:bg-slate-700 transition-colors"
                  title="Ganti Tema"
                >
                  {theme === 'dark' ? (
                    <><Sun size={18} className="text-amber-400" /><span className="text-[10px] font-black uppercase text-slate-300">Tema Terang</span></>
                  ) : (
                    <><Moon size={18} className="text-indigo-400" /><span className="text-[10px] font-black uppercase text-slate-600">Tema Gelap</span></>
                  )}
                </button>
                <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-slate-800/50 rounded-lg border border-slate-700/50">
                  {saveStatus === 'saving' ? <Loader2 size={14} className="animate-spin text-indigo-400" /> : saveStatus === 'saved' ? <CheckCircle2 size={14} className="text-emerald-400" /> : <Cloud size={12} className="text-slate-500"/>}
                  <span className="text-[10px] font-black uppercase text-slate-400">{saveStatus === 'saving' ? 'Saving' : saveStatus === 'saved' ? 'Saved' : 'Synced'}</span>
                </div>
                <div className="hidden sm:flex items-center bg-slate-800/80 rounded-xl p-1.5 border border-slate-700 shadow-sm">
                  <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronLeft size={20} /></button>
                  <div className="px-6 font-mono font-black text-indigo-400 w-48 text-center text-sm uppercase tracking-wider">
                    {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' }).toUpperCase()}
                  </div>
                  <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronRight size={20} /></button>
                </div>
            </div>
          </div>
          <div className="border-t border-slate-700/50 px-2 overflow-x-auto scrollbar-hide">
            <div className="flex space-x-1 py-1.5 sm:py-2">
              {TABS.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs font-black rounded-lg transition-all flex-1 justify-center sm:flex-none uppercase tracking-widest ${isActive ? 'text-white bg-indigo-600 shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
                    <Icon size={16} />{tab.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </nav>
      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && <SalarySlip data={currentData.salary} onChange={(s) => updateCurrentData({ salary: s })} />}
        {activeTab === 'budget' && <Budget income={currentNetIncome} data={currentData.budget} onChange={(b) => updateCurrentData({ budget: b })} />}
        {activeTab === 'charts' && <MonthlyCharts budgetData={currentData.budget} income={currentNetIncome} />}
        {activeTab === 'invest' && <Investments items={currentData.investments} onChange={(i) => updateCurrentData({ investments: i })} />}
        {activeTab === 'year' && <YearlySummary appState={appState} year={currentDate.getFullYear()} />}
        {activeTab === 'ai' && <AIAnalysis currentMonthData={currentData} netIncome={currentNetIncome} />}
      </main>
      {showCopyModal && (
        <div className="fixed inset-0 bg-slate-950/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="bg-slate-900 p-8 rounded-3xl max-w-md w-full border border-slate-800 shadow-2xl">
              <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Bulan Baru</h3>
              <p className="text-slate-400 mb-8 font-black">Data bulan ini belum ada. Salin template dari bulan sebelumnya?</p>
              <div className="flex gap-4">
                <button onClick={() => initializeMonth(true)} className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg">Salin</button>
                <button onClick={() => initializeMonth(false)} className="flex-1 bg-slate-800 text-slate-200 py-3 rounded-xl font-black uppercase tracking-widest hover:bg-slate-700 transition-all">Baru</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Lock, User, Eye, EyeOff, ShieldCheck, RefreshCw, ArrowLeft, KeyRound } from 'lucide-react';

interface LoginProps {
  onAuthenticated: () => void;
}

const Login: React.FC<LoginProps> = ({ onAuthenticated }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [isForgot, setIsForgot] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // Check if account already exists
  const hasAccount = !!localStorage.getItem('finance_user');

  useEffect(() => {
    if (!hasAccount) {
      setIsSignUp(true);
    }
  }, [hasAccount]);

  const handleAction = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (isForgot) {
      handleReset();
      return;
    }

    if (isSignUp) {
      handleSignUp();
    } else {
      handleLogin();
    }
  };

  const handleSignUp = () => {
    if (!username || !password) {
      setError('Username dan Password wajib diisi');
      return;
    }
    if (password !== confirmPassword) {
      setError('Konfirmasi password tidak cocok');
      return;
    }

    const userData = { username, password };
    localStorage.setItem('finance_user', JSON.stringify(userData));
    setSuccess('Akun berhasil dibuat! Silakan login.');
    setIsSignUp(false);
    setPassword('');
    setConfirmPassword('');
  };

  const handleLogin = () => {
    const savedData = localStorage.getItem('finance_user');
    if (!savedData) {
      setError('Akun tidak ditemukan. Silakan buat akun.');
      return;
    }

    const { username: savedUser, password: savedPass } = JSON.parse(savedData);
    if (username === savedUser && password === savedPass) {
      onAuthenticated();
    } else {
      setError('Username atau Password salah');
    }
  };

  const handleReset = () => {
    const savedData = localStorage.getItem('finance_user');
    if (!savedData) {
      setError('Sistem belum memiliki data akun untuk direset.');
      return;
    }

    if (password !== confirmPassword) {
      setError('Password baru tidak cocok');
      return;
    }

    const userData = { username, password };
    localStorage.setItem('finance_user', JSON.stringify(userData));
    setSuccess('Kredensial berhasil diperbarui!');
    setIsForgot(false);
    setPassword('');
    setConfirmPassword('');
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-[#0f172a] selection:bg-indigo-500/30">
      <div className="max-w-md w-full animate-fadeIn">
        <div className="glass-panel p-8 sm:p-10 rounded-[2.5rem] border border-white/10 shadow-2xl relative overflow-hidden">
          {/* Decorative Background */}
          <div className="absolute -top-24 -right-24 w-48 h-48 bg-indigo-600/20 rounded-full blur-3xl"></div>
          <div className="absolute -bottom-24 -left-24 w-48 h-48 bg-blue-600/10 rounded-full blur-3xl"></div>

          <div className="relative z-10 text-center mb-8">
            <div className="inline-flex p-4 rounded-3xl bg-indigo-600 shadow-xl mb-6 shadow-indigo-900/40">
              <ShieldCheck className="text-white w-8 h-8" />
            </div>
            <h1 className="text-2xl font-black text-white uppercase tracking-tighter">
              {isForgot ? 'Reset Akses' : isSignUp ? 'Buat Akun Baru' : 'Akses Keuangan'}
            </h1>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em] mt-2">
              ANIQ SUSILO - FINANCE MONTHLY
            </p>
          </div>

          <form onSubmit={handleAction} className="space-y-5 relative z-10">
            {error && (
              <div className="bg-rose-500/10 border border-rose-500/20 p-3 rounded-xl text-rose-500 text-[10px] font-black uppercase tracking-wider text-center animate-shake">
                {error}
              </div>
            )}
            {success && (
              <div className="bg-emerald-500/10 border border-emerald-500/20 p-3 rounded-xl text-emerald-500 text-[10px] font-black uppercase tracking-wider text-center">
                {success}
              </div>
            )}

            <div className="space-y-1.5">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 pl-1">Username</label>
              <div className="relative group">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
                <input 
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-4 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all"
                  placeholder="Masukkan username"
                  required
                />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 pl-1">
                {isForgot ? 'Password Baru' : 'Password'}
              </label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
                <input 
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-12 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all"
                  placeholder="••••••••"
                  required
                />
                <button 
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white transition-colors"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {(isSignUp || isForgot) && (
              <div className="space-y-1.5 animate-fadeIn">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 pl-1">Konfirmasi Password</label>
                <div className="relative group">
                  <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
                  <input 
                    type={showPassword ? "text" : "password"}
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-4 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all"
                    placeholder="••••••••"
                    required
                  />
                </div>
              </div>
            )}

            <button 
              type="submit"
              className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black uppercase text-xs tracking-[0.2em] transition-all shadow-lg shadow-indigo-900/40 active:scale-95"
            >
              {isForgot ? 'Update Password' : isSignUp ? 'Daftar Sekarang' : 'Masuk Aplikasi'}
            </button>

            <div className="pt-4 flex flex-col gap-3">
              {!isSignUp && !isForgot && (
                <button 
                  type="button"
                  onClick={() => { setIsForgot(true); setError(''); setSuccess(''); }}
                  className="text-[10px] font-black uppercase text-indigo-400 hover:text-indigo-300 tracking-widest transition-colors flex items-center justify-center gap-2"
                >
                  <RefreshCw size={12} /> Lupa Password atau Username?
                </button>
              )}

              {(isSignUp || isForgot) && (
                <button 
                  type="button"
                  onClick={() => { setIsSignUp(false); setIsForgot(false); setError(''); setSuccess(''); }}
                  className="text-[10px] font-black uppercase text-slate-500 hover:text-white tracking-widest transition-colors flex items-center justify-center gap-2"
                >
                  <ArrowLeft size={12} /> Kembali ke Login
                </button>
              )}

              {!isSignUp && !isForgot && (
                <div className="text-center">
                  <span className="text-[10px] font-black uppercase text-slate-600 tracking-widest">Belum punya akun? </span>
                  <button 
                    type="button" 
                    onClick={() => { setIsSignUp(true); setError(''); setSuccess(''); }}
                    className="text-[10px] font-black uppercase text-indigo-400 hover:text-indigo-300"
                  >
                    Buat Disini
                  </button>
                </div>
              )}
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { AppState, MonthlyData, DEFAULT_SALARY, DEFAULT_BUDGET } from './types';
import SalarySlip from './components/SalarySlip';
import Budget from './components/Budget';
import MonthlyCharts from './components/MonthlyCharts';
import Investments from './components/Investments';
import YearlySummary from './components/YearlySummary';
import AIAnalysis from './components/AIAnalysis';
import Login from './components/Login';
import { calculateGrossIncome, calculateTax, calculateOvertime, calculateBonus } from './utils';
import { Wallet, LayoutDashboard, PieChart, TrendingUp, Calendar, ChevronLeft, ChevronRight, Cloud, Loader2, CheckCircle2, Sparkles, Sun, Moon } from 'lucide-react';
import { supabase } from './supabaseClient';

const TABS = [
  { id: 'salary', label: 'Gaji', icon: Wallet },
  { id: 'budget', label: 'Anggaran', icon: LayoutDashboard },
  { id: 'charts', label: 'Grafik', icon: PieChart },
  { id: 'invest', label: 'Aset', icon: TrendingUp },
  { id: 'year', label: 'Tahunan', icon: Calendar },
  { id: 'ai', label: 'AI Analisis', icon: Sparkles },
];

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');
  const [appState, setAppState] = useState<AppState>({});
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  // Theme state
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('app-theme') as 'dark' | 'light') || 'dark';
  });

  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  // Feature: Auto-close/reset when minimized or tab switched
  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'hidden') {
        // Force reload to clear memory and start from the beginning
        window.location.reload();
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('app-theme', theme);
  }, [theme]);

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase.from('monthly_finance').select('month_id, data');
        if (error) throw error;
        if (data) {
          const loadedState: AppState = {};
          data.forEach((row: any) => { loadedState[row.month_id] = row.data; });
          setAppState(loadedState);
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (isLoading || !appState[currentMonthKey]) return;
    const saveData = async () => {
      setSaveStatus('saving');
      try {
        const { error } = await supabase.from('monthly_finance').upsert({ 
          month_id: currentMonthKey, 
          data: appState[currentMonthKey],
          updated_at: new Date().toISOString()
        });
        if (error) throw error;
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } catch (err) {
        console.error("Error saving data:", err);
        setSaveStatus('error');
      }
    };
    const timeoutId = setTimeout(saveData, 800);
    return () => clearTimeout(timeoutId);
  }, [appState, currentMonthKey, isLoading]);

  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     return gross - calculateTax(gross, salary.taxRate) - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  useEffect(() => {
    if (!isLoading && !appState[currentMonthKey]) {
      const prevDate = new Date(currentDate);
      prevDate.setMonth(currentDate.getMonth() - 1);
      const pKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
      if (appState[pKey]) {
        setPrevMonthKey(pKey);
        setShowCopyModal(true);
      } else {
        initializeMonth(false);
      }
    }
  }, [currentMonthKey, isLoading]);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      newData = JSON.parse(JSON.stringify(appState[prevMonthKey]));
      if (newData.budget.needs) newData.budget.needs.items.forEach(i => i.actual = 0);
      if (newData.budget.savings) newData.budget.savings.items.forEach(i => i.actual = 0);
      if (newData.budget.debt) newData.budget.debt.items.forEach(i => i.actual = 0);
      if (newData.budget.others) newData.budget.others.items.forEach(i => i.actual = 0);
      if (newData.budget.custom) newData.budget.custom.forEach(cat => cat.items.forEach(i => i.actual = 0));
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = { salary: { ...DEFAULT_SALARY }, budget: { ...DEFAULT_BUDGET }, investments: [] };
    }
    setAppState(prev => ({ ...prev, [currentMonthKey]: newData }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => {
      const existing = prev[currentMonthKey] || { 
        salary: { ...DEFAULT_SALARY }, 
        budget: { ...DEFAULT_BUDGET }, 
        investments: [] 
      };
      const updatedMonth = { ...existing, ...newData };
      return { 
        ...prev, 
        [currentMonthKey]: updatedMonth 
      };
    });
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  if (isLoading) return <div className="min-h-screen flex items-center justify-center bg-[#0f172a]"><Loader2 className="w-10 h-10 text-indigo-400 animate-spin" /></div>;

  // Render Login if not authenticated
  if (!isAuthenticated) {
    return <Login onAuthenticated={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="min-h-screen font-sans selection:bg-indigo-500/30 selection:text-indigo-200 theme-transition">
      <nav className="sticky top-0 z-50 pt-2 px-2 sm:pt-4 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl border border-white/5">
          <div className="flex flex-col sm:flex-row items-center justify-between p-3 sm:px-6 sm:h-20 gap-3">
            <div className="flex items-center justify-between w-full sm:w-auto">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-lg shadow-lg">
                     <Wallet className="text-white h-5 w-5 sm:h-6 sm:w-6" />
                  </div>
                  <div>
                    <h1 className="text-sm sm:text-xl font-black text-white uppercase tracking-tight leading-tight">ANIQ SUSILO</h1>
                    <p className="text-[10px] sm:text-xs font-black text-indigo-400 uppercase tracking-widest mt-0.5">FINANCE MONTHLY</p>
                  </div>
                </div>
                <div className="flex sm:hidden items-center gap-2">
                   <button onClick={toggleTheme} className="p-2 bg-slate-800 rounded-lg border border-slate-700 text-amber-400">
                     {theme === 'dark' ? <Sun size={16} /> : <Moon size={16} className="text-indigo-400" />}
                   </button>
                   <div className="flex items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
                      <button onClick={() => changeMonth(-1)} className="p-1.5"><ChevronLeft size={16} /></button>
                      <div className="px-2 font-mono font-black text-indigo-400 text-xs uppercase">
                        {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' })}
                      </div>
                      <button onClick={() => changeMonth(1)} className="p-1.5"><ChevronRight size={16} /></button>
                   </div>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button 
                  onClick={toggleTheme}
                  className="hidden sm:flex items-center gap-2 px-4 py-2 bg-slate-800/80 rounded-xl border border-slate-700 shadow-sm hover:bg-slate-700 transition-colors"
                  title="Ganti Tema"
                >
                  {theme === 'dark' ? (
                    <><Sun size={18} className="text-amber-400" /><span className="text-[10px] font-black uppercase text-slate-300">Tema Terang</span></>
                  ) : (
                    <><Moon size={18} className="text-indigo-400" /><span className="text-[10px] font-black uppercase text-slate-600">Tema Gelap</span></>
                  )}
                </button>
                <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-slate-800/50 rounded-lg border border-slate-700/50">
                  {saveStatus === 'saving' ? <Loader2 size={14} className="animate-spin text-indigo-400" /> : saveStatus === 'saved' ? <CheckCircle2 size={14} className="text-emerald-400" /> : <Cloud size={12} className="text-slate-500"/>}
                  <span className="text-[10px] font-black uppercase text-slate-400">{saveStatus === 'saving' ? 'Saving' : saveStatus === 'saved' ? 'Saved' : 'Synced'}</span>
                </div>
                <div className="hidden sm:flex items-center bg-slate-800/80 rounded-xl p-1.5 border border-slate-700 shadow-sm">
                  <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronLeft size={20} /></button>
                  <div className="px-6 font-mono font-black text-indigo-400 w-48 text-center text-sm uppercase tracking-wider">
                    {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' }).toUpperCase()}
                  </div>
                  <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronRight size={20} /></button>
                </div>
            </div>
          </div>
          <div className="border-t border-slate-700/50 px-2 overflow-x-auto scrollbar-hide">
            <div className="flex space-x-1 py-1.5 sm:py-2">
              {TABS.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs font-black rounded-lg transition-all flex-1 justify-center sm:flex-none uppercase tracking-widest ${isActive ? 'text-white bg-indigo-600 shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
                    <Icon size={16} />{tab.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </nav>
      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && <SalarySlip data={currentData.salary} onChange={(s) => updateCurrentData({ salary: s })} />}
        {activeTab === 'budget' && <Budget income={currentNetIncome} data={currentData.budget} onChange={(b) => updateCurrentData({ budget: b })} />}
        {activeTab === 'charts' && <MonthlyCharts budgetData={currentData.budget} income={currentNetIncome} />}
        {activeTab === 'invest' && <Investments items={currentData.investments} onChange={(i) => updateCurrentData({ investments: i })} />}
        {activeTab === 'year' && <YearlySummary appState={appState} year={currentDate.getFullYear()} />}
        {activeTab === 'ai' && <AIAnalysis currentMonthData={currentData} netIncome={currentNetIncome} />}
      </main>
      {showCopyModal && (
        <div className="fixed inset-0 bg-slate-950/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="bg-slate-900 p-8 rounded-3xl max-w-md w-full border border-slate-800 shadow-2xl">
              <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Bulan Baru</h3>
              <p className="text-slate-400 mb-8 font-black">Data bulan ini belum ada. Salin template dari bulan sebelumnya?</p>
              <div className="flex gap-4">
                <button onClick={() => initializeMonth(true)} className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg">Salin</button>
                <button onClick={() => initializeMonth(false)} className="flex-1 bg-slate-800 text-slate-200 py-3 rounded-xl font-black uppercase tracking-widest hover:bg-slate-700 transition-all">Baru</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Lock, User, Eye, EyeOff, ShieldCheck, RefreshCw, ArrowLeft, KeyRound, Loader2 } from 'lucide-react';
import { supabase } from '../supabaseClient';

interface LoginProps {
  onAuthenticated: () => void;
}

const Login: React.FC<LoginProps> = ({ onAuthenticated }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [isForgot, setIsForgot] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleAction = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    try {
      if (isForgot) {
        await handleReset();
      } else if (isSignUp) {
        await handleSignUp();
      } else {
        await handleLogin();
      }
    } catch (err: any) {
      setError(err.message || 'Terjadi kesalahan sistem');
    } finally {
      setLoading(false);
    }
  };

  const handleSignUp = async () => {
    if (!username || !password) throw new Error('Username dan Password wajib diisi');
    if (password !== confirmPassword) throw new Error('Konfirmasi password tidak cocok');

    // Cek apakah username sudah ada
    const { data: existing } = await supabase
      .from('app_users')
      .select('username')
      .eq('username', username)
      .single();

    if (existing) throw new Error('Username sudah digunakan');

    const { error: signUpError } = await supabase
      .from('app_users')
      .insert([{ username, password }]);

    if (signUpError) throw signUpError;

    setSuccess('Akun berhasil dibuat! Silakan login.');
    setIsSignUp(false);
    setPassword('');
    setConfirmPassword('');
  };

  const handleLogin = async () => {
    const { data, error: loginError } = await supabase
      .from('app_users')
      .select('*')
      .eq('username', username)
      .eq('password', password)
      .single();

    if (loginError || !data) {
      throw new Error('Username atau Password salah');
    }

    onAuthenticated();
  };

  const handleReset = async () => {
    if (!username || !password) throw new Error('Semua field wajib diisi');
    if (password !== confirmPassword) throw new Error('Password baru tidak cocok');

    const { data: existing } = await supabase
      .from('app_users')
      .select('username')
      .eq('username', username)
      .single();

    if (!existing) throw new Error('Username tidak ditemukan di database');

    const { error: updateError } = await supabase
      .from('app_users')
      .update({ password })
      .eq('username', username);

    if (updateError) throw updateError;

    setSuccess('Kredensial berhasil diperbarui di cloud!');
    setIsForgot(false);
    setPassword('');
    setConfirmPassword('');
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-[#0f172a] selection:bg-indigo-500/30">
      <div className="max-w-md w-full animate-fadeIn">
        <div className="glass-panel p-8 sm:p-10 rounded-[2.5rem] border border-white/10 shadow-2xl relative overflow-hidden">
          <div className="absolute -top-24 -right-24 w-48 h-48 bg-indigo-600/20 rounded-full blur-3xl"></div>
          <div className="absolute -bottom-24 -left-24 w-48 h-48 bg-blue-600/10 rounded-full blur-3xl"></div>

          <div className="relative z-10 text-center mb-8">
            <div className="inline-flex p-4 rounded-3xl bg-indigo-600 shadow-xl mb-6 shadow-indigo-900/40">
              <ShieldCheck className="text-white w-8 h-8" />
            </div>
            <h1 className="text-2xl font-black text-white uppercase tracking-tighter">
              {isForgot ? 'Cloud Reset' : isSignUp ? 'Daftar Akun Cloud' : 'Cloud Login'}
            </h1>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em] mt-2">
              Secure Cloud Access System
            </p>
          </div>

          <form onSubmit={handleAction} className="space-y-5 relative z-10">
            {error && (
              <div className="bg-rose-500/10 border border-rose-500/20 p-3 rounded-xl text-rose-500 text-[10px] font-black uppercase tracking-wider text-center">
                {error}
              </div>
            )}
            {success && (
              <div className="bg-emerald-500/10 border border-emerald-500/20 p-3 rounded-xl text-emerald-500 text-[10px] font-black uppercase tracking-wider text-center">
                {success}
              </div>
            )}

            <div className="space-y-1.5">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 pl-1">Username</label>
              <div className="relative group">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
                <input 
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-4 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all"
                  placeholder="Username Anda"
                  required
                />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 pl-1">
                {isForgot ? 'Password Baru' : 'Password'}
              </label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
                <input 
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-12 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all"
                  placeholder="••••••••"
                  required
                />
                <button 
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white transition-colors"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {(isSignUp || isForgot) && (
              <div className="space-y-1.5 animate-fadeIn">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 pl-1">Konfirmasi Password</label>
                <div className="relative group">
                  <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
                  <input 
                    type={showPassword ? "text" : "password"}
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-4 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all"
                    placeholder="••••••••"
                    required
                  />
                </div>
              </div>
            )}

            <button 
              type="submit"
              disabled={loading}
              className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black uppercase text-xs tracking-[0.2em] transition-all shadow-lg shadow-indigo-900/40 active:scale-95 flex items-center justify-center gap-3"
            >
              {loading ? <Loader2 size={16} className="animate-spin" /> : null}
              {isForgot ? 'Update di Cloud' : isSignUp ? 'Daftar Sekarang' : 'Masuk Dashboard'}
            </button>

            <div className="pt-4 flex flex-col gap-3">
              {!isSignUp && !isForgot && (
                <button 
                  type="button"
                  onClick={() => { setIsForgot(true); setError(''); setSuccess(''); }}
                  className="text-[10px] font-black uppercase text-indigo-400 hover:text-indigo-300 tracking-widest transition-colors flex items-center justify-center gap-2"
                >
                  <RefreshCw size={12} /> Lupa Akses? Reset Disini
                </button>
              )}

              {(isSignUp || isForgot) && (
                <button 
                  type="button"
                  onClick={() => { setIsSignUp(false); setIsForgot(false); setError(''); setSuccess(''); }}
                  className="text-[10px] font-black uppercase text-slate-500 hover:text-white tracking-widest transition-colors flex items-center justify-center gap-2"
                >
                  <ArrowLeft size={12} /> Kembali ke Login
                </button>
              )}

              {!isSignUp && !isForgot && (
                <div className="text-center">
                  <span className="text-[10px] font-black uppercase text-slate-600 tracking-widest">Akun belum terdaftar? </span>
                  <button 
                    type="button" 
                    onClick={() => { setIsSignUp(true); setError(''); setSuccess(''); }}
                    className="text-[10px] font-black uppercase text-indigo-400 hover:text-indigo-300"
                  >
                    Daftar Baru
                  </button>
                </div>
              )}
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { AppState, MonthlyData, DEFAULT_SALARY, DEFAULT_BUDGET } from './types';
import SalarySlip from './components/SalarySlip';
import Budget from './components/Budget';
import MonthlyCharts from './components/MonthlyCharts';
import Investments from './components/Investments';
import YearlySummary from './components/YearlySummary';
import AIAnalysis from './components/AIAnalysis';
import Login from './components/Login';
import { calculateGrossIncome, calculateTax, calculateOvertime, calculateBonus } from './utils';
import { Wallet, LayoutDashboard, PieChart, TrendingUp, Calendar, ChevronLeft, ChevronRight, Cloud, Loader2, CheckCircle2, Sparkles, Sun, Moon, LogOut } from 'lucide-react';
import { supabase } from './supabaseClient';

const TABS = [
  { id: 'salary', label: 'Gaji', icon: Wallet },
  { id: 'budget', label: 'Anggaran', icon: LayoutDashboard },
  { id: 'charts', label: 'Grafik', icon: PieChart },
  { id: 'invest', label: 'Aset', icon: TrendingUp },
  { id: 'year', label: 'Tahunan', icon: Calendar },
  { id: 'ai', label: 'AI Analisis', icon: Sparkles },
];

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');
  const [appState, setAppState] = useState<AppState>({});
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  // Theme state
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('app-theme') as 'dark' | 'light') || 'dark';
  });

  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  // Feature: Auto-close/reset when minimized or tab switched
  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'hidden') {
        // Force reload to clear memory and start from the beginning
        window.location.reload();
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('app-theme', theme);
  }, [theme]);

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  const handleLogout = () => {
    setIsAuthenticated(false);
    // Reload to ensure all sensitive memory states are cleared
    window.location.reload();
  };

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase.from('monthly_finance').select('month_id, data');
        if (error) throw error;
        if (data) {
          const loadedState: AppState = {};
          data.forEach((row: any) => { loadedState[row.month_id] = row.data; });
          setAppState(loadedState);
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (isLoading || !appState[currentMonthKey]) return;
    const saveData = async () => {
      setSaveStatus('saving');
      try {
        const { error } = await supabase.from('monthly_finance').upsert({ 
          month_id: currentMonthKey, 
          data: appState[currentMonthKey],
          updated_at: new Date().toISOString()
        });
        if (error) throw error;
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } catch (err) {
        console.error("Error saving data:", err);
        setSaveStatus('error');
      }
    };
    const timeoutId = setTimeout(saveData, 800);
    return () => clearTimeout(timeoutId);
  }, [appState, currentMonthKey, isLoading]);

  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     return gross - calculateTax(gross, salary.taxRate) - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  useEffect(() => {
    if (!isLoading && !appState[currentMonthKey]) {
      const prevDate = new Date(currentDate);
      prevDate.setMonth(currentDate.getMonth() - 1);
      const pKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
      if (appState[pKey]) {
        setPrevMonthKey(pKey);
        setShowCopyModal(true);
      } else {
        initializeMonth(false);
      }
    }
  }, [currentMonthKey, isLoading]);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      newData = JSON.parse(JSON.stringify(appState[prevMonthKey]));
      if (newData.budget.needs) newData.budget.needs.items.forEach(i => i.actual = 0);
      if (newData.budget.savings) newData.budget.savings.items.forEach(i => i.actual = 0);
      if (newData.budget.debt) newData.budget.debt.items.forEach(i => i.actual = 0);
      if (newData.budget.others) newData.budget.others.items.forEach(i => i.actual = 0);
      if (newData.budget.custom) newData.budget.custom.forEach(cat => cat.items.forEach(i => i.actual = 0));
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = { salary: { ...DEFAULT_SALARY }, budget: { ...DEFAULT_BUDGET }, investments: [] };
    }
    setAppState(prev => ({ ...prev, [currentMonthKey]: newData }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => {
      const existing = prev[currentMonthKey] || { 
        salary: { ...DEFAULT_SALARY }, 
        budget: { ...DEFAULT_BUDGET }, 
        investments: [] 
      };
      const updatedMonth = { ...existing, ...newData };
      return { 
        ...prev, 
        [currentMonthKey]: updatedMonth 
      };
    });
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  if (isLoading) return <div className="min-h-screen flex items-center justify-center bg-[#0f172a]"><Loader2 className="w-10 h-10 text-indigo-400 animate-spin" /></div>;

  // Render Login if not authenticated
  if (!isAuthenticated) {
    return <Login onAuthenticated={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="min-h-screen font-sans selection:bg-indigo-500/30 selection:text-indigo-200 theme-transition">
      <nav className="sticky top-0 z-50 pt-2 px-2 sm:pt-4 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl border border-white/5">
          <div className="flex flex-col sm:flex-row items-center justify-between p-3 sm:px-6 sm:h-20 gap-3">
            <div className="flex items-center justify-between w-full sm:w-auto">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-lg shadow-lg">
                     <Wallet className="text-white h-5 w-5 sm:h-6 sm:w-6" />
                  </div>
                  <div>
                    <h1 className="text-sm sm:text-xl font-black text-white uppercase tracking-tight leading-tight">ANIQ SUSILO</h1>
                    <p className="text-[10px] sm:text-xs font-black text-indigo-400 uppercase tracking-widest mt-0.5">FINANCE MONTHLY</p>
                  </div>
                </div>
                <div className="flex sm:hidden items-center gap-2">
                   <button onClick={handleLogout} className="p-2 bg-rose-500/10 rounded-lg border border-rose-500/20 text-rose-500">
                     <LogOut size={16} />
                   </button>
                   <button onClick={toggleTheme} className="p-2 bg-slate-800 rounded-lg border border-slate-700 text-amber-400">
                     {theme === 'dark' ? <Sun size={16} /> : <Moon size={16} className="text-indigo-400" />}
                   </button>
                   <div className="flex items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
                      <button onClick={() => changeMonth(-1)} className="p-1.5"><ChevronLeft size={16} /></button>
                      <div className="px-2 font-mono font-black text-indigo-400 text-xs uppercase">
                        {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' })}
                      </div>
                      <button onClick={() => changeMonth(1)} className="p-1.5"><ChevronRight size={16} /></button>
                   </div>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button 
                  onClick={handleLogout}
                  className="hidden sm:flex items-center gap-2 px-4 py-2 bg-rose-500/10 rounded-xl border border-rose-500/20 shadow-sm hover:bg-rose-500/20 transition-colors group"
                  title="Logout"
                >
                  <LogOut size={18} className="text-rose-500 group-hover:scale-110 transition-transform" />
                  <span className="text-[10px] font-black uppercase text-rose-600">Logout</span>
                </button>
                <button 
                  onClick={toggleTheme}
                  className="hidden sm:flex items-center gap-2 px-4 py-2 bg-slate-800/80 rounded-xl border border-slate-700 shadow-sm hover:bg-slate-700 transition-colors"
                  title="Ganti Tema"
                >
                  {theme === 'dark' ? (
                    <><Sun size={18} className="text-amber-400" /><span className="text-[10px] font-black uppercase text-slate-300">Tema Terang</span></>
                  ) : (
                    <><Moon size={18} className="text-indigo-400" /><span className="text-[10px] font-black uppercase text-slate-600">Tema Gelap</span></>
                  )}
                </button>
                <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-slate-800/50 rounded-lg border border-slate-700/50">
                  {saveStatus === 'saving' ? <Loader2 size={14} className="animate-spin text-indigo-400" /> : saveStatus === 'saved' ? <CheckCircle2 size={14} className="text-emerald-400" /> : <Cloud size={12} className="text-slate-500"/>}
                  <span className="text-[10px] font-black uppercase text-slate-400">{saveStatus === 'saving' ? 'Saving' : saveStatus === 'saved' ? 'Saved' : 'Synced'}</span>
                </div>
                <div className="hidden sm:flex items-center bg-slate-800/80 rounded-xl p-1.5 border border-slate-700 shadow-sm">
                  <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronLeft size={20} /></button>
                  <div className="px-6 font-mono font-black text-indigo-400 w-48 text-center text-sm uppercase tracking-wider">
                    {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' }).toUpperCase()}
                  </div>
                  <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronRight size={20} /></button>
                </div>
            </div>
          </div>
          <div className="border-t border-slate-700/50 px-2 overflow-x-auto scrollbar-hide">
            <div className="flex space-x-1 py-1.5 sm:py-2">
              {TABS.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs font-black rounded-lg transition-all flex-1 justify-center sm:flex-none uppercase tracking-widest ${isActive ? 'text-white bg-indigo-600 shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
                    <Icon size={16} />{tab.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </nav>
      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && <SalarySlip data={currentData.salary} onChange={(s) => updateCurrentData({ salary: s })} />}
        {activeTab === 'budget' && <Budget income={currentNetIncome} data={currentData.budget} onChange={(b) => updateCurrentData({ budget: b })} />}
        {activeTab === 'charts' && <MonthlyCharts budgetData={currentData.budget} income={currentNetIncome} />}
        {activeTab === 'invest' && <Investments items={currentData.investments} onChange={(i) => updateCurrentData({ investments: i })} />}
        {activeTab === 'year' && <YearlySummary appState={appState} year={currentDate.getFullYear()} />}
        {activeTab === 'ai' && <AIAnalysis currentMonthData={currentData} netIncome={currentNetIncome} />}
      </main>
      {showCopyModal && (
        <div className="fixed inset-0 bg-slate-950/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
           <div className="bg-slate-900 p-8 rounded-3xl max-w-md w-full border border-slate-800 shadow-2xl">
              <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Bulan Baru</h3>
              <p className="text-slate-400 mb-8 font-black">Data bulan ini belum ada. Salin template dari bulan sebelumnya?</p>
              <div className="flex gap-4">
                <button onClick={() => initializeMonth(true)} className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg">Salin</button>
                <button onClick={() => initializeMonth(false)} className="flex-1 bg-slate-800 text-slate-200 py-3 rounded-xl font-black uppercase tracking-widest hover:bg-slate-700 transition-all">Baru</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Lock, User, Eye, EyeOff, ShieldCheck, RefreshCw, ArrowLeft, KeyRound, Loader2 } from 'lucide-react';
import { supabase } from '../supabaseClient';

interface LoginProps {
  onAuthenticated: () => void;
}

const Login: React.FC<LoginProps> = ({ onAuthenticated }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [isForgot, setIsForgot] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleAction = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    try {
      if (isForgot) {
        await handleReset();
      } else if (isSignUp) {
        await handleSignUp();
      } else {
        await handleLogin();
      }
    } catch (err: any) {
      console.error("Auth Error:", err);
      if (err.message?.includes('relation "public.app_users" does not exist')) {
        setError('Tabel "app_users" belum dibuat di Supabase. Silakan jalankan perintah SQL di Dashboard Supabase.');
      } else {
        setError(err.message || 'Terjadi kesalahan sistem');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSignUp = async () => {
    if (!username || !password) throw new Error('Username dan Password wajib diisi');
    if (password !== confirmPassword) throw new Error('Konfirmasi password tidak cocok');

    const { data: existing, error: checkError } = await supabase
      .from('app_users')
      .select('username')
      .eq('username', username)
      .maybeSingle();

    if (checkError && checkError.code !== 'PGRST116') throw checkError;
    if (existing) throw new Error('Username sudah digunakan');

    const { error: signUpError } = await supabase
      .from('app_users')
      .insert([{ username, password }]);

    if (signUpError) throw signUpError;

    setSuccess('Akun berhasil dibuat! Silakan login.');
    setIsSignUp(false);
    setPassword('');
    setConfirmPassword('');
  };

  const handleLogin = async () => {
    const { data, error: loginError } = await supabase
      .from('app_users')
      .select('*')
      .eq('username', username)
      .eq('password', password)
      .maybeSingle();

    if (loginError) throw loginError;
    if (!data) {
      throw new Error('Username atau Password salah');
    }

    onAuthenticated();
  };

  const handleReset = async () => {
    if (!username || !password) throw new Error('Semua field wajib diisi');
    if (password !== confirmPassword) throw new Error('Password baru tidak cocok');

    const { data: existing, error: checkError } = await supabase
      .from('app_users')
      .select('username')
      .eq('username', username)
      .maybeSingle();

    if (checkError) throw checkError;
    if (!existing) throw new Error('Username tidak ditemukan di database');

    const { error: updateError } = await supabase
      .from('app_users')
      .update({ password })
      .eq('username', username);

    if (updateError) throw updateError;

    setSuccess('Kredensial berhasil diperbarui di cloud!');
    setIsForgot(false);
    setPassword('');
    setConfirmPassword('');
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-[#0f172a] selection:bg-indigo-500/30">
      <div className="max-w-md w-full animate-fadeIn">
        <div className="glass-panel p-8 sm:p-10 rounded-[2.5rem] border border-white/10 shadow-2xl relative overflow-hidden text-white">
          <div className="absolute -top-24 -right-24 w-48 h-48 bg-indigo-600/20 rounded-full blur-3xl"></div>
          <div className="absolute -bottom-24 -left-24 w-48 h-48 bg-blue-600/10 rounded-full blur-3xl"></div>

          <div className="relative z-10 text-center mb-8">
            <div className="inline-flex p-4 rounded-3xl bg-indigo-600 shadow-xl mb-6 shadow-indigo-900/40">
              <ShieldCheck className="text-white w-8 h-8" />
            </div>
            <h1 className="text-2xl font-black text-white uppercase tracking-tighter">
              {isForgot ? 'Cloud Reset' : isSignUp ? 'Daftar Akun Cloud' : 'Cloud Login'}
            </h1>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em] mt-2">
              Secure Cloud Access System
            </p>
          </div>

          <form onSubmit={handleAction} className="space-y-5 relative z-10">
            {error && (
              <div className="bg-rose-500/10 border border-rose-500/20 p-3 rounded-xl text-rose-500 text-[10px] font-black uppercase tracking-wider text-center">
                {error}
              </div>
            )}
            {success && (
              <div className="bg-emerald-500/10 border border-emerald-500/20 p-3 rounded-xl text-emerald-500 text-[10px] font-black uppercase tracking-wider text-center">
                {success}
              </div>
            )}

            <div className="space-y-1.5 text-left">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 pl-1">Username</label>
              <div className="relative group">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
                <input 
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-4 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all"
                  placeholder="Username Anda"
                  required
                />
              </div>
            </div>

            <div className="space-y-1.5 text-left">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 pl-1">
                {isForgot ? 'Password Baru' : 'Password'}
              </label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
                <input 
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-12 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all"
                  placeholder="••••••••"
                  required
                />
                <button 
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white transition-colors"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {(isSignUp || isForgot) && (
              <div className="space-y-1.5 animate-fadeIn text-left">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 pl-1">Konfirmasi Password</label>
                <div className="relative group">
                  <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
                  <input 
                    type={showPassword ? "text" : "password"}
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-4 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all"
                    placeholder="••••••••"
                    required
                  />
                </div>
              </div>
            )}

            <button 
              type="submit"
              disabled={loading}
              className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black uppercase text-xs tracking-[0.2em] transition-all shadow-lg shadow-indigo-900/40 active:scale-95 flex items-center justify-center gap-3"
            >
              {loading ? <Loader2 size={16} className="animate-spin" /> : null}
              {isForgot ? 'Update di Cloud' : isSignUp ? 'Daftar Sekarang' : 'Masuk Dashboard'}
            </button>

            <div className="pt-4 flex flex-col gap-3">
              {!isSignUp && !isForgot && (
                <button 
                  type="button"
                  onClick={() => { setIsForgot(true); setError(''); setSuccess(''); }}
                  className="text-[10px] font-black uppercase text-indigo-400 hover:text-indigo-300 tracking-widest transition-colors flex items-center justify-center gap-2"
                >
                  <RefreshCw size={12} /> Lupa Akses? Reset Disini
                </button>
              )}

              {(isSignUp || isForgot) && (
                <button 
                  type="button"
                  onClick={() => { setIsSignUp(false); setIsForgot(false); setError(''); setSuccess(''); }}
                  className="text-[10px] font-black uppercase text-slate-500 hover:text-white tracking-widest transition-colors flex items-center justify-center gap-2"
                >
                  <ArrowLeft size={12} /> Kembali ke Login
                </button>
              )}

              {!isSignUp && !isForgot && (
                <div className="text-center">
                  <span className="text-[10px] font-black uppercase text-slate-600 tracking-widest">Akun belum terdaftar? </span>
                  <button 
                    type="button" 
                    onClick={() => { setIsSignUp(true); setError(''); setSuccess(''); }}
                    className="text-[10px] font-black uppercase text-indigo-400 hover:text-indigo-300"
                  >
                    Daftar Baru
                  </button>
                </div>
              )}
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { AppState, MonthlyData, DEFAULT_SALARY, DEFAULT_BUDGET } from './types';
import SalarySlip from './components/SalarySlip';
import Budget from './components/Budget';
import MonthlyCharts from './components/MonthlyCharts';
import Investments from './components/Investments';
import YearlySummary from './components/YearlySummary';
import AIAnalysis from './components/AIAnalysis';
import Login from './components/Login';
import { calculateGrossIncome, calculateTax, calculateOvertime, calculateBonus } from './utils';
import { Wallet, LayoutDashboard, PieChart, TrendingUp, Calendar, ChevronLeft, ChevronRight, Cloud, Loader2, CheckCircle2, Sparkles, Sun, Moon, LogOut } from 'lucide-react';
import { supabase } from './supabaseClient';

const TABS = [
  { id: 'salary', label: 'Gaji', icon: Wallet },
  { id: 'budget', label: 'Anggaran', icon: LayoutDashboard },
  { id: 'charts', label: 'Grafik', icon: PieChart },
  { id: 'invest', label: 'Aset', icon: TrendingUp },
  { id: 'year', label: 'Tahunan', icon: Calendar },
  { id: 'ai', label: 'AI Analisis', icon: Sparkles },
];

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');
  const [appState, setAppState] = useState<AppState>({});
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [showCopyModal, setShowCopyModal] = useState(false);
  const [prevMonthKey, setPrevMonthKey] = useState<string | null>(null);

  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('app-theme') as 'dark' | 'light') || 'dark';
  });

  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('app-theme', theme);
  }, [theme]);

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  const handleLogout = () => {
    setIsAuthenticated(false);
    window.location.reload();
  };

  useEffect(() => {
    if (!isAuthenticated) return;
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase.from('monthly_finance').select('month_id, data');
        if (error) throw error;
        if (data) {
          const loadedState: AppState = {};
          data.forEach((row: any) => { loadedState[row.month_id] = row.data; });
          setAppState(loadedState);
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, [isAuthenticated]);

  useEffect(() => {
    if (!isAuthenticated || isLoading || !appState[currentMonthKey]) return;
    const saveData = async () => {
      setSaveStatus('saving');
      try {
        const { error } = await supabase.from('monthly_finance').upsert({ 
          month_id: currentMonthKey, 
          data: appState[currentMonthKey],
          updated_at: new Date().toISOString()
        });
        if (error) throw error;
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } catch (err) {
        console.error("Error saving data:", err);
        setSaveStatus('error');
      }
    };
    const timeoutId = setTimeout(saveData, 1000);
    return () => clearTimeout(timeoutId);
  }, [appState, currentMonthKey, isLoading, isAuthenticated]);

  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     return gross - calculateTax(gross, salary.taxRate) - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  const initializeMonth = (copyFromPrev: boolean) => {
    let newData: MonthlyData;
    if (copyFromPrev && prevMonthKey && appState[prevMonthKey]) {
      newData = JSON.parse(JSON.stringify(appState[prevMonthKey]));
      newData.salary.overtimeHours = 0;
      newData.salary.bonusMultiplier = 0;
      newData.salary.thr = 0;
      newData.salary.leavePay = 0;
    } else {
      newData = { salary: { ...DEFAULT_SALARY }, budget: { ...DEFAULT_BUDGET }, investments: [] };
    }
    setAppState(prev => ({ ...prev, [currentMonthKey]: newData }));
    setShowCopyModal(false);
  };

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => {
      const existing = prev[currentMonthKey] || { salary: { ...DEFAULT_SALARY }, budget: { ...DEFAULT_BUDGET }, investments: [] };
      return { ...prev, [currentMonthKey]: { ...existing, ...newData } };
    });
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  if (!isAuthenticated) {
    return <Login onAuthenticated={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="min-h-screen font-sans selection:bg-indigo-500/30 theme-transition">
      <nav className="sticky top-0 z-50 pt-2 px-2 sm:pt-4 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl border border-white/5">
          <div className="flex flex-col sm:flex-row items-center justify-between p-3 sm:px-6 sm:h-20 gap-3">
            <div className="flex items-center justify-between w-full sm:w-auto">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-lg shadow-lg">
                     <Wallet className="text-white h-5 w-5 sm:h-6 sm:w-6" />
                  </div>
                  <div>
                    <h1 className="text-sm sm:text-xl font-black text-white uppercase tracking-tight leading-tight">ANIQ SUSILO</h1>
                    <p className="text-[10px] sm:text-xs font-black text-indigo-400 uppercase tracking-widest mt-0.5">FINANCE MONT</p>
                  </div>
                </div>
                <div className="flex sm:hidden items-center gap-2">
                   <button onClick={handleLogout} className="p-2 bg-rose-500/10 rounded-lg text-rose-500 border border-rose-500/20">
                     <LogOut size={16} />
                   </button>
                   <button onClick={toggleTheme} className="p-2 bg-slate-800 rounded-lg text-amber-400 border border-slate-700">
                     {theme === 'dark' ? <Sun size={16} /> : <Moon size={16} className="text-indigo-400" />}
                   </button>
                   <div className="flex items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
                      <button onClick={() => changeMonth(-1)} className="p-1.5"><ChevronLeft size={16} /></button>
                      <div className="px-2 font-mono font-black text-indigo-400 text-xs uppercase">
                        {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' })}
                      </div>
                      <button onClick={() => changeMonth(1)} className="p-1.5"><ChevronRight size={16} /></button>
                   </div>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button 
                  onClick={handleLogout}
                  className="hidden sm:flex items-center gap-2 px-4 py-2 bg-rose-500/10 rounded-xl border border-rose-500/20 shadow-sm hover:bg-rose-500/20 transition-all text-rose-500"
                >
                  <LogOut size={18} />
                  <span className="text-[10px] font-black uppercase tracking-widest">Logout</span>
                </button>
                <button 
                  onClick={toggleTheme}
                  className="hidden sm:flex items-center gap-2 px-4 py-2 bg-slate-800/80 rounded-xl border border-slate-700 transition-colors"
                >
                  {theme === 'dark' ? <Sun size={18} className="text-amber-400" /> : <Moon size={18} className="text-indigo-400" />}
                  <span className="text-[10px] font-black uppercase text-slate-400">{theme === 'dark' ? 'Light' : 'Dark'}</span>
                </button>
                <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-slate-800/50 rounded-lg border border-slate-700/50">
                  {saveStatus === 'saving' ? <Loader2 size={14} className="animate-spin text-indigo-400" /> : saveStatus === 'saved' ? <CheckCircle2 size={14} className="text-emerald-400" /> : <Cloud size={12} className="text-slate-500"/>}
                  <span className="text-[10px] font-black uppercase text-slate-400">{saveStatus === 'saving' ? 'Saving' : saveStatus === 'saved' ? 'Saved' : 'Synced'}</span>
                </div>
                <div className="hidden sm:flex items-center bg-slate-800/80 rounded-xl p-1.5 border border-slate-700 shadow-sm">
                  <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronLeft size={20} /></button>
                  <div className="px-6 font-mono font-black text-indigo-400 w-48 text-center text-sm uppercase tracking-wider">
                    {currentDate.toLocaleString('id-ID', { month: 'long', year: 'numeric' }).toUpperCase()}
                  </div>
                  <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronRight size={20} /></button>
                </div>
            </div>
          </div>
          <div className="border-t border-slate-700/50 px-2 overflow-x-auto scrollbar-hide">
            <div className="flex space-x-1 py-1.5 sm:py-2">
              {TABS.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-1.5 px-3 py-2 sm:px-5 sm:py-2.5 text-xs font-black rounded-lg transition-all flex-1 justify-center sm:flex-none uppercase tracking-widest ${isActive ? 'text-white bg-indigo-600 shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
                    <Icon size={16} />{tab.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </nav>
      <main className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8 pb-24">
        {activeTab === 'salary' && <SalarySlip data={currentData.salary} onChange={(s) => updateCurrentData({ salary: s })} />}
        {activeTab === 'budget' && <Budget income={currentNetIncome} data={currentData.budget} onChange={(b) => updateCurrentData({ budget: b })} />}
        {activeTab === 'charts' && <MonthlyCharts budgetData={currentData.budget} income={currentNetIncome} />}
        {activeTab === 'invest' && <Investments items={currentData.investments} onChange={(i) => updateCurrentData({ investments: i })} />}
        {activeTab === 'year' && <YearlySummary appState={appState} year={currentDate.getFullYear()} />}
        {activeTab === 'ai' && <AIAnalysis currentMonthData={currentData} netIncome={currentNetIncome} />}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Lock, User, Eye, EyeOff, ShieldCheck, RefreshCw, ArrowLeft, KeyRound, Loader2 } from 'lucide-react';
import { supabase } from '../supabaseClient';

interface LoginProps {
  onAuthenticated: () => void;
}

const Login: React.FC<LoginProps> = ({ onAuthenticated }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [isForgot, setIsForgot] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleAction = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    try {
      if (isForgot) {
        await handleReset();
      } else if (isSignUp) {
        await handleSignUp();
      } else {
        await handleLogin();
      }
    } catch (err: any) {
      console.error("Auth Error:", err);
      if (err.message?.includes('relation "public.app_users" does not exist')) {
        setError('Tabel "app_users" belum ada. Pastikan SQL Editor Supabase sudah dijalankan.');
      } else {
        setError(err.message || 'Gagal terhubung ke Cloud.');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSignUp = async () => {
    if (!username || !password) throw new Error('Input tidak lengkap');
    if (password !== confirmPassword) throw new Error('Konfirmasi password salah');

    const { data: existing } = await supabase.from('app_users').select('username').eq('username', username).maybeSingle();
    if (existing) throw new Error('Username sudah ada');

    const { error: signUpError } = await supabase.from('app_users').insert([{ username, password }]);
    if (signUpError) throw signUpError;

    setSuccess('Berhasil daftar! Silakan Login.');
    setIsSignUp(false);
    setPassword('');
    setConfirmPassword('');
  };

  const handleLogin = async () => {
    const { data, error: loginError } = await supabase.from('app_users').select('*').eq('username', username).eq('password', password).maybeSingle();
    if (loginError) throw loginError;
    if (!data) throw new Error('Username atau Password salah');
    onAuthenticated();
  };

  const handleReset = async () => {
    if (!username || !password) throw new Error('Data tidak lengkap');
    if (password !== confirmPassword) throw new Error('Password tidak cocok');

    const { data: existing } = await supabase.from('app_users').select('username').eq('username', username).maybeSingle();
    if (!existing) throw new Error('Username tidak ditemukan');

    const { error: updateError } = await supabase.from('app_users').update({ password }).eq('username', username);
    if (updateError) throw updateError;

    setSuccess('Password diperbarui!');
    setIsForgot(false);
    setPassword('');
    setConfirmPassword('');
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-[#0f172a] selection:bg-indigo-500/30">
      <div className="max-w-md w-full animate-fadeIn">
        <div className="glass-panel p-8 sm:p-10 rounded-[2.5rem] border border-white/10 shadow-2xl relative overflow-hidden text-white">
          <div className="absolute -top-24 -right-24 w-48 h-48 bg-indigo-600/20 rounded-full blur-3xl"></div>
          <div className="relative z-10 text-center mb-8">
            <div className="inline-flex p-4 rounded-3xl bg-indigo-600 shadow-xl mb-6 shadow-indigo-900/40">
              <ShieldCheck className="text-white w-8 h-8" />
            </div>
            <h1 className="text-xl font-black text-white uppercase tracking-tighter">
              {isForgot ? 'Reset Akses' : isSignUp ? 'Daftar Cloud' : 'Masuk Dashboard'}
            </h1>
            <p className="text-slate-500 text-[9px] font-black uppercase tracking-[0.3em] mt-2">
              ANIQ SUSILO - FINANCE MONT
            </p>
          </div>

          <form onSubmit={handleAction} className="space-y-5 relative z-10">
            {error && <div className="bg-rose-500/10 border border-rose-500/20 p-3 rounded-xl text-rose-500 text-[10px] font-black uppercase text-center">{error}</div>}
            {success && <div className="bg-emerald-500/10 border border-emerald-500/20 p-3 rounded-xl text-emerald-500 text-[10px] font-black uppercase text-center">{success}</div>}

            <div className="space-y-1.5 text-left">
              <label className="text-[10px] font-black uppercase text-slate-500 pl-1">Username</label>
              <div className="relative group">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400" />
                <input type="text" value={username} onChange={(e) => setUsername(e.target.value)} className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-4 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all" placeholder="Username" required />
              </div>
            </div>

            <div className="space-y-1.5 text-left">
              <label className="text-[10px] font-black uppercase text-slate-500 pl-1">{isForgot ? 'Pass Baru' : 'Password'}</label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400" />
                <input type={showPassword ? "text" : "password"} value={password} onChange={(e) => setPassword(e.target.value)} className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-12 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all" placeholder="••••••••" required />
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white">{showPassword ? <EyeOff size={18} /> : <Eye size={18} />}</button>
              </div>
            </div>

            {(isSignUp || isForgot) && (
              <div className="space-y-1.5 animate-fadeIn text-left">
                <label className="text-[10px] font-black uppercase text-slate-500 pl-1">Konfirmasi Pass</label>
                <div className="relative group">
                  <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400" />
                  <input type={showPassword ? "text" : "password"} value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} className="w-full bg-slate-950/50 border border-slate-700 rounded-2xl py-3.5 pl-11 pr-4 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all" placeholder="••••••••" required />
                </div>
              </div>
            )}

            <button type="submit" disabled={loading} className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black uppercase text-xs tracking-widest transition-all shadow-lg flex items-center justify-center gap-3">
              {loading && <Loader2 size={16} className="animate-spin" />}
              {isForgot ? 'Update Cloud' : isSignUp ? 'Daftar Sekarang' : 'Masuk Aplikasi'}
            </button>

            <div className="pt-4 flex flex-col gap-3">
              {!isSignUp && !isForgot && (
                <button type="button" onClick={() => { setIsForgot(true); setError(''); setSuccess(''); }} className="text-[10px] font-black uppercase text-indigo-400 tracking-widest flex items-center justify-center gap-2">
                  <RefreshCw size={12} /> Lupa Username/Password?
                </button>
              )}
              {(isSignUp || isForgot) && (
                <button type="button" onClick={() => { setIsSignUp(false); setIsForgot(false); setError(''); setSuccess(''); }} className="text-[10px] font-black uppercase text-slate-500 tracking-widest flex items-center justify-center gap-2">
                  <ArrowLeft size={12} /> Kembali ke Login
                </button>
              )}
              {!isSignUp && !isForgot && (
                <div className="text-center">
                  <span className="text-[10px] font-black uppercase text-slate-600">Baru di sini? </span>
                  <button type="button" onClick={() => { setIsSignUp(true); setError(''); setSuccess(''); }} className="text-[10px] font-black uppercase text-indigo-400">Buat Akun</button>
                </div>
              )}
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

