                  <span className="hidden sm:inline text-[8px] font-black uppercase text-slate-400 tracking-tighter">
                    {saveStatus === 'saving' ? 'Syncing' : saveStatus === 'saved' ? 'Cloud Safe' : 'Connected'}
                  </span>
                </div>

                {/* Month Navigator */}
                <div className="flex items-center bg-slate-800/80 rounded-lg sm:rounded-xl p-1 border border-slate-700 shadow-sm">
                  <button onClick={() => changeMonth(-1)} className="p-1 sm:p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronLeft size={14} className="sm:size-5" /></button>
                  <div className="px-2 sm:px-6 font-mono font-black text-indigo-400 text-[9px] sm:text-sm uppercase tracking-wider text-center min-w-[60px] sm:min-w-[120px]">
                    {currentDate.toLocaleString('id-ID', { month: 'short', year: '2-digit' }).toUpperCase()}
                  </div>
                  <button onClick={() => changeMonth(1)} className="p-1 sm:p-2 hover:bg-slate-700 rounded-lg text-slate-400"><ChevronRight size={14} className="sm:size-5" /></button>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-1">
                  <button 
                    onClick={toggleTheme}
                    className="p-2 sm:px-4 sm:py-2 bg-slate-800/80 rounded-lg sm:rounded-xl border border-slate-700 transition-colors"
                  >
                    {theme === 'dark' ? <Sun size={14} className="text-amber-400 sm:size-5" /> : <Moon size={14} className="text-indigo-400 sm:size-5" />}
                  </button>
                  <button 
                    onClick={handleLogout}
                    className="p-2 sm:px-4 sm:py-2 bg-rose-500/10 rounded-lg sm:rounded-xl border border-rose-500/20 shadow-sm hover:bg-rose-500/20 transition-all text-rose-500"
                  >
                    <LogOut size={14} className="sm:size-5" />
                  </button>
                </div>
            </div>
          </div>

          {/* Tab Navigation */}
          <div className="border-t border-slate-700/50 px-1 overflow-x-auto scrollbar-hide">
            <div className="flex space-x-0.5 py-1">
              {TABS.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button 
                    key={tab.id} 
                    onClick={() => setActiveTab(tab.id)} 
                    className={`flex items-center gap-1 px-3 py-2 text-[9px] sm:text-xs font-black rounded-lg transition-all shrink-0 uppercase tracking-widest ${isActive ? 'text-white bg-indigo-600 shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
                  >
                    <Icon size={12} className="sm:size-4" />
                    <span>{tab.label}</span>
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-2 sm:px-6 lg:px-8 py-4 sm:py-8">
        <div className="animate-fadeIn">
          {activeTab === 'salary' && <SalarySlip data={currentData.salary} onChange={(s) => updateCurrentData({ salary: s })} />}
          {activeTab === 'budget' && <Budget income={currentNetIncome} data={currentData.budget} onChange={(b) => updateCurrentData({ budget: b })} />}
          {activeTab === 'charts' && <MonthlyCharts budgetData={currentData.budget} income={currentNetIncome} />}
          {activeTab === 'invest' && <Investments items={currentData.investments} onChange={(i) => updateCurrentData({ investments: i })} />}
          {activeTab === 'year' && <YearlySummary appState={appState} year={currentDate.getFullYear()} />}
          {activeTab === 'ai' && <AIAnalysis currentMonthData={currentData} netIncome={currentNetIncome} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MonthlyData } from '../types';
import { formatRupiah } from '../utils';
import { Sparkles, BrainCircuit, RefreshCw, TrendingUp, AlertCircle, CheckCircle2, Wifi } from 'lucide-react';

interface AIAnalysisProps {
  currentMonthData: MonthlyData;
  netIncome: number;
}

const AIAnalysis: React.FC<AIAnalysisProps> = ({ currentMonthData, netIncome }) => {
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const generateAnalysis = async () => {
    // 1. Cek Koneksi Internet
    if (!navigator.onLine) {
      setError("Perangkat Anda sedang offline. Mohon hubungkan ke internet.");
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      // Inisialisasi Google GenAI dengan model terbaru untuk analisis kompleks
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const budgetDetails = JSON.stringify({
        income: formatRupiah(netIncome),
        needs: currentMonthData.budget.needs?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        savings: currentMonthData.budget.savings?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        debt: currentMonthData.budget.debt?.items.map(i => ({ name: i.name, budget: i.budget, actual: i.actual })),
        others: currentMonthData.budget.others?.items.map(i => ({ name: i.name, actual: i.actual })),
        investments: currentMonthData.investments.map(i => ({ name: i.name, value: i.currentValue, target: i.targetValue }))
      });

      const prompt = `Bertindaklah sebagai Pakar Konsultan Keuangan Pribadi. 
      Lakukan analisis mendalam pada data keuangan bulanan berikut untuk Aniq Susilo.

      Data Keuangan:
      ${budgetDetails}

      Berikan respon dalam Bahasa Indonesia dengan struktur berikut:
      1. Health Check: Berikan evaluasi cepat tentang kondisi bulan ini.
      2. Budget Efficiency: Analisis apakah pengeluaran aktual sesuai dengan anggaran. Soroti jika ada overbudget.
      3. Aset & Investasi: Berikan komentar tentang pertumbuhan aset dan seberapa dekat dengan target.
      4. 3 Action Steps: Langkah nyata untuk meningkatkan kekayaan di bulan depan.

      Gunakan format Markdown yang profesional, rapi, dan mudah dibaca di layar HP.`;

      // Menggunakan gemini-3-pro-preview untuk kemampuan penalaran finansial yang lebih baik
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
      });

      const text = response.text;
      if (!text) {
        throw new Error("Gagal menerima respon dari AI.");
      }

      setAnalysis(text);
    } catch (err: any) {
      console.error("AI Analysis Error:", err);
      setError(`Gagal menganalisis: ${err.message || "Pastikan koneksi internet stabil."}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-4 sm:space-y-6 animate-fadeIn pb-12">
      <div className="glass-panel p-6 sm:p-10 rounded-[2rem] sm:rounded-[2.5rem] border border-indigo-500/20 shadow-2xl relative overflow-hidden">
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-indigo-600/10 rounded-full blur-3xl"></div>

        <div className="relative z-10 flex flex-col items-center text-center">
          <div className="bg-gradient-to-br from-indigo-500 to-blue-600 p-4 rounded-2xl sm:rounded-3xl shadow-xl mb-4 sm:mb-6">
            <BrainCircuit className="text-white w-8 h-8 sm:w-12 sm:h-12" />
          </div>
          <h2 className="text-lg sm:text-3xl font-black text-white uppercase tracking-tight mb-2">Financial AI Analyst</h2>
          <p className="text-slate-400 max-w-sm font-bold text-[10px] sm:text-sm leading-relaxed mb-6 sm:mb-8">
            Dapatkan saran strategi keuangan otomatis berdasarkan data anggaran dan aset Anda.
          </p>

          <button 
            onClick={generateAnalysis}
            disabled={isLoading}
            className="w-full sm:w-auto flex items-center justify-center gap-3 px-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl sm:rounded-2xl font-black uppercase text-[10px] sm:text-xs tracking-widest transition-all shadow-lg active:scale-95 disabled:opacity-50"
          >
            {isLoading ? (
              <>
                <RefreshCw className="w-4 h-4 animate-spin" />
                Menganalisis...
              </>
            ) : (
              <>
                <Sparkles className="w-4 h-4" />
                Mulai Analisis
              </>
            )}
          </button>
        </div>
      </div>

      {error && (
        <div className="glass-panel p-4 rounded-xl border-l-4 border-rose-500 flex items-center gap-3 bg-rose-500/10 animate-fadeIn">
          <AlertCircle className="text-rose-500 shrink-0" size={18} />
          <p className="text-rose-200 text-[10px] font-black uppercase">{error}</p>
        </div>
      )}

      {analysis && !isLoading && (
        <div className="glass-panel p-6 sm:p-10 rounded-[2rem] sm:rounded-[2.5rem] border border-white/5 shadow-xl animate-fadeIn">
          <div className="flex items-center gap-2 mb-6 border-b border-white/5 pb-3">
            <div className="w-1.5 h-5 bg-emerald-500 rounded-full"></div>
            <h3 className="text-xs sm:text-sm font-black text-white uppercase tracking-widest">Laporan Keuangan Cerdas</h3>
          </div>

          <div className="prose prose-invert max-w-none">
            <div className="text-slate-300 text-[11px] sm:text-sm leading-relaxed font-bold space-y-4 whitespace-pre-wrap">
              {analysis.split('\n').map((line, i) => {
                const trimmed = line.trim();
                if (trimmed.startsWith('#')) {
                  return <h3 key={i} className="font-black text-indigo-400 mt-4 mb-2 uppercase border-l-2 border-indigo-500 pl-2 text-xs sm:text-base">{trimmed.replace(/#/g, '').trim()}</h3>;
                }
                if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
                  return (
                    <div key={i} className="flex gap-2 items-start ml-1 mb-1">
                      <CheckCircle2 size={12} className="text-emerald-500 mt-0.5 shrink-0" />
                      <span className="text-slate-200">{trimmed.replace(/[-*]/, '').trim()}</span>
                    </div>
                  );
                }
                if (!trimmed) return <div key={i} className="h-1"></div>;
                return <p key={i} className="mb-1">{trimmed}</p>;
              })}
            </div>
          </div>

          <div className="mt-8 pt-6 border-t border-white/5 flex flex-col sm:flex-row justify-between items-center gap-3">
            <div className="flex items-center gap-2 text-[8px] font-black uppercase text-slate-500 tracking-widest">
              <Wifi size={10} className="text-indigo-500" />
              Online Real-time Analysis
            </div>
            <button onClick={generateAnalysis} className="text-[9px] font-black uppercase tracking-widest text-indigo-400 hover:text-white transition-colors flex items-center gap-2">
              <RefreshCw size={12} /> Perbarui Analisis
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AIAnalysis;

import React, { useState } from 'react';
import { Lock, User, Eye, EyeOff, ShieldCheck, RefreshCw, ArrowLeft, KeyRound, Loader2 } from 'lucide-react';

interface LoginProps {
  onAuthenticated: () => void;
}

const Login: React.FC<LoginProps> = ({ onAuthenticated }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [isForgot, setIsForgot] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const getLocalUsers = () => {
    const users = localStorage.getItem('app_local_users');
    return users ? JSON.parse(users) : {};
  };

  const handleAction = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    setTimeout(() => {
      try {
        const users = getLocalUsers();

        if (isForgot) {
          if (!users[username]) throw new Error('Username tidak ditemukan');
          if (password !== confirmPassword) throw new Error('Konfirmasi password tidak cocok');
          users[username] = password;
          localStorage.setItem('app_local_users', JSON.stringify(users));
          setSuccess('Password diperbarui!');
          setIsForgot(false);
        } 
        else if (isSignUp) {
          if (users[username]) throw new Error('Username sudah terdaftar');
          if (password !== confirmPassword) throw new Error('Password tidak cocok');
          users[username] = password;
          localStorage.setItem('app_local_users', JSON.stringify(users));
          setSuccess('Akun berhasil dibuat!');
          setIsSignUp(false);
        } 
        else {
          if (!users[username] || users[username] !== password) {
            throw new Error('Username atau Password salah');
          }
          localStorage.setItem('is_authenticated', 'true');
          onAuthenticated();
        }
      } catch (err: any) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }, 800);
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-[#0f172a] selection:bg-indigo-500/30">
      <div className="max-w-md w-full animate-fadeIn">
        <div className="glass-panel p-6 sm:p-10 rounded-[2rem] sm:rounded-[2.5rem] border border-white/10 shadow-2xl relative overflow-hidden text-white">
          <div className="absolute -top-24 -right-24 w-48 h-48 bg-indigo-600/20 rounded-full blur-3xl"></div>

          <div className="relative z-10 text-center mb-6 sm:mb-8">
            <div className="inline-flex p-3 sm:p-4 rounded-2xl sm:rounded-3xl bg-indigo-600 shadow-xl mb-4 sm:mb-6 shadow-indigo-900/40">
              <ShieldCheck className="text-white w-6 h-6 sm:w-8 sm:h-8" />
            </div>
            {/* Judul diselaraskan dengan Dashboard sesuai instruksi */}
            <div className="space-y-1">
              <h1 className="text-lg sm:text-2xl font-black text-white uppercase tracking-tighter leading-tight">
                ANIQ SUSILO - FINANCE MONTHLY
              </h1>
            </div>
            <div className="mt-4 pt-4 border-t border-white/5">
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">
                {isForgot ? 'Reset Akses' : isSignUp ? 'Daftar Akun' : 'Masuk Dashboard'}
              </p>
            </div>
          </div>

          <form onSubmit={handleAction} className="space-y-4 sm:space-y-5 relative z-10">
            {error && <div className="bg-rose-500/10 border border-rose-500/20 p-3 rounded-xl text-rose-500 text-[10px] font-black uppercase text-center">{error}</div>}
            {success && <div className="bg-emerald-500/10 border border-emerald-500/20 p-3 rounded-xl text-emerald-500 text-[10px] font-black uppercase text-center">{success}</div>}

            <div className="space-y-1.5 text-left">
              <label className="text-[9px] font-black uppercase text-slate-500 pl-1 tracking-widest">Username</label>
              <div className="relative group">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400" />
                <input 
                  type="text" 
                  value={username} 
                  onChange={(e) => setUsername(e.target.value)} 
                  className="w-full bg-slate-950/50 border border-slate-700 rounded-xl sm:rounded-2xl py-3 sm:py-3.5 pl-11 pr-4 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all" 
                  placeholder="Username" 
                  required 
                />
              </div>
            </div>

            <div className="space-y-1.5 text-left">
              <label className="text-[9px] font-black uppercase text-slate-500 pl-1 tracking-widest">{isForgot ? 'Password Baru' : 'Password'}</label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400" />
                <input 
                  type={showPassword ? "text" : "password"} 
                  value={password} 
                  onChange={(e) => setPassword(e.target.value)} 
                  className="w-full bg-slate-950/50 border border-slate-700 rounded-xl sm:rounded-2xl py-3 sm:py-3.5 pl-11 pr-12 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all" 
                  placeholder="••••••••" 
                  required 
                />
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white transition-colors">
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {(isSignUp || isForgot) && (
              <div className="space-y-1.5 animate-fadeIn text-left">
                <label className="text-[9px] font-black uppercase text-slate-500 pl-1 tracking-widest">Konfirmasi Password</label>
                <div className="relative group">
                  <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400" />
                  <input 
                    type={showPassword ? "text" : "password"} 
                    value={confirmPassword} 
                    onChange={(e) => setConfirmPassword(e.target.value)} 
                    className="w-full bg-slate-950/50 border border-slate-700 rounded-xl sm:rounded-2xl py-3 sm:py-3.5 pl-11 pr-4 text-white font-bold text-sm focus:outline-none focus:border-indigo-500 transition-all" 
                    placeholder="••••••••" 
                    required 
                  />
                </div>
              </div>
            )}

            <button type="submit" disabled={loading} className="w-full py-3.5 sm:py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl sm:rounded-2xl font-black uppercase text-[10px] tracking-[0.2em] transition-all shadow-lg flex items-center justify-center gap-3 active:scale-95">
              {loading ? <Loader2 size={16} className="animate-spin" /> : null}
              {isForgot ? 'Update Password' : isSignUp ? 'Daftar Akun' : 'Masuk Dashboard'}
            </button>

            <div className="pt-4 flex flex-col gap-3">
              {!isSignUp && !isForgot && (
                <button type="button" onClick={() => { setIsForgot(true); setError(''); setSuccess(''); }} className="text-[9px] font-black uppercase text-indigo-400 tracking-widest flex items-center justify-center gap-2 hover:text-indigo-300 transition-colors">
                  <RefreshCw size={12} /> Lupa Password?
                </button>
              )}
              {(isSignUp || isForgot) && (
                <button type="button" onClick={() => { setIsSignUp(false); setIsForgot(false); setError(''); setSuccess(''); }} className="text-[9px] font-black uppercase text-slate-500 tracking-widest flex items-center justify-center gap-2 hover:text-white transition-colors">
                  <ArrowLeft size={12} /> Kembali ke Login
                </button>
              )}
              {!isSignUp && !isForgot && (
                <div className="text-center">
                  <span className="text-[9px] font-black uppercase text-slate-600 tracking-widest">Belum punya akun? </span>
                  <button type="button" onClick={() => { setIsSignUp(true); setError(''); setSuccess(''); }} className="text-[9px] font-black uppercase text-indigo-400 hover:text-indigo-300">Buat Akun</button>
                </div>
              )}
            </div>
          </form>
        </div>
        <p className="mt-6 text-center text-[8px] font-black text-slate-600 uppercase tracking-[0.4em]">Local Secure Storage</p>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { AppState, MonthlyData, DEFAULT_SALARY, DEFAULT_BUDGET } from './types';
import SalarySlip from './components/SalarySlip';
import Budget from './components/Budget';
import MonthlyCharts from './components/MonthlyCharts';
import Investments from './components/Investments';
import YearlySummary from './components/YearlySummary';
import AIAnalysis from './components/AIAnalysis';
import Login from './components/Login';
import { calculateGrossIncome, calculateTax, calculateOvertime, calculateBonus } from './utils';
import { Wallet, LayoutDashboard, PieChart, TrendingUp, Calendar, ChevronLeft, ChevronRight, Cloud, Loader2, CheckCircle2, Sparkles, Sun, Moon, LogOut } from 'lucide-react';
import { supabase } from './supabaseClient';

const TABS = [
  { id: 'salary', label: 'Gaji', icon: Wallet },
  { id: 'budget', label: 'Anggaran', icon: LayoutDashboard },
  { id: 'charts', label: 'Grafik', icon: PieChart },
  { id: 'invest', label: 'Aset', icon: TrendingUp },
  { id: 'year', label: 'Tahun', icon: Calendar },
  { id: 'ai', label: 'AI', icon: Sparkles },
];

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState('salary');
  const [appState, setAppState] = useState<AppState>({});
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(() => {
    return localStorage.getItem('is_authenticated') === 'true';
  });
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');

  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('app-theme') as 'dark' | 'light') || 'dark';
  });

  const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentData: MonthlyData = appState[currentMonthKey] || {
    salary: { ...DEFAULT_SALARY },
    budget: { ...DEFAULT_BUDGET },
    investments: []
  };

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('app-theme', theme);
  }, [theme]);

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  const handleLogout = () => {
    localStorage.removeItem('is_authenticated');
    setAppState({});
    setActiveTab('salary');
    setCurrentDate(new Date());
    setIsAuthenticated(false);
  };

  useEffect(() => {
    if (!isAuthenticated) return;

    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase
          .from('monthly_finance')
          .select('month_id, data');

        if (error) throw error;

        if (data) {
          const loadedState: AppState = {};
          data.forEach((row: any) => { 
            loadedState[row.month_id] = row.data; 
          });
          setAppState(loadedState);
        }
      } catch (err) {
        console.error("Error fetching cloud finance data:", err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [isAuthenticated]);

  useEffect(() => {
    if (!isAuthenticated || isLoading || !appState[currentMonthKey]) return;

    const saveData = async () => {
      setSaveStatus('saving');
      try {
        const { error } = await supabase
          .from('monthly_finance')
          .upsert({ 
            month_id: currentMonthKey, 
            data: appState[currentMonthKey],
            updated_at: new Date().toISOString()
          });

        if (error) throw error;
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } catch (err) {
        console.error("Error saving to cloud:", err);
        setSaveStatus('error');
      }
    };

    const timeoutId = setTimeout(saveData, 1000);
    return () => clearTimeout(timeoutId);
  }, [appState, currentMonthKey, isLoading, isAuthenticated]);

  const calculateCurrentIncome = (data: MonthlyData) => {
     const { salary } = data;
     const ot = calculateOvertime(salary.basicSalary, salary.housingAllowance, salary.overtimeHours);
     const bonus = calculateBonus(salary.basicSalary, salary.housingAllowance, salary.bonusMultiplier);
     const gross = calculateGrossIncome(salary.basicSalary, salary.housingAllowance, salary.shiftAllowance, ot, bonus, salary.thr, salary.leavePay);
     return gross - calculateTax(gross, salary.taxRate) - salary.otherDeductions;
  };
  const currentNetIncome = calculateCurrentIncome(currentData);

  const updateCurrentData = (newData: Partial<MonthlyData>) => {
    setAppState(prev => {
      const existing = prev[currentMonthKey] || { 
        salary: { ...DEFAULT_SALARY }, 
        budget: { ...DEFAULT_BUDGET }, 
        investments: [] 
      };
      return { ...prev, [currentMonthKey]: { ...existing, ...newData } };
    });
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  if (!isAuthenticated) {
    return <Login onAuthenticated={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="min-h-screen font-sans selection:bg-indigo-500/30 theme-transition pb-20 sm:pb-8">
      {/* Sticky Header Optimized for Mobile */}
      <nav className="sticky top-0 z-50 pt-1 sm:pt-4 px-1 sm:px-6">
        <div className="max-w-7xl mx-auto glass-panel rounded-xl sm:rounded-2xl shadow-xl border border-white/5 overflow-hidden">
          <div className="flex items-center justify-between p-2 sm:px-6 sm:h-20 gap-2">
            <div className="flex items-center gap-2 sm:gap-3 text-left min-w-0 flex-1">
              <div className="bg-indigo-600 p-1.5 sm:p-2 rounded-lg shadow-lg shrink-0">
                 <Wallet className="text-white h-4 w-4 sm:h-6 sm:w-6" />
              </div>
              <div className="min-w-0">
                <h1 className="text-[10px] sm:text-lg font-black text-white uppercase tracking-tighter leading-none truncate">
                  ANIQ SUSILO - FINANCE MONTHLY
                </h1>
                <div className="flex items-center gap-1 mt-0.5">
                   <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                   <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest truncate">Live Cloud Sync</p>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-1.5 sm:gap-4 shrink-0">
                {/* Save Status - Icon Only on Mobile */}
                <div className="hidden sm:flex items-center gap-1.5 px-2 py-1 bg-slate-800/50 rounded-lg border border-slate-700/50">
                  {saveStatus === 'saving' ? (
                    <Loader2 size={12} className="animate-spin text-indigo-400" />
