          <div className="space-y-4">
             <div className="flex items-center gap-3">
                <div className="bg-indigo-600 p-2 rounded-lg">
                  <UserCircle className="text-white" size={20} />
                </div>
                <div>
                   <h3 className="text-white font-black text-sm uppercase">Personal Info</h3>
                   <div className="flex flex-wrap gap-x-4 gap-y-1 mt-1">
                      <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Name: <span className="text-indigo-400">ANIQ SUSILO</span></span>
                      <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">NIK: <span className="text-indigo-400">20142101</span></span>
                   </div>
                </div>
             </div>
             <div className="flex items-center gap-3">
                <div className="bg-slate-800 p-2 rounded-lg">
                  <Info className="text-slate-400" size={20} />
                </div>
                <div>
                   <h3 className="text-white font-black text-sm uppercase">Department Info</h3>
                   <div className="flex flex-wrap gap-x-4 gap-y-1 mt-1">
                      <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">DEPT: <span className="text-slate-300">PVC 2</span></span>
                      <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">GROUP: <span className="text-slate-300">D5</span></span>
                   </div>
                </div>
             </div>
          </div>

          <div className="flex flex-col justify-center items-end bg-indigo-900/10 p-5 rounded-2xl border border-indigo-500/20">
             <span className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] mb-1">Total Equivalent Hours</span>
             <div className="text-4xl sm:text-5xl font-black text-white tracking-tighter">
                {totalEqv.toFixed(2)}
             </div>
             <span className="text-[9px] text-slate-500 font-bold uppercase mt-2">Actual Total: {totalActual.toFixed(1)} Hours</span>
          </div>
