                         No overtime records for this month
                      </td>
                    </tr>
                  ) : (
                    entries.map((entry) => {
                      const eqv = calculateEqvHours(entry.actualHours, entry.type);
                      return (
                        <tr key={entry.id} className="hover:bg-white/5 transition-colors group">
                           <td className="px-6 py-3 min-w-[160px]">
                              <div className="space-y-2">
                                <div className="flex items-center gap-2 bg-slate-950 border border-slate-800 rounded-lg px-2 py-1">
                                   <Calendar size={12} className="text-slate-500" />
                                   <input 
                                      type="date" 
                                      value={entry.date} 
                                      onChange={(e) => updateEntry(entry.id, 'date', e.target.value)}
                                      className="bg-transparent text-[10px] text-white outline-none font-bold uppercase w-full"
                                   />
                                </div>
                                <select 
                                   value={entry.type} 
                                   onChange={(e) => updateEntry(entry.id, 'type', e.target.value)}
                                   className={`w-full bg-slate-950 border border-slate-800 rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none focus:border-indigo-500 ${entry.type === 'holiday' ? 'text-rose-400' : 'text-indigo-400'}`}
                                >
                                   <option value="normal">Normal Day</option>
                                   <option value="holiday">Holiday</option>
                                </select>
                              </div>
                           </td>
                           <td className="px-6 py-3 min-w-[180px]">
                              <div className="flex items-center gap-2 bg-slate-950 border border-slate-800 rounded-lg p-2">
                                 <input 
                                    type="time" 
                                    value={entry.startTime} 
                                    onChange={(e) => updateEntry(entry.id, 'startTime', e.target.value)}
                                    className="bg-transparent text-xs text-white outline-none font-mono font-black"
                                 />
                                 <ArrowRight size={12} className="text-slate-600" />
                                 <input 
                                    type="time" 
                                    value={entry.endTime} 
                                    onChange={(e) => updateEntry(entry.id, 'endTime', e.target.value)}
                                    className="bg-transparent text-xs text-white outline-none font-mono font-black"
                                 />
                              </div>
                           </td>
                           <td className="px-6 py-3">
                              <input 
                                 type="text" 
                                 value={entry.purpose} 
                                 onChange={(e) => updateEntry(entry.id, 'purpose', e.target.value)}
                                 placeholder="Enter purpose..."
                                 className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-xs text-white font-bold outline-none focus:border-indigo-500"
                              />
                           </td>
                           <td className="px-6 py-3 text-center w-20">
                              <div className="text-xs font-mono font-black text-slate-300">
                                 {entry.actualHours.toFixed(1)}
                              </div>
                           </td>
                           <td className="px-6 py-3 text-center">
                              <div className={`text-xs font-mono font-black ${eqv > 0 ? (entry.type === 'holiday' ? 'text-rose-500' : 'text-emerald-500') : 'text-slate-700'}`}>
                                 {eqv.toFixed(2)}
                              </div>
                           </td>
                           <td className="px-6 py-3 text-center">
                              <button onClick={() => removeEntry(entry.id)} className="p-2 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 rounded-lg transition-all">
                                 <Trash2 size={16} />
                              </button>
                           </td>
                        </tr>
                      );
                    })
                  )}
               </tbody>
            </table>
         </div>

         {/* Table Footer */}
         <div className="bg-slate-900/50 px-6 py-4 flex justify-between items-center border-t border-white/5">
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest italic opacity-50">
               *Auto-calculation enabled for Time Actual
            </span>
            <div className="flex gap-8 text-right">
               <div>
                  <p className="text-[8px] font-black text-slate-500 uppercase">Total Eqv</p>
                  <p className="text-lg font-black text-indigo-400">{totalEqv.toFixed(2)}</p>
               </div>
            </div>
         </div>
      </div>
    </div>
  );
};

